window.__Q=window.__Q||{};window.__Q["prev/4/A1"]=[{"q":"引起巨脾的白血病是","o":["急性淋巴细胞白血病","急性红白血病","急性单核细胞白血病","慢性粒细胞白血病","急性粒细胞白血病"],"a":3,"e":"慢性髓系白血病瘤细胞在骨髓及脾红髓弥漫浸润，脾脏显著增大可达数千毫升，常致巨脾。急性粒细胞白血病与急性淋巴细胞白血病以骨髓及淋巴结浸润为主，脾大较轻。急性单核细胞白血病易致牙龈增生。急性红白血病以红系与粒系异常增生为主"},{"q":"以肝内纤维组织增生为主，而少有假小叶形成的肝硬化是","o":["胆汁性肝硬化","乙肝肝硬化","丙肝肝硬化","药物性肝硬化","肝豆状核变性引起的肝硬化"],"a":0,"e":"胆汁性肝硬化由肝内、外胆道长期阻塞、胆汁淤积引起，以肝内纤维组织增生、纤维条索分割原有肝小叶为主，无明显肝细胞再生和肝小叶结构改建，假小叶形成不明显。B项乙肝、C项丙肝、D项药物性、E项肝豆状核变性所致的肝硬化均有明显假小叶形成，属典型结节性肝硬化"},{"q":"硬皮病的特征性病变为","o":["全身多个器官间质纤维化","全身细小动脉玻璃样变、硬化","全身皮肤小血管硬化","全身性皮肤变硬，胶原纤维增生","全身皮肤多发性肉芽肿形成并纤维化"],"a":0,"e":"系统性硬化的特征性病变是全身多个器官间质纤维化伴炎症，皮肤胶原纤维增生致硬化，胃肠道、肺、肾、心均可受累。全身细小动脉玻璃样变、硬化见于高血压与糖尿病；皮肤小血管硬化只是局部表现，不能概括本病"},{"q":"大叶性肺炎患者，明显的发绀症状常出现在哪一期","o":["充血水肿期","红色肝样变期","灰色肝样变期","溶解消散期","病变恢复期"],"a":1,"e":"红色肝样变期肺泡腔内充满纤维蛋白和大量红细胞，肺泡通气严重受阻，通气血流比例失调，发绀等缺氧症状最明显，痰呈铁锈色。A项充血水肿期以浆液渗出为主，缺氧轻；C项灰色肝样变期红细胞已崩解、充血消退，缺氧反而减轻；D项溶解消散期病变开始吸收，症状缓解"},{"q":"属于生理性肥大的组织器官是","o":["功能亢进的甲状腺","运动员的有关肌肉肥大","高血压患者的心脏","慢性增殖性炎的扁桃体","垂体腺瘤患者的肾上腺"],"a":1,"e":"运动员骨骼肌肥大属生理性肥大，由长期运动的功能负荷引起，肌纤维增粗、功能增强。甲状腺功能亢进时的甲状腺增生、高血压病的心脏肥大、慢性增殖性炎扁桃体增大及垂体腺瘤所致肾上腺增生均为病理性肥大"},{"q":"引起儿童期肾病综合征最常见的肾炎类型是","o":["急性弥漫性毛细血管内增生性肾小球肾炎","新月体性肾小球肾炎","弥漫性膜性肾小球肾炎","微小病变性肾小球病","弥漫性膜增生性肾小球肾炎"],"a":3,"e":"儿童期肾病综合征最常见的肾炎类型是微小病变性肾小球病（脂性肾病），以大量蛋白尿、低蛋白血症、水肿和高脂血症为表现，对激素敏感。急性弥漫增生性肾炎多表现为急性肾炎综合征，新月体性为急进性，膜性与膜增生性在儿童相对少见"},{"q":"如图所示，诊断为","o":["脑的卡他性炎","脑的纤维素性炎","脑的浆液性炎","脑表面化脓与积脓","脑脓肿"],"a":3,"e":"本题原题配有图片，图片未随文档保留，以下解析依文字线索推断：题干涉及图片/信息缺失，无法作答。脑表面化脓与积脓指化脓性炎发生于脑膜、脑表面，中性粒细胞向表面渗出并积聚于蛛网膜下腔，形成灰黄色脓性渗出物覆盖脑回。脑脓肿为脑实质内局限性化脓伴组织溶解坏死，形成脓腔；卡他性炎、浆液性炎与纤维素性炎的渗出物性质不同，均不形成表面积脓\n\n官方题库中缺失图片"},{"q":"子宫内膜癌中最常见的类型是","o":["鳞状细胞癌","子宫内膜样腺癌","腺棘皮癌","腺鳞癌","浆液性乳头状癌"],"a":1,"e":"子宫内膜癌绝大多数为子宫内膜样腺癌，与子宫内膜增生及雌激素长期持续作用有关，肥胖、糖尿病、不孕、吸烟为高危因素。浆液性乳头状癌与透明细胞癌少见但侵袭性强、预后差；鳞状细胞癌多来自宫颈；腺棘皮癌、腺鳞癌均属少见亚型"},{"q":"老年人产生萎缩的器官主要是","o":["心、肾","脑、心","肝、肺","心、肺","肾、脑"],"a":1,"e":"老年人器官萎缩以脑、心、肝、肾等为主，其中脑萎缩（脑回变窄、脑沟变宽）与心肌褐色萎缩最为显著。肝、肺，心、肾及心、肺等组合均不如脑、心典型"},{"q":"诊断肿瘤最可靠的方法是","o":["CT检查","X线透视","超声波检查","脱落细胞学检查","活组织检查"],"a":4,"e":"活组织检查取病变组织做病理切片，可直接观察细胞和组织的形态改变，是肿瘤诊断最可靠、最具权威性的方法，也是判定良恶性的最终依据。A项CT、B项X线、C项超声只能显示占位的大小、部位和密度，属影像学定位；D项脱落细胞学检查简便但假阴性率高，可靠性不能等同于活检"},{"q":"脓肿最常见的致病菌是","o":["溶血性链球菌","铜绿假单胞菌","金黄色葡萄球菌","白色葡萄球菌","草绿色链球菌"],"a":2,"e":"金黄色葡萄球菌产生凝血酶使纤维蛋白原转变为纤维蛋白，病灶局限，并具层粘连蛋白受体易在远部形成迁徙性脓肿，是脓肿最常见致病菌。溶血性链球菌透明质酸酶强，多引起蜂窝织炎；铜绿假单胞菌多见于烧伤及院内感染"},{"q":"动脉粥样硬化主要发生在","o":["细、小动脉","大、中动脉","细、小静脉","大、中静脉","毛细血管"],"a":1,"e":"动脉粥样硬化主要累及大、中动脉，如主动脉、冠状动脉、脑动脉和肾动脉，病变始于内膜，形成脂纹、纤维斑块和粥样斑块。A项细、小动脉的病变为玻璃样变和纤维素样坏死，属高血压病改变；C、D项静脉不发生粥样硬化；E项毛细血管只出现透明血栓等微循环改变。弹力型与弹力肌型动脉的中内膜是病变基础"},{"q":"风湿性心内膜炎的后期病变不包括","o":["心内膜下纤维化","腱索增粗和缩短","瓣叶之间发生粘连","心室壁肉柱变扁平","瓣膜增厚、卷曲、缩短及钙化"],"a":0,"e":"风湿性心内膜炎后期以瓣膜增厚、变硬、卷曲、短缩、钙化，瓣叶互相粘连及腱索增粗缩短为特点，最终形成慢性心瓣膜病。心内膜下纤维化见于心内膜心肌纤维化和心内膜下心肌梗死，不属风湿后期改变；心室壁肉柱变扁平亦见于心内膜弥漫纤维化"},{"q":"肝细胞发生广泛变性，点状坏死，符合上述病变特点的是","o":["急性普通型肝炎","轻度慢性肝炎","重度慢性肝炎","重型肝炎","亚急性重型肝炎"],"a":0,"e":"急性普通型肝炎肝细胞广泛水肿变性，坏死轻微，呈点状散在分布于肝小叶内，汇管区少量炎细胞浸润。轻度慢性肝炎为汇管区炎症伴少量碎屑状坏死；重度慢性肝炎坏死广泛并伴纤维化；重型肝炎呈大块或亚大块坏死"},{"q":"属于慢性心包炎改变的是","o":["化脓性心包炎","缩窄性心包炎","出血性心包炎","浆液性心包炎","浆液纤维素性心包炎"],"a":1,"e":"缩窄性心包炎属慢性心包炎，心包纤维化、增厚并与心脏粘连，形成坚硬外壳限制心室舒张，致静脉压升高。化脓性、出血性、浆液性及浆液纤维素性心包炎均属急性渗出性病变，可吸收或转为缩窄"},{"q":"最常见的脑出血原因是","o":["血液病","原发性高血压","血管畸形","血管瘤破裂","脑脓肿"],"a":1,"e":"脑内出血最常见的病因是原发性高血压，细小动脉硬化使管壁变脆，血压骤升时破裂，好发于基底节、内囊，故又称高血压性脑出血。A项血液病、C项血管畸形、D项血管瘤破裂均可致出血但属少见原因。E项脑脓肿破坏血管引起的出血为局部感染并发症，不是群体中最常见病因"},{"q":"一般心肌缺血多长时间内，梗死心肌细胞内的糖原消失","o":["5分钟","8分钟","10分钟","15分钟","30分钟"],"a":4,"e":"心肌梗死后30分钟内，缺血心肌细胞内糖原减少或消失，属早期可逆性改变，PAS染色可显示。A项5分钟、B项8分钟、C项10分钟过短，光镜下尚无明显改变；D项15分钟亦不足以使糖原普遍消失。心肌细胞缺血20～30分钟即发生不可逆损伤"},{"q":"肺石棉沉着症并发的最常见的恶性肿瘤是","o":["喉癌","肺癌","食管癌","胃癌","恶性胸膜间皮瘤"],"a":4,"e":"石棉肺患者并发恶性肿瘤按发生率依次为恶性胸膜间皮瘤、肺癌、食管癌、胃癌和喉癌，50%～80%的恶性胸膜间皮瘤有石棉接触史。肺癌发生率亦显著高于一般人群，但居第二位。喉癌、食管癌与胃癌的发生率更低，故最常见者为恶性胸膜间皮瘤"},{"q":"手术后好发血栓的部位是","o":["下肢静脉","肾动脉","颈静脉","冠状动脉","门静脉"],"a":0,"e":"术后长期卧床、血流缓慢、静脉淤滞及血液高凝状态，使下肢深静脉成为血栓最好发部位。肾动脉、冠状动脉属动脉系统，多在粥样硬化基础上形成动脉血栓；门静脉血栓与肝硬化、腹腔感染相关，均非术后常见"},{"q":"一般不会出现肉芽组织的病变是","o":["结核空洞","脓肿壁","化生病灶","动脉粥样硬化","陈旧性心肌梗死"],"a":2,"e":"肉芽组织常见于慢性炎症、脓肿壁、结核空洞、动脉粥样硬化斑块及陈旧性心肌梗死的机化修复过程。化生是一种成熟上皮或间叶组织被另一种成熟组织替代的适应性改变，不形成肉芽组织，故为该题答案"},{"q":"泌尿系统最常见的恶性肿瘤是","o":["输尿管鳞状细胞癌","Wilms瘤","肾细胞癌","输尿管移行细胞癌","膀胱移行细胞癌"],"a":2,"e":"官方答案为【肾细胞癌】，但依据教材，正确答案为【膀胱移行细胞癌】。肾细胞癌只是肾脏最常见的恶性肿瘤，就整个泌尿系统而言膀胱癌发病率最高，其中绝大多数为移行细胞癌。肾母细胞瘤见于儿童，输尿管移行细胞癌和鳞癌均少见"},{"q":"炎症反应中最有防御作用的是","o":["组织增生","动脉充血","发热反应","吞噬作用","液体渗出"],"a":3,"e":"炎症中最有防御意义的是吞噬作用：中性粒细胞与巨噬细胞吞噬并杀灭病原体，是清除致炎因子的核心环节。组织增生属修复反应；动脉充血与液体渗出利于运送抗体和细胞，但为辅助环节；发热属全身反应"},{"q":"膀胱癌的最常见组织学类型是","o":["肉瘤样癌","鳞状细胞癌","未分化癌","腺癌","移行细胞癌"],"a":4,"e":"膀胱癌组织学类型中尿路上皮癌（移行细胞癌）占90%以上，起源于膀胱黏膜尿路上皮，多呈乳头状生长，术后易复发。鳞状细胞癌约占3%～7%，多与结石、慢性刺激有关；腺癌不足2%；肉瘤样癌与未分化癌均罕见"},{"q":"急性感染性心内膜炎的最常见的病原体是","o":["金黄色葡萄球菌","白假丝酵母菌","肠球菌","溶血性链球菌","草绿色链球菌"],"a":0,"e":"急性感染性心内膜炎最常见的病原体为金黄色葡萄球菌，其次为肺炎链球菌与A群链球菌，赘生物粗大松软、含大量细菌。草绿色链球菌是亚急性感染性心内膜炎的主要致病菌。肠球菌多见于亚急性者及泌尿生殖道操作后。白假丝酵母菌见于真菌性心内膜炎"},{"q":"持续高热易发生变性坏死的脏器主要是","o":["心、肝、胃","心、脾、胃","心、肝、肾","肝、脾、心","胃、肝、脾"],"a":2,"e":"持续高热时代谢旺盛、耗氧增加，心、肝、肾等实质器官对缺氧最敏感，易发生细胞水肿、脂肪变性乃至凝固性坏死。脾以淤血与淋巴组织增生为主，胃黏膜以充血、糜烂为主，均不以变性坏死为突出表现"},{"q":"引起心肌炎最常见的原因是","o":["醉酒","细菌感染","免疫反应","药物中毒","柯萨奇B组病毒"],"a":4,"e":"病毒性心肌炎以柯萨奇B组病毒最常见，其次为柯萨奇A组、埃可病毒和腺病毒，机制包括病毒直接损伤心肌与免疫反应。A项醉酒不属感染性病因；B项细菌感染以白喉杆菌心肌炎为代表，现已少见；C项免疫反应是发病环节而非病因；D项药物中毒属中毒性心肌炎。题干问最常见原因，应落在柯萨奇B组病毒"},{"q":"动脉粥样硬化斑块中泡沫细胞的主要来源是","o":["内皮细胞和巨噬细胞","平滑肌细胞","单核细胞和平滑肌细胞","淋巴细胞和内皮细胞","中性粒细胞和单核细胞"],"a":2,"e":"泡沫细胞由吞噬脂质的巨噬细胞即血中单核细胞迁入内膜后转化而成；中膜平滑肌细胞迁入内膜、表型由收缩型转为合成型后摄取脂质，形成肌源性泡沫细胞，是进展期的主要来源。内皮细胞与淋巴细胞无吞噬脂质能力，中性粒细胞不参与粥样斑块形成"},{"q":"下列哪种疾病无肺透明膜形成","o":["流感病毒肺炎","成人呼吸窘迫综合征","大叶性肺炎","腺病毒肺炎","新生儿呼吸窘迫综合征"],"a":2,"e":"大叶性肺炎为肺泡内纤维蛋白性渗出，肺泡壁毛细血管通透性增高但结构完整，不形成透明膜。新生儿呼吸窘迫综合征因肺表面活性物质缺乏，ARDS及流感病毒、腺病毒肺炎因肺泡上皮弥漫损伤、渗出物机化，均可形成透明膜"},{"q":"成人型呼吸窘迫综合征早期最有诊断意义的病理组织学变化是","o":["部分肺泡萎陷","肺泡壁充血水肿","肺泡腔充满水肿液","透明膜形成","毛细血管内中性粒细胞聚集"],"a":3,"e":"ARDS早期肺泡上皮和毛细血管内皮受损，表面活性物质减少，血浆蛋白渗出并在肺泡内表面浓缩成薄层红染膜状物，即透明膜，是本病最有诊断意义的组织学标志。A项肺泡萎陷、B项肺泡壁充血水肿、C项肺泡腔水肿液早期均可见但特异性差。E项中性粒细胞聚集见于任何急性炎症，不能作为诊断依据"},{"q":"关于亚急性感染性心内膜炎，下列哪项描述是错误的","o":["常引起栓塞","常由草绿色链球菌引起","可在拔牙或尿道手术后发生","常发生在原有病变的心瓣膜上","常在二尖瓣闭锁缘形成单行排列、灰白色、粟粒大小的赘生物"],"a":4,"e":"亚急性感染性心内膜炎的赘生物位于已有病变的瓣膜上，呈息肉状或菜花状，质松脆易脱落，底部有肉芽组织与溃疡，故闭锁缘单行排列、灰白粟粒大是风湿性心内膜炎的疣状赘生物。本病多由草绿色链球菌引起，常发生于拔牙、尿道手术后，栓塞常见"},{"q":"鼻咽癌的好发部位是位于鼻咽的","o":["顶部","前壁","外侧壁","咽隐窝","顶部和侧壁"],"a":0,"e":"鼻咽癌最常发生于鼻咽顶部，其次为外侧壁和咽隐窝，前壁最少见。顶部与侧壁同时受累属两个部位并存，并非好发的单一部位。咽隐窝毗邻咽鼓管咽口，受累较早，易引起耳鸣、听力下降和鼓室积液。鼻咽癌多为低分化鳞癌，与EB病毒感染密切相关，早期即可出现颈淋巴结转移"},{"q":"大叶性肺炎红色肝样变期属于哪一种炎症","o":["出血性炎","纤维素性炎","出血浆液性炎","出血纤维素性炎","出血化脓性炎"],"a":3,"e":"红色肝样变期肺泡壁毛细血管仍扩张充血，肺泡腔内充满纤维蛋白、大量红细胞及少量中性粒细胞和巨噬细胞，兼有纤维素性炎与明显出血，故为出血性纤维素性炎。单纯纤维素性炎以纤维蛋白渗出为主而出血不明显；化脓性炎以中性粒细胞渗出为特点"},{"q":"除下列哪项外均为中晚期食管癌的肉眼类型","o":["髓质型","蕈伞型","平坦型","溃疡型","缩窄型"],"a":2,"e":"中晚期食管癌肉眼分为髓质型、蕈伞型、溃疡型与缩窄型，以髓质型最多见，缩窄型易致梗阻。平坦型属早期食管癌的表浅型，病变限于黏膜及黏膜下层，故不属于中晚期肉眼类型"},{"q":"属于原位癌的是","o":["小肝癌","大肠黏膜下癌","胃黏膜内癌","早期食管癌","乳腺导管原位癌"],"a":2,"e":"官方答案为【胃黏膜内癌】，但依据教材，正确答案为【乳腺导管原位癌】。原位癌指异型细胞累及上皮全层而未突破基底膜，乳腺导管原位癌是典型代表。胃黏膜内癌已侵及黏膜固有层，属早期胃癌；结直肠只有侵及黏膜下层才称癌，黏膜内癌归入高级别上皮内瘤变"},{"q":"非霍奇金淋巴瘤按细胞来源分类，分为","o":["B细胞性和T细胞性","滤泡型和弥漫型","低度和高度恶性","外周型和中枢型","大细胞性和小细胞性"],"a":0,"e":"非霍奇金淋巴瘤按细胞来源分为B细胞性、T细胞性和NK细胞性，其中B细胞性占多数。滤泡型与弥漫型为生长方式分类；低度与高度恶性为分级；外周型与中枢型按发生部位；大细胞性与小细胞性为形态学描述"},{"q":"上皮非典型性增生是指","o":["上皮细胞增生，但极性不丧失","不转移","不浸润上皮下层","上皮细胞异型增生，排列紊乱，极性消失","不会进一步发展为原位癌或浸润癌"],"a":3,"e":"上皮非典型增生指上皮细胞增生并出现异型性，核大深染、核质比增高，排列紊乱、极性丧失，但基底膜完整。病变可进一步发展为原位癌乃至浸润癌。极性不丧失属单纯性增生的特点，不转移、不浸润上皮下层则为原位癌的生物学表现"},{"q":"下列所有情况均符合肺出血肾炎综合征，除外","o":["患者可出现咯血和血尿","患者常死于肺出血和尿毒症","电镜下未发现电子致密物的沉积","免疫荧光显示肾小球内颗粒状IgG沉积","免疫荧光显示肾小球内线状IgG沉积"],"a":3,"e":"肺出血肾炎综合征即Goodpasture综合征，抗GBM抗体与肾小球基膜及肺泡基膜交叉反应，免疫荧光呈特征性线状IgG沉积，电镜下无电子致密物，临床表现为咯血、血尿，常死于肺出血和尿毒症。颗粒状IgG沉积见于免疫复合物介导的肾炎，如急性弥漫性增生性肾炎"},{"q":"哪一型大肠癌多见于青年人，且预后较差","o":["隆起型","溃疡型","浸润型","胶样型","息肉型"],"a":3,"e":"大肠癌的胶样型癌细胞分泌大量黏液，肉眼呈半透明胶冻状，多见于青年人，恶性程度高、预后差。隆起型、溃疡型、浸润型和息肉型多见于中老年，以溃疡型最为多见，预后相对较好。胶样型镜下多为黏液腺癌或印戒细胞癌，间质内可见大量黏液湖"},{"q":"风湿性心内膜炎的特征性病变是","o":["心瓣膜水肿","心瓣膜溃疡、穿孔","心瓣膜混合血栓形成","心瓣膜闭锁缘上疣状血栓形成","心瓣膜增厚变形"],"a":3,"e":"风湿性心内膜炎的特征性病变为瓣膜闭锁缘（心房面）单行排列的疣状赘生物，由血小板和纤维素构成，灰白半透明。瓣膜水肿为早期渗出改变；溃疡、穿孔见于感染性心内膜炎；混合血栓见于心房颤动；瓣膜增厚变形为反复发作后的结局"},{"q":"长管状骨骨折时可能引起的栓塞是","o":["空气栓塞","脂肪栓塞","血栓栓塞","细胞栓塞","细菌栓塞"],"a":1,"e":"长骨骨折时骨髓脂肪细胞破裂，脂滴经破裂的静脉窦进入血流引起脂肪栓塞，栓子多阻塞肺血管。空气栓塞多因静脉损伤后空气进入或环境压力骤降所致。血栓栓塞的栓子来自脱落的血栓。细胞栓塞与细菌栓塞分别见于肿瘤细胞播散和脓毒血症"},{"q":"急性普通型肝炎的病变特点是","o":["肝细胞广泛变性，坏死严重","肝细胞广泛变性，炎细胞浸润明显","肝细胞广泛变性，坏死轻微","肝细胞广泛变性，淤胆明显","肝细胞广泛变性，Kupffer细胞增生活跃"],"a":2,"e":"急性普通型肝炎以肝细胞广泛水肿为主，胞质疏松乃至气球样变，坏死轻微，仅见散在点状坏死，汇管区少量炎细胞浸润。广泛坏死见于重型肝炎；碎屑状坏死伴明显炎细胞浸润见于慢性肝炎；明显淤胆见于淤胆型肝炎"},{"q":"关于毒性甲状腺肿的发病机制，目前认为最可能是","o":["自身免疫反应","食物中含有致甲状腺肿的物质","病毒引起的甲状腺炎症","甲状腺异常增生形成的新生物","土壤和水中缺碘"],"a":0,"e":"毒性弥漫性甲状腺肿（Graves病）目前认为最可能的发病机制是自身免疫反应，患者血清中含促甲状腺激素受体抗体，刺激甲状腺增生及激素分泌。缺碘致单纯性甲状腺肿，致甲状腺肿物质、病毒性甲状腺炎及新生物均非其主要机制"},{"q":"漏出性出血常见的部位是","o":["小静脉","小动脉","大动脉","毛细血管","大静脉"],"a":3,"e":"漏出性出血发生于毛细血管，因管壁通透性增高使红细胞漏出，见于缺氧、感染、中毒及维生素C缺乏。小静脉、小动脉与大静脉出血多为破裂性，由外伤或血管壁破坏引起，出血量较大"},{"q":"淋巴结癌转移时，癌细胞首先出现在","o":["副皮质区","淋巴滤泡中心","淋巴结门部","边缘窦","淋巴结的髓质"],"a":3,"e":"淋巴结转移时瘤细胞经输入淋巴管首先进入被膜下边缘窦，再累及皮质与髓质，使淋巴结肿大变硬，并可突破被膜致相邻淋巴结融合成团。副皮质区为T细胞区，淋巴滤泡中心为B细胞区，均非瘤细胞首先到达处。淋巴结门部为输出淋巴管所在"},{"q":"有关流行性脑脊髓膜炎的描述中，错误的是","o":["皮肤有瘀点和瘀斑","脑膜刺激征","颅内压升高症状","血性脑脊液","脑脊液中糖含量降低"],"a":3,"e":"流行性脑脊髓膜炎为脑膜炎双球菌引起的化脓性炎，脑脊液浑浊、中性粒细胞增多、糖降低、蛋白升高，故血性脑脊液错误。血性脑脊液见于蛛网膜下腔出血；瘀点瘀斑、脑膜刺激征、颅内压升高均为流脑的典型表现"},{"q":"形成神经细胞卫星现象是下列哪一种细胞的增生","o":["小胶质细胞","星形胶质细胞","少突胶质细胞","淋巴细胞","中性粒细胞"],"a":2,"e":"卫星现象指一个神经元周围有5个以上少突胶质细胞围绕，见于神经元受损时，其意义尚不明确。噬神经细胞现象为小胶质细胞或血源性巨噬细胞吞噬坏死神经元。星形胶质细胞增生形成胶质瘢痕。淋巴细胞与中性粒细胞浸润属炎症反应，不构成卫星现象"},{"q":"碎片状坏死发生的部位是","o":["肝小叶中央静脉","肝小叶周边界板区","肝小叶中间区","肾皮质区","肾髓质区"],"a":1,"e":"碎片状坏死发生于肝小叶周边界板处，肝细胞灶性坏死崩解使界板破坏，伴炎症细胞浸润，故又称界面性肝炎，常见于慢性肝炎。点状坏死位于小叶内，为散在的单个或数个肝细胞坏死。小叶中央区坏死见于淤血或缺血。肾皮质与肾髓质与坏死部位无关"},{"q":"原发性肝癌最常见的组织学类型是","o":["未分化癌","胆管上皮癌","肝细胞癌","类癌","混合性肝癌"],"a":2,"e":"原发性肝癌组织学以肝细胞癌最多见，占80%以上，癌细胞似肝细胞、呈梁索状排列，间质为血窦样。胆管细胞癌次之，起自胆管上皮，呈腺管样并伴丰富纤维间质；混合型、未分化癌、类癌均少见。肝细胞癌多伴肝硬化背景、甲胎蛋白常升高；胆管细胞癌多无肝硬化背景，两者鉴别依赖形态与免疫表型"},{"q":"下列哪项不符合病毒性肺炎的特点","o":["常见病因是流感病毒","间质性肺炎","中性粒细胞浸润","检出病毒包涵体","透明膜形成"],"a":2,"e":"病毒性肺炎多由流感病毒等引起，病变为间质性肺炎，肺泡间隔增宽并见淋巴细胞、单核细胞浸润，上皮细胞内可查见病毒包涵体，重症肺泡表面有透明膜形成。渗出细胞以淋巴细胞为主，故中性粒细胞浸润不符合。中性粒细胞浸润是葡萄球菌、链球菌所致化脓性炎的特点，小叶性肺炎亦以中性粒细胞渗出为主"},{"q":"膀胱癌最突出的临床表现是","o":["无痛性血尿","膀胱刺激征","尿路梗阻","蛋白尿和管型尿","腹部肿块"],"a":0,"e":"膀胱癌最突出的症状是无痛性、间歇性血尿，由肿瘤乳头断裂、表面坏死溃疡出血所致，早期可仅为镜下血尿。膀胱刺激征多见于膀胱炎；尿路梗阻见于肿瘤阻塞输尿管口；蛋白尿和管型尿属肾小球疾病表现"},{"q":"肺小细胞癌不会引起","o":["肺性骨关节病","肌无力综合征","类癌综合征","Cushing综合征","甲状腺功能亢进"],"a":4,"e":"肺小细胞癌源于神经内分泌细胞，可异位分泌ACTH致Cushing综合征、分泌5-HT致类癌综合征，并引起肌无力综合征与肺性骨关节病。甲状腺功能亢进由甲状腺激素分泌过多引起，与肺癌异位内分泌无关"},{"q":"肝硬化时蜘蛛痣发生的主要原因是","o":["血管内压增高","雌激素灭活减少","凝血机制障碍","门静脉压增高","低蛋白血症"],"a":1,"e":"肝硬化时肝细胞对雌激素的灭活能力下降，血中雌激素水平升高，使小动脉末梢扩张而形成蜘蛛痣。门静脉压增高引起的是侧支循环开放、脾大与腹水，并不产生蜘蛛痣。凝血机制障碍表现为出血倾向，低蛋白血症导致水肿，血管内压增高则与淤血性改变相关"},{"q":"食管肿瘤在显微镜下如图可见肿瘤细胞排列呈腺样结构，这种肿瘤最可能是","o":["未分化癌","腺癌","鳞癌Ⅰ级","鳞癌Ⅲ级","鳞状上皮乳头状瘤"],"a":1,"e":"本题原题配有图片，图片未随文档保留，以下解析依文字线索推断：题干涉及图片/信息缺失，无法作答。腺癌的癌细胞形成大小不等、形状不规则的腺样结构，细胞异型明显，多见于胃肠道、肺、乳腺。未分化癌无腺管与鳞状分化；鳞癌可见角化珠与细胞间桥；鳞状上皮乳头状瘤为良性，被覆分化良好的鳞状上皮\n\n官方题库中缺失图片"},{"q":"关于肾细胞癌，下列哪项描述是正确的","o":["常在早期即有临床症状","大部分患者因血尿、腰痛和腰部肿块三联症被发现","最常见的组织病理学形态为透明细胞癌","转移少见，发生时也只局限于肾周","肉眼上肿瘤切面实性，灰白色，含少量脂质"],"a":2,"e":"肾细胞癌最常见亚型为透明细胞癌，约占70%~80%，癌细胞胞质透明、富含脂质与糖原，呈巢状排列伴丰富毛细血管网。早期多无症状，出现血尿、腰痛、肿块三联症时多已晚期；转移早且广泛，切面常呈金黄伴出血坏死"},{"q":"来源于三个胚层组织的肿瘤称","o":["癌肉瘤","混合瘤","畸胎瘤","错构瘤","胚胎瘤"],"a":2,"e":"畸胎瘤源于多能生殖细胞，含三个胚层衍生的组织，如皮肤、骨、软骨、腺体、神经。癌肉瘤为癌与肉瘤成分并存于同一肿瘤；混合瘤由两个胚层或同一胚层多种组织构成，如多形性腺瘤；错构瘤为局部组织异常组合、结构紊乱；胚胎瘤指胚胎性恶性肿瘤"},{"q":"金黄色葡萄球菌引起","o":["导管周围乳腺炎","乳腺导管扩张症","脂肪坏死","肉芽肿性乳腺炎","急性乳腺炎"],"a":4,"e":"急性乳腺炎多发生于哺乳期，病原以金黄色葡萄球菌为主，经乳头皲裂侵入，形成化脓性炎甚至脓肿。A项导管周围乳腺炎与棒状杆菌等有关，B项乳腺导管扩张症为非感染性退行性变，C项脂肪坏死为外伤后无菌性改变，D项肉芽肿性乳腺炎属特发性小叶肉芽肿性炎，四者均非金葡菌所致"},{"q":"导致肉眼所见“虎斑心”的形态改变的是心肌细胞发生","o":["淀粉样变性","脂肪变性","脂褐素沉积","细胞水肿","黏液样变性"],"a":1,"e":"虎斑心为心肌脂肪变性：严重贫血、缺氧时心肌脂质代谢障碍，脂肪沿心室壁内层及乳头肌呈黄色条纹，与暗红色心肌相间，状似虎斑。淀粉样变呈灰白蜡样；脂褐素沉积为棕色萎缩；细胞水肿使心肌苍白松软；黏液样变性见于间叶组织肿瘤"},{"q":"下列组织发生的肿瘤不能称为癌的是","o":["肠上皮","血管内皮","肝细胞","胆管上皮","甲状腺腺上皮"],"a":1,"e":"癌是上皮组织来源的恶性肿瘤，血管内皮属间叶组织，其恶性肿瘤称血管肉瘤，不能称癌。肠上皮、胆管上皮、甲状腺腺上皮及肝细胞均为上皮组织，发生的恶性肿瘤分别称肠癌、胆管癌、甲状腺癌和肝细胞癌"},{"q":"引起卵巢krukenberg瘤的是","o":["肝癌","肺癌","胃肠道癌","乳腺癌","子宫颈癌"],"a":2,"e":"Krukenberg瘤多由胃肠道黏液癌侵及浆膜后种植于卵巢，尤其胃印戒细胞癌，也可经淋巴道或血行转移，镜下富于黏液的印戒细胞弥漫浸润，双侧卵巢增大。A项肝癌、B项肺癌、D项乳腺癌、E项子宫颈癌虽可转移至卵巢，但形成的不是这种以印戒细胞为特征的转移性黏液癌"},{"q":"毛细血管内增生性肾小球肾炎的肉眼变化主要呈现","o":["大白肾","大红肾","颗粒性固缩肾","瘢痕肾","多囊肾"],"a":1,"e":"毛细血管内增生性肾小球肾炎（急性肾炎）肾脏充血肿大、被膜紧张、色暗红，称大红肾，表面见出血点时为蚤咬肾。A项大白肾见于膜性肾病等肾病综合征；C项颗粒性固缩肾为高血压肾或慢性肾炎晚期表现，与本病急性充血不符"},{"q":"确定癌的主要依据是","o":["灰白、质硬","瘤细胞呈巢状排列","出现病理性核分裂象","细胞异型性明显","40岁以上中老年人"],"a":1,"e":"癌起源于上皮组织，瘤细胞呈巢状、腺管状或条索状排列，与间质分界较清，是确定癌的主要组织学依据。灰白、质硬的切面外观仅作参考。病理性核分裂象与明显细胞异型性反映恶性程度，肉瘤亦可具备。发病年龄不能用于定性诊断"},{"q":"下列关于乳腺导管内乳头状瘤的描述错误的是","o":["多见于中老年妇女","恶变率极低","乳腺肿物多位于乳晕下","绝大多数是多发性","直径一般小于2cm"],"a":3,"e":"乳腺导管内乳头状瘤多见于中老年妇女，多位于乳晕下大导管，直径常小于2cm，多为单发，恶变率极低，故绝大多数为多发性的说法错误。多发者称乳头状瘤病，需警惕恶变，临床常有乳头溢液"},{"q":"几乎无纤维、血管、间质的肿瘤是","o":["横纹肌肉瘤","肝细胞癌","黑色素瘤","淋巴瘤","绒毛膜癌"],"a":4,"e":"绒毛膜癌由分化不良的滋养层细胞构成，不形成绒毛，也无自身纤维血管间质，瘤细胞直接侵入宿主血管获取血供，故几乎无纤维、血管和间质。横纹肌肉瘤、黑色素瘤、肝细胞癌均有间质与血管；淋巴瘤虽间质少，仍存网状纤维支架"},{"q":"不符合慢性支气管炎咳嗽咳痰的病理基础是","o":["黏膜上皮杯状细胞增多","浆液细胞黏液化","黏液腺增生","管壁充血水肿，炎性渗出","纤毛细胞增生"],"a":4,"e":"慢支咳嗽咳痰的病理基础是黏液腺增生肥大、杯状细胞增多及浆液腺黏液腺化生，黏液分泌增多，管壁充血水肿与炎性渗出亦参与。纤毛细胞不是增生而是变性、坏死、脱落乃至鳞状化生，纤毛清除功能下降"},{"q":"在化脓性炎中，坏死组织的液化分解是由于下列哪一类细胞的浸润所致","o":["巨噬细胞","中性粒细胞","嗜酸性粒细胞","淋巴细胞","浆细胞"],"a":1,"e":"化脓性炎中浸润的中性粒细胞坏死后成为脓细胞，释放大量蛋白溶解酶，使坏死组织液化形成脓液。巨噬细胞主要吞噬清除，嗜酸性粒细胞见于寄生虫与过敏，淋巴细胞、浆细胞参与慢性炎症与免疫反应，均不释放大量蛋白溶解酶"},{"q":"下列属于T细胞性淋巴瘤的恶性肿瘤是","o":["淋巴浆细胞性淋巴瘤","蕈样霉菌病/Sezary综合征","滤泡性淋巴瘤","套细胞淋巴瘤","绿色瘤"],"a":1,"e":"蕈样肉芽肿病是原发于皮肤的成熟T细胞淋巴瘤，Sézary综合征为其变异型，表现为红皮病、淋巴结肿大和外周血出现肿瘤性T细胞。滤泡性淋巴瘤、套细胞淋巴瘤和淋巴浆细胞淋巴瘤均属B细胞肿瘤；绿色瘤为髓系肉瘤"},{"q":"下列关于冠状动脉粥样硬化性心脏病的叙述，哪一项是错误的","o":["左心侧壁的梗死常由左前降支阻塞引起","透壁性心肌梗死的发生机制常与粥样斑块继发血栓形成有关","心内膜下心肌梗死灶常为多发性小灶性","心肌梗死时服用硝酸酯类药物不能缓解疼痛","冠状动脉病变最常见而严重的分支为左前降支"],"a":0,"e":"左心室侧壁由左冠状动脉旋支供血，其梗死由旋支阻塞引起；左前降支阻塞主要引起左心室前壁、心尖及室间隔前2/3梗死，故该项错误。透壁性梗死常由斑块继发血栓形成所致，心内膜下梗死为多发性小灶，冠脉病变以左前降支最重；心梗时硝酸酯类多不能缓解疼痛"},{"q":"下列哪种不是神经系统变性疾病","o":["Alzheimer病","Parkinson病","外伤","慢性进行性舞蹈病","纹状体黑质变性"],"a":2,"e":"神经系统变性疾病指原因不明、以神经元原发性变性为特征的一组疾病，包括Alzheimer病、Parkinson病、慢性进行性舞蹈病和纹状体黑质变性。外伤属外源性物理损伤，引起脑挫伤、颅内出血等，病因与机制明确，不属变性病"},{"q":"下列哪项是急性出血性胰腺炎的表现","o":["胰腺肿大、变硬","腹腔内少量渗出","广泛出血坏死","局限性脂肪坏死","中性粒细胞及单核细胞浸润"],"a":2,"e":"急性出血坏死型胰腺炎以胰腺广泛出血坏死为特征，胰腺肿大质软、呈暗红色无光泽，分叶结构模糊，腹腔可有血性渗出液。局限性脂肪坏死见于急性水肿型胰腺炎，病情轻、预后好，腹腔仅少量渗出。中性粒细胞与单核细胞浸润为一般炎症反应，非本型特征"},{"q":"创伤性脂肪栓塞时，栓塞部位通常是","o":["肝","肾","肺","脑","心"],"a":2,"e":"创伤性脂肪栓塞时脂滴经静脉入右心，随血流首先到达肺，直径大于20μm的栓子阻塞肺动脉分支与毛细血管，故肺为最常见栓塞部位。直径小于20μm的脂滴可通过肺毛细血管进入体循环，阻塞脑、肾等器官血管，但属少数。肝有双重供血，较少受累"},{"q":"有关原发性高血压的叙述，下列错误的是","o":["高血压病常引起左心室肥大","高血压常引起下肢坏疽","高血压可继发糖尿病","高血压晚期的肾脏常为颗粒性固缩肾","脑出血是高血压病的主要致死原因"],"a":2,"e":"原发性高血压因外周阻力增加引起左心室向心性肥大，晚期形成颗粒性固缩肾，脑出血是最主要死因。糖尿病是高血压的常见合并症，可致血压升高，高血压不会继发糖尿病；下肢坏疽主要由动脉粥样硬化闭塞和糖尿病大血管病变引起"},{"q":"胃肠道的恶性肿瘤经血道首先转移到","o":["肺","淋巴结","肝","骨","脑"],"a":2,"e":"胃肠道恶性肿瘤侵入门静脉系统，瘤细胞随门静脉血流首先停留于肝窦，形成肝转移，故肝是最常见的首发血道转移部位。经体循环静脉入右心者先转移至肺，如骨肉瘤的肺转移；淋巴道转移至局部淋巴结，不属血道"},{"q":"乳腺癌中最常见的类型是","o":["小叶原位癌","粉刺癌","浸润性导管癌","浸润性小叶癌","伴髓样特征的癌"],"a":2,"e":"乳腺浸润性癌非特殊型既往称浸润性导管癌，占乳腺癌的大多数，由导管原位癌发展而来。小叶原位癌与粉刺癌属非浸润性癌，后者为导管原位癌的一型。浸润性小叶癌占浸润性癌的少数。伴髓样特征的癌属特殊类型，预后相对较好"},{"q":"下列关于心肌梗死的合并症的描述，哪项是错误的","o":["心脏破裂多见","可引起心源性休克","附壁血栓多见于左心室","室壁瘤较多见","常引起急性充血性心力衰竭"],"a":4,"e":"心肌梗死急性期心室排血量骤降，引起急性左心衰竭甚至心源性休克。充血性心力衰竭指慢性全心衰竭，不是急性心肌梗死的常见合并症。透壁性梗死易并发心脏破裂与室壁瘤，左心室附壁血栓脱落可致体循环栓塞"},{"q":"IgA肾病的超微结构改变主要是","o":["系膜区电子致密物沉积","内皮下电子致密物沉积","上皮下电子致密物沉积","基膜内电子致密物沉积","肾小球内没有电子致密物沉积"],"a":0,"e":"IgA肾病的光镜改变为系膜细胞和系膜基质增生，电镜下电子致密物主要沉积于系膜区，免疫荧光示系膜区IgA呈颗粒状沉积。内皮下沉积见于膜增生性肾小球肾炎Ⅰ型，上皮下沉积为膜性肾小球病的特征，基膜内带状致密物见于膜增生性肾小球肾炎Ⅱ型"},{"q":"手术切口为何选择术后5～7日拆线","o":["伤口内肉芽组织已长满","伤口两侧出现胶原纤维连接","伤口内成肌纤维细胞大量形成","伤口内成纤维细胞增生达高峰","炎症基本消失"],"a":1,"e":"术后第5~7天伤口两侧出现胶原纤维连接，抗张强度增加，切口达临床愈合标准，此时拆线不易裂开。肉芽组织第3天即可填满伤口，成纤维细胞增生高峰与成肌纤维细胞形成均早于胶原连接，故不能作为拆线依据"},{"q":"骨髓瘤起源于","o":["淋巴细胞","浆细胞","粒细胞","单核细胞","造血干细胞"],"a":1,"e":"骨髓瘤起源于浆细胞，瘤细胞表达CD138、CD38而不表达CD19、CD20，特征为全身多发溶骨性病变伴单克隆免疫球蛋白增多。A项淋巴细胞起源的恶性肿瘤为淋巴瘤，C项粒细胞起源者为粒细胞白血病，D项单核细胞起源者为单核细胞白血病。E项造血干细胞虽为共同前体，但骨髓瘤已有明确浆细胞分化，不能笼统归为干细胞肿瘤"},{"q":"伤寒带菌者细菌一般居留于","o":["结肠","胆囊","小肠","肝脏","直肠"],"a":1,"e":"伤寒带菌者细菌主要隐伏于胆囊，在胆汁中繁殖并随粪便排出，是重要传染源，多见于既往患病或隐性感染者。细菌经口入小肠，主要累及回肠下段淋巴组织，结肠、直肠与肝脏不是主要居留部位"},{"q":"下列哪种类型为不累及肺泡的肺气肿","o":["全腺泡型","腺泡中央型","腺泡周围型","不规则型","间质性肺气肿"],"a":4,"e":"间质性肺气肿因肺泡壁破裂，气体进入肺间质（小叶间隔、肺膜下），不累及肺泡腔，故不属肺泡性肺气肿。全腺泡型、腺泡中央型、腺泡周围型、不规则型均累及肺泡，只是受累部位与范围不同。间质性肺气肿气体沿小叶间隔扩散，可进入纵隔与颈部皮下，形成皮下气肿"},{"q":"下述哪种肿瘤的发生可与化生有关","o":["皮肤鳞状细胞癌","肾盂移行细胞癌","肠黏液腺癌","肝胆管上皮癌","肠型胃癌"],"a":4,"e":"慢性萎缩性胃炎伴肠上皮化生，即胃黏膜柱状上皮被含杯状细胞、潘氏细胞的肠型上皮取代，是肠型胃癌的重要癌前病变。皮肤鳞状细胞癌源于表皮角化上皮本身，肾盂移行细胞癌源于尿路上皮，肝胆管上皮癌源于胆管上皮，均非化生所致"},{"q":"慢性轻度肝炎细胞坏死的特点是","o":["点状坏死","灶性坏死","碎片状坏死","大块坏死","溶解性坏死"],"a":0,"e":"慢性轻度肝炎的肝细胞坏死轻微，呈点状或灶状，仅累及单个至数个肝细胞，伴门管区轻度炎症和纤维化。碎片状坏死见于中度以上慢性肝炎，提示界板破坏；大块坏死见于重型肝炎；溶解性坏死是按坏死机制命名的类型，不描述坏死范围"},{"q":"急性弥漫性增生性肾小球肾炎和急性肾盂肾炎患者，尿液检查最大的不同是","o":["红细胞","脱落细胞","纤维素","细菌","蛋白"],"a":3,"e":"急性弥漫性增生性肾小球肾炎为免疫复合物介导的变态反应性炎，尿中可见红细胞、蛋白和管型，但无细菌；急性肾盂肾炎为细菌感染所致的化脓性炎，尿中可查见细菌和白细胞，故细菌是两者最大的不同。A项红细胞两者均可有，B项脱落细胞、E项蛋白在肾炎更突出，均不能区分"},{"q":"关于心肌梗死的描述，下列哪项是错误的","o":["梗死灶形态不规则","病变多属出血性梗死","全层梗死可致心脏破裂","梗死多发生在左心室前壁或心尖部","病变累及心室壁心腔侧1/3称心内膜下梗死"],"a":1,"e":"心肌梗死多属贫血性梗死，因冠状动脉为终末支、侧支循环少，梗死灶呈灰白色。梗死多位于左心室前壁与心尖部；透壁性梗死可致心脏破裂；累及心室壁内层1/3为心内膜下梗死。出血性梗死需严重淤血与双重血供，不符合心肌"},{"q":"风湿性心肌炎会出现以下哪种特征性结构","o":["Osler结节","Negri小体","Aschoff小体","环形红斑","McCallum斑"],"a":2,"e":"风湿性心肌炎的特征性病变是心肌间质内形成Aschoff小体（风湿性肉芽肿），中心纤维素样坏死，周围绕以Anitschkow细胞。A项Osler结节见于感染性心内膜炎；B项Negri小体是狂犬病特征；E项McCallum斑为风湿性心内膜炎左房内膜斑块，D项环形红斑是皮肤表现而非心肌结构"},{"q":"下列哪项病变可发生转移性钙化","o":["结核病时的干酪样坏死","胰腺炎时的脂肪坏死","结缔组织的透明变性","甲状旁腺功能亢进","血吸虫病时的虫卵结节"],"a":3,"e":"转移性钙化由全身钙磷代谢障碍致血钙升高，钙盐沉积于正常组织，见于甲状旁腺功能亢进、维生素D摄入过多及肾衰竭。干酪样坏死、脂肪坏死、透明变性及虫卵结节内的钙化均属营养不良性钙化，发生在坏死或变性组织内，血清钙正常"},{"q":"关于风湿病的论述中，哪一项是错误的是","o":["风湿病是累及全身结缔组织的变态反应性疾病","心脏病变对患者危害最大","风湿性心内膜炎引起的慢性心瓣膜病严重影响心脏功能","风湿性关节炎常可导致关节畸形","皮下结节和环形红斑对临床诊断风湿病有帮助"],"a":3,"e":"风湿性关节炎为浆液性渗出性炎，累及膝、踝、肩、腕等大关节，呈游走性反复发作，炎症消退后不遗留关节畸形，故该项错误。导致关节畸形的是类风湿关节炎，其滑膜增生形成血管翳，破坏关节软骨和关节囊。A项变态反应性结缔组织病、B项心脏受累危害最大、C项慢性瓣膜病影响心功能、E项皮下结节和环形红斑有诊断价值，均正确"},{"q":"脑动脉粥样硬化最常见的部位是","o":["大脑中动脉","大脑前动脉","大脑后动脉","大脑中动脉及Willis环","基底动脉及大脑后动脉"],"a":3,"e":"脑动脉粥样硬化最常见于颈内动脉起始部、基底动脉、大脑中动脉和基底动脉环即Willis环。A项大脑中动脉虽为好发部位之一，表述不全面；B项大脑前动脉、C项大脑后动脉、E项基底动脉及大脑后动脉均只涉及部分血管。Willis环与大脑中动脉是斑块和管腔狭窄最集中的部位"},{"q":"抑制动脉粥样硬化发病的因素是","o":["胆固醇","高密度脂蛋白","低密度脂蛋白","极低密度脂蛋白","β脂蛋白"],"a":1,"e":"HDL将外周组织胆固醇逆向转运至肝，并具抗氧化、保护内皮作用，是抑制动脉粥样硬化发病的因素。LDL、VLDL、β脂蛋白（即LDL）及胆固醇均促进粥样斑块形成。吸烟、高血压、糖尿病、高脂血症则促进斑块形成，与HDL作用相反"},{"q":"肺气肿的病变部位在","o":["肺泡","支气管","呼吸性细支气管以远的肺组织","管径＜2mm的小支气管","终末细支气管"],"a":2,"e":"肺气肿累及末梢肺组织，即呼吸性细支气管、肺泡管、肺泡囊和肺泡，含气量过多伴肺泡间隔破坏。管径小于2mm的小支气管病变属慢性阻塞性细支气管炎。支气管与终末细支气管受累不属肺气肿范围，肺气肿亦不局限于肺泡，还包括呼吸性细支气管等结构"},{"q":"下列哪种疾病最不可能发生结缔组织玻璃样变","o":["结核病的干酪样坏死","纤维型星形胶质细胞瘤","肺硅沉着病","慢性胸膜炎","心肌梗死"],"a":1,"e":"结缔组织玻璃样变以胶原纤维交联、变性、融合为实质，需有胶原存在；星形胶质细胞增生形成胶质瘢痕，不含胶原纤维，机械强度弱，故不发生此种改变。干酪样坏死灶、硅肺纤维化、慢性胸膜炎机化及心肌梗死瘢痕均富含胶原，可发生玻璃样变"},{"q":"脑萎缩的大体特征是","o":["脑沟加深，脑回变窄","脑沟加深，脑回增宽","脑沟变窄，脑回增宽","脑沟变窄，脑回变窄","脑沟变浅，脑回变窄"],"a":0,"e":"脑萎缩时脑实质体积缩小，脑回变窄、脑沟增宽加深，切面见代偿性脑室扩张，以额叶、颞叶、顶叶最显著。脑水肿时脑组织肿胀，脑回变宽、脑沟变窄变浅，与萎缩相反。脑沟变窄伴脑回增宽属水肿或占位表现，脑沟变浅而脑回变窄在形态上不成立"},{"q":"关于急性重型肝炎的病变特点，不正确的是","o":["肝明显缩小，包膜皱缩","肝实质弥漫大块坏死","网状支架塌陷","肝质地柔软","肝细胞再生结节形成"],"a":4,"e":"急性重型肝炎肝体积显著缩小、包膜皱缩、质地柔软，肝实质弥漫性大块坏死，网状支架塌陷，无明显肝细胞再生。肝细胞再生结节是亚急性重型肝炎与肝硬化的表现，不符合急性重型肝炎"},{"q":"诊断肉瘤的主要依据是","o":["青年人","无包膜","肺部转移","异型性大，分裂象","瘤细胞弥漫分布，与间质分界不清"],"a":4,"e":"肉瘤源于间叶组织，瘤细胞多不成巢、弥漫分布，与间质分界不清，间质血管丰富而纤维组织少，故切面呈鱼肉状。异型性大、核分裂象多仅为恶性的一般标志，癌同样具备；无包膜、肺转移亦非肉瘤所特有，癌晚期同样经血行转移至肺"},{"q":"下列关于纤维素性炎症的叙述中，哪项是正确的","o":["合并有少量中性粒细胞浸润时应称为化脓性纤维素性炎","当出现机化以后便引起纤维素性粘连","其好发部位为黏膜、浆膜和肺","假膜的必有成分是纤维素、白细胞、浆膜间皮细胞和细菌","咽部假膜常与其下方的黏膜疏松粘连，易剥脱而引发严重后果"],"a":2,"e":"纤维素性炎以纤维蛋白原渗出形成纤维素为特征，好发于黏膜、浆膜和肺，如白喉假膜、胸膜炎及大叶性肺炎。B项机化后形成的是纤维性粘连而非纤维素性粘连；D项假膜由纤维素、白细胞和坏死黏膜组成，不含浆膜间皮细胞，咽部假膜粘连紧密、强行剥离易出血"},{"q":"下列属于良性肿瘤的是","o":["肾母细胞瘤","精原细胞瘤","髓母细胞瘤","淋巴瘤","葡萄胎"],"a":4,"e":"葡萄胎属良性滋养细胞疾病，病变局限于宫腔，不侵入肌层，多数清宫后可痊愈。A项肾母细胞瘤、B项精原细胞瘤、C项髓母细胞瘤、D项淋巴瘤均为恶性肿瘤，名称中的瘤字不等于良性。葡萄胎有恶变潜能，约10%可转为侵袭性葡萄胎，2%～3%发展为绒毛膜癌"},{"q":"肿瘤对放射治疗和化学治疗的敏感性取决于","o":["是否有变性坏死","是否有包膜","瘤细胞的分化程度","主、间质的比例","发生的部位"],"a":2,"e":"肿瘤对放疗、化疗的敏感性主要取决于瘤细胞的分化程度：分化越低、增殖越活跃，S期细胞比例越高，对射线与药物越敏感。有无变性坏死、有无包膜、发生部位均与敏感性无关；主间质比例影响质地与硬度，不影响敏感性"},{"q":"局灶性节段性肾小球硬化的临床特点是","o":["极少出现血尿和高血压","激素治疗效果好","多表现为肾病综合征","多见于中、老年人","少量蛋白尿"],"a":2,"e":"局灶性节段性肾小球硬化多表现为肾病综合征，镜下或肉眼血尿与高血压亦不少见，激素治疗反应差。本病多见于青少年，男性多于女性，呈慢性进展，可致肾衰竭。少量蛋白尿与激素敏感是微小病变性肾小球病的特点，两者常被混淆"},{"q":"下列哪个病变可能引起大量蛋白尿","o":["肾小球脏层上皮细胞增生","系膜增生","肾小球毛细血管袢粘连","肾小球毛细血管基底膜呈虫蛀状","肾小球内皮细胞增生"],"a":3,"e":"基底膜呈虫蛀状见于膜性肾小球病，免疫复合物使基膜严重损伤、电荷与机械屏障丧失，血浆蛋白大量漏出，产生非选择性蛋白尿。系膜增生、内皮细胞增生与毛细血管袢粘连主要引起血尿和轻度蛋白尿；脏层上皮细胞增生并非本病的典型改变"},{"q":"引起亚急性感染性心内膜炎的常见病原体是","o":["草绿色链球菌","金黄色葡萄球菌","产气荚膜梭状芽孢杆菌","柯萨奇B组病毒","朊病毒"],"a":0,"e":"亚急性感染性心内膜炎多由毒力较弱的草绿色链球菌引起，常发生在原有瓣膜病基础上，病程缓慢。金黄色葡萄球菌多致急性感染性心内膜炎；产气荚膜梭状芽孢杆菌、柯萨奇B组病毒、朊病毒均非本病常见病原体"},{"q":"AIDS患者血液检查减少最明显的是","o":["淋巴细胞","中性粒细胞","巨噬细胞","NK细胞","树突细胞"],"a":0,"e":"AIDS由HIV选择性破坏CD4⁺T淋巴细胞，致淋巴细胞显著减少、免疫功能缺陷，血象减少最明显。中性粒细胞、巨噬细胞、NK细胞及树突细胞虽可受影响，但减少程度与诊断意义均不及淋巴细胞突出"},{"q":"慢性乙型肝炎时出现毛玻璃样肝细胞的原因是","o":["滑面内质网增生，内质网池内有大量HBsAg颗粒","线粒体肿胀","粗面内质网内有大量HBsAg颗粒","核糖体增多","高尔基体复合体内有大量HBsAg颗粒"],"a":0,"e":"慢性乙肝时HBsAg在肝细胞滑面内质网池内大量聚集，光镜见胞质呈毛玻璃样，这是其成因。粗面内质网、高尔基体复合体、核糖体均非HBsAg聚集部位；线粒体肿胀为细胞水肿改变，与毛玻璃样肝细胞形成无关"},{"q":"乳腺癌最常见的组织学类型是","o":["浸润性小叶癌","髓样癌","浸润性导管癌","导管原位癌为主的浸润性导管癌","小管癌"],"a":2,"e":"浸润性导管癌现称浸润性癌非特殊型，占乳腺癌70%，是最常见的组织学类型，癌细胞突破基底膜呈巢状、索状浸润。A项浸润性小叶癌约占10%；B项髓样癌、E项小管癌属特殊类型，比例低；D项导管原位癌属非浸润性癌"},{"q":"干酪样坏死好发于","o":["风湿病","伤寒","结核","麻风","梅毒"],"a":2,"e":"干酪样坏死是结核病的特征性病变，坏死组织呈黄色奶酪样，镜下为无结构红染颗粒。风湿病多为纤维素样坏死；伤寒为单核巨噬细胞增生性炎；麻风、梅毒虽可有类似坏死，但典型干酪样坏死以结核最好发"},{"q":"单核巨噬细胞在局部增生、聚集而形成的结节状病灶称","o":["炎性假瘤","炎性息肉","炎性浸润","肉芽肿","肉芽组织"],"a":3,"e":"肉芽肿是巨噬细胞及其衍生细胞即上皮样细胞和多核巨细胞局限性增生、聚集形成的境界清楚的结节状病灶，属特殊类型的慢性炎症。肉芽组织是新生毛细血管和成纤维细胞构成的修复性组织；炎性假瘤为炎细胞与纤维组织混杂的瘤样病变"},{"q":"NK/T细胞淋巴瘤，常发生部位是","o":["肠道","淋巴结","鼻腔","皮肤","扁桃体"],"a":2,"e":"NK/T细胞淋巴瘤多累及结外部位，鼻腔是典型最好发部位，其次为口腔腭部、鼻咽和鼻窦，表现为顽固性鼻塞、鼻出血和鼻面部肿胀。原发于淋巴结者少见；肠道和皮肤为其他类型结外淋巴瘤的常见部位"},{"q":"容易转移到脊椎的癌是","o":["胃癌","肾癌","前列腺癌","卵巢癌","膀胱癌"],"a":2,"e":"前列腺癌易经吻合支进入脊椎静脉丛，血行转移以脊椎骨最常见，其次为股骨近端、骨盆和肋骨，且可不伴肺转移。胃癌多经门静脉转移至肝；卵巢癌以腹腔种植为主；膀胱癌先转移至盆腔淋巴结。前列腺癌骨转移多为成骨性，血清PSA和酸性磷酸酶升高，可先于肺转移出现"},{"q":"与子宫颈癌发生密切相关的病毒是","o":["单纯疱疹病毒","人乳头瘤病毒","EB病毒","腺病毒","巨细胞病毒"],"a":1,"e":"人乳头瘤病毒HPV-16、18型感染是子宫颈癌最主要的致病因素，其E6、E7蛋白分别结合并灭活p53和Rb，导致细胞周期失控和恶性转化。A项单纯疱疹病毒、C项EB病毒、D项腺病毒、E项巨细胞病毒与宫颈癌关系不明确。HPV-6、11型只引起生殖道乳头状瘤"},{"q":"以下哪类肿瘤不发生转移","o":["高分化癌","原位癌","早期浸润癌","微小癌","霍奇金病"],"a":1,"e":"原位癌局限于上皮层内，未突破基底膜，无间质浸润，因而不发生转移。高分化癌、早期浸润癌（已突破基底膜）、微小癌及霍奇金病均可发生转移"},{"q":"图中的主要成分是","o":["增生的肉芽组织","纤维蛋白沉积","血小板和纤维蛋白","红细胞和纤维蛋白","纤维蛋白"],"a":2,"e":"本题原题配有图片，图片未随文档保留，以下解析依文字线索推断：题干涉及图片/信息缺失，无法作答。血栓头部为白色血栓，由血小板黏集成堆并被纤维蛋白交织而成，肉眼灰白、质实，与血管壁附着紧密。纤维蛋白沉积、红细胞与纤维蛋白构成的是血栓体部或尾部；肉芽组织长入血栓属机化，为血栓的结局而非其成分\n\n官方题库中缺失图片"},{"q":"炎症早期出现炎性充血时，最先累及的血管为","o":["细动脉","小动脉","细静脉","小静脉","毛细血管"],"a":0,"e":"炎症早期致炎因子经轴突反射及血管活性胺作用，首先使细动脉扩张、血流加快，局部氧合血红蛋白增多而呈鲜红色，随后毛细血管和小静脉也扩张。细静脉、小静脉扩张发生于淤血阶段，毛细血管扩张为后续改变，均非最早受累的血管"},{"q":"急性病毒性肝炎时，最常见的炎症细胞是","o":["中性粒细胞","嗜酸性粒细胞","单核细胞","淋巴细胞","浆细胞"],"a":3,"e":"急性病毒性肝炎属变质性炎，浸润的炎症细胞以淋巴细胞为主，也可见单核细胞。中性粒细胞主见细菌感染，嗜酸性粒细胞主见过敏与寄生虫病，浆细胞主见慢性炎症，均非急性病毒性肝炎最常见的炎症细胞"},{"q":"关于慢性肺源性心脏病，下列哪项是错误的","o":["能够导致肺循环阻力增加的疾病可引起慢性肺源性心脏病","慢性支气管炎是最常见的原发疾病","间质性肺炎引起肺间质纤维化可并发慢性肺源性心脏病","慢性肺源性心脏病发生的关键环节是肺动脉高压","右心肥大、扩张是其病变特点"],"a":2,"e":"慢性肺源性心脏病的关键环节是肺动脉高压，凡使肺循环阻力增加的疾病（慢支、肺气肿、肺血管病变）均可致病，右心肥大扩张为形态特点。间质性肺炎指病毒、支原体所致的急性间质性渗出性炎，不引起肺间质纤维化，故该项错误"},{"q":"动脉粥样硬化的继发性病变中最危险的是","o":["钙化","斑块内出血","斑块破裂","动脉瘤形成","粥样瘤性溃疡"],"a":2,"e":"斑块破裂使纤维帽破损，粥样坏死物和脂质入血形成胆固醇栓子，同时胶原暴露激活血小板与凝血，迅速形成血栓阻塞管腔，可致急性心肌梗死或猝死。A项钙化使管壁变硬；B项斑块内出血使斑块迅速增大；D项动脉瘤形成可破裂出血；E项粥样瘤性溃疡是破裂后的结果，危险性低于急性血栓形成"},{"q":"下列描述与浆液性囊腺瘤不相符的是","o":["多为单侧发生","可有乳头状结构","常为多房性生长","囊壁为单层立方上皮","恶变率高"],"a":2,"e":"浆液性囊腺瘤多为单房，囊壁被覆单层立方或柱状上皮，囊内为清亮液体，部分可有乳头状突起，故常为多房性生长不符。多房、囊内含黏液是黏液性囊腺瘤的特点。A项单侧多见、B项可有乳头、D项单层立方上皮均正确。E项浆液性囊腺瘤恶变率低，交界性者才明显升高"},{"q":"较多嗜酸性粒细胞浸润见于","o":["伤寒杆菌感染","变态反应或寄生虫感染","乙型脑炎病毒感染","溶血性链球菌感染","葡萄球菌感染"],"a":1,"e":"嗜酸性粒细胞浸润见于寄生虫感染与IgE介导的过敏反应，其颗粒内主要嗜碱性蛋白对虫体有独特毒性。伤寒杆菌感染引起巨噬细胞增生与伤寒肉芽肿，外周血白细胞反而减少。乙型脑炎病毒以淋巴细胞、单核细胞及小胶质细胞增生为主，葡萄球菌感染则以中性粒细胞渗出为主"},{"q":"诊断肝硬化最可靠的依据是","o":["白球蛋白比值倒置","面部、胸前蜘蛛痣","脾肿大","腹水","肝穿刺活检，镜下见假小叶形成"],"a":4,"e":"诊断肝硬化最可靠的依据是肝穿刺活组织检查见假小叶形成，此为形态学确诊标准。蜘蛛痣、脾大、腹水、白球蛋白比值倒置均为门脉高压与肝功能减退的表现，特异性不足，只能提示而不能确诊。假小叶由纤维组织包绕的肝细胞团构成，中央静脉缺如或偏位，是肝硬化的形态学标志"},{"q":"扩张型心肌病的病变特点是","o":["室间隔不匀称肥厚","不伴有附壁血栓","心肌间质纤维化","心肌细胞不均匀性肥大","心肌细胞数量增多"],"a":2,"e":"扩张型心肌病心脏四腔扩张，镜下心肌细胞肥大与萎缩交错排列，核大深染、胞质空泡变，伴小灶性液化性肌溶解及心肌间质纤维化。室间隔不匀称肥厚、心肌细胞不均匀性肥大是肥厚型心肌病的特点；心肌细胞仅体积改变，数量不增多"},{"q":"慢性胃溃疡最常见的并发症是","o":["出血","穿孔","梗阻","癌变","粘连"],"a":0,"e":"慢性胃溃疡的常见并发症包括出血、穿孔、梗阻和癌变，其中出血最常见，因溃疡底部血管被侵蚀破裂。穿孔、梗阻、癌变发生率较低，粘连不是慢性胃溃疡的主要并发症"},{"q":"下列哪项不是肉芽组织的作用","o":["抗感染保护创面","填补伤口及其他组织缺损","机化血栓","包裹坏死、炎性渗出物及其他异物","能抗牵拉"],"a":4,"e":"肉芽组织的作用为抗感染保护创面、填补组织缺损、机化血栓与坏死渗出物、包裹异物，但其质地脆弱，不具抗牵拉能力。抗牵拉依靠后期胶原沉积形成的瘢痕组织；机化与包裹均为肉芽组织长入并取代无生机物质的过程"},{"q":"炎症时渗出的纤维素是指下列哪种成分","o":["纤维组织","纤维蛋白","纤维细胞","纤维蛋白原","胶原纤维"],"a":1,"e":"纤维素即纤维蛋白，由血浆纤维蛋白原在凝血酶作用下转化并聚合而成，是纤维蛋白性渗出的主体。纤维蛋白原为可溶性前体，尚未聚合；纤维组织与胶原纤维属结缔组织成分；纤维细胞是合成胶原的细胞"},{"q":"痢疾杆菌感染，结肠发生","o":["蜂窝织炎","表面化脓","浆液性炎","假膜性炎","出血性炎"],"a":3,"e":"志贺菌侵入结肠黏膜后释放内毒素，引起黏膜坏死与大量纤维蛋白渗出，形成假膜性炎，假膜脱落后遗留不规则浅表溃疡。蜂窝织炎为疏松结缔组织的弥漫性化脓性炎，表面化脓见于化脓性支气管炎，浆液性炎与出血性炎的渗出成分不同，均非菌痢的病变特点"},{"q":"前列腺癌血行转移的最常见部位是","o":["颅骨","脊椎骨","股骨","盆骨","肋骨"],"a":1,"e":"前列腺癌经血行转移主要至骨，以脊椎骨最常见，其次为股骨近端、骨盆和肋骨，机制与癌细胞经吻合支进入脊椎静脉丛有关，故转移至脊椎时可不伴肺转移。颅骨转移少见，盆骨多属局部浸润或区域扩散，并非血行转移的首位部位"},{"q":"下面关于大叶性肺炎不正确的描述是","o":["肺泡壁毛细血管可扩张、充血","肺泡壁结构通常遭到破坏","肺泡腔内可有大量红细胞、少量中性粒细胞和巨噬细胞","病变常累及肺大叶的全部或大部","主要由肺炎球菌引起的以肺泡内纤维素渗出为主的炎症"],"a":1,"e":"大叶性肺炎为肺泡内的纤维蛋白性炎，肺泡壁毛细血管扩张充血，肺泡腔内充满纤维蛋白、红细胞、中性粒细胞与巨噬细胞，但肺泡壁结构通常完整、不遭破坏，故病变消散后肺组织可完全恢复。累及肺大叶全部或大部、由肺炎链球菌引起均符合其特征；肺泡壁破坏见于小叶性肺炎与肺脓肿"},{"q":"流行性乙型脑炎的病变部位最轻微的是","o":["大脑皮层","脊髓","丘脑","中脑","基底核"],"a":1,"e":"乙型脑炎为变质性炎，病变以大脑皮质、基底节、丘脑最重，脑干次之，脊髓最轻，故临床以高热、意识障碍、抽搐等脑部症状为主。脊髓受累轻微，很少出现典型的脊髓前角运动神经元损害表现；中脑、基底核病变程度均重于脊髓"},{"q":"新月体主要由下列哪种细胞增生形成","o":["系膜细胞","足细胞","内皮细胞","壁层上皮细胞/巨噬细胞","中性粒细胞"],"a":3,"e":"新月体由增生的壁层上皮细胞和渗出的单核细胞（即巨噬细胞）构成，故称壁层上皮细胞/巨噬细胞性新月体，可混有中性粒细胞和淋巴细胞。系膜细胞增生见于系膜增生性肾炎，内皮细胞增生见于急性弥漫性增生性肾炎；足细胞损伤表现为足突融合，不形成新月体"},{"q":"流行性乙型脑炎的主要病变中不包括","o":["脑实质有上皮样细胞小灶形成","脑组织中胶质结节形成","脑小血管周围淋巴细胞“血管套”形成","筛网状软化灶","神经细胞变性坏死"],"a":0,"e":"流行性乙型脑炎的基本病变为神经细胞变性坏死、筛网状软化灶形成、胶质结节增生、血管周围淋巴细胞套及脑膜炎症，不形成上皮样细胞小灶。上皮样细胞结节是结核等肉芽肿性炎的特征。B项胶质结节、C项血管套、D项筛网状软化灶、E项神经细胞变性坏死均为乙脑典型改变"},{"q":"如图，可能的疾病是","o":["急性肾小球肾炎","急进性肾小球肾炎","慢性肾小球肾炎","慢性肾盂肾炎","肾癌"],"a":3,"e":"本题原题配有图片，图片未随文档保留，以下解析依文字线索推断：题干涉及图片/信息缺失，无法作答。慢性肾盂肾炎双肾不对称缩小，表面有不规则、宽大的凹陷性瘢痕，肾盂肾盏纤维化变形，镜下间质慢性炎、纤维化并见甲状腺样管型。慢性肾小球肾炎为双肾对称缩小、弥漫细颗粒；肾癌表现为实性肿块伴出血坏死\n\n官方题库中缺失图片"},{"q":"脑动脉发生栓塞，其栓子最可能来自","o":["下肢浅静脉血栓","下肢深静脉血栓","左心室附壁血栓","肺动脉血栓","下腔静脉血栓"],"a":2,"e":"体循环动脉栓塞的栓子约80%来自左心腔，脑栓塞最常见于心房颤动时的附壁血栓及左心室附壁血栓脱落。下肢深静脉血栓与下腔静脉血栓脱落后经右心进入肺循环，引起肺动脉栓塞；肺动脉内血栓不能逆流进入脑动脉"},{"q":"化脓性炎中，坏死组织的溶解液化是由于下列哪一类细胞存在所致","o":["炎症部位坏死的组织细胞","浸润的巨噬细胞","浸润的浆细胞","浸润的嗜酸性粒细胞","脓细胞"],"a":4,"e":"脓细胞即变性坏死的中性粒细胞，其溶酶体释放蛋白水解酶，使坏死组织溶解液化形成脓液。巨噬细胞、浆细胞、嗜酸性粒细胞虽参与炎症，但液化能力弱；坏死组织自身自溶在化脓性炎中并非主导。故化脓性炎以中性粒细胞浸润为标志，脓液黏稠，呈灰黄或黄绿色"},{"q":"如图，此图的病变属","o":["肥大","化生","萎缩","增生","扩大"],"a":2,"e":"本题原题配有图片，图片未随文档保留，以下解析依文字线索推断：题干涉及图片/信息缺失，无法作答。萎缩指已发育正常的细胞、组织和器官体积缩小、重量减轻、色泽变深，镜下细胞体积变小，胞质内可出现脂褐素。肥大表现为细胞体积增大、器官重量增加。化生是已分化成熟的细胞类型被另一种分化成熟细胞取代，与体积改变无关\n\n官方题库中缺失图片"},{"q":"肺出血肾炎综合征的病理类型为","o":["新月体性肾小球肾炎","微小病变性肾小球病","膜性肾小球肾炎","膜增生性肾小球肾炎","IgA肾病"],"a":0,"e":"肺出血肾炎综合征由抗肾小球基底膜抗体与肺泡基底膜交叉反应引起，肾小球壁层上皮细胞增生形成新月体，属急进性（新月体性）肾小球肾炎，免疫荧光呈线性IgG沉积。微小病变、膜性肾病、膜增生性肾炎和IgA肾病均无抗GBM抗体"},{"q":"见于甲床，直径1cm的紫蓝色结节是","o":["血管球瘤","血管外皮瘤","肉芽组织型血管瘤","上皮样血管内皮瘤","毛细血管瘤"],"a":0,"e":"血管球瘤起源于血管球体的平滑肌样细胞，好发于甲床，呈紫蓝色小结节，直径多小于1cm，触痛显著。血管外皮瘤位于深部软组织；肉芽组织型血管瘤多见于妊娠期牙龈与皮肤；上皮样血管内皮瘤属低度恶性血管肿瘤"},{"q":"胰头癌早期扩散的主要方式是","o":["直接蔓延至胆总管和十二指肠","经门静脉转移到肝","经血行转移至肺","经淋巴道转移至腹腔淋巴结","腹腔内种植性转移"],"a":0,"e":"胰头癌早期即直接浸润胆总管下端及十二指肠，引起阻塞性黄疸和肠梗阻，这是其早期扩散的主要方式。经门静脉转移至肝、血行至肺、淋巴道至腹腔淋巴结及腹膜种植性转移均属较晚期途径。胰体尾癌早期症状隐匿，确诊多偏晚，其扩散以血行至肝、肺及淋巴道为主"},{"q":"Ⅱ型膜性增生性肾小球肾炎的特征性表现，除外","o":["GBM中出现不规则的带状电子密度极高的沉积物","免疫荧光显示肾小球以C3沉积为主","光镜下见肾小球细胞增多，基底膜增厚","银染色显示GBM增厚并分离，呈双轨状","电镜下见内皮下出现致密沉积物，免疫荧光呈颗粒状"],"a":4,"e":"Ⅱ型膜增生性肾炎即致密沉积物病，超微结构特征为基底膜致密层内大量电子密度极高的带状沉积物。免疫荧光以C3沉积为主，通常无IgG及C1q、C4。光镜下系膜细胞增生插入致基底膜增厚，银染色呈双轨状。内皮下沉积伴颗粒状荧光是Ⅰ型的改变"},{"q":"细小动脉壁玻璃样变最常见于下列哪种疾病","o":["急性弥漫性增生性肾小球肾炎","急性肾盂肾炎","快速进行性肾小球肾炎","急进型高血压","缓进型高血压"],"a":4,"e":"细小动脉壁玻璃样变又称细小动脉硬化，因血浆蛋白渗入并沉积于内膜下，使管壁增厚、管腔狭窄，最常见于缓进型高血压和糖尿病的肾、脑、脾细小动脉。急进型高血压表现为细小动脉纤维蛋白样坏死和增生性小动脉硬化；急性肾小球肾炎与肾盂肾炎的病变位于肾小球及间质，不在细小动脉壁"},{"q":"关于炎症的论述，下列正确的是","o":["炎症反应均对机体有利","炎症是一种防御反应","任何有机体均可发生炎症","损伤必然导致炎症","炎症是活体组织的损伤"],"a":1,"e":"炎症是活体组织对损伤因子的防御性反应，以血管反应、渗出和白细胞吞噬为特征，本质是防御。炎症并非对机体均有利，可造成组织破坏；单细胞生物不发生炎症；完全缺血坏死无血管反应，故损伤不一定引起炎症"},{"q":"下肢骨折后，石膏固定，长期不活动，使患肢变细，肌肉萎缩，属于","o":["压迫性萎缩","内分泌性萎缩","营养不良性萎缩","去神经性萎缩","失用性萎缩"],"a":4,"e":"骨折后石膏固定、肢体长期不活动，工作负荷减少使肌肉蛋白质分解增强、肌纤维变细，属失用性萎缩。去神经性萎缩由运动神经元损伤使肌肉失去神经支配所致。压迫性萎缩见于石膏过紧压迫局部组织，营养不良性萎缩则源于慢性消耗与蛋白质缺乏，均与制动无关"},{"q":"Krukenberg瘤的本质是","o":["胃癌","肠癌","卵巢癌","肝癌","肾癌"],"a":0,"e":"Krukenberg瘤为胃癌尤其印戒细胞癌转移至卵巢形成的黏液癌，本质仍为胃癌，多经种植性转移，也可经淋巴道或血行。肠癌、肝癌亦可转移至卵巢但组织形态不同；卵巢原发癌不属转移性肿瘤"},{"q":"细胞因子主要由哪些细胞产生","o":["肥大细胞和血小板","中性粒细胞和嗜酸性粒细胞","淋巴细胞和单核细胞","中性粒细胞和嗜碱性粒细胞","肥大细胞和嗜碱性粒细胞"],"a":2,"e":"细胞因子主要由活化的淋巴细胞和单核巨噬细胞产生，如IL-2、IFN-γ来自T细胞，IL-1、TNF-α来自单核细胞。肥大细胞与嗜碱性粒细胞释放组胺等血管活性胺；中性粒细胞与嗜酸性粒细胞主要释放溶酶体酶和颗粒蛋白"},{"q":"关于病毒性肝炎的肝细胞基本病变，下列选项错误的是","o":["气球样变","细胞质疏松化","嗜酸性变","肝细胞糖原沉积","肝细胞溶解性坏死"],"a":3,"e":"病毒性肝炎的肝细胞基本病变为细胞水肿即胞质疏松化、气球样变，嗜酸性变及嗜酸性小体形成，溶解性坏死和凋亡，糖原沉积不属其基本病变，肝细胞损伤时糖原反而减少。A项气球样变、B项胞质疏松化、C项嗜酸性变、E项溶解性坏死均为典型改变"},{"q":"化脓性炎症的主要特征为","o":["血清渗出","血浆蛋白渗出","中性粒细胞渗出","纤维蛋白渗出","血清渗出、血浆蛋白渗出及纤维蛋白渗出"],"a":2,"e":"化脓性炎以中性粒细胞渗出并伴组织坏死液化、脓液形成为特征。以血清渗出为主者称浆液性炎，见于烧伤水疱与结核性胸膜炎早期。以纤维蛋白渗出为主者称纤维蛋白性炎，见于大叶性肺炎与白喉。血浆蛋白渗出属浆液性渗出的组成部分，不构成独立类型"},{"q":"判断良恶性肿瘤的主要组织学特征是","o":["肿瘤细胞排列紊乱","肿瘤细胞核的异型性","肿瘤细胞的多型性","肿瘤细胞质嗜碱性","肿瘤细胞失去极性"],"a":1,"e":"判断良恶性主要看细胞核的异型性，包括核体积增大、核质比增高、核大小形状不一、染色质粗颗粒状、核仁明显及病理性核分裂象。细胞排列紊乱、失去极性属结构异型性，异型增生亦可出现；细胞多型性与胞质嗜碱性只是异型性的部分表现"},{"q":"下列有关流行性脑脊髓炎的述说错误的是","o":["脑膜刺激征","脑膜充血","颅内压增高","脑脊液浑浊","筛状软化灶"],"a":4,"e":"流行性脑脊髓膜炎为化脓性脑膜炎，脑膜充血、脓性渗出、颅内压增高、脑膜刺激征，脑脊液浑浊。筛状软化灶为乙型脑炎的特征性病变，故该项错误。脑脊液涂片或培养可找到脑膜炎双球菌，皮肤瘀点涂片阳性率亦高"},{"q":"均来源于甲状腺滤泡上皮细胞的肿瘤是","o":["髓样癌、乳头状癌、未分化癌","乳头状癌、滤泡癌、嗜酸细胞型腺瘤","非典型腺瘤、乳头状癌、髓样癌","髓样癌、滤泡癌、滤泡性腺瘤","嗜酸细胞型腺瘤、髓样癌、滤泡癌"],"a":1,"e":"甲状腺滤泡上皮可向滤泡及乳头方向分化，并可发生嗜酸性细胞变，故乳头状癌、滤泡癌和嗜酸细胞型腺瘤均起源于滤泡上皮。髓样癌起源于滤泡旁C细胞，属神经内分泌肿瘤，分泌降钙素而TG阴性；凡含髓样癌的组合均不成立，非典型腺瘤的名称亦不规范"},{"q":"只有一个开口的病理性盲管是","o":["糜烂","溃疡","窦道","瘘管","空洞"],"a":2,"e":"窦道是组织坏死后形成的只开口于皮肤或黏膜表面的深在性盲管，仅有一个开口；瘘管则有两个以上开口，连接两个腔隙或体表。A项糜烂为表皮黏膜的浅表缺损，B项溃疡为较深的组织缺损，E项空洞为坏死物排出后遗留的腔隙，均无盲管结构"},{"q":"与肾病综合征发生最密切相关的肾小球病变是","o":["基膜增厚","中性粒细胞浸润","系膜细胞增生","内皮细胞增生","肾小球硬化"],"a":0,"e":"肾病综合征以大量蛋白尿为特征，其基础是滤过膜损伤、基膜增厚及足细胞足突融合，致蛋白大量漏出。中性粒细胞浸润提示急性渗出性炎；系膜细胞、内皮细胞增生见于急性增生性肾小球肾炎；肾小球硬化见于慢性硬化性肾炎"},{"q":"原发性肝癌是指","o":["胆管上皮发生的癌","肝细胞和肝内胆管上皮发生的癌","肝细胞发生的癌","肝细胞和肝外胆管上皮发生的癌","来自库普弗细胞的恶性肿瘤"],"a":1,"e":"原发性肝癌起源于肝细胞或肝内胆管上皮细胞，组织学分为肝细胞癌、肝内胆管癌和混合型肝细胞癌-胆管癌，其中肝细胞癌占75%～85%。肝外胆管上皮发生的癌属肝外胆管癌，不归入原发性肝癌；库普弗细胞来源的恶性肿瘤极为罕见"},{"q":"不符合子宫内膜癌描述的是","o":["生长较缓慢","多见于年轻女性","主要为淋巴道转移","常引起阴道流血","与雌激素刺激有关"],"a":1,"e":"子宫内膜癌多见于绝经后中老年妇女，与长期雌激素刺激、肥胖、糖尿病、不孕有关，生长相对缓慢，临床主要表现为绝经后阴道流血。转移以淋巴道为主，晚期可血行转移至肺、肝、骨。年轻女性患者仅见于不孕治疗或雌激素不规范使用者，不能作为一般规律"},{"q":"肾盂肾炎最主要的感染途径是","o":["上行性感染","血源性感染","邻近器官炎症的蔓延","医源性感染","多途径感染"],"a":0,"e":"肾盂肾炎主要经上行性感染：细菌由尿道、膀胱、输尿管上行至肾盂肾盏，以大肠杆菌最常见，女性多见。血源性感染多为金黄色葡萄球菌，病变呈双侧多发脓肿；邻近器官蔓延与医源性感染均少见。上行性感染多累及一侧或双侧肾盂肾盏，伴肾乳头坏死与中性粒细胞浸润"},{"q":"液化性坏死好发生于下列哪种器官","o":["脑","心","肝","脾","肺"],"a":0,"e":"脑组织富含水分和磷脂、可凝固的蛋白质少，缺血坏死后水解酶迅速作用，组织溶解液化形成软化灶，故液化性坏死好发于脑。心、肝、脾、肺的缺血性坏死以凝固性坏死为主，坏死组织保持轮廓而质实；脓肿虽也液化，但属化脓性炎的结果，不是器官好发性的答案"},{"q":"下列哪项不属于微小病变性肾小球病的病变特点","o":["又称为脂性肾病","是引起成人肾病综合征的最常见原因","光镜下肾小球基本正常，肾小管上皮有脂质沉积","蛋白尿的主要成分是小分子的白蛋白，属于选择性蛋白尿","皮质类固醇激素治疗大都效果明显"],"a":1,"e":"微小病变性肾小球病多见于儿童，是儿童肾病综合征最常见的原因，成人最常见者为膜性肾小球病，故该项归属错误。光镜下肾小球基本正常、肾小管上皮细胞脂质沉积为本病特点，又称脂性肾病。蛋白尿成分为小分子白蛋白，属选择性蛋白尿，皮质类固醇治疗大都敏感"},{"q":"高血压病脑出血好发的部位是","o":["枕叶","基底节","脑桥","小脑","顶叶"],"a":1,"e":"高血压脑出血最好发于基底节，尤以豆状核区最多见，因豆纹动脉自大脑中动脉呈直角发出，承受较高压力冲击而易破裂。内囊出血常与之并存。脑桥与小脑出血居其次，大脑白质亦可见。枕叶、顶叶并非好发部位，多与淀粉样血管病相关"},{"q":"假小叶的显微镜下的特点不包括","o":["再生的肝细胞结节","增生的纤维组织分隔包绕","小胆管和假胆管增生","肝细胞内嗜酸性小体","慢性炎细胞浸润"],"a":3,"e":"假小叶由增生的纤维组织分割包绕肝细胞团构成，中央静脉缺如、偏位或两个以上，汇管区可被包入，伴小胆管增生及慢性炎细胞浸润。嗜酸性小体是单个肝细胞凋亡的产物，见于病毒性肝炎，不参与假小叶构成"},{"q":"下列变化属于坏死的病理改变的是","o":["细胞体积肿大，细胞质内有红染颗粒","细胞体积缩小，细胞质内有脂褐素颗粒","细胞核膜破裂，染色质崩解为小碎片","细胞核增大，细胞核的DNA含量增加","细胞体积正常或稍大，出现双核"],"a":2,"e":"核碎裂表现为染色质崩解、核膜破裂，核物质分散于胞质，是坏死的典型核改变，常伴核固缩与核溶解。细胞体积肿大、胞质内红染颗粒为细胞水肿；体积缩小伴脂褐素为萎缩；核增大、DNA增多及双核提示再生或异型增生，均不属坏死"},{"q":"肺气肿是指肺内残气增多，持续扩张性病变，主要累及","o":["肺内细小支气管","终末细支气管","左、右支气管","呼吸性细支气管及远端肺组织","局限于肺泡"],"a":3,"e":"肺气肿是末梢肺组织含气量过多伴肺泡间隔破坏，累及呼吸性细支气管、肺泡管、肺泡囊和肺泡。肺内细小支气管与终末细支气管的病变属慢性支气管炎范畴，不构成肺气肿的定义部位。左右支气管为大支气管，病变不累及该处，病变亦不局限于肺泡"},{"q":"下列哪项不属于大叶性肺炎的特征","o":["通常1周后病变消散","受累肺叶通气良好","有时肺发生纤维化","常由肺炎球菌引起","肺泡内充满纤维蛋白性渗出物"],"a":1,"e":"大叶性肺炎时肺泡腔内充满纤维蛋白性渗出物，肺组织实变、通气功能明显下降，故受累肺叶通气良好的说法错误。病变常累及肺大叶全部或大部，多由肺炎链球菌引起，约1周后进入消散期，少数因纤维蛋白溶解不全而机化形成肺肉质变"},{"q":"病理诊断肉瘤的主要依据是","o":["间质稀少","血液供应丰富","有肺转移","瘤细胞呈弥散分布","浸润性生长"],"a":3,"e":"肉瘤起源于间叶组织，瘤细胞多呈弥漫分布、不形成癌巢，与间质分界不清，间质血管丰富。癌的瘤细胞呈巢状、腺管状或条索状排列，间质纤维较多。间质稀少、血供丰富和浸润性生长虽常见于肉瘤，但癌亦可具备，不能作为诊断依据"},{"q":"易并发肺肉质变的肺部疾病是","o":["间质性肺炎","大叶性肺炎","小叶性肺炎","病毒性肺炎","干酪样肺炎"],"a":1,"e":"大叶性肺炎渗出大量纤维蛋白而中性粒细胞偏少时，纤维蛋白不能被蛋白水解酶溶解，由肉芽组织长入机化，形成肺肉质变。小叶性肺炎以化脓性渗出为主；间质性肺炎与病毒性肺炎累及肺泡间隔；干酪样肺炎为结核性坏死"},{"q":"新月体性肾小球肾炎的主要病变是","o":["肾球囊脏层上皮细胞增生","毛细血管壁纤维蛋白样坏死","单核细胞渗出于肾球囊内","中性粒细胞渗出于肾球囊内","肾球囊壁层上皮细胞增生和巨噬细胞增生"],"a":4,"e":"新月体性（急进性）肾小球肾炎的主要病变为肾球囊壁层上皮细胞与渗出的巨噬细胞增生，形成新月体或环形体，压迫毛细血管丛。脏层上皮增生、纤维素样坏死、单核或中性粒细胞渗出均非新月体的主要构成"},{"q":"具有发热作用的炎症介质是","o":["IL-1","C3a","IL-8","C5a","IL-10"],"a":0,"e":"IL-1与TNF、前列腺素是引起发热的主要炎症介质，作用于下丘脑体温调节中枢使调定点上移。C3a和C5a主要增加血管通透性并趋化白细胞；IL-8是趋化性细胞因子；IL-10为抗炎因子，抑制炎症反应"},{"q":"败血症是指","o":["细菌大量入血，血中可查到细菌，但可无中毒症状","细菌毒素入血，引起中毒症状","细菌产物被吸收入血引起中毒症状","细菌入血繁殖并产生毒素从而引起中毒症状，并在一些器官形成脓肿","细菌入血，繁殖并产生毒素，并有中毒症状"],"a":4,"e":"败血症指细菌入血后大量繁殖并产生毒素，引起全身中毒症状及皮肤黏膜出血点、脾和淋巴结肿大。仅血中查到细菌而无中毒症状为菌血症；细菌毒素入血引起症状为毒血症；化脓菌引起败血症并在多个器官形成转移性脓肿则为脓毒败血症"},{"q":"以下哪项病变有助于对尖锐湿疣的诊断","o":["多量角化不全细胞","凹空细胞","表皮棘层肥厚","乳头状瘤样增生","角质层肥厚"],"a":1,"e":"尖锐湿疣由HPV感染引起，表皮浅层出现挖空细胞即凹空细胞，细胞核增大深染、核周胞质空化呈空晕，是诊断依据，原位杂交可检出HPVDNA。角化不全、棘层肥厚与乳头状瘤样增生见于多种疣状增生性病变，特异性不足。角质层肥厚为一般角化过度表现"},{"q":"急性、慢性粒细胞白血病时，在骨内、骨膜下或其他器官内，出现白血病细胞形成的瘤结节，该瘤为","o":["黄色瘤","白色瘤","棕色瘤","绿色瘤","转移瘤"],"a":3,"e":"绿色瘤又称粒细胞肉瘤，为急、慢性粒细胞白血病细胞在骨内、骨膜下或器官形成的瘤结节，因含大量髓过氧化物酶而切面呈绿色。黄色瘤为含脂质的泡沫细胞聚积，棕色瘤见于甲状旁腺功能亢进，转移瘤为他处转移的癌，均非白血病细胞瘤结"},{"q":"关于湿性坏疽的描述，下列不正确的是","o":["常继发于肠、子宫及肺等内脏器官的坏死","坏死组织与周围组织边界不清","常有恶臭味","若发于肢体末端，只有动脉的阻塞","全身中毒症状明显"],"a":3,"e":"湿性坏疽多发生于与外界相通的内脏，需动脉阻塞同时伴静脉回流受阻，坏死组织水分多、腐败菌繁殖旺盛，肿胀呈蓝绿色，与正常组织界限不清，有恶臭和明显中毒症状。仅动脉阻塞而静脉回流尚通畅者发生干性坏疽；气性坏疽由产气荚膜梭菌产生大量气体"},{"q":"左锁骨上淋巴结转移性腺癌的原发部位最可能是","o":["乳腺","甲状腺","食管","胃","肝脏"],"a":3,"e":"左锁骨上淋巴结即Virchow淋巴结收纳胃的淋巴并经胸导管汇入，故该处转移性腺癌的原发灶最可能为胃。乳腺转移至腋窝淋巴结，甲状腺至颈深淋巴结，食管至纵隔淋巴结，肝癌多经血行转移"},{"q":"决定创伤愈合后局部组织抗牵拉的因素是","o":["创伤愈合的时间","创面大小和深度","是否伴有感染","愈合过程中肉芽组织的量","愈合部位胶原的含量"],"a":4,"e":"愈合后的抗牵拉能力取决于瘢痕中胶原的含量与排列，胶原充足、纤维束致密者张力强度高。肉芽组织的量决定缺损填充是否充分；感染和异物使愈合延迟；创面大小和深度决定愈合方式。这些因素影响愈合进程，不直接决定抗张力"},{"q":"脾动脉分支完全阻塞可引起脾的","o":["出血性梗死","脓毒性梗死","液化性坏死","贫血性梗死","坏疽"],"a":3,"e":"脾动脉分支完全阻塞后，脾组织致密、侧支循环不充分，梗死灶内出血少，属贫血性梗死，镜下为凝固性坏死，早期组织轮廓尚保存。出血性梗死需严重淤血和双重血供，见于肺和肠；液化性坏死见于脑；坏疽需合并腐败菌感染"},{"q":"下述组织或器官的体积增大，仅由肥大引起的是","o":["哺乳期的乳腺","功能亢进的甲状腺","健美运动员的骨骼肌","妊娠期的子宫","促肾上腺皮质激素细胞腺瘤患者的肾上腺"],"a":2,"e":"健美运动员骨骼肌增粗仅由肌纤维肥大即细胞体积增大所致，不伴细胞数目增多。哺乳期乳腺、功能亢进的甲状腺、妊娠期子宫、ACTH腺瘤患者的肾上腺均伴细胞增生，属增生或肥大与增生并存。心肌与骨骼肌属永久性细胞，只能肥大不能增生；肝、肾、甲状腺既可肥大也可增生"},{"q":"关于凋亡叙述，下列错误的是","o":["凋亡的发生与基因调节有关","活体内单个细胞或小团细胞的死亡","又称程序性细胞死亡","细胞质膜破裂，核也碎裂","不引起急性炎症反应"],"a":3,"e":"凋亡为活体内单个细胞或小团细胞的死亡，受基因调控，又称程序性细胞死亡，细胞膜保持完整并形成凋亡小体，不引起急性炎症反应。细胞膜与细胞器膜破裂、核碎裂伴自溶是细胞坏死的特征，坏死才引发周围炎症反应，故该项属坏死而非凋亡"},{"q":"右下肢静脉血栓脱落主要栓塞于","o":["肺动脉","下腔静脉","右心房","右心室","右下肢大静脉"],"a":0,"e":"右下肢静脉血栓脱落后随静脉血经下腔静脉、右心房、右心室进入肺动脉，栓塞肺动脉及其分支，引起肺栓塞。下腔静脉与右心腔为血流通道，不构成栓塞部位，因血流方向始终指向肺。栓子小而多时可阻塞肺动脉小分支，引起肺出血性梗死"},{"q":"下列哪种肾脏疾病肾组织免疫荧光检查在肾小球内找不到免疫球蛋白和补体的沉积","o":["弥漫性膜性肾小球肾炎","弥漫性系膜增生性肾小球肾炎","微小病变性肾小球病","弥漫性膜增生性肾小球肾炎","肺出血肾炎综合征"],"a":2,"e":"微小病变性肾小球病的免疫荧光阴性，肾小球内无免疫球蛋白和补体沉积，电镜仅见足突消失。膜性肾病呈颗粒状IgG和C3沉积；膜增生性肾炎有内皮下或系膜区沉积；肺出血肾炎综合征呈线性IgG沉积"},{"q":"青年女性急性乳腺炎的重要病因是","o":["乳腺增生","乳腺发育不良","病毒感染","乳汁淤积伴细菌感染","哺乳次数多"],"a":3,"e":"急性乳腺炎多见于哺乳期初产妇，乳汁淤积为细菌繁殖提供条件，金黄色葡萄球菌经乳头皲裂侵入。乳腺增生、发育不良不构成病因；病毒感染不引起化脓性炎；哺乳次数多本身无害，哺乳不当致淤积才是关键"},{"q":"下列哪项病变不会引起梗死","o":["血管受压","动脉痉挛","血管瘤","血栓形成","栓塞"],"a":2,"e":"血管瘤属血管先天性畸形或良性肿瘤，瘤腔与血流相通，不引起管腔阻塞，故不导致梗死。血管受压（肿瘤压迫、止血带）、动脉痉挛、血栓形成、栓塞均可使动脉腔闭塞、血流中断而形成梗死。梗死是否发生还取决于供血血管类型与侧支循环，肺、肠有双重血供，淤血时多为出血性梗死"},{"q":"下列哪种恶性瘤属于T细胞型淋巴瘤","o":["毛细胞淋巴瘤","蕈样霉菌病","套细胞淋巴瘤","滤泡性淋巴瘤","淋巴母细胞淋巴瘤"],"a":1,"e":"蕈样霉菌病是原发于皮肤的T细胞淋巴瘤，瘤细胞为CD4+辅助性T细胞，早期呈湿疹样皮损，晚期可累及淋巴结和内脏。毛细胞白血病源于B细胞，套细胞淋巴瘤与滤泡性淋巴瘤均为B细胞肿瘤；淋巴母细胞淋巴瘤可源于T或B前体细胞，不具T细胞型特异性"},{"q":"马氏斑（McCllum's patch）位于","o":["左心房","左心室","右心房","右心室","心外膜"],"a":0,"e":"马氏斑是风湿性心内膜炎反复发作时，反流血液冲击左心房后壁心内膜引起的灶状增厚，位于左心房。左心室和右心一般不受累；心外膜病变为风湿性心外膜炎的纤维素性渗出。该处心内膜因长期受反流冲击而纤维性增厚，肉眼呈灰白色斑块，是慢性心瓣膜病的佐证"},{"q":"下列哪项不是活检获取病变组织的方法","o":["纤维支气管镜刷片","局部切除","钳取","细针吸取","搔刮"],"a":0,"e":"活检是切取病变组织行组织学检查，包括局部切除、内镜钳取、搔刮及细针吸取。纤维支气管镜刷片仅收集脱落细胞做涂片，属细胞学检查，不能获得组织结构，故不属活检取材方法。细针吸取可获细胞或组织条，属活检范畴；刷片只取表面脱落细胞，无法判断组织结构"},{"q":"有关氧化氮的描述错误的是","o":["包括一氧化氮和二氧化氮","吸入后与呼吸道中的氧气相互作用","生成硝酸和亚硝酸","可损害呼吸道上皮","哮喘患者对二氧化氮敏感"],"a":1,"e":"氮氧化物包括一氧化氮和二氧化氮，吸入后与呼吸道黏膜表面的水分作用生成硝酸和亚硝酸，损伤呼吸道上皮并增高气道反应性，哮喘患者对二氧化氮更敏感。故与呼吸道中氧气相互作用之说错误，氧气并非其转化介质"},{"q":"下述哪种病变只是由纤维素及血小板组成","o":["亚急性感染性心内膜炎的赘生物","风湿性心内膜炎的赘生物","心肌梗死的附壁血栓","静脉内柱状血栓的体部","静脉内柱状血栓的尾部"],"a":1,"e":"风湿性心内膜炎的赘生物属白色血栓，仅由血小板和纤维蛋白构成，单行附着于瓣膜闭锁缘，质地坚实不易脱落。亚急性感染性心内膜炎赘生物含细菌团、坏死组织与炎细胞；心肌梗死附壁血栓为混合血栓；静脉血栓体部由白色血栓与红色血栓相间构成"},{"q":"下列不符合病毒性肺炎的是","o":["早期表现为间质性肺炎","以中性粒细胞浸润为主","常见病因是流感病毒","部分病例可有透明膜形成","上皮细胞内可见病毒包涵体"],"a":1,"e":"病毒性肺炎早期为间质性肺炎，肺泡间隔内淋巴细胞和单核细胞浸润，上皮细胞内可见病毒包涵体，重症肺泡表面形成透明膜，常见病因为流感病毒。以中性粒细胞浸润为主是细菌性化脓性炎的特点，不符合病毒性肺炎"},{"q":"常发生在肝硬化基础上的肝肿瘤是","o":["肝炎后肝癌","弥漫型肝癌","巨块型肝癌","多结节型肝癌","肝内转移癌"],"a":3,"e":"多结节型肝癌多在肝硬化基础上发生，肝内散在多个大小不等的癌结节，背景见假小叶。肝炎后肝癌按病因命名，不是形态类型；巨块型为单一大块、肝硬化背景较少；弥漫型为细小癌结节弥漫分布，较少见；肝内转移癌属继发性肿瘤"},{"q":"急性弥漫性增生性肾小球肾炎最主要的病变特点是","o":["肾球囊壁层上皮细胞增生","肾小球毛细血管壁纤维素样坏死","肾小球系膜细胞和内皮细胞增生","肾小球毛细血管内血栓形成及基底膜增厚","肾小球内中性粒细胞浸润"],"a":2,"e":"急性弥漫性增生性肾炎的病变特点是弥漫性毛细血管内皮细胞和系膜细胞增生，伴中性粒细胞与巨噬细胞浸润，致肾小球体积增大、缺血。球囊壁层上皮细胞增生形成新月体是急进性肾炎的特征。毛细血管壁纤维素样坏死见于急进型高血压等，并非本病的主要改变"},{"q":"心衰细胞见于","o":["右心衰竭时肺泡腔内","肺水肿时肺泡腔内","脾淤血时脾脏内","左心衰竭时肺泡腔内","肝淤血时肝脏内"],"a":3,"e":"心衰细胞为吞噬含铁血黄素的巨噬细胞，见于左心衰竭所致慢性肺淤血时的肺泡腔内。右心衰竭引起体循环淤血，形成槟榔肝与脾淤血；肺水肿未发生红细胞破坏时无明显含铁血黄素沉积"},{"q":"肝组织呈碎片状坏死或桥接坏死见于","o":["急性重型肝炎","亚急性重症肝炎","慢性持续性肝炎","慢性活动性肝炎","急性普通型肝炎"],"a":3,"e":"碎片状坏死与桥接坏死提示炎症活动度高，见于慢性活动性肝炎即中、重度慢性肝炎，坏死累及界板并向小叶间桥接，易进展为肝硬化。慢性持续性肝炎以门管区炎症为主，无碎片状坏死。急性普通型肝炎为点状坏死。重型肝炎为大片或亚大块坏死"},{"q":"区域性心肌梗死最常发生的部位是","o":["左心室后壁","左心室侧壁","左心室前壁","室间隔后1/3","右心室"],"a":2,"e":"区域性心肌梗死即透壁性心肌梗死，多累及左心室前壁、心尖部及室间隔前2/3，由左前降支供血区缺血所致。左心室后壁与室间隔后1/3由右冠状动脉供血，侧壁由左旋支供血，右心室单独梗死少见"},{"q":"下列哪种慢性风湿性心瓣膜病中不引起肺淤血","o":["二尖瓣狭窄","二尖瓣关闭不全","三尖瓣狭窄","主动脉瓣狭窄","主动脉瓣关闭不全"],"a":2,"e":"三尖瓣狭窄阻碍右心血液进入肺动脉，引起体循环淤血而不影响肺循环，故不引起肺淤血。二尖瓣狭窄与关闭不全、主动脉瓣狭窄与关闭不全均致左房压升高或左心衰，血液淤积于肺，引起肺淤血"},{"q":"肠上皮化生常见于","o":["慢性萎缩性胃炎","急性感染性胃炎","急性刺激性胃炎","疣状胃炎","慢性浅表性胃炎"],"a":0,"e":"肠上皮化生指胃黏膜腺上皮被含杯状细胞的肠型上皮取代，是慢性萎缩性胃炎的标志性改变，常伴腺体减少和黏膜变薄。慢性浅表性胃炎以炎细胞浸润为主，一般无化生；疣状胃炎和急性胃炎分别以疣状病灶、急性渗出为特点"},{"q":"镜影细胞最主要的特点是","o":["为多核瘤巨细胞","细胞大、胞质丰富、呈双色性","有大的嗜酸性核仁","核大、核膜厚、核呈空泡状","双核并列、有大的嗜酸性核仁、如影随形"],"a":4,"e":"镜影细胞为双核并列、形态对称的R-S细胞，两核相向排列如照镜，各含一大而醒目、直径与红细胞相当的嗜酸性核仁，周围有空晕。单核者称霍奇金细胞。胞质双色性与多核瘤巨细胞可见于R-S细胞的变异型，但非镜影细胞的核心特征"},{"q":"下列哪一类型的肝炎易演变为坏死后性肝硬化","o":["急性黄疸性肝炎","急性普通肝炎","慢性活动性肝炎","亚急性重型肝炎","慢性持续性肝炎"],"a":3,"e":"亚急性重型肝炎肝细胞大片坏死，残留肝细胞结节状再生，形成粗大不等的假小叶与宽纤维间隔，是坏死后性肝硬化的典型前身。A项急性黄疸性肝炎、B项急性普通肝炎多可痊愈；E项慢性持续性肝炎进展缓慢，主要演变为门脉性肝硬化，坏死后性少见"},{"q":"关于霍奇金病，有诊断意义的细胞是","o":["类上皮细胞","陷窝细胞","镜影细胞","异物巨细胞","异型性组织细胞"],"a":2,"e":"霍奇金病具有诊断意义的是R-S细胞，典型者为双核、核仁大而嗜酸、呈镜影状排列的镜影细胞。陷窝细胞见于结节硬化型；类上皮细胞见于结核等肉芽肿；异物巨细胞见于异物性肉芽肿；异型组织细胞见于组织细胞肿瘤"},{"q":"下列哪种肿瘤的恶性型归入癌","o":["腺瘤","纤维瘤","脂肪瘤","滑膜瘤","血管瘤"],"a":0,"e":"腺瘤属腺上皮良性肿瘤，其恶性型即腺癌，故恶性型归入癌。B项纤维瘤、C项脂肪瘤、E项血管瘤分别来源于纤维、脂肪和血管组织，恶性型依次为纤维肉瘤、脂肪肉瘤和血管肉瘤，均归入肉瘤。D项滑膜瘤的恶性型为滑膜肉瘤，属软组织肉瘤，与癌的上皮来源不同"},{"q":"梅毒引起的心血管病变主要见于","o":["主动脉","冠状动脉","肾动脉","颈总动脉","肺动脉"],"a":0,"e":"梅毒引起的心血管病变主要累及主动脉，特别是升主动脉和主动脉弓，表现为梅毒性主动脉炎，可致主动脉瓣关闭不全和主动脉瘤。冠状动脉、肺动脉、颈总动脉和肾动脉虽可受累，但病变远不如主动脉常见和典型"},{"q":"大叶性肺炎肉质变是因为","o":["局部组织缺血","纤维素渗出较多","机体抵抗力降低","中性粒细胞数量过少","合并其他细菌感染"],"a":3,"e":"肺肉质变因中性粒细胞数量过少、释放的蛋白水解酶不足，渗出的纤维蛋白不能被溶解而由肉芽组织机化，肺呈肉样实变。纤维素渗出过多、机体抵抗力降低只加重病变程度，局部缺血与合并感染不是直接机制"},{"q":"股静脉内较大的血栓完全机化需要","o":["2天","1周","2周","1个月","2个月"],"a":2,"e":"血栓机化由肉芽组织逐渐取代血栓，较大血栓约2周可完全机化，此时血栓与血管壁紧密黏着不再脱落。形成后1～2天已有内皮细胞和成纤维细胞从管壁长入，2周是完全机化的时间点；1个月以上多进入钙化"},{"q":"心力衰竭细胞最常见于","o":["左心衰竭","右心衰竭","肺水肿","肝淤血","肺炎"],"a":0,"e":"心力衰竭细胞是左心衰竭引起慢性肺淤血时，肺泡腔内巨噬细胞吞噬红细胞并分解出含铁血黄素而形成的褐色细胞，故最常见于左心衰竭。右心衰竭引起体循环淤血和槟榔肝；肺水肿和肺炎不出现含铁血黄素巨噬细胞"},{"q":"恶性腱鞘巨细胞瘤的特征不包括","o":["易浸润周围软组织","瘤细胞以异型的组织细胞样滑膜细胞为主","转移多见，易复发","多位于指和腕关节屈侧","极为罕见"],"a":2,"e":"恶性腱鞘巨细胞瘤极罕见，多位于指、腕关节屈侧，易浸润周围软组织，瘤细胞以异型的组织细胞样滑膜细胞为主，局部复发常见而转移少见，故转移多见的表述不成立。良性者以多核巨细胞及含铁血黄素沉积为特点"},{"q":"下列哪项最符合远隔器官转移瘤的特点","o":["与原发瘤组织学类型不同","在远隔器官内形成单个转移灶","分化程度同原发肿瘤","多个圆形结节，散在分布于脏器边缘，可形成“癌脐”","淋巴道转移的结果"],"a":3,"e":"血行转移瘤多呈多个圆形结节，边界清楚，散在分布于器官表面，中央坏死凹陷形成癌脐。转移瘤组织学类型与原发瘤一致，数目可单可多，淋巴道转移为另一转移途径而非其形态特点"},{"q":"下列哪项符合慢性肺源性心脏病的演进","o":["支气管肺炎→代偿性肺气肿→慢性肺源性心脏病","慢性支气管炎→阻塞性肺气肿→慢性肺源性心脏病","间质性肺炎→间质性肺气肿→慢性肺源性心脏病","大叶性肺炎→肺肉质变→慢性肺源性心脏病","肺癌阻塞、压迫支气管→肺气肿→慢性肺源性心脏病"],"a":1,"e":"慢性支气管炎反复发作，炎症向细支气管周围扩展致管壁增厚、管腔狭窄，形成阻塞性肺气肿，肺毛细血管床减少并伴缺氧性肺小动脉痉挛，肺循环阻力升高，最终导致慢性肺源性心脏病。A项支气管肺炎为急性化脓性炎，D项大叶性肺炎肺肉质变属机化改变，均不演变为肺气肿。E项肺癌压迫所致肺气肿为局限性，不是肺心病的主要途径"},{"q":"肺癌的早期诊断中最有价值的检查是","o":["早期症状的发现","纤维支气管镜活检","X线检查","CT检查","血液检查"],"a":1,"e":"纤维支气管镜可直接观察段以上支气管的病变并取活组织做病理检查，对中央型肺癌早期诊断价值最高。A项早期症状缺乏特异性；C项X线、D项CT只能发现阴影，不能定性；E项血液检查无特异性标志。痰脱落细胞学检查可辅助普查，阳性率低于活检"},{"q":"低度恶性的上皮性肿瘤是","o":["浆液性囊腺瘤","黏液性囊腺瘤","浆液性囊腺癌","黏液性囊腺癌","交界性浆液性囊腺瘤"],"a":4,"e":"交界性浆液性囊腺瘤属交界性肿瘤，上皮增生活跃、异型性明显但无间质浸润，介于良恶性之间，为低度恶性。浆液性与黏液性囊腺瘤为良性；浆液性囊腺癌、黏液性囊腺癌侵袭性强，属明确恶性，不属低度恶性"},{"q":"下列哪项不是真性肿瘤","o":["白血病","动脉瘤","蕈样肉芽肿","霍奇金淋巴瘤","鲍温病"],"a":1,"e":"动脉瘤是动脉壁局部薄弱或结构破坏后向外膨出形成的永久性局限性扩张，属血管病变而非肿瘤。白血病、霍奇金淋巴瘤、蕈样肉芽肿和鲍温病均为真性肿瘤，分别属造血系统肿瘤、淋巴瘤和表皮原位癌"},{"q":"急性左心衰竭时常引起","o":["肺水肿","眼睑水肿","脑水肿","下肢水肿","心包积液"],"a":0,"e":"急性左心衰竭时肺静脉压骤升，肺毛细血管滤过压增高，液体渗入肺间质与肺泡，形成急性肺水肿，表现为端坐呼吸、咳粉红色泡沫痰。眼睑水肿与下肢水肿见于右心衰竭，心包积液不是其直接结果"},{"q":"下列最符合鳞状细胞癌的特征的是","o":["发生于原有单层扁平上皮的覆盖部位","呈外生性生长","癌细胞的排列及形态仍保留单层扁平上皮的某些特征","癌珠形成","主要经淋巴道转移"],"a":2,"e":"鳞状细胞癌由鳞状上皮恶变而成，癌细胞排列及形态保留复层鳞状上皮的分层、角化等特征。发生于单层扁平上皮覆盖处并非鳞癌起源；外生性生长非特异；癌珠仅见于高分化鳞癌，不能概括全部；主要经淋巴道转移亦非其最具特征之处"},{"q":"腺上皮鳞化后发生恶性变，所形成的恶性肿瘤称为","o":["腺癌","腺棘皮癌","腺鳞癌","鳞状细胞癌","低分化腺癌"],"a":3,"e":"腺上皮发生鳞状上皮化生后恶变，肿瘤完全由鳞状细胞构成，故称鳞状细胞癌。A项腺癌是腺上皮直接恶变、仍形成腺样结构者。C项腺鳞癌须同时具有腺癌和鳞癌两种成分，本例只有鳞化后的单一成分。B项腺棘皮癌为腺癌组织中含良性鳞状上皮团，鳞状成分并不恶变；E项低分化腺癌仍属腺上皮来源"},{"q":"在门脉性肝硬化与坏死后肝硬化病变的区别中，不包括","o":["假小叶的大小","纤维间隔的厚薄","炎细胞浸润的轻重","肝内小血管改建的有无","肝细胞坏死的多少"],"a":3,"e":"门脉性肝硬化与坏死后性肝硬化的区别在于假小叶大小、纤维间隔厚薄、炎细胞浸润轻重和肝细胞坏死多少：前者结节小、间隔细而均匀，后者结节大、间隔宽窄不一、坏死较重。两者均有肝内血管改建，故此项不能用于鉴别"},{"q":"关于高血压小动脉的病变叙述中，下列错误的是","o":["中膜平滑肌细胞肥大和增生","膜内胶原和弹性纤维增多","内膜弹性纤维增多","内膜内血浆蛋白渗入，发生玻璃样变","内弹力膜分裂"],"a":3,"e":"良性高血压小动脉硬化表现为中膜平滑肌细胞肥大增生、内膜胶原与弹性纤维增多、内弹力膜分裂，管壁增厚、管腔狭窄。内膜血浆蛋白渗入致玻璃样变是细动脉（肾入球动脉、视网膜动脉）的病变，部位不同，故该项所述不属小动脉改变"},{"q":"与硅肺发病关系最密切的细胞是","o":["成纤维细胞","中性粒细胞","巨噬细胞","CD4+T细胞","B细胞"],"a":2,"e":"硅肺发病的关键是肺泡巨噬细胞吞噬硅尘后崩解，释放硅尘与IL-1、TNF等细胞因子，刺激成纤维细胞增生并合成胶原，形成硅结节和肺纤维化。中性粒细胞仅参与早期炎症；CD4+T细胞、B细胞与本病关系较小；成纤维细胞是效应细胞而非始动细胞"},{"q":"毛玻璃样肝细胞可见于","o":["急性普通型肝炎","慢性普通型肝炎","急性重型肝炎","亚急性重型肝炎","酒精性肝病"],"a":1,"e":"毛玻璃样肝细胞见于HBsAg携带者和慢性肝炎患者，尤以慢性普通型肝炎多见，胞质内充满HBsAg细颗粒，电镜下为滑面内质网池内大量HBsAg。急性普通型肝炎以气球样变、点状坏死为主；急性和亚急性重型肝炎以大片坏死为主；酒精性肝病的特征为Mallory小体"},{"q":"如图，卵巢黏液性囊腺瘤的特点是","o":["细胞有明显异型性","无黏液分泌","囊壁内衬单层立方上皮","囊壁内衬单层高柱状上皮","乳头分支多而复杂，细胞层次增多，超过3层以上"],"a":3,"e":"本题原题配有图片，图片未随文档保留，以下解析依文字线索推断：题干涉及图片/信息缺失，无法作答。卵巢黏液性囊腺瘤囊壁与囊内衬单层高柱状黏液上皮，核位于基底、无明显异型，间质纤维少。细胞异型明显、无黏液分泌、乳头分支复杂或上皮层次超过3层，均提示交界性肿瘤或黏液性囊腺癌\n\n官方题库中缺失图片"},{"q":"关于淋巴瘤的叙述，错误的是","o":["青少年多见，是儿童最常见的恶性肿瘤之一","肉眼呈结节状，可有假包膜，切面呈“鱼肉样”","是原发于淋巴结和结外淋巴组织的恶性肿瘤","分为霍奇金病、非霍奇金病和白血病三大类型","淋巴组织结构破坏，瘤细胞弥漫分布，瘤细胞间可有网状纤维穿插包绕"],"a":3,"e":"淋巴瘤分霍奇金淋巴瘤与非霍奇金淋巴瘤两大类，白血病属造血系统肿瘤，与淋巴瘤并列而不属其分类，故该项错误。淋巴瘤原发于淋巴结和结外淋巴组织，青少年多见，肉眼呈结节状、切面鱼肉样。镜下淋巴结结构破坏，瘤细胞弥漫分布，网状纤维穿插其间"},{"q":"脓肿时病变局限在局部主要是由于","o":["细菌的毒素","血浆凝固酶的作用","中性粒细胞的浸润","脓液的黏稠度大","脓肿膜的形成"],"a":1,"e":"金黄色葡萄球菌产生血浆凝固酶，使渗出的纤维蛋白原转变为纤维蛋白，在病灶周围形成纤维蛋白屏障，限制细菌蔓延，故脓肿多局限。脓肿膜是局限后的结果；链球菌的透明质酸酶和链激酶降解基质、溶解纤维蛋白，导致蜂窝织炎扩散"},{"q":"下列可确诊支气管扩张症的是","o":["肺实变体征","咳大量脓痰","反复咯血","肺部湿啰音","支气管碘油造影"],"a":4,"e":"支气管碘油造影可显示支气管囊状或柱状扩张，是确诊支气管扩张症的依据。肺实变体征、咳大量脓痰、反复咯血、肺部湿啰音均为临床表现，可提示诊断但不能确诊"},{"q":"慢性肝淤血肉眼观如图所示，关于其形态特征说法不正确的是","o":["色暗红，体积增大，切面湿润","色灰白，体积缩小，切面干燥","重量增加，质地变硬","切面可见红黄相间的条纹","又称槟榔肝"],"a":1,"e":"本题原题配有图片，图片未随文档保留，以下解析依文字线索推断：题干涉及图片/信息缺失，无法作答。慢性肝淤血时肝体积增大、重量增加、色暗红、切面湿润，因小叶中央淤血与周边肝细胞脂肪变并存，切面呈红黄相间条纹，故称槟榔肝。色灰白、体积缩小、切面干燥是器官萎缩的表现，与淤血相反\n\n官方题库中缺失图片"},{"q":"以“满天星”图像为病变特点的疾病是","o":["皮肤T细胞型淋巴瘤","淋巴母细胞性淋巴瘤","组织细胞型淋巴瘤","Burkitt淋巴瘤","霍奇金病"],"a":3,"e":"Burkitt淋巴瘤镜下见弥漫增生的肿瘤细胞间散在吞噬细胞碎片的巨噬细胞，形成“满天星”图像。皮肤T细胞型淋巴瘤、淋巴母细胞性淋巴瘤、组织细胞型淋巴瘤及霍奇金病均无此典型图像"},{"q":"流行性乙型脑炎的噬神经细胞现象是由（ ）侵入神经细胞内产生的","o":["巨噬细胞","小胶质细胞","淋巴细胞","巨噬细胞和小胶质细胞","小胶质细胞和淋巴细胞"],"a":3,"e":"乙脑时变性坏死的神经元被小胶质细胞和侵入的巨噬细胞包围、吞噬，形成噬神经细胞现象。单纯巨噬细胞或小胶质细胞表述均不全面，淋巴细胞不参与噬神经过程，故为巨噬细胞和小胶质细胞共同作用"},{"q":"流行性脑脊髓膜炎的传染途径主要是通过","o":["呼吸道","皮肤","泌尿道","蚊子叮咬后经血","消化道"],"a":0,"e":"流脑经呼吸道传播，脑膜炎双球菌借飞沫由鼻咽部侵入，冬春季引起流行。皮肤传播见于钩端螺旋体病；泌尿道和消化道不是其传播途径；蚊媒传播见于乙型脑炎、疟疾等。患者和带菌者为传染源，病原体在鼻咽部繁殖后入血形成菌血症，再侵犯脑脊髓膜"},{"q":"甲状腺乳头状癌的核特征不包括","o":["磨玻璃核","核大深染、染色质粗糙、明显核仁","核沟","核内包涵体","细胞核拥挤重叠"],"a":1,"e":"甲状腺乳头状癌的核特征包括核透明呈磨玻璃样、核沟、核内假包涵体和核拥挤重叠，是诊断的关键依据。核大深染、染色质粗糙伴明显核仁是滤泡癌与未分化癌的异型表现，乳头状癌的核反而淡染透明，故该项不属其特征"},{"q":"严重肝实质疾病引起出血的原因是","o":["凝血因子消耗过多","凝血因子合成减少","红细胞破坏","血小板生成减少","凝血因子无功能"],"a":1,"e":"肝脏是合成凝血因子的主要场所，可合成纤维蛋白原、凝血酶原及因子Ⅴ、Ⅶ、Ⅸ、Ⅹ等，严重肝实质疾病时凝血因子合成减少而致出血。凝血因子消耗过多见于DIC，红细胞破坏致溶血性贫血，血小板生成减少源于骨髓病变，凝血因子无功能见于异常蛋白血症"},{"q":"下列关于Crohn病的描述，哪一项是错误的","o":["病变主要累积回肠末端","可引起肠穿孔及瘘管形成","病变呈节段性","溃疡呈地图状","常见非干酪样肉芽肿"],"a":3,"e":"克罗恩病溃疡为纵行裂隙状，沿肠管长轴分布，黏膜呈铺路石样，病变节段性分布于回肠末端，可致肠穿孔与瘘管形成，镜下常见非干酪样肉芽肿。地图状溃疡是细菌性痢疾假膜脱落后的特征，故该项描述错误"},{"q":"肠阿米巴病引起的最常见的并发症为","o":["肺脓肿","心包炎","脑脓肿","脓胸","肝脓肿"],"a":4,"e":"肠阿米巴病的滋养体侵入肠壁小静脉，经门静脉入肝，形成阿米巴肝脓肿，是肠阿米巴病最常见的并发症，多位于肝右叶，脓液呈咖啡色。肺脓肿多由肝脓肿穿膈直接蔓延而来，脑脓肿、脓胸、心包炎均少见，不属最常见者"},{"q":"下列组织对缺氧的耐受性依次为","o":["脑＞肝＞肾","肾＞肝＞脑","肝＞脑＞肾","肝＞肾＞脑","肾＞脑＞肝"],"a":1,"e":"各器官对缺氧的耐受性差别很大，肾小管上皮耐受性较强，肝细胞次之，神经元最敏感，缺血数分钟即发生不可逆损伤。心肌细胞缺血20～30分钟即死亡。骨骼肌与纤维结缔组织耐受性最强，故由高到低为肾、肝、脑"},{"q":"高血压失代偿期心脏变为","o":["左心室向心性肥大","左心室明显扩张","左心室乳头肌明显增粗","左心室心肌收缩力加强","心肌出现弥漫性纤维化"],"a":1,"e":"高血压失代偿期左心室由向心性肥大转为离心性肥大，心腔明显扩张，室壁相对变薄，收缩力下降并出现心力衰竭。向心性肥大、乳头肌增粗、收缩力增强见于代偿期；弥漫性纤维化见于心肌病与慢性缺血"},{"q":"急性重型肝炎肝细胞常见而普遍的病变是","o":["坏死","变性","再生","萎缩","化生"],"a":0,"e":"急性重型肝炎以肝细胞严重而广泛的大块坏死为特征，坏死自小叶中央迅速扩展至周边，仅小叶周边残留少许变性肝细胞，故肝体积显著缩小。再生不明显，因病程短且网状支架塌陷。变性属早期较轻改变，萎缩与化生不属本型的主要病变"},{"q":"流式细胞技术样本单细胞悬液的细胞数不应少于","o":["5个","10个","25个","20个","15个"],"a":1,"e":"本题原题配有图片，图片未随文档保留，以下解析依文字线索推断：题干涉及图片/信息缺失，无法作答。流式细胞术要求单细胞悬液有足够细胞，一般不少于10⁴个，方能使采集事件数满足统计要求；细胞过少则结果波动大、不可靠。此项数值的计数单位缺失，5、15、20、25更无法对应任何标准界值\n\n官方题库中缺失图片"},{"q":"子宫颈早期浸润癌是指","o":["癌细胞未突破基膜","癌细胞突破基膜，浸润深度不超过基膜下5mm","癌细胞突破基膜，浸润深度不超过基膜下7mm","癌细胞未突破基膜，但已累及腺体","癌细胞突破基底膜，但未累及腺体"],"a":1,"e":"早期浸润癌指癌细胞突破基底膜侵入固有层间质，但浸润深度不超过基底膜下5mm，肉眼难以判断，仅在镜下确诊。癌细胞未突破基底膜者为原位癌；浸润深度超过5mm者为浸润癌；累及腺体而基膜完整者仍属原位癌累及腺体"},{"q":"减压病的栓塞是","o":["血栓栓塞","羊水栓塞","气体栓塞","脂肪栓塞","虫卵栓塞"],"a":2,"e":"减压病时原溶于血液和组织液的气体在低压环境下迅速游离成气泡阻塞血管，属气体栓塞。脂肪栓塞源于长骨骨折或脂肪组织严重挫伤后脂滴入血。血栓栓塞的栓子来自脱落的血栓，羊水栓塞发生于分娩过程中羊水进入母体血循环，虫卵栓塞见于血吸虫病"},{"q":"伤寒的病变特点除外","o":["脾肿大","病灶中较多中性粒细胞浸润","伤寒肉芽肿形成","回肠下段集合和孤立淋巴小结肿大","皮肤玫瑰疹"],"a":1,"e":"伤寒为巨噬细胞介导的增生性炎，病灶内为伤寒细胞构成的伤寒肉芽肿，中性粒细胞极少。回肠下段集合与孤立淋巴小结肿大坏死并形成溃疡，脾脏肿大、皮肤玫瑰疹及肝脾髓样肿胀均为典型表现"},{"q":"下列哪种细胞属于永久性细胞","o":["表皮细胞","心肌细胞","肾小管上皮细胞","肝细胞","造血细胞"],"a":1,"e":"心肌细胞、骨骼肌细胞和神经细胞属永久性细胞，出生后不能分裂增生，损伤后只能由瘢痕修复。表皮细胞和造血细胞属不稳定细胞，再生能力强；肝细胞和肾小管上皮细胞属稳定细胞，受损后可增生修复"},{"q":"关于子宫平滑肌瘤的叙述，下列哪项错误","o":["女性生殖系统中最常见的肿瘤","肿瘤境界清楚，但常无包膜","可发生黏液变性","常发生恶变","瘤组织呈编织状排列"],"a":3,"e":"子宫平滑肌瘤是女性生殖系统最常见的良性肿瘤，切面灰白、呈编织状，境界清楚但无包膜，可发生玻璃样变、黏液变性及红色变性。恶变率不足0.5%，故常发生恶变的说法错误。肌瘤可单发或多发，多发者使子宫增大变形；红色变性多见于妊娠期或产褥期"},{"q":"尿路梗阻或尿液排泄不畅所致的肾盂积水，肾实质发生的病变为","o":["营养不良性萎缩","神经性萎缩","失用性萎缩","压迫性萎缩","内分泌性萎缩"],"a":3,"e":"尿路梗阻致肾盂积水，肾盂内压升高并长期压迫周围肾组织，使其缺血缺氧，肾皮质和髓质萎缩变薄，属压迫性萎缩。失用性萎缩见于肢体固定；营养不良性萎缩见于慢性消耗；神经性萎缩见于神经损伤后；内分泌性萎缩见于靶腺失去促激素刺激"},{"q":"肺孢子虫病较为特征的组织病理学改变是肺泡内出现大量的","o":["红细胞","淋巴细胞","水肿液","泡沫样渗出物","中性粒细胞"],"a":3,"e":"肺孢子虫病肺泡腔内充满泡沫样渗出物，由肺泡巨噬细胞、浆细胞、纤维蛋白及成团的肺孢子菌构成，呈伊红染细泡沫状，为特征性改变。淋巴细胞浸润见于病毒性肺炎，中性粒细胞浸润提示细菌感染，水肿液见于肺水肿，红细胞增多见于出血性炎"},{"q":"大叶性肺炎的病理变化，除外","o":["肺组织大面积广泛实变","肺泡性炎","以纤维素渗出为主","可合并肺肉质变","常有肺泡壁结构破坏"],"a":4,"e":"大叶性肺炎为肺泡内纤维蛋白性炎，肺泡壁结构完整不被破坏，故消散后肺组织可完全恢复正常。肺组织大片实变、以纤维素渗出为主、可合并肺肉质变均符合；肺泡壁破坏见于小叶性肺炎"},{"q":"肝细胞弥漫性水样变性主要见于","o":["急性重型肝炎","亚急性重型肝炎","慢性持续性肝炎","急性普通型肝炎","淤胆型肝炎"],"a":3,"e":"急性普通型肝炎以肝细胞弥漫性水样变性即气球样变为最常见、最突出的病变，伴嗜酸性变与点状坏死。急性重型肝炎以大片坏死为主，肝细胞大量消失。亚急性重型肝炎为亚大块坏死伴结节状再生。慢性持续性肝炎病变轻而局限，淤胆型肝炎以胆汁淤积为特征"},{"q":"慢性阻塞性肺病最常见于","o":["支气管哮喘","支气管扩张","肺脓肿","肺结核球","慢性支气管炎"],"a":4,"e":"慢性阻塞性肺疾病以慢性支气管炎和肺气肿最常见，长期吸烟致小气道慢性炎症、黏液腺增生、管腔狭窄及弹性回缩力下降。支气管哮喘为可逆性发作性痉挛，支气管扩张为管壁破坏后的永久性扩张，均不属慢阻肺主体"},{"q":"甲状腺滤泡性腺瘤和滤泡癌的鉴别诊断最重要的是","o":["滤泡大小","被膜是否受侵犯","是否有包膜和血管侵犯","淋巴结是否有转移","远处器官是否有转移"],"a":2,"e":"滤泡性腺瘤与滤泡癌的组织结构可十分相似，鉴别关键是包膜是否被肿瘤穿透及有无血管侵犯，出现包膜浸润或血管内癌栓即为癌。滤泡大小、有无包膜本身无鉴别意义；淋巴结与远处转移出现时已属晚期，不能用于早期鉴别"},{"q":"冰冻切片时下列哪种组织需要厚切片","o":["骨髓","淋巴","肌肉","脂肪","纤维"],"a":3,"e":"脂肪组织质地软、缺乏支持结构，冰冻时难以切薄，需较厚切片方能保持完整。骨髓含脂肪与骨小梁，淋巴组织细胞密集，肌肉与纤维组织富含纤维成分，均可切得较薄。故冰冻切片需厚切者为脂肪组织"},{"q":"肿瘤的生长速度主要取决于","o":["肿瘤是良性还是恶性","肿瘤细胞的生长分数和肿瘤细胞的生成与丢失之比","肿瘤所处部位是否有足够的生长空间","肿瘤间质血管是否丰富","机体的免疫状态"],"a":1,"e":"肿瘤生长速度取决于生长分数、倍增时间及瘤细胞生成与死亡的比例，其中生长分数和生成与丢失之比影响最大。良性或恶性并不决定生长快慢，良性肿瘤亦可缓慢长大。间质血管丰富与生长空间只提供条件。机体免疫状态影响瘤细胞存活，但不属主要决定因素"},{"q":"第二期梅毒的主要表现是","o":["主动脉炎","硬性下疳","梅毒疹","软性下疳","树胶样肿形成"],"a":2,"e":"二期梅毒为螺旋体血行播散所致，主要表现为皮肤黏膜梅毒疹，如斑疹、丘疹、扁平湿疣，传染性极强。硬性下疳为一期梅毒；主动脉炎与树胶样肿为三期梅毒；软性下疳由杜克雷嗜血杆菌引起，不属梅毒"},{"q":"肉瘤的肉眼特点通常为","o":["结节状、有包膜，切面灰白质硬","结节状、有包膜，切面灰白质软","分叶状，可有或无包膜，切面灰红或粉红色，质硬","形状不定，切面灰白色，质硬，干燥","不规则结节状，有无完整包膜不定，切面灰红色，湿润质软如鱼肉状"],"a":4,"e":"肉瘤体积较大，呈不规则结节状，有无完整包膜不定，切面灰红或灰白、湿润，质软如鱼肉状，常伴出血坏死和囊性变。癌切面多灰白、干燥、质硬；分叶状、质韧并有完整包膜多见于脂肪瘤、纤维腺瘤等良性肿瘤"},{"q":"不属于化脓性炎的疾病是","o":["急性细菌性心内膜炎","急性蜂窝织炎性阑尾炎","急性肾盂肾炎","急性风湿性心内膜炎","皮肤疖痈"],"a":3,"e":"急性风湿性心内膜炎属变态反应性炎，瓣膜闭锁缘形成的是白色血栓即赘生物，由血小板和纤维蛋白构成，无中性粒细胞渗出和脓液形成。A项急性细菌性心内膜炎、B项蜂窝织炎性阑尾炎、C项急性肾盂肾炎、E项皮肤疖痈均由化脓菌引起，以中性粒细胞渗出和脓液形成为共同特点"},{"q":"下述哪种情况不容易引起空气栓塞","o":["胸部外伤损伤深静脉","分娩时子宫强烈收缩","头颈部外伤损伤深静脉","静脉穿刺输液","儿童青枝骨折"],"a":4,"e":"空气栓塞多因头颈部或胸部深静脉损伤、分娩时子宫强烈收缩、静脉穿刺输液等使气体进入静脉。儿童青枝骨折为不完全骨折，软组织与深静脉损伤轻，气体不易进入血流，故不易引起空气栓塞"},{"q":"肝细胞癌患者最有诊断意义的血清学指标是","o":["甲胎蛋白","癌胚抗原","碱性磷酸酶","酸性磷酸酶","γ-谷氨酰转肽酶"],"a":0,"e":"甲胎蛋白由胎肝与卵黄囊合成，肝细胞癌时显著升高，是诊断、疗效监测及复发判断最有意义的血清学指标。癌胚抗原多见于结直肠癌；碱性磷酸酶升高见于胆道梗阻与骨肿瘤；γ-谷氨酰转肽酶缺乏特异性"},{"q":"下述关于四肢动脉粥样硬化的叙述中，哪项是错误的","o":["四肢动脉粥样硬化常见于下肢动脉","可以继发血栓形成","可引起肢体局部坏疽","较小动脉管腔狭窄，就易产生严重后果","行走时可出现跛行症状"],"a":3,"e":"四肢动脉粥样硬化多见于下肢动脉，可继发血栓形成、管腔闭塞，侧支循环不足时致肢体坏疽与间歇性跛行。较大动脉（股动脉、腘动脉）狭窄才易产生严重后果；较小动脉侧支丰富，狭窄后后果相对轻，故该项错误"},{"q":"关于肺疾病的叙述，下列哪项是正确的","o":["肺气肿发生气流受阻的主要病因是小气道病变","支原体主要引起小叶性肺炎","支气管肺炎常作为独立疾病发生","硅沉着病主要由直径＜5μm的粉尘引起","α1-抗胰蛋白酶缺乏是肺气肿的主要原因"],"a":0,"e":"肺气肿时小气道管壁慢性炎症、纤维化及弹性回缩力下降，气流受阻主要源于小气道病变。支原体引起间质性肺炎；支气管肺炎多为继发性；α1-抗胰蛋白酶缺乏仅见于少数年轻患者。硅沉着病以游离二氧化硅粉尘致病，本质是硅结节与弥漫纤维化，并非肺气肿气流受限的机制"},{"q":"脑膜瘤来源于","o":["硬脑膜","软脑膜和硬脑膜","蛛网膜","软脑膜","脑神经鞘膜"],"a":2,"e":"脑膜瘤起源于蛛网膜帽状细胞，多位于矢状窦旁及大脑凸面，可与硬脑膜粘连但并非源自硬脑膜。软脑膜病变见于脑膜炎；脑神经鞘膜瘤为神经鞘瘤，来源与脑膜瘤不同。脑膜瘤多呈膨胀性生长、边界清楚，血管瘤型血供丰富，易与血管性病变混淆"},{"q":"高血压时，血管壁玻璃样变性常见于","o":["冠状动脉","肾弓形动脉","主动脉","肾小球入球动脉","脑基底动脉"],"a":3,"e":"良性高血压时细动脉因长期高压致血浆蛋白渗入内膜下，发生玻璃样变，以肾小球入球动脉最典型。肾弓形动脉属小动脉，主要为内膜纤维化；冠状动脉与脑基底动脉、主动脉是动脉粥样硬化好发处，非玻璃样变典型部位"},{"q":"成人呼吸窘迫综合征发病机制中最关键的因素是","o":["血氧含量下降","微血管内血栓形成","呼吸膜损伤","肺泡活性物质合成和分泌减少","小动脉壁纤维蛋白样坏死"],"a":2,"e":"ARDS的核心是肺毛细血管内皮与肺泡上皮受损，即呼吸膜损伤，使肺泡毛细血管通透性显著增高，富含蛋白的液体渗出形成透明膜，导致进行性低氧血症。微血管内血栓形成、肺泡表面活性物质减少属继发改变；血氧含量下降是结果而非始动因素；小动脉壁纤维蛋白样坏死见于恶性高血压等"},{"q":"在机化的血栓中形成与原血管腔相沟通的毛细血管，使部分血流得以恢复，这种现象称为","o":["血栓脱落","侧支循环形成","血栓机化","血栓硬化","再通"],"a":4,"e":"血栓机化过程中形成与原血管腔相通、内皮衬覆的毛细血管，使部分血流恢复，称再通。血栓机化为肉芽组织取代血栓；血栓硬化指机化后玻璃样变；血栓脱落即形成栓子；侧支循环为原有吻合支扩张代偿，与再通机制不同"},{"q":"细菌性痢疾所致溃疡的形态是","o":["溃疡长轴与肠长轴垂直","溃疡呈烧瓶状","溃疡边缘堤状隆起","溃疡呈地图状","溃疡长轴与肠长轴平行"],"a":3,"e":"细菌性痢疾为假膜性炎，假膜脱落后形成大小不等、形状不规则的地图状溃疡，边缘不整齐。肠结核溃疡长轴与肠长轴垂直；肠阿米巴溃疡呈烧瓶状；癌性溃疡边缘堤状隆起；伤寒溃疡长轴与肠长轴平行"},{"q":"葡萄簇型横纹肌肉瘤之主要形态特征是","o":["幼稚横纹肌细胞","原始间叶细胞","丰富的黏液样基质","紧靠黏膜下方有一宽带状的细胞密集区，细胞核大，核分裂易见，称为“形成层”","肿瘤表面被覆上皮糜烂溃疡形成"],"a":3,"e":"葡萄簇型（葡萄状）横纹肌肉瘤好发于婴幼儿空腔脏器黏膜下，特征是在紧靠黏膜下方形成宽带状细胞密集区，细胞幼稚、核大、核分裂多，称“形成层”。幼稚横纹肌细胞、原始间叶细胞、丰富黏液样基质及表面黏膜糜烂溃疡均为伴随改变，非主要形态特征"},{"q":"子宫颈鳞状上皮非典型增生是指","o":["上皮细胞有异型性，完全失去分化能力","上皮细胞变成癌细胞，但基底膜完整","上皮细胞呈不规则形增生，钉突延长，基底膜不完整","上皮细胞既具有异型性，但又保持其分化能力","子宫颈柱状上皮被鳞状上皮代替"],"a":3,"e":"子宫颈鳞状上皮非典型增生指上皮细胞出现异型性但仍保持一定分化能力，表现为核增大深染、核质比增大、极性紊乱，病变未累及全层。异型细胞累及上皮全层而未突破基底膜即为原位癌；柱状上皮被鳞状上皮取代是鳞状化生"},{"q":"气性坏疽是湿性坏疽的一种特殊形式，主要是合并了","o":["结核杆菌感染","产气荚膜杆菌感染","金黄色葡萄球菌感染","链球菌感染","白假丝酵母菌感染"],"a":1,"e":"气性坏疽由产气荚膜杆菌（魏氏杆菌）引起，属湿性坏疽的特殊形式，细菌分解坏死组织产生大量气体，形成蜂窝状、捻发感。结核杆菌引起干酪样坏死，金黄色葡萄球菌与链球菌引起一般化脓性炎，白假丝酵母菌属真菌感染，均不产气"},{"q":"尿道发生肿瘤，尿路阻塞，肉眼观肾体积增大，肾实质变薄，称为","o":["肥大","变性","萎缩","发育不良","增生"],"a":2,"e":"尿路阻塞使肾盂内压升高，肾实质受压迫而缺血，肾单位逐渐萎缩，肾体积增大实为肾盂肾盏积水扩张、肾实质变薄，属压迫性萎缩。肥大指细胞或器官体积增大，增生为细胞数目增多，变性为细胞内物质蓄积，发育不良为先天发育障碍"},{"q":"下列哪项不是绒癌的特征","o":["子宫肌层内可见侵蚀的绒毛","呈暗红色、出血坏死的肿块","主要为血行转移","可有阴道结节出现","刮宫后hCG不恢复正常"],"a":0,"e":"绒毛膜癌自身无绒毛结构，瘤细胞成片增生并伴大片出血坏死，故子宫肌层内查见侵蚀的绒毛是侵袭性葡萄胎的特点。绒癌主要为血行转移，最常至肺，其次为脑、肝和阴道壁；阴道壁可形成暗红色转移结节；刮宫后hCG持续不降提示滋养细胞肿瘤残留"},{"q":"急性炎症时组织变红的主要原因是","o":["血管内血栓形成","动脉性充血","肉芽组织形成","静脉性充血","血管扩张"],"a":1,"e":"急性炎症时细动脉扩张、血流加快，形成动脉性充血，局部呈鲜红色、温度升高。静脉性充血致暗红、温度降低；血栓形成使血流停滞；肉芽组织形成见于修复期；血管扩张只是充血的一个环节，不能完整解释变红"},{"q":"类风湿性关节炎关节固定的主要原因是","o":["骨质疏松","慢性炎症，肉芽组织和瘢痕形成","肌痉挛","软骨变性","关节附近小动脉炎"],"a":1,"e":"类风湿性关节炎滑膜慢性炎症增生形成血管翳，覆盖并破坏关节软骨，后期肉芽组织机化、纤维瘢痕形成，导致关节纤维性或骨性强直，这是关节固定的主因。A项骨质疏松、D项软骨变性仅为早期改变；C项肌痉挛是疼痛保护性反应，不造成持久固定"},{"q":"胃中分化腺癌，侵及固有肌层，未侵犯浆膜时，肿瘤分期为","o":["TX","T1","T2","T3","T4"],"a":2,"e":"胃癌侵犯固有肌层而未穿透浆膜，按TNM分期属T2。A项TX指原发肿瘤无法评估，与已明确的浸润深度不符；B项T1限于黏膜及黏膜下层；D项T3穿透浆膜下层结缔组织；E项T4侵犯浆膜或邻近结构。分期依据浸润深度，肌层受累正是T2的界定"},{"q":"葡萄胎患者经彻底刮宫后，连续监测血、尿中hCG，如持续升高，说明","o":["正常","胎儿仍存活","恶变","怀孕","复发"],"a":2,"e":"葡萄胎清宫后hCG应逐渐降至正常，若持续升高或下降后又上升，提示滋养细胞仍在增殖并具侵袭性，即恶变为侵袭性葡萄胎或绒毛膜癌。A项正常应呈下降趋势；B项胎儿已不存在，不可能存活；D项怀孕需有再次妊娠证据；E项复发指肿瘤再现，此时尚未确诊肿瘤，用恶变更准确"},{"q":"胃最常见的两种良性肿瘤是","o":["平滑肌瘤和纤维瘤","脂肪瘤和腺瘤","神经纤维瘤和腺瘤","腺瘤和平滑肌瘤","纤维瘤和血管瘤"],"a":3,"e":"胃良性肿瘤以腺瘤（管状、绒毛状）和平滑肌瘤最常见，前者属癌前病变，后者源于黏膜肌层或血管壁平滑肌。纤维瘤、脂肪瘤、神经纤维瘤、血管瘤在胃均罕见，不构成最常见类型。胃癌好发于胃窦，与腺瘤、慢性萎缩性胃炎及幽门螺杆菌感染密切相关，故腺瘤须及时处理"},{"q":"下列哪项对良性胃溃疡的大体形态描述是错误的","o":["圆形或椭圆形","溃疡边缘整齐","溃疡底部凹凸不平，有坏死","周围黏膜皱襞向溃疡集中","直径一般＜2cm"],"a":2,"e":"良性胃溃疡底部平坦洁净，自内向外为炎性渗出层、坏死组织层、肉芽组织层和瘢痕层，坏死层薄而均匀。底部凹凸不平、有坏死且出血明显是溃疡型胃癌的大体特点。良性溃疡多呈圆形或椭圆形，直径多小于2cm，边缘整齐，周围黏膜皱襞向溃疡集中"},{"q":"重度慢性乙型病毒性肝炎时，肝细胞质出现毛玻璃样改变的原因是","o":["粗面内质网内有大量HBsAg","滑面内质网内有大量HBsAg","线粒体肿胀","胞质内细胞器的变性","肝细胞水肿"],"a":1,"e":"毛玻璃样肝细胞是乙型肝炎的特殊形态表现，电镜下为滑面内质网增生、池内充满HBsAg颗粒，光镜下胞质充满嗜酸性细颗粒而呈不透明毛玻璃样，免疫组化HBsAg阳性。粗面内质网是合成蛋白质的场所，HBsAg不在此大量潴留；线粒体肿胀与细胞水肿均不能形成毛玻璃样外观"},{"q":"动脉粥样硬化继发性病变中最危险的并发症是","o":["动脉瘤的形成","血栓的形成","钙化","斑块内出血","斑块破裂"],"a":0,"e":"动脉粥样硬化继发改变有斑块内出血、斑块破裂、血栓形成、钙化及动脉瘤形成，其中动脉瘤形成最危险，破裂可致致命性大出血（如腹主动脉瘤破裂）。血栓形成可致缺血梗死，出血与破裂亦较重，但凶险程度不及动脉瘤破裂"},{"q":"小叶性肺炎的病变范围","o":["以呼吸性细支气管为中心","以终末细支管为中心","以细支气管为中心","以支气管为中心","以肺泡管为中心"],"a":2,"e":"小叶性肺炎为化脓性炎，病变以细支气管为中心向周围肺泡蔓延，形成散在的灰黄实变灶，故又称支气管肺炎。大叶性肺炎累及肺大叶，以肺泡为中心；呼吸性细支气管和肺泡管属病变扩展的范围，不是炎症的中心结构"},{"q":"亚急性感染性心内膜炎皮肤表现为","o":["Osler结节","Negri小体","Aschoff小体","环形红斑","McCallum斑"],"a":0,"e":"Osler结节是亚急性感染性心内膜炎的免疫性皮肤表现，为指趾末端暗红色痛性小结节。Negri小体见于狂犬病海马锥体细胞；Aschoff小体为风湿病的特征性肉芽肿；环形红斑与McCallum斑均见于风湿性心脏病"},{"q":"关于胃癌的发生，下列哪项错误","o":["来源于胃腺颈部的干细胞","与肠上皮化生有关","与假幽门腺化生关系密切","与非典型增生有关","来源于胃小凹底部的干细胞"],"a":4,"e":"官方答案为【来源于胃小凹底部的干细胞】，但依据教材，正确答案为【与假幽门腺化生关系密切】。胃癌主要发生自胃腺颈部和胃小凹底部的组织干细胞，A、E两项均成立；与胃癌密切相关的是肠上皮化生和不典型增生，假幽门腺化生是胃体腺萎缩后的腺体转化，与癌变关系不密切"},{"q":"细胞在生长过程中，如果互相接触，则生长停止，这种现象叫","o":["再生性增生","生长的接触抑制","修复","完全再生","二期愈合"],"a":1,"e":"培养细胞汇合后相互接触即停止分裂，称接触抑制，是正常细胞调节增殖的重要机制，恶性肿瘤细胞常丧失此特性。再生性增生指组织缺损后实质细胞增生修复。二期愈合为创口伴缺损、感染时的修复方式。修复是损伤后的整体恢复过程，不指此现象"},{"q":"老年男性，曾是一名石棉矿矿工，尸检见胸膜腔内有一肿块，约5cm×4cm×3cm大小，如图所示，应首先考虑的诊断为","o":["胸膜斑","胸膜孤立性纤维瘤","周围型肺腺癌累及胸膜","恶性胸膜间皮瘤","结核性胸膜炎伴纤维斑块形成"],"a":3,"e":"本题原题配有图片，图片未随文档保留，以下解析依文字线索推断：题干涉及图片/信息缺失，无法作答。石棉接触是恶性胸膜间皮瘤的明确职业危险因素，胸膜腔肿块应首先考虑该诊断。胸膜斑为石棉沉着病的纤维斑块，多双侧、不形成肿块；孤立性纤维瘤与石棉无关；周围型肺癌累及胸膜、结核性胸膜炎纤维斑块均需影像病理鉴别，无图不能确诊\n\n官方题库中缺失图片"},{"q":"以下病变最不可能是慢性酒精中毒引起的是","o":["脂肪肝","酒精性肝炎","肝硬化","肝细胞内Mallory小体形成","肝细胞内含铁血黄素沉着"],"a":4,"e":"慢性酒精中毒依次引起脂肪肝、酒精性肝炎（Mallory小体、气球样变、中性粒细胞浸润）和肝硬化。肝细胞内含铁血黄素沉着见于血色病、反复输血或溶血，不属酒精性肝损害的典型改变。酒精性肝病还可见肝细胞气球样变、点灶状坏死及窦周纤维化，最终发展为肝硬化"},{"q":"关于传染性单核细胞增多症的叙述，下列哪项是错误的","o":["累及血液、肝脾与肾","周围血中淋巴细胞增多，并出现异型性，伴发热，喉痛","由EB病毒引起，抗EB病毒抗体滴度增加","淋巴结内可出现肉芽肿和小脓肿","全身淋巴结明显肿大"],"a":3,"e":"传染性单核细胞增多症由EB病毒引起，累及血液、肝、脾与淋巴结，周围血淋巴细胞增多并出现异型淋巴细胞，伴发热、咽痛、淋巴结肿大。淋巴结内出现肉芽肿和小脓肿为猫抓病或化脓性淋巴结炎的表现，故该项错误"},{"q":"子宫颈上皮内瘤变（CIN）是指","o":["轻度不典型增生","原位癌","重度不典型增生","不同程度的不典型增生和原位癌的统称","浸润性癌"],"a":3,"e":"子宫颈上皮内瘤变指宫颈上皮不同程度的异型增生直至原位癌的连续谱系，CINⅠ为轻度、Ⅱ为中度、Ⅲ为重度异型增生及原位癌，均未突破基底膜。浸润性癌已突破基底膜；单纯轻度或重度不典型增生只是其中一级"},{"q":"易发生干性坏疽的器官是","o":["肺","肝","肠","四肢","心"],"a":3,"e":"干性坏疽多见于动脉阻塞而静脉回流通畅的四肢末端，因水分蒸发使坏死区干燥皱缩、呈黑色，与正常组织界限清楚。肺、肠发生坏疽时组织含水多且与外界相通，多为湿性坏疽。肝与心血供丰富，坏死后易被吸收，一般不形成坏疽"},{"q":"下列哪项不是原发性肺结核病的特点","o":["初次感染","儿童多见","原发综合征","支气管播散","大多可自愈"],"a":3,"e":"原发性肺结核为初次感染结核分枝杆菌，儿童多见，形成由肺原发灶、结核性淋巴管炎和肺门淋巴结结核构成的原发综合征，多数经纤维化、钙化自愈。支气管播散是继发性肺结核慢性纤维空洞型的扩散方式，原发灶以淋巴道和血行播散为主，血行播散可致粟粒性结核"},{"q":"炎性水肿的主要原因是","o":["血浆胶体渗透压降低","毛细血管壁通透性增高","淋巴管阻塞","静脉压升高","醛固酮、抗利尿激素水平增高"],"a":1,"e":"炎性水肿的主要原因是毛细血管壁通透性增高，血浆蛋白和液体渗入组织间隙，局部胶体渗透压升高，水分潴留。A项血浆胶体渗透压降低见于肾病综合征、肝硬化；C项淋巴管阻塞引起淋巴性水肿；D项静脉压升高引起淤血性水肿；E项醛固酮、抗利尿激素增多引起钠水潴留，均非炎性水肿的主要机制"},{"q":"炎症早期局部组织呈鲜红色是因为","o":["炎性肉芽组织形成","静脉淤血","动脉性充血","红细胞漏出","炎细胞渗出"],"a":2,"e":"炎症早期致炎因子使细动脉扩张、血流加快，微循环内氧合血红蛋白增多，局部呈鲜红色、温度升高，属动脉性充血。静脉淤血时还原血红蛋白增多，局部呈暗红色；红细胞漏出为淤血性出血，炎细胞渗出与肉芽组织形成均不引起鲜红色"},{"q":"风湿病时，链球菌的何种成分与结缔组织发生反应","o":["链球菌溶血素“O”","链球菌多糖","链球菌透明质酸","胞壁C抗原","胞壁M抗原"],"a":4,"e":"A群乙型溶血性链球菌细胞壁的M蛋白与人心肌纤维肌膜、心瓣膜存在共同抗原表位，感染后产生的抗体与自身组织交叉反应，引起风湿性心脏病，M蛋白被视为致风湿源性标记。链球菌溶血素O仅用于检测抗链球菌抗体。多糖与透明质酸不参与此交叉反应"},{"q":"关于慢性溃疡性结肠炎，下列哪项是错误的","o":["病因不明，多数认为与自身免疫有关","病变可累及结肠各段，偶可见回肠","本病仅限于肠溃疡，不伴全身性疾病","肠黏膜可有假息肉形成","溃疡局部肠黏膜上皮有癌变的可能"],"a":2,"e":"溃疡性结肠炎虽以结肠黏膜的连续性溃疡为基本病变，但常伴肠外免疫性疾病，如游走性多关节炎、葡萄膜炎、原发性硬化性胆管炎，故仅限于肠溃疡的说法错误。本病病因不明，多认为与自身免疫有关，可累及结肠各段并偶及回肠，黏膜可形成假息肉，病程长者有癌变可能"},{"q":"关于梅毒疹，错误的叙述是","o":["可见于全身皮肤黏膜","为斑丘疹","可不治自愈","见于第二期梅毒","镜下为血管炎和肉芽肿性病变"],"a":4,"e":"梅毒疹见于第二期梅毒，广泛分布于全身皮肤黏膜，多为斑疹、丘疹，可不治自愈，镜下以浆细胞浸润和闭塞性小动脉内膜炎为主，肉芽肿形成是第三期树胶肿的特点，故该项错误。A项全身皮肤黏膜、B项斑丘疹、C项可不治自愈、D项见于第二期均符合。血管炎与肉芽肿并存见于晚期梅毒，不是梅毒疹的表现"},{"q":"以下哪点与高分化恶性肿瘤不符","o":["异型性较小","常见于老年人","侵袭性较小","不发生转移","肿瘤体积较小"],"a":3,"e":"不发生转移与恶性肿瘤的本质相悖：分化程度高只说明瘤细胞接近成熟、异型性小、生长较慢，恶性者仍具浸润和转移能力，只是发生较晚。A项异型性较小、C项侵袭性较小、E项体积较小均可出现在高分化恶性肿瘤中，B项常见于老年人亦与其生长缓慢、病程较长相符。转移是恶性肿瘤区别于良性肿瘤的关键，与分化高低无必然对应"},{"q":"继发性肺结核最常见的临床类型是","o":["局灶型肺结核","浸润型肺结核","肺结核球","干酪样肺炎","慢性纤维空洞型肺结核"],"a":1,"e":"继发性肺结核以浸润型最常见，多位于上叶尖后段，以渗出伴干酪样坏死为主，易形成空洞。局灶型为早期静止病灶；肺结核球为干酪灶纤维包裹；干酪样肺炎为大片干酪坏死；慢性纤维空洞型为晚期类型"},{"q":"关于克罗恩病的病变，下列错误的是","o":["病变主要累及结肠","病变肠黏膜高度水肿如铺路石","黏膜面常形成裂隙状溃疡","临床上呈慢性经过","病变局限呈节段性分布"],"a":0,"e":"克罗恩病主要累及回肠末端，其次为结肠、回肠近端和空肠，故主要累及结肠的说法错误。病变呈节段性分布，由正常黏膜分隔，肠壁全层炎症致黏膜高度水肿呈铺路石样，并形成纵行溃疡与裂隙，临床呈慢性经过，伴腹痛、腹泻、肠梗阻和瘘管"},{"q":"关于弥漫性非毒性甲状腺肿错误的说法是","o":["分为增生期、胶质贮积期、结节期、出血囊性变期","可伴有甲状腺功能亢进","常呈地域性分布，与缺碘密切相关","增生的甲状腺滤泡可以形成乳头","甲状腺内形成大小不等的结节，常伴有出血、坏死、囊性变及钙化"],"a":0,"e":"弥漫性非毒性甲状腺肿只分增生期、胶质贮积期、结节期三期，无出血囊性变期，出血囊性变仅是结节期的继发改变。缺碘致甲状腺素不足、TSH升高是主要机制，故呈地域性分布；结节期滤泡上皮可呈乳头样增生，结节内常伴出血、坏死、囊性变及钙化，部分病例可伴甲亢"},{"q":"人类免疫缺陷病毒的传播途径不包括","o":["性接触传播","输血和血制品的应用","母婴垂直传播","应用污染的针头静脉注射","呼吸道传播"],"a":4,"e":"HIV传播途径为性接触、输血及血制品、母婴垂直传播及污染针头静脉注射。呼吸道不是其传播途径，飞沫与一般生活接触不传播，故呼吸道传播为不包括项"},{"q":"引起肾盂肾炎最主要的病原菌是","o":["肺炎杆菌","葡萄球菌","链球菌","副大肠杆菌","大肠杆菌"],"a":4,"e":"肾盂肾炎最常见病原菌为大肠杆菌，占绝大多数，多经尿路上行感染。肺炎杆菌、葡萄球菌、链球菌、副大肠杆菌亦可致病，但发生率均远低于大肠杆菌"},{"q":"下列疾病或病变中属于化脓性炎的是","o":["结肠嗜酸性脓肿","肝阿米巴脓肿","脊柱旁冷脓肿","睾丸树胶样肿","淋病尿道炎"],"a":4,"e":"淋病奈瑟菌侵犯泌尿生殖道的柱状上皮和移行上皮，引起化脓性尿道炎，中性粒细胞渗出形成脓液。阿米巴脓肿为液化性坏死，非化脓性炎；冷脓肿是结核干酪样坏死；树胶样肿为梅毒肉芽肿；嗜酸性脓肿见于寄生虫感染"},{"q":"可导致肝脏肿大的疾病不包括","o":["肺源性心脏病","普通型肝炎","重型肝炎","糖尿病","酒精性肝病"],"a":2,"e":"重型肝炎肝细胞大块坏死、网状支架塌陷，肝体积显著缩小、包膜皱缩，故不引起肝肿大。肺源性心脏病右心衰致肝淤血肿大，普通型肝炎肝细胞水肿、酒精性肝病脂肪变及糖尿病肝糖原沉积均使肝脏增大"},{"q":"膜增生性肾小球肾炎的特点是肾小球的","o":["肾球囊壁层上皮增生，形成大量新月体","毛细血管丛内皮细胞显著增生肥大","系膜细胞增生伴基质增多，基膜增厚，及双轨征形成","肾球囊壁增厚，肾小球周围纤维化","基底膜伸出钉突状突起"],"a":2,"e":"膜增生性肾小球肾炎的特征为系膜细胞增生伴系膜基质增多、基膜增厚，银染可见基膜呈“双轨征”。大量新月体见于新月体性肾炎，内皮细胞显著增生见于急性增生性肾炎，钉突形成是膜性肾炎特点，肾球囊壁增厚纤维化属硬化性改变"},{"q":"以下哪项不引起左心室肥大","o":["二尖瓣关闭不全","第三期梅毒","二尖瓣狭窄","主动脉瓣关闭不全","原发性高血压"],"a":2,"e":"单纯二尖瓣狭窄时左心室舒张期充盈减少、容量负荷降低，左心室不肥大甚至缩小，故不引起左心室肥大。二尖瓣关闭不全致左心室容量负荷增加，主动脉瓣关闭不全与原发性高血压分别引起容量、压力负荷过重，均可致左心室肥大。第三期梅毒致主动脉瓣关闭不全，同样引起左心室肥大"},{"q":"下列哪项不是慢性淤血的后果","o":["实质细胞的增生","出血","含铁血黄素沉积","间质细胞增生","可并发血栓形成"],"a":0,"e":"慢性淤血的后果包括淤血性出血、含铁血黄素沉积、间质纤维组织增生、血栓形成及实质细胞萎缩。长期淤血使实质细胞缺氧、代谢障碍而萎缩甚至坏死，并非增生；间质细胞则反应性增生。故该项与慢性淤血的结局恰好相反"},{"q":"系统性红斑狼疮患者皮肤损害的典型病变表现为","o":["皮下小结","蜘蛛痣","肢体环形红斑","面部蝶形红斑","出血点"],"a":3,"e":"SLE的皮肤损害以面颊部蝶形红斑最典型，镜下见表皮萎缩、基底细胞液化、表皮真皮交界处纤维蛋白样坏死及血管周围淋巴细胞浸润。环形红斑和皮下小结是风湿病的皮肤表现；蜘蛛痣见于肝硬化；出血点为血管性或血小板异常所致"},{"q":"外科病理学应用最广泛的病理学研究方法是","o":["尸体剖验","细胞培养和组织培养","动物实验","电镜","活检"],"a":4,"e":"活组织检查从活体取材行病理诊断，可直接观察病变组织结构，是外科病理学应用最广泛的研究方法。尸体剖验用于死因分析，细胞与组织培养、动物实验属实验病理学，电镜为辅助观察手段"},{"q":"下肢静脉内血栓脱落易引起","o":["下肢坏疽","脑动脉栓塞","肝脏梗死","肺动脉栓塞","肾动脉栓塞"],"a":3,"e":"下肢深静脉血栓脱落后经下腔静脉、右心进入肺动脉，引起肺动脉栓塞。脑、肾动脉栓塞栓子多来自左心或主动脉；肝脏因门静脉与肝动脉双重血供极少梗死；下肢坏疽为动脉阻塞所致，非静脉血栓脱落的结果"},{"q":"慢性酒精中毒引起的病变，当戒酒后可完全恢复的是","o":["酒精性肝炎","脂肪肝","小结节性肝硬化","大结节性肝硬化","混合结节性肝硬化"],"a":1,"e":"慢性酒精中毒所致肝损伤中，单纯脂肪肝在戒酒后可以完全恢复，肝细胞内脂滴被代谢清除。A项酒精性肝炎已出现Mallory小体和点灶状坏死伴中性粒细胞浸润，恢复不完全；C项小结节性、D项大结节性、E项混合结节性肝硬化时假小叶和纤维间隔已形成，属不可逆改变"},{"q":"多发生在青年妇女的霍奇金淋巴瘤是","o":["结节硬化型","富于淋巴细胞的经典型","混合细胞型","淋巴细胞减少型","结节性淋巴细胞为主型"],"a":0,"e":"结节硬化型约占经典型霍奇金淋巴瘤的一半，多见于青年妇女，发病高峰15～34岁，好发于颈部、锁骨上及纵隔淋巴结，瘤细胞为陷窝细胞。混合细胞型多见于成人，淋巴细胞减少型多见于老年人且预后最差。结节性淋巴细胞为主型以男性多见，年龄30～50岁"},{"q":"卵巢肿瘤中最常见的是","o":["浆液性肿瘤","黏液性肿瘤","生殖细胞肿瘤","性索间质肿瘤","转移性肿瘤"],"a":0,"e":"卵巢上皮性肿瘤占卵巢肿瘤的大多数，其中浆液性肿瘤最常见，约60%为良性、25%为恶性。黏液性肿瘤约占卵巢肿瘤的25%；生殖细胞肿瘤、性索间质肿瘤均较少见；转移性肿瘤即Krukenberg瘤更为少见"},{"q":"新生的毛细血管、成纤维细胞长入血肿内的过程为","o":["化生","栓塞","机化","再通","血栓形成"],"a":2,"e":"机化是新生肉芽组织长入并取代坏死组织、血栓、脓液或异物的过程，新生毛细血管和成纤维细胞长入血肿属机化。再通是血栓内形成新血管使血流部分重建；化生是成熟组织转变为另一种成熟组织；栓塞是异常物质阻塞血管"},{"q":"下列关于乙型脑炎病理改变的描述中，正确的是","o":["病变以小脑最为严重","病变在大脑皮层最轻微","神经细胞变性坏死为主要病变","病变累及脊髓前角神经细胞","病变组织中有中性粒细胞浸润"],"a":2,"e":"乙型脑炎以神经细胞变性坏死为主要病变，可见卫星现象、噬神经细胞现象、筛状软化灶、胶质结节及淋巴细胞血管套。病变以大脑皮质、基底核、间脑最重，小脑与脊髓受累较轻；浸润细胞以淋巴细胞和单核细胞为主"},{"q":"急性普通性肝炎的病理临床联系中，错误的是","o":["弥漫肝细胞变性-肝肿大","肝包膜紧张-肝区痛","部分肝细胞坏死-SGPT升高","肝细胞脂肪变性-厌油腻饮食","胆红素摄取、结合、分泌障碍"],"a":3,"e":"急性普通型肝炎以肝细胞弥漫性气球样变为主，肝肿大牵张包膜致肝区痛，部分肝细胞坏死使SGPT升高，胆红素摄取、结合与分泌障碍引起黄疸。肝细胞脂肪变性见于慢性丙型肝炎与酒精性肝病，不是急性普通型肝炎病变与厌油症状之间的对应机制"},{"q":"高血压时心脏向心性肥大指","o":["左心室心肌肥厚而心腔不扩张","左心室心肌肥厚而心腔扩张","左心室壁厚度正常而心腔明显扩张","左心室、左心房心肌明显肥厚","左右心室心肌均肥厚"],"a":0,"e":"向心性肥大指长期压力负荷增高时心室壁增厚而心腔不扩张、相对缩小，见于高血压与主动脉瓣狭窄。心肌肥厚伴心腔扩张为离心性肥大，见于容量负荷过重及代偿失调期。心室壁厚度正常而心腔明显扩张属扩张性改变，左右心室均肥厚见于全心扩大"},{"q":"慢性肺源性心脏病的特征不包括","o":["阻塞性通气功能障碍","肺循环阻力增加","肺动脉压升高","右心室肥厚","右心室扩张"],"a":0,"e":"慢性肺源性心脏病以肺循环阻力增加、肺动脉压升高、右心室肥厚和扩张为特征，最终引起右心衰竭。阻塞性通气功能障碍是慢性支气管炎、肺气肿导致肺心病的前驱环节，属病因性改变，不是肺心病本身的特征"},{"q":"最多见的原发性颅内肿瘤是","o":["胶质瘤","脑膜瘤","血管网状细胞瘤","神经鞘瘤","髓母细胞瘤"],"a":0,"e":"胶质瘤占原发性颅内肿瘤的40%，是最多见者，包括成人型弥漫性胶质瘤、儿童型弥漫性胶质瘤等。脑膜瘤约占30%，居第二位；神经鞘瘤约占8%；血管网状细胞瘤与髓母细胞瘤均较少见，后者多见于儿童"},{"q":"慢性胃溃疡经久难愈的局部因素主要是","o":["局部溃疡过大","局部溃疡过深","溃疡周边组织水肿","溃疡底部神经纤维变性、断裂","溃疡底部小动脉增生性内膜炎"],"a":4,"e":"溃疡底部瘢痕内的小动脉受炎症刺激发生增殖性内膜炎，管壁增厚、管腔狭窄并可有血栓形成，局部血供不足使组织再生受限，溃疡经久难愈。神经纤维变性断裂引起顽固性疼痛；水肿和炎性渗出见于活动期，不构成难愈的局部基础"},{"q":"下列不会导致支气管扩张症的疾病是","o":["肺结核","慢性支气管炎","小叶性肺炎","大叶性肺炎","肺囊性纤维化"],"a":3,"e":"支气管扩张由支气管壁反复损伤、破坏及周围纤维组织牵拉所致，常见于肺结核、慢性支气管炎、小叶性肺炎与肺囊性纤维化。大叶性肺炎为肺泡内渗出性炎，支气管壁结构完整，痊愈后不留扩张"},{"q":"组织损伤的修复过程起始于","o":["损伤早期","损伤后期","炎症起始期","炎症后期","炎症静止期"],"a":2,"e":"组织损伤后炎症反应与修复几乎同时启动，中性粒细胞清除坏死物，巨噬细胞释放生长因子，成纤维细胞与内皮细胞随即增生，故修复起始于炎症起始期。损伤后期与炎症后期以瘢痕形成、组织改建为主，属修复的延续阶段；炎症静止期则已无活跃的修复活动"},{"q":"下列哪项不是变异型R-S细胞","o":["“爆米花”细胞","多形性R-S细胞","未分化R-S细胞","陷窝细胞","上皮样细胞"],"a":4,"e":"霍奇金淋巴瘤的变异型R-S细胞包括陷窝细胞、爆米花细胞、多形性R-S细胞和未分化R-S细胞。上皮样细胞是肉芽肿中巨噬细胞衍生的细胞，见于结核结节等，不属于R-S细胞。经典型R-S细胞为双核镜影细胞，CD15和CD30阳性，是诊断霍奇金淋巴瘤的重要依据"},{"q":"骨折愈合的最终阶段应是","o":["骨性骨痂形成","骨痂改建","纤维性骨痂连接","骨样组织中有钙盐沉着","完成了软骨化骨过程"],"a":1,"e":"骨折愈合经历血肿形成、纤维性骨痂、骨性骨痂与骨痂改建，最终经改建塑形恢复原有骨结构，故骨痂改建为最终阶段。骨性骨痂形成后尚需改建；纤维性骨痂为早期连接；骨样组织钙盐沉着是骨性骨痂形成的标志"},{"q":"有关室间隔缺损的描述错误的是","o":["高位膜部缺损最多见","血液自右向左分流","早期患儿不出现发绀","晚期可出现肺动脉高压","可出现传导阻滞"],"a":1,"e":"室间隔缺损时左心室压高于右心室，血液自左向右分流，故右向左分流的说法错误。高位膜部缺损最多见；早期为左向右分流，患儿不发绀；分流量大者晚期肺血管硬化、肺动脉高压，可逆转为右向左分流而出现发绀；缺损邻近传导束，可出现传导阻滞"},{"q":"肿瘤发生血行转移的依据是","o":["肿瘤细胞进入静脉","血液中发现有肿瘤","血管中发现有肿瘤栓子","远处器官形成同一类型肿瘤","肿瘤细胞进入淋巴管"],"a":3,"e":"血行转移的确切依据是在远隔部位形成与原发瘤相同组织学类型的肿瘤，仅血中查见瘤细胞或血管内有瘤栓均不足以证明，因多数入血瘤细胞被NK细胞消灭。肿瘤细胞侵入静脉只是转移的前提。侵入淋巴管属淋巴道转移的途径，不证明血行转移"},{"q":"肿瘤经血行转移的最常累及的器官是","o":["肺、脑","肝、肺","肺、骨","肝、脑","肝、骨"],"a":4,"e":"血行转移中瘤细胞进入静脉后常停留在肝窦或经体循环播散至骨，肝、骨因血供丰富且血流缓慢成为常见靶器官。肺亦可经血行转移（全身静脉回流首站），脑相对少见；选项以肝、骨组合最符合题意"},{"q":"不是急性胰腺炎临床表现的是","o":["血清钙、钾、钠离子水平下降","血清淀粉酶升高","血清碱性磷酸酶活性增高","休克","持续性腹痛"],"a":2,"e":"急性胰腺炎时胰酶外溢、脂肪坏死皂化消耗钙，血清钙降低；组织坏死与频繁呕吐致钾、钠下降，淀粉酶升高，并出现持续性腹痛甚至休克。血清碱性磷酸酶增高反映胆道梗阻或骨病变，不是急性胰腺炎的表现"},{"q":"以下关于胰腺癌的描述，不准确的是","o":["吸烟是重要的危险因素","以腺癌最常见","以胰头部最多见","60%的患者有K-ras基因突变","大多发病隐匿"],"a":3,"e":"胰腺癌K-ras基因突变率约90%，60%的表述明显偏低。吸烟是明确危险因素，组织学以导管腺癌最常见，约2/3位于胰头，早期缺乏特异症状，出现黄疸时多已侵犯周围组织"},{"q":"下列哪一类型的霍奇金淋巴瘤的预后最好","o":["结节硬化型","弥漫纤维化型的淋巴细胞减少型","网状细胞型的淋巴细胞减少型","混合细胞型","淋巴细胞为主型"],"a":4,"e":"霍奇金淋巴瘤各型中淋巴细胞为主型分化最好、R-S细胞少，预后最佳。结节硬化型预后较好；混合细胞型居中；淋巴细胞减少型包括弥漫纤维化型与网状细胞型，瘤细胞多、免疫功能低下，预后最差"},{"q":"脾、肾梗死灶肉眼检查的主要特点为","o":["多呈楔形、灰白色、界限清楚","多呈不规则形、暗红色、界限不清","多呈楔形、暗红色、界限不清","多呈地图形、暗红色、界限不清","多呈地图形、灰白色、界限清楚"],"a":0,"e":"脾、肾动脉呈锥形分支，梗死灶呈楔形，尖端指向血管阻塞处；组织致密、出血少，故呈灰白色，与周围界限清楚，边缘常有充血出血带。暗红色、界限不清是出血性梗死的特点，见于肺与肠。地图形为心肌梗死灶的形状"},{"q":"与获得性免疫缺陷综合征发病密切的病毒是","o":["HCV","HBV","HPV","HIV","EBV"],"a":3,"e":"获得性免疫缺陷综合征由HIV感染引起，病毒破坏CD4+T淋巴细胞，造成严重免疫抑制，继发机会性感染和肿瘤。A项HCV引起丙型肝炎并可致肝硬化和肝癌；B项HBV引起乙型肝炎；C项HPV与宫颈癌、生殖道乳头状瘤有关；E项EB病毒与鼻咽癌、Burkitt淋巴瘤及传染性单核细胞增多症有关，均不引起AIDS"},{"q":"腺泡中央型肺气肿病变主要累及","o":["肺小叶","终末细支气管","肺泡囊","呼吸性细支气管","细支气管"],"a":3,"e":"腺泡中央型肺气肿累及呼吸性细支气管，其近端扩张而肺泡管、肺泡囊及远端肺泡不受累，多见于中老年吸烟者。全腺泡型累及呼吸性细支气管至肺泡囊全程，远端腺泡型仅累及肺泡囊"},{"q":"下列属于恶性肿瘤的是","o":["多形性腺瘤","甲状腺腺瘤","乳腺纤维腺瘤","脂肪母细胞瘤","肾母细胞瘤"],"a":4,"e":"肾母细胞瘤又称Wilms瘤，来源于肾脏基，是儿童最常见的肾脏恶性肿瘤。A项多形性腺瘤、B项甲状腺腺瘤、C项乳腺纤维腺瘤均为良性；D项脂肪母细胞瘤为儿童软组织良性脂肪性肿瘤，虽含未成熟脂肪母细胞但不转移。名称带母细胞者并非均为恶性，须结合生物学行为判断"},{"q":"关于大叶性肺炎下列哪项是错误的","o":["由细菌感染引起","病变多从肺泡开始","炎症不破坏肺泡壁结构","患者常有胸痛及咳铁锈色痰","以中性粒细胞渗出为主的炎症"],"a":4,"e":"大叶性肺炎由肺炎链球菌引起，是以肺泡内弥漫性纤维蛋白渗出为主的纤维素性炎，病变从肺泡开始经肺泡孔蔓延，不破坏肺泡壁支架，愈后结构可完全恢复，临床有胸痛和铁锈色痰。以中性粒细胞渗出为主是小叶性肺炎的化脓性炎特点"},{"q":"风湿性心包炎时心包脏层病变属于","o":["肉芽肿性炎","纤维素性炎","化脓性炎","浆液、纤维素性炎","特异性增生性炎"],"a":3,"e":"风湿性心包炎累及心包脏层，以浆液和纤维蛋白渗出为主，形成浆液纤维素性炎，渗出的纤维素使心包脏壁两层粗糙，听诊有心包摩擦音。A项肉芽肿性炎为风湿小结但非心包主要病变；C项化脓性炎见于细菌感染；B项单纯纤维素性炎未包含浆液成分，不如D项准确"},{"q":"HE制片中最常用的脱水剂","o":["丙酮","正丁醇","乙醇","环乙酮","叔丁醇"],"a":2,"e":"常规HE制片中乙醇是最常用的脱水剂，可配成梯度浓度逐级脱水，兼有硬化组织的作用，随后经二甲苯透明。丙酮脱水作用强但使组织收缩明显，多用于快速制片；正丁醇、叔丁醇和环己酮应用较少。梯度乙醇由低浓度到高浓度逐步替换组织内水分，可减少组织收缩，透明后便于浸蜡包埋"},{"q":"病毒性肺炎特点中不包括","o":["常是上呼吸道病毒感染向下蔓延所致","细胞内可检见包涵体","病变严重者，肺泡内可出现脓性渗出物","肺组织内出现灶状坏死","炎症从支气管、细支气管开始沿肺间质发展"],"a":2,"e":"病毒性肺炎以间质受累为主，炎症从支气管、细支气管壁及周围间质发展，肺泡内多为浆液、少量纤维蛋白和单核细胞渗出，重者出现透明膜和灶状坏死，一般无脓性渗出物，脓性渗出提示继发细菌感染。A项上呼吸道病毒向下蔓延、B项细胞内包涵体、D项灶状坏死、E项沿间质发展均正确"},{"q":"下列哪一种疾病不会引起肺门淋巴结肿大","o":["支气管肺炎","支气管扩张症","肺癌","肺结核","肺硅沉着症"],"a":1,"e":"支气管扩张症病变限于支气管壁的持久性不可逆扩张和慢性炎症，不引起肺门淋巴结明显肿大。A项支气管肺炎常伴肺门淋巴结反应性肿大；C项肺癌可经淋巴道转移至肺门淋巴结；D项肺结核原发综合征由原发灶、淋巴管炎和肺门淋巴结炎组成；E项硅肺的尘细胞经淋巴引流至肺门淋巴结致其肿大纤维化"},{"q":"如图为脑出血的大体观，有关该病变的叙述正确的是","o":["通常出血量小","属漏出性出血","多由于较大的血管破裂所致","由毛细血管和毛细血管后静脉通透性增加所致","凝血因子缺乏亦是主要原因"],"a":2,"e":"脑出血属破裂性出血，多由高血压时基底节豆纹动脉等较大血管破裂所致，出血量大，可形成血肿并破入脑室。漏出性出血由毛细血管和毛细血管后静脉通透性增高引起，出血量少；凝血因子缺乏引起的是多发性渗血，不形成脑内大血肿"},{"q":"下列哪项因素一般与慢性胃炎无关","o":["长期慢性刺激","自身免疫损伤","幽门螺杆菌感染","十二指肠液反流","遗传因素"],"a":4,"e":"慢性胃炎的病因包括幽门螺杆菌感染、长期理化刺激如烈酒浓茶与过热饮食、十二指肠液反流及自身免疫损伤，自身免疫性胃炎伴抗壁细胞抗体与恶性贫血。遗传因素与消化性溃疡病的家族聚集有关，不列为慢性胃炎的常见病因"},{"q":"动脉瘤是指","o":["动脉发生的良性肿瘤","动脉血管破裂形成的血肿","动脉内血栓形成并机化","血管壁的局部扩张","动脉发生的恶性肿瘤"],"a":3,"e":"动脉瘤并非真性肿瘤，而是血管壁局部薄弱后向外膨出形成的局限性扩张，按形态分为囊状、梭形和蜿蜒状。A项良性肿瘤、E项恶性肿瘤均属新生物；B项血管破裂形成的血肿是假性动脉瘤的成因；C项血栓机化可使管腔再通，与动脉瘤不同"},{"q":"小叶性肺炎不会出现的并发症是","o":["肺脓肿","呼吸衰竭","支气管扩张","肺肉质变","心力衰竭"],"a":3,"e":"小叶性肺炎为化脓性炎，可并发肺脓肿、支气管扩张、呼吸衰竭及心力衰竭。肺肉质变是大叶性肺炎肺泡腔内纤维素性渗出物机化所致，故不会出现于小叶性肺炎。小叶性肺炎的化脓灶融合可致呼吸衰竭，迁延不愈可致支气管扩张，与肺肉质变机制不同"},{"q":"哪项描述符合瘢痕组织的特点","o":["细胞间有丰富的液体成分","组织内有大量的毛细血管","组织色泽鲜红、质地柔软","组织质地较硬、缺乏弹性","组织内有较多的炎性细胞"],"a":3,"e":"瘢痕组织由致密胶原纤维束构成，纤维细胞稀少、血管减少，呈灰白半透明，质硬韧而缺乏弹性。细胞间液体丰富、毛细血管多、色泽鲜红柔软是肉芽组织的特点；炎细胞较多见于炎症活动期或肉芽组织"},{"q":"胶质结节中，增生的细胞主要是","o":["星形胶质细胞","内皮细胞","少突胶质细胞","大脑锥体神经元","小胶质细胞"],"a":4,"e":"胶质结节又称小胶质细胞结节，由小胶质细胞局灶性增生聚集成团形成，见于病毒性脑炎。星形胶质细胞增生形成胶质瘢痕；少突胶质细胞围绕神经元构成卫星现象；内皮细胞增生见于血管新生，不形成胶质结节"},{"q":"原发性肺结核的特点不包括","o":["多见于儿童","形成原发综合征","急性全身性粟粒性结核多见","肺门淋巴结易受累","原发病灶常见于肺上叶下部或肺下叶上部近脏胸膜处"],"a":2,"e":"原发性肺结核多见于儿童，形成原发综合征，肺门淋巴结易受累，原发病灶多在肺上叶下部或下叶上部近胸膜处。急性全身性粟粒性结核为结核杆菌血行播散的结果，属继发性或播散性病变，并非原发肺结核的常见特点，故为不包括项"},{"q":"乳头溢液或溢血多发生于","o":["乳腺纤维腺瘤","乳腺导管癌","乳腺小叶癌","乳腺导管内乳头状瘤","乳腺腺病"],"a":3,"e":"乳腺导管内乳头状瘤发生于输乳管，瘤体血管丰富且质脆，易出血，故以乳头溢液或溢血为主要表现。导管癌的溢液多为血性，但常伴肿块、皮肤橘皮样改变；小叶癌早期多无症状；纤维腺瘤为无痛活动性肿块；乳腺腺病以周期性胀痛为主"},{"q":"属于漏出性出血的是","o":["溃疡出血","结核空洞性出血","创伤性出血","DIC出血","支气管扩张性出血"],"a":3,"e":"DIC时微血管内广泛形成纤维蛋白性微血栓，消耗凝血因子和血小板并激活纤溶系统，毛细血管通透性增高，红细胞经内皮间隙漏出，属漏出性出血。A项溃疡出血、B项结核空洞出血为病变侵蚀血管壁所致，C项创伤性出血为血管破裂，E项支气管扩张出血来自支气管动脉破裂，均属破裂性出血"},{"q":"下列关于心内膜下心肌梗死的描述，哪项是错误的","o":["梗死仅累及心室壁内侧的1/3的心肌","梗死波及肉柱及乳头肌","梗死灶常表现为小灶状坏死","严重者坏死灶融合引起环状梗死","梗死灶不规则地分布于左心室四周"],"a":3,"e":"心内膜下心肌梗死累及心室壁内侧约1/3心肌，波及肉柱与乳头肌，常呈多发性小灶状坏死、不规则分布于左心室四周。其坏死灶多散在而不融合成环，所谓环状梗死并非其表现，故该项描述错误"},{"q":"关于正常子宫内膜的基本结构，下列哪一点是错误的","o":["子宫内膜分为基底层和功能层","致密层为功能层的表层","海绵层腺体最多","基底层对卵巢激素反应最敏感","功能层有周期性变化"],"a":3,"e":"子宫内膜功能层包括致密层与海绵层，受卵巢激素调节发生周期性变化，致密层为表层，海绵层腺体最丰富。基底层不受激素周期性影响，月经后由它增生修复功能层，故基底层对卵巢激素最敏感的说法错误"},{"q":"良性高血压晚期会引起","o":["继发性颗粒性固缩肾","肾水变性","原发性颗粒性固缩肾","肾凹陷性瘢痕","肾盂积水"],"a":2,"e":"良性高血压晚期入球小动脉玻璃样变、管腔狭窄致肾缺血，肾单位萎缩、纤维化，形成双侧对称、表面细颗粒状的原发性颗粒性固缩肾。继发性颗粒性固缩肾见于慢性肾小球肾炎；凹陷性瘢痕见于慢性肾盂肾炎"},{"q":"出现箭头所指图1、2改变的可能的肾炎是","o":["急性肾小球肾炎","急进性肾小球肾炎","急性肾盂肾炎","慢性肾盂肾炎","肾癌"],"a":1,"e":"本题原题配有图片，图片未随文档保留，以下解析依文字线索推断：题干涉及图片/信息缺失，无法作答。若图示为肾小球球囊壁层上皮细胞增生形成新月体，则为急进性肾小球肾炎，临床呈急进性肾炎综合征，预后差。急性肾炎以系膜与内皮细胞增生为主。急性肾盂肾炎为化脓性炎，慢性肾盂肾炎表现为瘢痕与肾盂变形，肾癌为透明细胞巢状肿瘤\n\n官方题库中缺失图片"},{"q":"主动脉粥样硬化时，病变最严重的部位是","o":["升主动脉","主动脉弓","降主动脉","主动脉根部","腹主动脉"],"a":4,"e":"主动脉粥样硬化病变以腹主动脉最为严重，其次为主动脉弓、降主动脉，升主动脉相对较轻，这与腹主动脉血流动力学及分支开口等因素有关"},{"q":"在大多数类型的组织损伤中血管通透性升高的速发反应主要是下列哪种因素影响","o":["补体","细菌毒素","过敏毒素","组胺","坏死分解产物"],"a":3,"e":"速发短暂反应由组胺介导：组胺作用于细静脉内皮细胞H1受体，使细胞收缩、间隙增宽，通透性升高，持续约15～30分钟。细菌毒素与坏死分解产物作用较晚而持久；补体C3a、C5a属过敏毒素，主要参与白细胞趋化与肥大细胞脱颗粒"},{"q":"下面疾病中，低度恶性的肿瘤是","o":["鳞状细胞癌","鳞状细胞乳头状瘤","疣状癌","牙龈瘤","黏膜白斑"],"a":2,"e":"疣状癌为高分化鳞状细胞癌，呈疣状或菜花状外生性生长，癌细胞异型性小，生长缓慢，极少转移，属低度恶性肿瘤。鳞状细胞癌的恶性程度依分化程度而定，多数不属低度恶性。鳞状细胞乳头状瘤与牙龈瘤为良性肿瘤。黏膜白斑属癌前病变，并非肿瘤"},{"q":"急性重型肝炎的病变性质是","o":["以肝细胞变性为主的炎症","以肝细胞坏死为主的炎症","以肝细胞增生为主的炎症","以汇管区渗出为主的炎症","以汇管区增生为主的炎症"],"a":1,"e":"急性重型肝炎以肝细胞大片坏死为主，坏死带融合、网状支架塌陷，再生不明显，肝体积缩小、呈黄红色，临床迅速出现肝衰竭。以变性为主见于急性普通型；以增生为主见于肝硬化；汇管区渗出或增生为主不符合本病"},{"q":"下列哪项不是生殖细胞起源的肿瘤","o":["无性细胞瘤","葡萄胎","颗粒细胞瘤","畸胎瘤","绒癌"],"a":2,"e":"颗粒细胞瘤起源于卵巢性索间质的颗粒细胞，分泌雌激素，可致子宫内膜增生甚至癌变，属低度恶性肿瘤。无性细胞瘤、畸胎瘤、绒癌均源于生殖细胞，葡萄胎为滋养细胞良性病变，与性索间质无关"},{"q":"关于梗阻性黄疸的描述错误的是","o":["具有诊断特异性","是胰头癌最重要的临床表现","往往呈进行性加重","大部分患者出现黄疸时已属中晚期胰腺癌","可以出现在慢性胰腺炎患者"],"a":0,"e":"梗阻性黄疸呈进行性加重，是胰头癌最重要、最常见的临床表现，慢性胰腺炎因胆总管受压也可出现，多数患者出现黄疸时已属中晚期胰腺癌。黄疸本身缺乏诊断特异性，需结合影像学和肿瘤标志物判断"},{"q":"侵袭性葡萄胎与葡萄胎的主要不同是","o":["滋养细胞增生","绒毛水肿","hCG水平增高","绒毛间质血管消失","绒毛及滋养细胞侵蚀子宫肌层的深层"],"a":4,"e":"侵袭性葡萄胎与葡萄胎的关键区别是水泡状绒毛侵入子宫肌层深层并引起出血坏死，可经血管栓塞至阴道、肺、脑，而良性葡萄胎病变局限于宫腔。A项滋养细胞增生、B项绒毛水肿、D项绒毛间质血管消失在两者中均可出现，属葡萄胎本身的组织学特征，不能用于鉴别；C项hCG升高两病皆有"},{"q":"下列哪种变性是发生于细胞内","o":["脂肪变性","细动脉玻璃样变","淀粉样变性","黏液样变性","营养不良性钙化"],"a":0,"e":"脂肪变性为中性脂肪在实质细胞胞质内蓄积，属细胞内变性。细动脉玻璃样变是血浆蛋白渗入血管壁并在内膜下沉积，属细胞外改变。淀粉样变性为淀粉样蛋白沉积于细胞间质。黏液样变性发生于间质。营养不良性钙化多为钙盐沉积于坏死组织，属细胞外钙化"},{"q":"慢性炎症中，最常见的细胞是","o":["嗜酸性粒细胞","淋巴细胞","中性粒细胞","肥大细胞","嗜碱性粒细胞"],"a":1,"e":"慢性炎症灶内浸润的细胞主要为淋巴细胞、浆细胞和单核巨噬细胞，淋巴细胞受抗原刺激后分化为浆细胞产生抗体，反映机体对损伤的持续反应。中性粒细胞见于急性炎症及慢性炎症急性发作；嗜酸性粒细胞与寄生虫感染、过敏有关；肥大细胞参与I型超敏反应"},{"q":"初次吸入结核杆菌，最早引起的肺内病变是","o":["原发综合征","沿支气管出现广泛渗出","结核性淋巴结炎","原发灶的渗出及坏死","肺门淋巴结结核"],"a":3,"e":"初次感染结核杆菌，最早在肺内形成以渗出和干酪样坏死为主的原发灶，多位于上叶下部或下叶上部近胸膜处。随后细菌沿淋巴管引流至肺门淋巴结形成结核性淋巴结炎，三者合称原发综合征，故原发病灶的渗出及坏死为最早病变"},{"q":"细胞肿胀常发生于下述哪一组脏器","o":["心、肺、肾","心、脑、肾","胰、脾、肾","心、肝、肾","脑、肠、肺"],"a":3,"e":"细胞肿胀即细胞水肿，因缺氧、感染、中毒使ATP减少、钠泵功能下降，细胞内水钠积聚，最常发生于代谢活跃、对缺氧敏感的心、肝、肾实质细胞。脑和肺以细胞外间隙水肿液积聚为主，脾、胰较少发生实质细胞肿胀"},{"q":"下列癌的恶性程度相对较低的是","o":["卵巢黏液腺癌","肺小细胞癌","皮肤基底细胞癌","肝胆管细胞癌","肾盂移行细胞癌"],"a":2,"e":"皮肤基底细胞癌由基底细胞样癌细胞构成，生长缓慢，呈局部浸润性生长，极少转移，恶性程度低，预后好。肺小细胞癌分化极差、倍增快、早期即转移；卵巢黏液腺癌、肝胆管细胞癌及肾盂移行细胞癌均属中高度恶性，预后较差"},{"q":"慢性支气管炎患者通气和换气功能障碍的病变基础是","o":["支气管黏膜上皮细胞变性、坏死脱落","支气管壁腺体增生、肥大","支气管壁充血、水肿、淋巴细胞和浆细胞浸润","急、慢性细支气管炎及细支气管周围炎","支气管管壁平滑肌束断裂，萎缩"],"a":3,"e":"慢性支气管炎时急、慢性细支气管炎及细支气管周围炎使管壁增厚、管腔狭窄，黏液栓形成，气道阻力增加，是通气换气功能障碍并发展为阻塞性肺气肿的病变基础。A项上皮变性坏死脱落、B项腺体增生肥大、C项充血水肿及炎细胞浸润、E项平滑肌断裂萎缩均为慢支改变，但不直接构成气道阻塞的基础"},{"q":"肱静脉血栓形成可引起","o":["肺动脉栓塞","尺动脉栓塞","桡动脉栓塞","脑动脉栓塞","肾动脉栓塞"],"a":0,"e":"肱静脉属上肢深静脉，血栓脱落经腋静脉、锁骨下静脉、上腔静脉入右心，阻塞肺动脉分支引起肺栓塞。尺动脉、桡动脉、脑动脉与肾动脉属体循环，其栓子须来自左心或主动脉，不能来自体静脉"},{"q":"关于风湿性肉芽肿的叙述，下列哪项是错误的","o":["中心部位有较多纤维蛋白","多发生于心肌间质血管旁","常伴有淋巴细胞、浆细胞浸润","特征性细胞是Aschoff细胞","是风湿病的特征性病变，具有诊断意义"],"a":0,"e":"风湿性肉芽肿即Aschoff小体，中心为纤维素样坏死，周围有Aschoff细胞、淋巴细胞和浆细胞，多位于心肌间质小血管旁，是风湿病的特征性病变，具诊断意义。中心有较多纤维蛋白者为新月体性肾炎球囊内的渗出，与本病变不同。Aschoff细胞体积大、胞质丰富，为标志性细胞"},{"q":"伤寒的传播途径是","o":["消化道传播","呼吸道传播","血液传播","接触传播","内源性感染"],"a":0,"e":"伤寒沙门菌随患者或带菌者的粪尿排出，经污染的水和食物经口感染，属粪口途径即消化道传播。病原体先侵入肠黏膜淋巴组织，再经胸导管入血形成菌血症。呼吸道传播是结核病的主要途径，血液与接触传播不是伤寒的传播方式"},{"q":"嗜铬细胞瘤最常见于","o":["肾上腺髓质","主动脉旁副节细胞","肾上腺皮质","甲状旁腺细胞","胰岛细胞"],"a":0,"e":"嗜铬细胞瘤约90%发生于肾上腺髓质，由嗜铬细胞发生，分泌去甲肾上腺素和肾上腺素，引起阵发性高血压。肾上腺皮质肿瘤多为腺瘤或腺癌，主动脉旁副节瘤属肾上腺外副节瘤，甲状旁腺与胰岛细胞肿瘤来源不同"},{"q":"正常淋巴滤泡生发中心免疫表型特点是","o":["CD20+，BCL2+","CD3+，BCL2+","CD19+，BCL2+","CD20+，BCL2-","CD3+，BCL2-"],"a":3,"e":"正常淋巴滤泡生发中心为B细胞增殖区，表达CD20、CD10、BCL6，不表达BCL2，故为CD20阳性、BCL2阴性。套区B细胞为CD20阳性、BCL2阳性；滤泡性淋巴瘤因t(14;18)过表达BCL2，生发中心细胞BCL2阳性，是鉴别反应性滤泡增生的要点"},{"q":"容易发生出血性梗死的器官是","o":["心","肾","脑","脾","肠"],"a":4,"e":"肠管有双重血液供应且组织疏松，发生肠扭转、肠套叠或嵌顿时静脉先受阻，局部严重淤血，动脉随后闭塞，血液大量漏入梗死区，形成暗红色出血性梗死。心、肾、脾、脑组织致密、侧支循环少，梗死为贫血性，呈灰白色"},{"q":"肝穿刺活检，镜下表现如图。应诊断为","o":["急性普通型肝炎","慢性中度肝炎","肝细胞肝癌","急性重型肝炎","亚急性重型肝炎"],"a":2,"e":"本题原题配有图片，图片未随文档保留，以下解析依文字线索推断：题干涉及图片/信息缺失，无法作答。肝细胞癌镜下癌细胞呈多边形、胞质丰富，排列成梁索状或假腺管状，其间有丰富血窦，细胞异型明显，核分裂象多见。急性普通型肝炎以肝细胞气球样变、点状坏死为主，重型肝炎为大片坏死，均无肿瘤性结构\n\n官方题库中缺失图片"},{"q":"食管癌的直接浸润一般不会引起","o":["食管-气管瘘","肺脓肿","脓胸","大出血","颈部淋巴结肿大"],"a":4,"e":"颈部淋巴结肿大是食管癌经淋巴道转移所致，属转移而非直接浸润。癌组织穿透食管壁可直接侵入气管形成食管-气管瘘，继发肺脓肿、脓胸；侵蚀主动脉可致大出血。食管癌的局部浸润还常累及喉返神经、胸导管及心包"},{"q":"克罗恩病的病变特点不包括","o":["黏膜面有裂隙状溃疡形成","肠壁各层见大量慢性炎症细胞浸润","部分病例肠壁有结核样肉芽肿结构","病变常呈节段性分布","肉芽肿中心有干酪样坏死，不易和结核鉴别"],"a":4,"e":"克罗恩病为肠壁全层慢性炎，黏膜面见纵行裂隙状溃疡与鹅卵石样外观，病变呈节段性跳跃分布，可见非干酪性结核样肉芽肿。肉芽肿中心出现干酪样坏死是肠结核的特征，为二者鉴别的关键"},{"q":"胃癌的最主要转移途径是","o":["血行转移","直接蔓延","淋巴道转移","消化道内转移","腹腔内种植"],"a":2,"e":"胃癌主要经淋巴道转移，首先至幽门下及胃小弯淋巴结，晚期经胸导管转移至左锁骨上淋巴结即Virchow淋巴结。血行转移多见于晚期，经门静脉至肝；种植性转移见于癌侵及浆膜之后；直接蔓延至邻近器官"},{"q":"B型慢性萎缩性胃炎好发于","o":["贲门","胃小弯","胃大弯","胃窦部","胃底部"],"a":3,"e":"B型慢性萎缩性胃炎与幽门螺杆菌感染有关，病变多位于胃窦部，抗壁细胞抗体阴性，胃酸中度降低或正常，不伴恶性贫血，为我国患者的主要类型。A型累及胃体和胃底，由自身免疫引起。B型可进展为萎缩性胃炎伴肠上皮化生，是胃癌发生的病理基础之一"},{"q":"甲状腺腺瘤与结节性甲状腺肿的主要区别是","o":["发病年龄和性别不同","有无完整的包膜，瘤内组织结构是否一致","结节的数目不同","滤泡中有无胶质","前者肿块为单个，大小不超过3cm"],"a":1,"e":"甲状腺腺瘤有完整包膜，瘤内滤泡结构单一一致，并压迫周围甲状腺组织形成薄层纤维包膜。结节性甲状腺肿为多结节、无完整包膜，结节内增生与胶质贮积并存，常伴出血囊性变、钙化。发病年龄、结节数目、滤泡内有无胶质均不能作为鉴别依据"},{"q":"从图中所示的主要病理改变中，下列哪一项是错误的","o":["筛状软化灶","淋巴细胞浸润的围管现象","蛛网膜下腔见大量中性粒细胞","神经细胞变性坏死","形成胶质结节"],"a":2,"e":"本题原题配有图片，图片未随文档保留，以下解析依文字线索推断：题干涉及图片/信息缺失，无法作答。图示应为乙型脑炎：筛状软化灶、淋巴细胞围管性浸润、神经细胞变性坏死、胶质结节形成。其浸润细胞以淋巴细胞和单核细胞为主，蛛网膜下腔大量中性粒细胞为流行性脑脊髓膜炎的化脓性改变，故该项错误\n\n官方题库中缺失图片"},{"q":"如图所示，它属于下列哪个部位的何种病变","o":["黏膜的纤维素性炎","浆膜的纤维素性炎","黏膜的浆液性炎","浆膜的浆液性炎","化脓性炎"],"a":0,"e":"本题原题配有图片，图片未随文档保留，以下解析依文字线索推断：题干涉及图片/信息缺失，无法作答。黏膜的纤维蛋白性炎即假膜性炎，渗出物由纤维蛋白、中性粒细胞、坏死黏膜和病原菌组成，在黏膜表面形成灰白色假膜，见于白喉、细菌性痢疾。B项浆膜纤维蛋白性炎形成绒毛心；C、D项浆液性炎渗出液清亮；E项化脓性炎以脓性渗出为特征\n\n官方题库中缺失图片"},{"q":"创伤一期愈合和二期愈合的差异主要是","o":["是否为手术切口","是否经过扩创术","是否有大量肉芽组织形成","创面是否有出血","创面是否有炎症反应"],"a":2,"e":"一期愈合与二期愈合的本质差别在于缺损大小及肉芽组织充填量：一期创缘整齐、对合紧密，肉芽组织少、瘢痕小；二期缺损大，需大量肉芽组织填平，瘢痕大。是否手术切口、有无扩创、有无出血及炎症反应轻重只是促成条件，不构成根本差异"},{"q":"原发性肝癌的肉眼分型不包括","o":["结节型","弥漫型","巨块型","混合型","小肝癌"],"a":3,"e":"原发性肝癌肉眼分型为巨块型、多结节型、弥漫型和小肝癌，混合型不属此分型。混合型肝细胞癌-胆管癌是依据组织学来源划分的类型，含肝细胞癌与肝内胆管癌两种成分，与肉眼分型无关。小肝癌指单个结节直径小于3cm或两个结节直径之和小于3cm者"},{"q":"发生液化性坏死基本条件应包括","o":["含有较多的可凝固蛋白","组织淤血较严重","组织比较松软","产生蛋白酶较多","有腐败菌感染"],"a":3,"e":"液化性坏死发生于可凝固蛋白少、蛋白水解酶多的组织，如脑梗死与脓肿，酶性消化使坏死组织溶解成液态。凝固性坏死见于含蛋白多、缺血的心肝脾肾；坏疽由腐败菌感染所致；淤血与组织松软不是决定条件"},{"q":"下列哪项属于肝功能不全的表现","o":["脾大","胃肠道淤血","蜘蛛痣","腹水","侧支循环形成"],"a":2,"e":"蜘蛛痣是肝功能不全时对雌激素灭活减少、小动脉扩张所致，属肝功能不全表现。脾大、胃肠道淤血、腹水及侧支循环形成均为门脉高压的表现，而非肝细胞功能不全的直接表现"},{"q":"伤寒肠道病变的好发部位是","o":["空肠","横结肠","乙状结肠","回盲部","回肠末端"],"a":4,"e":"伤寒肠道病变好发于回肠末端，此处集合淋巴小结和孤立淋巴小结丰富，依次经历增生、坏死、溃疡、愈合四期。空肠、横结肠、乙状结肠及回盲部淋巴组织相对较少，不是伤寒肠道病变的典型好发部位"},{"q":"具有高比重，静置凝固，黄色浑浊等性状的腹水见于","o":["门静脉高压","右心衰竭","慢性肾炎","低蛋白血症","腹膜炎"],"a":4,"e":"腹膜炎所致腹水为渗出液，蛋白含量高、比重大于1.018、静置可凝固、外观黄色浑浊、细胞数多。门静脉高压、右心衰竭、慢性肾炎和低蛋白血症形成的腹水为漏出液，清亮、低比重、不易凝固。渗出液因血管通透性增高、富含纤维蛋白，故静置后凝固；漏出液蛋白多低于25g/L"},{"q":"胃活检切片，镜下表现如图，应诊断为","o":["低分化腺癌","髓样癌","印戒细胞癌","硬癌","癌肉瘤"],"a":2,"e":"本题原题配有图片，图片未随文档保留，以下解析依文字线索推断：题干涉及图片/信息缺失，无法作答。印戒细胞癌的癌细胞胞质内充满黏液，将核挤向一侧呈印戒状，弥漫浸润，多见于胃。低分化腺癌腺管结构消失但无黏液空泡；髓样癌癌细胞成片、间质少；硬癌间质纤维丰富而癌细胞少；癌肉瘤含癌与肉瘤两种成分\n\n官方题库中缺失图片"},{"q":"在我国引起肺源性心脏病最常见的疾病是","o":["肺结核","硅沉着症","支气管哮喘","支气管扩张症","慢性支气管炎伴肺气肿"],"a":4,"e":"我国肺源性心脏病最常见的病因是慢性支气管炎并发阻塞性肺气肿，占80%以上，其致气道阻塞、肺组织减少、肺血管床减少，肺动脉压升高。肺结核、硅沉着症、支气管哮喘、支气管扩张症均为次要病因"},{"q":"胃癌的好发部位是","o":["胃体","胃底部","胃窦部","胃大弯","胃小弯"],"a":2,"e":"胃癌好发于胃窦部，约占50%~60%，其次为胃小弯与贲门部，胃体、胃底及大弯侧发生率低。胃溃疡亦好发于胃窦小弯侧，部位相近而性质不同；贲门癌在我国所占比例近年有所上升"},{"q":"下列哪种恶性肿瘤属于B细胞型淋巴瘤","o":["霍奇金淋巴瘤","滤泡性淋巴瘤","蕈样肉芽肿（蕈样霉菌病）","恶性组织细胞增生症","Sezary综合征"],"a":1,"e":"滤泡性淋巴瘤源于生发中心B细胞，表达CD20与BCL2，伴t(14;18)易位。霍奇金淋巴瘤虽起源于B细胞，但以R-S细胞为特征，分类上单列；蕈样肉芽肿与Sezary综合征为皮肤T细胞淋巴瘤；恶性组织细胞增生症源于组织细胞"},{"q":"目前我国死亡率最高的肿瘤是","o":["肝癌","胃癌","乳腺癌","子宫颈癌","肺癌"],"a":4,"e":"我国恶性肿瘤死亡率首位为肺癌，与吸烟、大气污染密切相关。胃癌、肝癌次之；乳腺癌、子宫颈癌在女性多发，但总体死亡率低于肺癌。肺癌发病率与死亡率均居首位，早期诊断与手术切除是改善预后的关键"},{"q":"关于中央型肺癌的特点，应除外","o":["由段以上支气管发生","位于肺门部","多是小细胞肺癌","较易被纤维支气管镜检查发现","巨大癌块环绕癌变支气管"],"a":2,"e":"中央型肺癌发生于段及段以上支气管，位于肺门部，常形成环绕癌变支气管的巨大癌块，痰脱落细胞学和纤维支气管镜检查易发现。其组织学以鳞状细胞癌最多见；小细胞肺癌多位于肺门，腺癌多位于肺外周，故多是小细胞肺癌不属中央型特点"},{"q":"下列有关病毒性心肌炎的叙述，哪项是不正确的","o":["常由柯萨奇B组病毒感染引起","病毒通过B淋巴细胞介导引起炎症反应","晚期有明显的间质纤维化","心肌细胞变性、坏死","心肌间质内炎细胞浸润"],"a":1,"e":"病毒性心肌炎多由柯萨奇B组病毒引起，病毒直接损伤心肌并在细胞内复制，同时经T淋巴细胞介导的细胞免疫反应致病。病变为心肌细胞变性坏死、间质炎细胞浸润，晚期出现间质纤维化，故由B淋巴细胞介导的说法错误"},{"q":"交界性肿瘤是指","o":["既有癌组织，又有肉瘤成分的肿瘤","侵犯表皮和真皮交界部位的肿瘤","介于良性和恶性之间的肿瘤","侵犯黏膜和黏膜基层交界部位的肿瘤","既有腺癌成分、又有鳞癌成分的肿瘤"],"a":2,"e":"交界性肿瘤指组织形态和生物学行为介于良性与恶性之间的肿瘤，如卵巢交界性浆液性乳头状囊腺瘤，需按复发转移风险度评估。含癌与肉瘤两种成分者为癌肉瘤；腺癌与鳞癌成分并存为腺鳞癌；侵犯表皮真皮交界处者并非交界性肿瘤的含义"},{"q":"容易发生肠粘连、狭窄的疾病为","o":["阿米巴病","细菌性痢疾","伤寒","结核","息肉"],"a":3,"e":"肠结核因干酪样坏死、溃疡形成及纤维组织增生，愈合后纤维收缩易致肠管环形狭窄与肠粘连。阿米巴病形成烧瓶状溃疡，多致肠穿孔；细菌性痢疾为假膜性炎，愈合多不留狭窄；伤寒溃疡长轴与肠长轴平行，较少引起狭窄"},{"q":"梅毒的特征性病变是","o":["明显干酪样坏死","玫瑰疹","树胶样肿","象皮肿","异物肉芽肿"],"a":2,"e":"树胶样肿即梅毒瘤，是三期梅毒的特征性病变，中央为凝固性坏死，周围淋巴细胞、浆细胞浸润及纤维化，可见多核巨细胞。玫瑰疹为二期梅毒皮损；象皮肿见于丝虫病；明显干酪样坏死以结核最典型"},{"q":"神经元单纯性萎缩一般不常伴有","o":["周围血管性淋巴细胞浸润","明显的胶质细胞增生","嗜神经细胞现象","神经细胞内包涵体","缺血性病变"],"a":1,"e":"神经元单纯性萎缩表现为神经元体积缩小、周围血管淋巴细胞浸润、噬神经细胞现象及胞内包涵体，常伴缺血性改变，但不伴明显胶质细胞增生。明显胶质增生多见于脑软化、胶质瘢痕等，而非单纯性萎缩的常规表现"},{"q":"肿瘤分期是指","o":["肿瘤细胞的分化程度","肿瘤细胞的恶性程度","肿瘤细胞核分裂象的多少","肿瘤的生长范围和扩散程度","肿瘤细胞的浸润及转移能力"],"a":3,"e":"肿瘤分期指恶性肿瘤的生长范围和播散程度，依据原发瘤大小、浸润深度、邻近器官受累、淋巴结转移和远处转移确定。分化程度和核分裂象数目用于分级；恶性程度由分级推断；浸润转移能力是生物学行为描述，不等同于分期"},{"q":"黏液变性是指","o":["组织间质内出现大量的类黏液","黏液腺分泌过多","胃印戒细胞癌的癌细胞中有大量黏液","浆液腺发生黏液化而分泌大量黏液","支气管黏膜上皮中的杯状细胞分泌黏液"],"a":0,"e":"黏液变性指组织间质内出现大量类黏液即氨基多糖积聚，胶原纤维分解断裂变疏松，充以淡蓝色胶状液体，常见于甲状腺功能减退的黏液水肿和间叶组织肿瘤。B项黏液腺分泌过多、E项杯状细胞分泌黏液属分泌亢进；C项印戒细胞癌的黏液位于癌细胞内，为细胞内黏液；D项浆液腺黏液化属化生性改变"},{"q":"伤寒增生的细胞是","o":["淋巴细胞","单核巨噬细胞","中性粒细胞","嗜酸性粒细胞","浆细胞"],"a":1,"e":"伤寒的特征性病变是全身单核巨噬细胞系统增生，巨噬细胞吞噬伤寒沙门菌、红细胞及坏死碎屑后成为伤寒细胞，聚集成伤寒小结。中性粒细胞增多见于急性化脓性炎；淋巴细胞为主见于病毒感染；嗜酸性粒细胞与寄生虫感染、过敏反应有关"},{"q":"下述哪种病变不会出现冠状动脉粥样硬化","o":["心肌的变性和坏死","心肌内糖原沉积","心肌间质出血","心肌的代偿性肥大","心肌内纤维化"],"a":1,"e":"冠状动脉粥样硬化使心肌缺血，引起心肌变性坏死、间质纤维化、代偿性肥大及间质出血。心肌内糖原沉积见于糖原贮积病，由溶酶体酸性α-葡萄糖苷酶等缺陷所致，与冠状动脉病变无关"},{"q":"肿瘤生长分数是指","o":["肿瘤细胞中处于增殖阶段的细胞比例","肿瘤细胞中处于合成前期的细胞比例","肿瘤细胞中处于有丝分裂期的细胞比例","肿瘤细胞中处于合成前、后期的细胞比例","肿瘤细胞中处于合成期的细胞比例"],"a":0,"e":"生长分数指肿瘤细胞群体中处于增殖阶段（增殖周期）细胞所占比例，反映肿瘤生长活性。合成前期、合成期、有丝分裂期仅对应细胞周期的单一时相，不能代表增殖整体的比例"},{"q":"在活体内血栓形成过程中的启动因素是","o":["激活内源性凝血系统","血小板的黏集","激活外源性凝血系统","合成前列环素","生成纤溶酶原活化因子"],"a":1,"e":"血栓形成的启动环节是血小板黏附于损伤内膜裸露的胶原并被激活，发生黏集形成血小板小堆，成为血栓起始点。内、外源性凝血系统的激活在血小板活化之后放大凝血过程。前列环素由内皮细胞生成，抑制血小板聚集。纤溶酶原活化因子促进血栓溶解"},{"q":"肝功能不全患者蜘蛛状血管痣好发于","o":["腹前壁","颈、面部、前臂及手掌","全身各部","上肢及下肢","背部及颈部"],"a":1,"e":"肝硬化时雌激素灭活减少使小动脉末梢扩张，蜘蛛痣好发于颈、面部、上胸部及前臂、手掌等上腔静脉引流区，压迫中心红点可使其消退。全身各部广泛分布不符合其好发规律。腹前壁为门脉高压侧支循环即海蛇头的部位，与蜘蛛痣性质不同"},{"q":"图为肺淤血镜下表现，箭头所指细胞为","o":["心力衰竭时某些形态特殊的心肌细胞","硅沉着病致右心衰竭时，肺内吞噬硅尘的巨噬细胞","褐色硬变肺内含有含铁血黄素的巨噬细胞","心力衰竭时肺内吞噬炭末的巨噬细胞","心力衰竭时肺泡腔内的泡沫细胞"],"a":2,"e":"本题原题配有图片，图片未随文档保留，以下解析依文字线索推断：题干涉及图片/信息缺失，无法作答。慢性肺淤血时红细胞漏入肺泡腔，被巨噬细胞吞噬后形成含铁血黄素，即心力衰竭细胞，见于褐色硬变肺。D项吞噬炭末的是尘细胞，不含含铁血黄素；E项泡沫细胞吞噬脂质，多见于动脉粥样硬化；A项为心肌细胞，与肺无关\n\n官方题库中缺失图片"},{"q":"脑出血最常见的原因是","o":["血液病","血管瘤破裂","高血压病脑内出血","脑内小动脉粥样硬化","外伤"],"a":2,"e":"脑内出血最常见的病因是高血压病，细小动脉硬化和微动脉瘤在血压骤升时破裂，好发于基底节、内囊。A项血液病、B项血管瘤破裂、D项脑内小动脉粥样硬化均为少见原因；E项外伤所致属外伤性颅内出血。D项脑动脉粥样硬化主要引起缺血性脑梗死"},{"q":"与癌前病变无关的描述是","o":["如不及时治愈有可能转变为癌","演变为癌的时间较长","细胞形态可有异型性","癌前病变可分为遗传性和获得性","适应性反应"],"a":4,"e":"癌前病变指有恶变潜能的良性病变，如不及时治愈可能转癌、演变时间较长、细胞可有异型性、可分为遗传性与获得性。适应性反应是细胞组织对刺激的应答性改变（如肥大、增生、化生），不属于癌前病变范畴，故无关"},{"q":"肝穿刺送检标本，镜下如图所示，箭头所指肝细胞出现何种病变","o":["细胞水肿","脂肪变性","玻璃样变性","嗜酸性变","点状坏死"],"a":3,"e":"本题原题配有图片，图片未随文档保留，以下解析依文字线索推断：题干涉及图片/信息缺失，无法作答。嗜酸性变表现为肝细胞胞质水分减少、浓缩红染，核固缩，进而形成嗜酸性小体，多见于病毒性肝炎。细胞水肿为胞质疏松淡染乃至气球样变；脂肪变性为胞质内圆形脂滴空泡；玻璃样变形成Mallory小体；点状坏死为细胞崩解伴炎细胞浸润\n\n官方题库中缺失图片"},{"q":"下面疾病中属于癌前病变的是","o":["黏膜白斑","白塞综合征","Wegener肉芽肿","复发性阿弗他溃疡","牙龈瘤"],"a":0,"e":"黏膜白斑发生于口腔、外阴黏膜，上皮增生伴异型增生，可进展为鳞状细胞癌，属癌前病变。白塞综合征为血管炎性反复口腔、生殖器溃疡；Wegener肉芽肿为坏死性血管炎伴肉芽肿；复发性阿弗他溃疡为良性复发性溃疡；牙龈瘤为炎性增生性瘤样病变，四者均非癌前病变"},{"q":"下列哪种肿瘤无血管及间质","o":["脂肪瘤","横纹肌肉瘤","纤维肉瘤","畸胎瘤","绒毛膜癌"],"a":4,"e":"绒毛膜癌由异型增生的滋养层细胞构成，无绒毛结构，自身不含血管和间质，靠侵蚀宿主血管获取营养，易早期血行转移。脂肪瘤、横纹肌肉瘤、纤维肉瘤、畸胎瘤均含血管和间质，故仅绒毛膜癌无血管及间质"},{"q":"下列不是流行性脑脊髓膜炎的临床表现的是","o":["脑膜刺激征状","颅内压升高","偏瘫","脑脊髓液细胞数增加","脑神经麻痹"],"a":2,"e":"流脑是脑脊髓膜的急性化脓性炎，临床表现为脑膜刺激征、颅内压升高、脑脊液细胞数增多，脓性渗出物包绕脑神经可致脑神经麻痹，一般不出现偏瘫。偏瘫由脑实质受累引起，见于乙型脑炎、脑出血及脑梗死等"},{"q":"在淋巴结内有多核巨细胞、类上皮细胞形成的结节样反应，此时可排除","o":["猫抓病","结核","非典型分枝杆菌感染","性病性淋巴肉芽肿","窦组织细胞增生"],"a":0,"e":"类上皮细胞与多核巨细胞构成的结节为结核样肉芽肿，结核、非典型分枝杆菌感染及性病性淋巴肉芽肿均典型出现。猫抓病早期为组织细胞增生，典型病变是被膜下上皮样细胞聚集伴中央中性粒细胞微脓肿，多核巨细胞少见。窦组织细胞增生以窦内组织细胞增生并吞噬淋巴细胞为特点"},{"q":"细动脉透明变性常见于下列哪项","o":["肾、心、脾、视网膜等处的细动脉","肺、胰、肠系膜等处的细动脉","肾、脑、肝、心等处的细动脉","心、肺、脾、视网膜等处的细动脉","肾、脑、脾、视网膜等处的细动脉"],"a":0,"e":"细动脉透明变性多见于良性高血压，累及肾入球动脉、心、脾、视网膜等处细动脉，管壁均质红染增厚、管腔狭窄。B项肺、胰、肠系膜并非好发部位；E项把心换成脑，脑细动脉透明变性不如心、肾典型，故该组合不符合题意"},{"q":"亚急性感染性心内膜炎的赘生物脱落后最易引起栓塞的部位是","o":["皮肤","心脏","肾","脾","脑"],"a":4,"e":"亚急性感染性心内膜炎的赘生物松脆易脱落，栓子随体循环血流进入脑、肾、脾及下肢动脉，其中脑动脉栓塞最常见且症状突出，可致偏瘫、失语。皮肤表现为Osler结节等免疫性小血管炎，并非栓塞部位；心脏是感染原发处，不为栓塞靶器官"},{"q":"槟榔肝是指","o":["肝细胞肿胀","肝细胞脂肪变性、淤血","慢性肝炎","肝硬化","肝细胞萎缩"],"a":1,"e":"槟榔肝为慢性肝淤血，肝小叶中央区淤血呈暗红色，周边肝细胞脂肪变性呈黄色，红黄相间似槟榔切面。肝细胞肿胀、萎缩见于其他损伤；肝硬化以假小叶形成为特征，与单纯淤血不同"},{"q":"下列哪一项不符合肺动脉高压形成的机制","o":["缺氧引起肺小动脉痉挛","长期、反复痉挛导致肺小动脉玻璃样变","肺内无肌性细动脉肌化","肺纤维化及肺气肿可引起肺动脉高压","肌型小动脉中膜肥厚，内膜下出现纵形肌束"],"a":1,"e":"长期反复的肺小动脉痉挛使血管壁发生中膜肥厚、内膜纤维化及无肌型细动脉肌化，而非玻璃样变；玻璃样变是高血压病细动脉硬化的特征。A项缺氧性痉挛、C项无肌性细动脉肌化、E项肌型小动脉中膜肥厚及内膜下纵行肌束，均为肺心病肺血管构型重建表现。D项肺纤维化、肺气肿使毛细血管床减少，确可引起肺动脉高压"},{"q":"阿米巴滋养体所引起的组织坏死是","o":["凝固性坏死","干酪样坏死","湿性坏疽","液化性坏死","纤维素样坏死"],"a":3,"e":"溶组织内阿米巴滋养体分泌溶组织酶，溶解破坏肠壁及肝组织，形成液化性坏死，肝脓肿呈巧克力酱样。凝固性坏死见缺血梗死；干酪样坏死为结核特征；湿性坏疽见肠管等；纤维素样坏死见结缔组织病"},{"q":"可造成感染慢性化的肝炎病毒是","o":["肝炎病毒C","肝炎病毒A、E","肝炎病毒A、D","肝炎病毒B、C、D","肝炎病毒C、D、E"],"a":3,"e":"乙型、丙型和丁型肝炎病毒可引起慢性感染，病毒持续存在导致慢性肝炎并进展为肝硬化，丁型需与乙型同时或重叠感染。甲型和戊型经消化道传播，多为自限性急性肝炎，不形成慢性携带状态。丙型肝炎慢性化率最高，可达50%～85%；乙型多见于围生期及儿童期感染者"},{"q":"炎症反应的最重要的指征是","o":["血管扩张","红细胞漏出","血浆渗出","白细胞游出","纤维素渗出"],"a":3,"e":"炎症最重要的指征是白细胞自血管游出并在组织内聚集，尤其中性粒细胞，是清除病原体的核心环节。血管扩张与血浆渗出为早期血管反应；红细胞漏出见于出血性炎；纤维素渗出见于纤维素性炎，均非最重要指征"},{"q":"某患者白带增多，宫颈活检镜下见鳞状上皮层下部近2/3的细胞出现异型性，应诊断为","o":["宫颈上皮内瘤变Ⅰ级","宫颈上皮内瘤变Ⅱ级","宫颈上皮内瘤变Ⅲ级","宫颈原位癌","宫颈柱状上皮异位"],"a":1,"e":"宫颈上皮内瘤变按异型细胞占据上皮层的厚度分级，异型细胞限于上皮下1/3为Ⅰ级，超过1/3而未达全层为Ⅱ级，超过2/3至全层为Ⅲ级，全层异型而基膜完整为原位癌。本例异型细胞达近2/3、未累及全层，符合Ⅱ级。柱状上皮异位为宫颈外口柱状上皮外移，属生理性改变，无细胞异型"},{"q":"高血压脑出血最易发生病变的动脉是","o":["基底动脉","豆纹动脉内侧动脉","大脑中动脉","豆纹动脉外侧动脉","Willis动脉"],"a":3,"e":"高血压脑出血最易累及豆纹动脉外侧支，因其自大脑中动脉垂直发出、承受压力高、管壁薄，称出血动脉，出血多位于基底核。大脑中动脉主干、基底动脉及Willis环受累以缺血性病变为主。壳核出血最常见，出血量大时可破入脑室，引起昏迷与脑疝"},{"q":"电镜下细胞凋亡的特征性改变是","o":["细胞皱缩","细胞质致密","染色质边集","核碎裂","凋亡小体形成"],"a":4,"e":"凋亡的特征性改变是细胞膜内陷包裹细胞器形成凋亡小体，电镜下胞质致密、细胞器完整。细胞皱缩、染色质边集、核碎裂在凋亡中虽可见，但非特异；凋亡小体形成为凋亡的标志性结构，也是与坏死鉴别的主要依据"},{"q":"子宫颈癌最常见的组织学类型为","o":["黏液癌","鳞状细胞癌","腺癌","未分化癌","大细胞癌"],"a":1,"e":"子宫颈癌以鳞状细胞癌最多见，占80%左右，多起源于鳞柱交界处的移行带，与高危型HPV感染密切相关。腺癌约占20%，近年有上升趋势；黏液癌、未分化癌及大细胞癌均少见，不能作为最常见的组织学类型"},{"q":"大叶性肺炎患者的铁锈色痰变成黏液脓痰是在","o":["充血水肿期","红色肝样变期","灰色肝样变期","溶解消散期","病变恢复期"],"a":2,"e":"大叶性肺炎红色肝样变期红细胞被巨噬细胞吞噬分解为含铁血黄素，痰呈铁锈色；进入灰色肝样变期，肺泡内红细胞减少、纤维素与中性粒细胞增多，痰转为黏液脓性。充血水肿期痰为浆液性，溶解消散期痰稀薄而量多"},{"q":"下列关于妊娠期子宫内膜的特征叙述，哪一个是错误的","o":["子宫内膜致密层形成蜕膜组织","海绵层腺体扩张，弯曲，分泌增强","腺体上皮细胞呈顶浆分泌，腺体弯曲呈锯齿状","部分腺体出现A-S现象","腺体可呈腺瘤样增生"],"a":2,"e":"妊娠期子宫内膜形成蜕膜，致密层为蜕膜组织，海绵层腺体扩张弯曲、分泌增强，可见A-S现象，腺体可呈腺瘤样增生。“腺体上皮细胞呈顶浆分泌、腺体弯曲呈锯齿状”是月经周期分泌期子宫内膜的特征，而非妊娠期特征，故错误"},{"q":"诊断慢性浅表性胃炎最有意义的是","o":["黏膜浅层溃疡形成","黏膜浅层嗜酸性粒细胞和中性粒细胞浸润","黏膜浅层淋巴细胞浸润和上皮坏死脱落","黏膜浅层炎细胞浸润和腺体增生","黏膜浅层淋巴细胞、浆细胞浸润伴固有层腺体消失"],"a":2,"e":"慢性浅表性胃炎病变限于黏膜浅层，固有层内淋巴细胞、浆细胞浸润，可伴表面上皮坏死脱落，腺体保持完整、无萎缩。腺体消失、肠上皮化生是慢性萎缩性胃炎的特征；腺体增生肥大见于肥厚性胃炎；黏膜浅层溃疡形成属消化性溃疡"},{"q":"下列哪型肝炎的肝脏重量减轻最明显","o":["急性普通型肝炎","急性重型肝炎","亚急性重型肝炎","重度慢性肝炎","轻度慢性肝炎"],"a":1,"e":"急性重型肝炎肝细胞弥漫性大片坏死，肝体积明显缩小、重量显著减轻、被膜皱缩、质地柔软，故肝重量减轻最明显。亚急性重型肝炎因有结节状再生，体积缩小程度较轻；慢性肝炎和急性普通型肝炎肝重量变化不明显"},{"q":"癌变率较高的大肠病变是","o":["绒毛状腺瘤","增生性息肉","锯齿状腺瘤","幼年性息肉","炎性息肉"],"a":0,"e":"绒毛状腺瘤的绒毛纤细、上皮异型明显，癌变率可达30%～40%，明显高于管状腺瘤，属大肠癌最重要的癌前病变。增生性息肉为黏膜上皮过度增生形成的良性息肉，几乎不癌变；幼年性息肉属错构瘤性；炎性息肉继发于慢性炎症，癌变罕见"},{"q":"可以诊断为恶性肿瘤的是","o":["肿瘤有出血","肿瘤有坏死","肿瘤有火山口状溃疡形成","肿瘤的异型性明显","肿瘤呈浸润性生长"],"a":3,"e":"异型性明显，表现为核大深染、核仁显著、核浆比增大及病理性核分裂，是判断恶性最可靠的形态依据。出血、坏死、囊性变在良性肿瘤生长迅速时也可出现；火山口状溃疡需镜下证实；浸润性生长可见于血管瘤等良性肿瘤"},{"q":"下列都符合流行性乙型脑炎，除外","o":["病毒引起的急性传染病","也称日本夏季脑炎","以蚊虫为传播媒介","脑组织以渗出性病变为主","病变以大脑皮质、基底节、视丘最为严重"],"a":3,"e":"流行性乙型脑炎是病毒血症后病毒侵入中枢神经系统引起的变质性炎，以神经细胞变性坏死、筛状软化灶形成为主，渗出与增生轻微，故以渗出性病变为主不符合。本病又称日本夏季脑炎，经蚊虫叮咬传播，病变以大脑皮质、基底节、丘脑最重"},{"q":"尸体解剖时血管中常见到的固体质块是","o":["透明血栓","白色血栓","红色血栓","混合血栓","血凝块"],"a":4,"e":"尸体解剖时血液凝固形成血凝块，呈暗红色胶冻状、与血管壁不粘连，为死后变化。血栓为生前形成、与管壁粘连且有层次；透明血栓见于微血管，白色、红色、混合血栓均为生前不同类型，均与死后血凝块不同"},{"q":"急性胰腺炎时，下列哪项不可能出现","o":["胰腺坏死病变呈间隔性小叶周围分布，坏死灶外周有炎性细胞包绕","常见淋巴管炎、静脉炎、血栓形成","血清中碱性磷酸酶活性增高","部分病人可有心包积液、化学性腹水和胸腔积液","血清及尿中淀粉酶和脂酶含量增高"],"a":2,"e":"急性胰腺炎胰腺坏死呈小叶周围分布、外周炎细胞包绕，常伴淋巴管炎、静脉炎及血栓，可出现化学性腹水胸水心包积液，血清尿淀粉酶脂酶升高。碱性磷酸酶增高主要见于肝胆和骨病，与胰腺炎症无直接关系，故不可能出现"},{"q":"革囊胃的形成是指","o":["范围较大的溃疡型胃癌","胃溃疡广泛瘢痕形成","胃癌癌细胞弥漫浸润胃壁","胃癌伴胃囊性扩张","胃黏液腺癌大量黏液潴留"],"a":2,"e":"癌细胞在胃壁内弥漫浸润生长，致胃壁普遍增厚变硬、胃腔缩小，状如皮革，称革囊胃，属浸润型胃癌。范围较大的溃疡型胃癌形成火山口状溃疡而非弥漫增厚。胃溃疡瘢痕形成致胃变形，但胃壁不弥漫增厚。黏液潴留形成黏液湖见于黏液腺癌，不产生革囊胃"},{"q":"由肥大细胞释放的炎症介质有","o":["溶菌酶","血管活性胺","激肽","补体","缓激肽"],"a":1,"e":"肥大细胞脱颗粒释放的炎症介质以组胺为代表，属血管活性胺，可致血管扩张和通透性升高。溶菌酶来自中性粒细胞与巨噬细胞；激肽、缓激肽来自血浆激肽系统；补体为血浆蛋白系统成分，均非肥大细胞释放"},{"q":"关于慢性支气管炎的说法，下列哪项是错误的","o":["40岁以上男性多见","可伴喘息症状","常见反复咳嗽、咳痰","可进展为肺心病","常伴发作性呼气性呼吸困难"],"a":4,"e":"慢性支气管炎以反复咳嗽、咳痰为特征，痰多呈白色黏液泡沫状，可伴喘息，40岁以上男性多见，长期进展可致肺气肿与肺心病。发作性呼气性呼吸困难是支气管哮喘的表现，故该项错误。喘息型慢性支气管炎可闻及哮鸣音，但发作性、可逆性气道痉挛为哮喘特征，两者机制不同"},{"q":"良性肿瘤的异型性主要表现在","o":["瘤细胞的多形性","细胞核的多形性","组织结构的异型性","病理性核分裂","细胞异型性"],"a":2,"e":"良性肿瘤的细胞异型性不明显，主要表现是组织结构异型性，即瘤细胞的空间排列方式与相应正常组织存在差异，如腺瘤的腺体大小和排列不整。A项瘤细胞多形性、B项细胞核多形性、D项病理性核分裂、E项细胞异型性均为恶性肿瘤的显著特征，良性者即便出现也较轻"},{"q":"下列哪一种细胞器对缺氧最敏感","o":["线粒体","溶酶体","滑面内质网","高尔基体","粗面内质网"],"a":0,"e":"线粒体对缺氧最敏感，缺氧时氧化磷酸化受抑、ATP生成减少、钠泵失灵，细胞水肿，故线粒体是缺血缺氧最早受累的细胞器，也是不可逆损伤的关键。溶酶体破裂发生在损伤后期，粗面内质网、滑面内质网、高尔基体改变出现较晚"},{"q":"引起急性感染性心内膜炎的常见病原体是","o":["草绿色链球菌","金黄色葡萄球菌","痢疾杆菌","柯萨奇B组病毒","朊病毒"],"a":1,"e":"急性感染性心内膜炎起病急、进展快，以金黄色葡萄球菌最多见，赘生物大而松软，易脱落形成含菌栓子。亚急性感染性心内膜炎以甲型溶血性链球菌即草绿色链球菌最多见，肠球菌次之。痢疾杆菌、柯萨奇B组病毒与朊病毒均不引起本病的瓣膜赘生物"},{"q":"二尖瓣狭窄可继发以下改变，但除外哪项","o":["肺褐色硬化","槟榔肝及脾大","三尖瓣相对关闭不全","左心房附壁血栓形成","主动脉关闭不全"],"a":4,"e":"二尖瓣狭窄致左心房压升高、肺淤血，长期形成肺褐色硬化；肺循环阻力增高致右心室肥大与三尖瓣相对关闭不全，左心房扩张易形成附壁血栓，右心衰致槟榔肝与脾大。主动脉瓣关闭不全为独立瓣膜病变，非二尖瓣狭窄的继发改变"},{"q":"系统性红斑狼疮患者心脏典型病变为","o":["心瓣膜非细菌性疣状赘生物","心外膜纤维素性炎","心瓣膜闭锁缘菜花样赘生物","MeCallum斑","心瓣膜钙化"],"a":0,"e":"系统性红斑狼疮心脏受累以心包炎最常见，而最典型者为心瓣膜非细菌性疣赘性心内膜炎，赘生物小而单行排列，可累及瓣膜两面。心外膜纤维素性炎即绒毛心，见于尿毒症与风湿病。瓣膜菜花样赘生物为感染性心内膜炎表现，McCallum斑为风湿性心内膜炎的心内膜斑块"},{"q":"Krukenberg瘤是指","o":["胃黏液癌种植转移至膀胱上","肺癌种植转移至胸膜上","胃黏液癌种植转移至腹膜上","胃黏液癌种植转移至肠壁上","胃黏液癌种植转移至卵巢上"],"a":4,"e":"Krukenberg瘤指胃肠道黏液癌，特别是胃印戒细胞癌种植转移至卵巢形成的双侧卵巢黏液腺癌，镜下见富于黏液的印戒细胞弥漫浸润。种植于腹膜、肠壁或膀胱者不称此瘤，肺癌胸膜种植亦不属此命名。故其来源以胃癌为主"},{"q":"下列不属于肉芽肿性炎的是","o":["风湿病","伤寒","肺硅沉着病","乙型脑炎","麻风"],"a":3,"e":"乙型脑炎为病毒所致的变质性炎，以神经细胞变性坏死、筛状软化灶形成为主，无肉芽肿形成。风湿病为Aschoff小体、伤寒为伤寒小结、肺硅沉着病为硅结节、麻风为结核样或麻风性肉芽肿，均属肉芽肿性炎"},{"q":"与慢性胃炎发病有关的细菌是","o":["大肠杆菌","葡萄球菌","链球菌","幽门螺杆菌","白假丝酵母菌"],"a":3,"e":"幽门螺杆菌是慢性胃炎最主要的致病菌，寄居于胃黏膜表面和胃小凹内，不侵入腺体，通过尿素酶和细胞毒素损伤黏膜屏障。大肠埃希菌、葡萄球菌和链球菌多引起急性感染或化脓性病变；白假丝酵母菌见于免疫力低下者"},{"q":"组织固定后脱水的顺序依次是","o":["70%乙醇，80%乙醇，95%乙醇，100%乙醇","70%乙醇，95%乙醇，80%乙醇，100%乙醇","100%乙醇，95%乙醇，80%乙醇，70%乙醇","95%乙醇，100%乙醇，70%乙醇，80%乙醇","80%乙醇，100%乙醇，70%乙醇，95%乙醇"],"a":0,"e":"组织固定后脱水须用梯度乙醇由低到高逐级置换，顺序为70%、80%、95%、100%乙醇，每级停留适当时间，以免组织骤然收缩。B项把95%置于80%之前、C项由高到低逆行、D项高浓度先行，均造成组织收缩变形。E项80%后直接入100%属跳级，脱水不彻底，影响透明与浸蜡"},{"q":"毛细血管再生时在蛋白分解酶作用下基底膜分解，首先出现的变化是","o":["内皮细胞分裂增生形成幼芽","内皮细胞分泌层粘连蛋白","内皮细胞分泌Ⅳ型胶原","成纤维细胞分泌Ⅲ型胶原","出现毛细血管管腔"],"a":0,"e":"毛细血管再生时，蛋白分解酶降解基底膜后，首先出现内皮细胞分裂增生并向缺损处迁移，形成实心细胞索（幼芽），继而出现管腔、分泌Ⅳ型胶原和层粘连蛋白重建基底膜。B项层粘连蛋白、C项Ⅳ型胶原分泌属基底膜重建的后续步骤；D项Ⅲ型胶原由成纤维细胞产生；E项管腔出现晚于幼芽形成"},{"q":"与坏死后肝硬化相比，下列哪项是门脉性肝硬化常见的特点","o":["肝功能障碍","上消化道大出血","合并胆管上皮癌","合并肝细胞肝癌","结节大小相仿"],"a":4,"e":"门脉性肝硬化为小结节型，结节大小相仿、直径多小于3mm、纤维间隔细窄。坏死后性肝硬化结节大小悬殊、间隔宽大。二者均可出现肝功能障碍、肝细胞癌及上消化道出血，合并胆管上皮癌多见于胆汁性肝硬化"},{"q":"肝硬化患者出现颈部蜘蛛状血管痣，考虑肝脏对（ ）灭活作用减弱所致","o":["雌激素","雄激素","生长激素","甲状腺激素","甲状旁腺激素"],"a":0,"e":"肝硬化时肝细胞对雌激素的灭活减弱，血中雌激素水平升高，引起小动脉末梢扩张，形成蜘蛛痣与肝掌，并可致男性乳腺发育。雄激素灭活减少并非蜘蛛痣成因；生长激素、甲状腺激素、甲状旁腺激素与之无关"},{"q":"肺静脉血栓脱落致脑动脉阻塞的现象称为","o":["血栓再通","血栓机化","血栓软化","血栓钙化","血栓栓塞"],"a":4,"e":"肺静脉血栓脱落随血流经左心进入体循环，阻塞脑动脉，属血栓栓塞。血栓再通为机化后血流部分恢复；血栓机化为肉芽组织取代血栓；血栓软化是纤维蛋白溶解致血栓溶解；血栓钙化形成静脉石。栓塞后果取决于栓子大小、数目与阻塞部位，脑栓塞常致脑软化"},{"q":"最常见的鼻咽癌组织学类型是","o":["去分化癌","泡状核细胞癌","腺癌","高分化鳞癌","低分化鳞癌"],"a":4,"e":"鼻咽癌最常见者为低分化鳞状细胞癌，癌巢分层不明显，细胞间无细胞间桥、无角化珠，与EB病毒感染关系密切。高分化鳞癌可见角化珠与细胞间桥，所占比例低。泡状核细胞癌是低分化鳞癌的一个亚型。腺癌少见，去分化癌不属常用分类"},{"q":"急性、慢性（急性变）粒细胞白血病时，在骨内、骨膜下或其他器官内，可由白血细胞形成瘤结，瘤组织在新鲜时，外观呈某种颜色，可称为","o":["白色瘤","黄色瘤","绿色瘤","转移瘤","棕色瘤"],"a":2,"e":"急性、慢性粒细胞白血病细胞在骨内、骨膜下或其他器官形成瘤结，因富含髓过氧化物酶，新鲜切面呈绿色，故称绿色瘤。白色瘤非规范病名，黄色瘤为脂质泡沫细胞聚积，棕色瘤见甲旁亢，转移瘤为他处转移癌，均不符"},{"q":"引起心肌炎最常见的病毒是","o":["柯萨奇病毒","埃可病毒","腺病毒","风疹病毒","巨细胞病毒"],"a":0,"e":"病毒性心肌炎以柯萨奇病毒最常见，尤以B组为主，其次为A组、埃可病毒和腺病毒。B项埃可病毒、C项腺病毒、D项风疹病毒、E项巨细胞病毒虽均可致心肌炎，但检出率明显低于柯萨奇病毒。题干只问最常见者，应选柯萨奇病毒"},{"q":"绒毛心是指","o":["心外膜的纤维素性炎","心外膜的纤维素性化脓性炎","心外膜的化脓性炎","心外膜的浆液性炎","心外膜的纤维性增生的结果"],"a":0,"e":"绒毛心是心外膜的纤维素性炎，纤维素渗出并随心脏搏动被牵拉成绒毛状，见于风湿性心外膜炎与尿毒症。纤维素性化脓性炎与化脓性炎形成脓性渗出；浆液性炎为心包积液；纤维性增生致心包粘连缩窄"},{"q":"可能发生恶变的是","o":["蓝痣","混合痣","表皮疣状痣","皮内痣","交界痣"],"a":4,"e":"交界痣的痣细胞位于表皮与真皮交界处，增生活跃，受摩擦等刺激后可能恶变为黑色素瘤。皮内痣与混合痣较稳定，恶变罕见；蓝痣、表皮疣状痣亦极少恶变"},{"q":"下列哪种细胞不是通过变形运动离开血管的","o":["中性粒细胞","红细胞","嗜酸性粒细胞","淋巴细胞","巨噬细胞"],"a":1,"e":"炎症时白细胞借变形运动穿过内皮细胞间隙游出，中性粒细胞、嗜酸性粒细胞、淋巴细胞与巨噬细胞均具此能力。红细胞无变形运动，仅在血管通透性显著增高时被动漏出，属出血性渗出。巨噬细胞由单核细胞游出后转化而来，同样经血管壁移行"},{"q":"属于阻塞型先天性心脏病的是","o":["房间隔缺损","室间隔缺损","动脉导管开放","法洛四联症","主动脉缩窄"],"a":4,"e":"先天性心脏病按血流动力学分为非发绀型、发绀型和阻塞型，主动脉缩窄因主动脉局限性狭窄致血流受阻，属阻塞型。房间隔缺损、室间隔缺损、动脉导管未闭均为左向右分流的非发绀型，法洛四联症为右向左分流的发绀型"},{"q":"在触发凝血过程中起核心作用的是","o":["血小板的活化","胶原","凝血因子Ⅻ","纤维连接蛋白","凝血酶敏感蛋白"],"a":0,"e":"血栓形成启动时，内皮损伤暴露胶原，血小板黏附、活化并释放ADP、血栓素A2，形成血小板黏集堆，同时激活凝血系统，故血小板活化是核心环节。胶原是血小板黏附的底物，凝血因子Ⅻ启动内源性凝血，纤维连接蛋白与凝血酶敏感蛋白参与基质构成"},{"q":"恶性高血压病病变特点是","o":["细动脉壁发生纤维素样坏死","细动脉壁发生炎症性改变","细动脉壁发生黏液变性","细动脉壁发生玻璃样变","细动脉壁发生痉挛"],"a":0,"e":"恶性高血压（急进型高血压）的病变特点是细动脉壁发生纤维素样坏死，进展迅速，可伴出血与内脏坏死。细动脉玻璃样变是良性高血压特点；炎症性改变、黏液变性及血管痉挛均非恶性高血压的特征性病变"},{"q":"软组织透明细胞肉瘤的起源是","o":["滑膜","神经外胚叶","纤维组织","平滑肌","上皮组织"],"a":1,"e":"软组织透明细胞肉瘤起源于神经外胚叶，瘤细胞呈多边形或梭形、胞质透明，常浸润腱膜和肌腱，属少见的高度恶性软组织肿瘤。A项滑膜起源者为滑膜肉瘤；C项纤维组织为纤维肉瘤；D项平滑肌为平滑肌肉瘤；E项上皮组织为癌"},{"q":"胰腺癌患者最常见的基因异常是","o":["c-erbB-2基因扩增","p53基因突变","c-myc基因转位","K-ras基因突变","c-kit基因突变"],"a":3,"e":"胰腺癌最常见的基因异常是K-ras基因第12密码子点突变，发生率80%～90%，属启动事件。p53突变见于进展期；c-erbB-2扩增多见于乳腺癌；c-myc转位见于Burkitt淋巴瘤；c-kit突变见于胃肠道间质瘤"},{"q":"关于甲状腺乳头状癌错误的说法是","o":["乳头状癌BRAF基因可以不突变","直径小于1cm的乳头状癌称为微小乳头状癌","恶性程度较低，但局部淋巴结转移较早","甲状腺乳头状癌细胞常呈磨玻璃样，有核沟及核内包涵体","甲状腺乳头状癌的乳头一般没有纤维血管间质"],"a":4,"e":"甲状腺乳头状癌的乳头分支复杂，乳头中心有纤维血管间质，间质内常见同心圆状钙化的砂粒体，故乳头无纤维血管间质的说法错误。癌细胞核呈毛玻璃样，有核沟与核内包涵体；直径小于1cm者称微小乳头状癌；恶性程度低但局部淋巴结转移早；BRAF基因可不突变"},{"q":"阑尾炎的基本病变是属于","o":["肉芽肿性炎","急性增生性炎","蜂窝织炎","纤维素性炎","变质性炎"],"a":2,"e":"阑尾炎的基本病变为阑尾壁的弥漫性化脓性炎，即蜂窝织炎，大量中性粒细胞弥漫浸润于黏膜下层、肌层及浆膜层，与周围组织界限不清。肉芽肿性炎见于结核、克罗恩病；纤维素性炎见于大叶性肺炎与菌痢；变质性炎见于病毒性肝炎、乙型脑炎"},{"q":"肺转移性肝癌是指","o":["肝癌和肺癌互相转移","肝癌转移到肺","肝和肺同时发生转移性癌","肺癌转移到肝","肝癌和肺癌同期转移到其他地方"],"a":1,"e":"肺转移性肝癌指原发灶在肝、经血道转移至肺所形成的转移瘤，即肝癌转移到肺。若原发灶在肺而转移至肝，应称肝转移性肺癌。命名时前置器官为转移部位，后置器官为原发部位。转移瘤命名以转移部位在前、原发部位在后；肺内多发、边界清楚的结节提示转移"},{"q":"左心房血栓脱落不会引起","o":["脑梗死","肺梗死","肾梗死","脾梗死","下肢梗死"],"a":1,"e":"左心房血栓脱落后进入体循环动脉系统，可栓塞脑、肾、脾及下肢动脉引起相应梗死。肺梗死的栓子来自右心或肺动脉系统（如下肢深静脉血栓），左房血栓无法进入肺循环，故不会引起肺梗死"},{"q":"下列哪种癌较早经淋巴道转移","o":["甲状腺乳头状腺癌","食管鳞状细胞癌","子宫颈鳞状细胞癌","鼻咽低分化鳞状细胞癌","胃黏液腺癌"],"a":3,"e":"鼻咽低分化鳞状细胞癌分化差、恶性度高，早期即转移至颈深上淋巴结，淋巴道转移出现最早。B项食管鳞癌、C项宫颈鳞癌以直接浸润蔓延为主，淋巴结转移相对较晚；E项胃黏液腺癌易经腹膜种植和血道转移，淋巴道并非其突出途径"},{"q":"胃溃疡镜下变化由内向外分别是","o":["炎性渗出、坏死、肉芽、瘢痕","坏死、炎性渗出、肉芽、瘢痕","瘢痕、肉芽、炎性渗出、坏死","瘢痕、肉芽、坏死、炎性渗出","坏死、肉芽、炎性渗出、瘢痕"],"a":0,"e":"胃溃疡底部由表面至深部依次分为炎性渗出层、坏死组织层、肉芽组织层和瘢痕层，炎性渗出位于最内面，故该排列正确。B项将坏死置于渗出之前、C项与D项从瘢痕起始均由外向内倒置，不符合溃疡底面层次的实际顺序"},{"q":"急性感染性心内膜炎中瓣膜赘生物中，不具有的成分是","o":["大量细菌","大量肉芽组织","大量中性粒细胞","坏死组织","大量血小板和纤维蛋白"],"a":1,"e":"急性感染性心内膜炎的赘生物由大量细菌、纤维蛋白与血小板、坏死组织及中性粒细胞构成，质松脆易脱落，因病程急、进展快，尚无肉芽组织长入。肉芽组织见于亚急性者的愈合期或风湿性心内膜炎的机化过程，故赘生物中不具大量肉芽组织"},{"q":"乳腺小叶原位癌的特点是","o":["癌细胞局限于小叶腺泡内","癌细胞局限于导管内","癌细胞丰富、间质少","纤维间质丰富，癌细胞少","癌细胞与间质大致相等"],"a":0,"e":"小叶原位癌的瘤细胞充满膨胀的小叶末梢导管与腺泡，呈实体排列，小叶结构尚存，基底膜完整，未突破至间质。癌细胞局限于扩张导管内者是导管原位癌。癌细胞丰富而间质少描述的是髓样癌，纤维间质丰富伴癌细胞少描述的是硬癌"},{"q":"淋病属于","o":["化脓性炎症","假膜性炎","浆液性炎症","变质性炎症","肉芽肿性炎症"],"a":0,"e":"淋病由淋球菌引起，主要侵犯泌尿生殖道黏膜，表现为急性化脓性炎（脓性卡他），尿道口流脓。假膜性炎见白喉与细菌性痢疾，浆液性炎见烧伤，变质性炎见病毒性肝炎，肉芽肿性炎见结核等"},{"q":"下列与肝硬化形成最为密切的是","o":["急性重型肝炎","轻度慢性肝炎","重度慢性肝炎","急性普通型肝炎","急性甲型肝炎"],"a":2,"e":"重度慢性肝炎肝细胞反复变性坏死伴纤维组织增生，逐步形成纤维间隔与假小叶，最易进展为肝硬化。急性普通型肝炎多可痊愈；轻度慢性肝炎进展缓慢；急性重型肝炎多短期内死于肝衰竭，来不及形成肝硬化；甲型肝炎不转为慢性"},{"q":"系统性红斑狼疮患者皮肤损害具有病理学诊断意义的是","o":["表皮萎缩、角化过度","基底细胞液化","狼疮带","表皮真皮交界处水肿","血管周围淋巴细胞浸润"],"a":2,"e":"免疫荧光显示真皮与表皮交界处IgG、IgM及C3呈颗粒或团块状沉积，形成狼疮带，对系统性红斑狼疮有诊断意义。基底细胞液化、表皮萎缩与血管周围淋巴细胞浸润见于盘状红斑等皮肤病变，特异性不足。表皮真皮交界处水肿为一般炎症改变。狼疮小体多见于淋巴结与肾小球"},{"q":"关于慢性支气管炎的描述错误的是","o":["黏膜腺体增生、肥大","支气管壁平滑肌断裂、萎缩","黏膜上皮可出现鳞状化生","典型临床表现为伴有哮鸣音的呼气性呼吸困难","支气管壁充血水肿，淋巴细胞、浆细胞浸润"],"a":3,"e":"慢性支气管炎的典型表现是慢性咳嗽、咳大量黏液脓性痰，伴哮鸣音的呼气性呼吸困难只见于喘息型，是支气管哮喘的特点。黏膜腺体增生肥大、管壁平滑肌断裂萎缩、上皮鳞状化生及管壁慢性炎细胞浸润均为其基本病理改变"},{"q":"下列疾病不可能发生纤维结缔组织玻璃样变的是","o":["结核性纤维素性胸膜炎","硅肺","慢性浅表性胃炎","肝硬化","心肌梗死"],"a":2,"e":"纤维结缔组织玻璃样变是胶原纤维交联、变性、融合的结果，见于结核性纤维素性胸膜炎机化、硅肺纤维化、肝硬化纤维间隔及心肌梗死瘢痕。慢性浅表性胃炎病变限于黏膜浅层，以炎症细胞浸润为主，无明显纤维组织增生，故不出现此种改变"},{"q":"急性炎症组织中最多的细胞浸润是","o":["浆细胞","淋巴细胞","嗜酸性粒细胞","中性粒细胞","巨噬细胞"],"a":3,"e":"急性炎症24小时内以中性粒细胞浸润为主，其趋化与吞噬能力强，是化脓性炎的主要渗出细胞。24~48小时后单核巨噬细胞逐渐增多；淋巴细胞与浆细胞见于慢性炎症；嗜酸性粒细胞见于寄生虫感染与变态反应"},{"q":"风湿病变累及全身结缔组织，其中最严重的器官是","o":["脑","血管","心脏","皮肤","关节"],"a":2,"e":"风湿病可累及全身结缔组织，以心脏受累最重：风湿性心内膜炎致瓣膜增厚变形、狭窄或关闭不全，最终心力衰竭。关节病变为游走性大关节炎，属渗出性、不留畸形；皮肤受累为环形红斑与皮下结节；中枢受累为小舞蹈病；血管为坏死性血管炎，后果均轻于心脏"},{"q":"有关前列腺癌，下列说法错误的是","o":["90%以上是腺癌","PSA染色多为阴性","很少侵犯直肠","最常见的转移部位是骨","好发于50岁以上的老年人"],"a":1,"e":"前列腺癌90%以上为腺癌，免疫组化PSA、PSAP表达阳性，血清PSA升高是诊断随访的重要指标，故染色多为阴性的说法错误。C项前列腺与直肠间有筋膜相隔，很少侵犯直肠；D项最常见转移部位为骨，尤以骨盆、脊柱多见；E项好发于50岁以上老年男性，均属实"},{"q":"下列哪一项是恶性肿瘤独有的特征","o":["局部肿块","恶病质","出血坏死","浸润性生长","转移"],"a":4,"e":"转移是恶性肿瘤独有的特征，癌细胞脱离原发灶，经淋巴道、血道或种植在其他部位形成继发瘤，良性肿瘤从不转移。局部肿块、出血坏死可见于良性肿瘤；浸润性生长虽多见于恶性肿瘤，但血管瘤等良性病变亦可呈浸润性生长；恶病质为晚期表现"},{"q":"下列对阑尾炎的描述哪一项是错误的","o":["临床主要表现为转移性右下腹疼痛","根据病程常分为急性和慢性","细菌和病毒是阑尾炎发病的主要因素","大部分阑尾炎伴有阑尾腔阻塞","常见并发症是阑尾周围脓肿和急性弥漫性腹膜炎"],"a":2,"e":"阑尾炎发病的两个主要因素是阑尾腔阻塞与细菌感染，且无特定病原菌，病毒不是致病因素。临床以转移性右下腹痛为典型表现，按病程分急性与慢性；50%～80%的病例伴阑尾腔阻塞；阑尾周围脓肿与急性弥漫性腹膜炎是主要并发症"},{"q":"透明血栓多发生在","o":["毛细血管","动脉系统","静脉系统","心房","心室"],"a":0,"e":"透明血栓发生于微循环血管内，主要在毛细血管，由嗜酸性同质的纤维蛋白构成，又称纤维蛋白性血栓，最常见于DIC，需显微镜下观察。B项动脉系统多见白色血栓和混合血栓，C项静脉系统为延续性血栓，D项心房、E项心室内为附壁的混合血栓"},{"q":"关于慢性胃溃疡，下列哪项是错误的","o":["溃疡多位于胃大弯近幽门侧","溃疡边缘整齐不隆起","溃疡一般较深","溃疡直径多在2cm以内","溃疡周围黏膜皱襞呈放射状"],"a":0,"e":"胃溃疡多位于胃小弯侧，愈近幽门愈多见，尤以胃窦部为著，胃底及大弯侧少见，故该项把部位说颠倒了。B项描述的是良性溃疡的边缘，整齐如刀切、不隆起。C、E两项亦属良性溃疡所见，溃疡常深达肌层甚至浆膜层，周围黏膜皱襞受瘢痕牵拉呈放射状集中"},{"q":"为提高阳性率，胸腹腔积液标本离心后取哪一层细胞涂片最好","o":["试管上层","红细胞层","交界层","红细胞之上的白膜层","底层"],"a":3,"e":"胸腹腔积液离心后肿瘤细胞比重较轻，集中于红细胞之上的白膜层（交界层上方），取该层涂片阳性率最高。试管上层为清亮液体，红细胞层与底层含大量红细胞及碎屑，均不宜用于查找癌细胞。积液量少或细胞数低时，可加抗凝剂防止凝固，再用密度梯度离心提高检出率"},{"q":"IgA肾病的最显著特点是","o":["血清IgA水平增高","复发性血尿","弥漫性系膜增多","系膜区IgA沉积","血清C3下降"],"a":3,"e":"IgA肾病的确诊依据是免疫荧光显示系膜区以IgA为主的颗粒状沉积，常伴C3，临床表现为反复发作的镜下或肉眼血尿。血清IgA水平可正常或升高，无诊断特异性。弥漫性系膜增生仅提示系膜增生性病变。血清补体多正常，与链球菌感染后肾炎的低补体不同"},{"q":"关于风湿病，下列哪一项是错误的","o":["与A组乙型溶血性链球菌感染有关","是一种结缔组织病","以形成风湿小体为病变特征","风湿性关节炎常可导致关节畸形","皮下结节和环形红斑对临床诊断风湿病有帮助"],"a":3,"e":"风湿性关节炎为滑膜的浆液性炎，渗出物易被完全吸收，不破坏关节软骨，故不遗留关节畸形，呈游走性、反复发作。导致关节畸形的是类风湿关节炎，其滑膜增生形成血管翳并侵蚀软骨。本病与A组乙型溶血性链球菌感染有关，属结缔组织病，以风湿小体为特征"},{"q":"下列不属于坏死后性肝硬化的病变特点的是","o":["假小叶大小不等","纤维间隔较宽","炎细胞浸润明显","假小叶大小相仿","碎片状坏死"],"a":3,"e":"坏死后性肝硬化属大结节型，假小叶大小不等、纤维间隔宽且炎细胞浸润明显，常伴碎片状坏死，故假小叶大小相仿不符。A项假小叶大小不等、B项纤维间隔较宽、C项炎细胞浸润明显、E项碎片状坏死均为其特点。小结节型肝硬化的结节才大小相仿、直径多小于3mm、纤维间隔较细，两者恰成对照"},{"q":"组织切片最常用的染色方法是","o":["苏丹Ⅲ染色","苏木素伊红染色","Masson三色染色","PAS染色","嗜银染色"],"a":1,"e":"苏木素-伊红染色操作简便、对比清晰，可同时显示细胞核与胞质，是组织切片最基本、最常用的染色方法。苏丹Ⅲ染脂肪，PAS染糖原与基膜，Masson三色染胶原，嗜银染色显示网状纤维，均为针对性特殊染色，只在HE染色不能确诊时选用"},{"q":"关于肺出血肾炎综合征的叙述，错误的是","o":["属于快速进行性肾炎1型","抗GBM的抗体与肺泡基底膜发生交叉反应，引起反复咯血","病理特征是肾小球内新月体形成","常继发于链球菌感染或系统性红斑狼疮","肾小球内IgG和C3沿毛细血管袢呈线状沉积"],"a":3,"e":"肺出血肾炎综合征即Goodpasture综合征，由抗GBM抗体与肺泡基膜交叉反应引起，属急进性肾炎Ⅰ型，免疫荧光呈线状沉积，病理特征为新月体形成。继发于链球菌感染或系统性红斑狼疮者属Ⅱ型免疫复合物型肾炎，荧光呈颗粒状，与本综合征的发病机制不同"},{"q":"脑膜瘤最好发于","o":["颅后凹","蝶骨嵴的侧面","窦汇周围","上矢状窦两侧","小脑脑桥角"],"a":3,"e":"脑膜瘤起源于蛛网膜帽状细胞，好发于大脑凸面矢状窦旁，即上矢状窦两侧，与该处蛛网膜颗粒密集分布相一致，肿瘤多呈结节状、质韧、有包膜并附着于硬脑膜。蝶骨嵴、颅后凹、小脑脑桥角及窦汇周围均可发生，但发生率明显低于矢状窦旁"},{"q":"符合腺泡中央型肺气肿的病变特点是","o":["细支气管和肺泡弥漫性扩张","呼吸性细支气管扩张","肺泡管和肺囊泡扩张","呼吸细支气管和肺囊泡扩张","呼吸细支气管和肺泡管扩张"],"a":1,"e":"腺泡中央型肺气肿最常见于中老年吸烟者或慢性支气管炎患者，病变位于肺腺泡中央的呼吸性细支气管，呈囊状扩张，而肺泡管和肺泡囊扩张不明显。A项弥漫性扩张、C项肺泡管和肺囊泡扩张、E项呼吸细支气管和肺泡管扩张均不符；D项为全腺泡型肺气肿的特点，其呼吸性细支气管、肺泡管、肺泡囊和肺泡均扩张"},{"q":"早期食管癌是指","o":["未发生转移的癌","局限于上皮层内的癌","局限于黏膜或黏膜下层，不论是否发生淋巴结转移","病变长度小于3cm，未发生淋巴结转移","局限于黏膜层，不论是否发生淋巴结转移"],"a":2,"e":"早期食管癌指癌组织局限于黏膜或黏膜下层，未侵犯肌层，无论有无淋巴结转移，多为原位癌或黏膜内癌，临床无明显症状。局限于上皮层内者仅指原位癌；未发生转移、病变长度小于3cm均不能作为早期癌的判定标准"},{"q":"医院内肺炎常见的病原体是","o":["厌氧菌多见","支原体多见","革兰阴性杆菌多见","真菌多见","病毒多见"],"a":2,"e":"医院内肺炎以革兰阴性杆菌最常见，如铜绿假单胞菌、克雷伯菌、大肠埃希菌，与气管插管、广谱抗生素应用、免疫抑制相关。社区获得性肺炎以肺炎链球菌为主；厌氧菌见于吸入性肺炎；支原体、病毒多为轻症社区感染；真菌见于长期免疫抑制者"},{"q":"并发肺肉质变最主要的原因是","o":["含铁血黄素沉积","细菌毒力过强","单核细胞浸润过多","中性粒细胞渗出过少","纤维蛋白渗出过多"],"a":3,"e":"肺肉质变因病灶内中性粒细胞渗出过少，释放的蛋白酶不足以溶解肺泡腔内的纤维蛋白，纤维蛋白被肉芽组织机化，使肺组织呈肉样实变。纤维蛋白渗出过多是形成基础，决定机化的关键是中性粒细胞数量；细菌毒力强易致化脓和坏死"},{"q":"下列哪种损伤不能发生完全再生","o":["骨折","肝细胞坏死但网状支架未塌陷","腺体及基膜都受损","腺体仅有腺上皮受损","子宫内膜脱落"],"a":2,"e":"腺体及基膜均受损时，腺上皮虽可再生但无法重建腺管结构，只能由瘢痕修复，属不完全再生。骨折、网状支架完整的肝细胞坏死、仅腺上皮受损的腺体以及周期性脱落的子宫内膜均可完全再生"},{"q":"下列哪种疾病可导致心肌间质中出现大量淋巴单核细胞浸润","o":["风湿性心肌炎","病毒性心肌炎","心肌病","心肌梗死","细菌性心肌炎"],"a":1,"e":"病毒性心肌炎是嗜心肌病毒感染引起的非特异性间质性炎症，心肌间质内出现大量淋巴细胞、单核细胞浸润，心肌细胞变性坏死。风湿性心肌炎形成Aschoff小体，以风湿细胞为主。细菌性心肌炎为化脓性炎，以中性粒细胞为主。心肌梗死以凝固性坏死伴中性粒细胞浸润为特征"},{"q":"属于发绀型先天性心脏病的是","o":["房间隔缺损","室间隔缺损","动脉导管开放","法洛四联症","主动脉缩窄"],"a":3,"e":"法洛四联症由肺动脉狭窄、室间隔缺损、主动脉骑跨和右心室肥大组成，右向左分流使体循环血氧饱和度下降，早期即出现发绀，是成人最常见的发绀型先天性心脏病。A项房间隔缺损、B项室间隔缺损、C项动脉导管开放为左向右分流的非发绀型；E项主动脉缩窄属阻塞型"},{"q":"急性肺淤血时最典型的症状是","o":["心悸","胸闷","呼吸困难","粉红色泡沫痰","铁锈色痰"],"a":3,"e":"急性肺淤血时肺毛细血管压骤升，血浆与红细胞漏入肺泡，与气体混合形成粉红色泡沫痰，伴气促、发绀及濒死感。铁锈色痰为大叶性肺炎红细胞崩解后含铁血黄素所致；心悸、胸闷缺乏特异性"},{"q":"慢性炎症病灶内浸润的炎细胞主要是","o":["中性粒细胞和单核细胞","单核细胞和淋巴细胞","浆细胞和嗜碱性粒细胞","淋巴细胞和嗜酸性粒细胞","嗜酸性粒细胞和嗜碱性粒细胞"],"a":1,"e":"慢性炎症灶以单核巨噬细胞、淋巴细胞和浆细胞浸润为主，反映持续免疫反应与组织修复并存。中性粒细胞见于急性炎症；嗜酸性粒细胞见于寄生虫感染与变态反应；嗜碱性粒细胞在炎症灶中少见。浆细胞产生抗体，巨噬细胞负责吞噬清除，三者共同构成长病程炎症的细胞背景"},{"q":"引起急性胰腺炎的原因，不包括","o":["营养不良","暴饮暴食","大量饮酒","胆石症","胆道蛔虫"],"a":0,"e":"急性胰腺炎主要病因为胆道疾病如胆石症、胆道蛔虫，以及暴饮暴食和大量饮酒，致胰液排出受阻、胰酶原位激活并自身消化。营养不良是慢性胰腺炎及胰腺萎缩的成因，不属急性胰腺炎的常见病因"},{"q":"动脉粥样硬化早期，哪种细胞最早迁入动脉内膜","o":["嗜酸性粒细胞","淋巴细胞","中性粒细胞","单核细胞","成纤维细胞"],"a":3,"e":"动脉粥样硬化早期内皮受损后，单核细胞黏附并迁入内膜，分化为巨噬细胞吞噬脂质形成泡沫细胞，是最早迁入的细胞。嗜酸性粒细胞、中性粒细胞非早期主角，成纤维细胞参与纤维斑块形成更晚，淋巴细胞出现亦晚于单核"},{"q":"早期发现胃癌最可靠的方法是","o":["X线钡餐检查","超声检查","胃液特异酶检测","胃液脱落细胞学检查","纤维胃镜活组织检查"],"a":4,"e":"纤维胃镜可直视黏膜色泽、糜烂与微小癌灶并取活组织行病理检查，是早期发现和确诊胃癌最可靠的方法。X线钡餐对早期浅表病变敏感度低，胃液脱落细胞学阳性率有限，超声对空腔脏器显示不佳"},{"q":"在溃疡愈合期，填补溃疡的是","o":["肌细胞和结缔组织","淋巴细胞和淋巴组织","上皮细胞和肉芽组织","成纤维细胞和肌组织","不稳定细胞和组织"],"a":2,"e":"溃疡愈合由底部肉芽组织填补缺损，边缘上皮细胞增生并覆盖创面，二者共同完成修复。肌细胞再生能力弱，不能填补溃疡；淋巴细胞不参与组织填充；不稳定细胞仅指增生活跃的上皮细胞本身"},{"q":"下列能反映小叶性肺炎的本质的是","o":["支气管及肺泡的化脓性炎症","支气管及肺泡的纤维素性炎症","支气管及肺泡的卡他性炎症","支气管及肺泡的出血性炎症","支气管及肺泡结构的破坏"],"a":0,"e":"小叶性肺炎的本质是以细支气管为中心、累及周围肺泡的急性化脓性炎症，故又称支气管肺炎，病灶散在分布于两肺下叶和背侧。B项纤维素性炎见于大叶性肺炎；C项卡他性炎为黏膜的浆液性渗出；D项出血性炎见于流行性出血热、炭疽；E项结构破坏是炎症的结果而非本质"},{"q":"胃癌最主要的转移途径是","o":["直接扩散","淋巴道转移","血行转移","腹腔内种植","盆腔内种植"],"a":1,"e":"胃癌最主要转移途径为淋巴道转移，癌细胞侵入胃壁淋巴管，先至局部淋巴结，晚期可经胸导管转移至左锁骨上淋巴结。胃内播散和直接蔓延属局部扩散；血道转移多见于晚期；种植性转移可形成卵巢Krukenberg瘤，但均非主要途径"},{"q":"细小动脉壁玻璃样变最常发生于","o":["心、脾、肺、视网膜等处的细动脉","肾、脑、脾、视网膜等处的细动脉","心、肝、肾、脑等处的细动脉","肺、胰、脾、肠等处的细动脉","肺、脑、脾、视网膜等处的细动脉"],"a":1,"e":"细小动脉壁玻璃样变常见于缓进型高血压和糖尿病，最易累及肾入球动脉、脑和脾的细小动脉以及视网膜动脉。A、C项列入心、肝、肺，D、E项以肺、胰、肠为主，均不符。心、肝的细动脉不是好发部位，肺循环以毛细血管床受累为主，细小动脉玻璃样变不明显"},{"q":"化脓菌入血、生长繁殖、产生毒素、形成多发性脓肿，最合适的病名是","o":["脓毒败血症","毒血症","败血症","菌血症","噬血症"],"a":0,"e":"化脓菌入血并在血中繁殖、产生毒素，同时在全身多个器官形成栓塞性脓肿，称脓毒败血症，多继发于金黄色葡萄球菌引起的化脓性病灶。仅细菌入血而无症状为菌血症，毒素入血致中毒症状为毒血症，细菌繁殖产毒引起全身中毒症状为败血症"},{"q":"慢性肾盂肾炎与慢性硬化性肾小球肾炎的肉眼区别主要是","o":["体积缩小","质地变硬","肾内小动脉硬化","颜色苍白","表面有不规则的凹陷性瘢痕"],"a":4,"e":"慢性肾盂肾炎双肾不对称缩小，表面有不规则、宽大的凹陷性瘢痕，切面肾盂肾盏变形。慢性硬化性肾小球肾炎双肾对称缩小，表面呈弥漫细颗粒状。体积缩小、质地变硬、颜色苍白为两者共有，不能作为鉴别点"},{"q":"关于流行性乙型脑炎的叙述，下列哪项是正确的","o":["乙脑病毒属于DNA病毒","有较多的中性粒细胞围血管浸润","镂空筛状软化灶形成具有一定的诊断意义","小胶质细胞越多，预后越好","出现脑膜刺激征基本上可排除脑炎"],"a":2,"e":"乙脑病变严重时神经组织发生液化性坏死，形成染色浅淡、质地疏松的镂空筛网状软化灶，对本病诊断具特征性意义。乙脑病毒为RNA病毒。浸润细胞以淋巴细胞、单核细胞及小胶质细胞为主。小胶质细胞结节提示病变活动，与预后无关；脑膜刺激征不能排除脑炎"},{"q":"膜增生性肾小球肾炎可伴有下列哪种表现","o":["明显血尿","脂滴沉积","红细胞增多症","IgA沉积","低补体血症"],"a":4,"e":"膜增生性肾小球肾炎由循环免疫复合物沉积或补体替代途径异常激活所致，Ⅱ型者血清C3明显降低而C1、C4正常，故常伴低补体血症。脂滴沉积见于微小病变性肾小球病，IgA沉积为IgA肾病的免疫荧光特征，明显血尿多见于急性弥漫性增生性肾炎"},{"q":"患者，男，58岁，进行性声嘶2个月，伴吞咽困难，临床检查示喉部新生物。活检镜下如图，正确的诊断是","o":["喉乳头状瘤","喉恶性淋巴瘤侵及固有腺体","喉低分化鳞状细胞癌侵及固有腺体","喉腺癌","喉高分化鳞状细胞癌侵及固有腺体"],"a":2,"e":"本题原题配有图片，图片未随文档保留，以下解析依文字线索推断：题干涉及图片/信息缺失，无法作答。喉癌以鳞状细胞癌多见，低分化者异型性大、核分裂多、角化少，可侵及固有腺体；高分化者角化明显、可见癌珠。喉乳头状瘤为良性，腺癌源于腺上皮，恶性淋巴瘤为淋巴组织来源，确诊需依赖镜下图片鉴别分化程度与浸润\n\n官方题库中缺失图片"},{"q":"下列哪种出血不属于破裂性出血","o":["慢性纤维空洞型肺结核大咯血","肝硬化食管-胃底静脉曲张大呕血","十二指肠溃疡柏油样便","胃癌呕血","肺淤血性出血"],"a":4,"e":"破裂性出血由心脏或血管壁破裂所致，出血量大，如肺结核空洞大咯血、食管胃底静脉曲张破裂呕血、溃疡侵蚀血管致柏油样便、胃癌呕血。肺淤血性出血因毛细血管通透性增高、红细胞漏出所致，属漏出性出血，出血量小、呈点状"},{"q":"下列哪种最支持恶性肿瘤的形态","o":["肿瘤与周围组织分界不清","囊性变","出血、坏死","病理性核分裂","质硬"],"a":3,"e":"病理性核分裂象表现为染色体分派紊乱、不对称或多极分裂，是恶性肿瘤细胞异型性的核心表现。分界不清、出血坏死、质地坚硬在良性肿瘤合并感染或生长迅速时也可出现，特异性不足"},{"q":"伤寒小结的组成主要是","o":["伤寒细胞、中性粒细胞","多核巨细胞、上皮样细胞","上皮样细胞、淋巴细胞","巨噬细胞、伤寒细胞","淋巴细胞、浆细胞"],"a":3,"e":"伤寒小结由吞噬伤寒沙门菌、红细胞和细胞碎片的巨噬细胞即伤寒细胞聚集而成，属感染性肉芽肿，故其成分为巨噬细胞与伤寒细胞。中性粒细胞不是主要成分；多核巨细胞、上皮样细胞为结核结节的特征；淋巴细胞、浆细胞仅少量分布于结节周围"},{"q":"有Ph1染色体标志的主要是","o":["急性粒细胞白血病","慢性粒细胞白血病","慢性淋巴细胞白血病","急性淋巴细胞白血病","急性单核细胞白血病"],"a":1,"e":"Ph1染色体即t(9;22)形成的BCR-ABL融合基因，是慢性粒细胞白血病的标志，见于90%以上患者。急性粒细胞白血病可有其他核型异常；急性单核细胞白血病以t(9;11)等多见；急性淋巴细胞白血病仅少数携Ph1；慢淋以+12常见"},{"q":"慢性硬化性肾小球肾炎的晚期发生高血压的最主要原因是","o":["肾小球滤过率减少","少尿","肾小管重吸收增加","肾素分泌增加","高脂血症"],"a":3,"e":"慢性硬化性肾小球肾炎晚期肾组织缺血、入球小动脉硬化，球旁细胞肾素分泌增多，经肾素-血管紧张素-醛固酮系统使血压持续升高，水钠潴留亦加重高血压。肾小球滤过率减少与少尿是肾功能减退的表现，非升压原因。高脂血症不参与本病的血压升高机制"},{"q":"革囊胃是指","o":["胃癌伴胃扩张","胃黏液癌","胃癌弥漫浸润型","胃溃疡广泛瘢痕形成","范围较大的溃疡型胃癌"],"a":2,"e":"革囊胃为胃癌弥漫浸润型，癌组织在胃壁内弥漫浸润并伴大量纤维组织增生，胃壁增厚变硬、胃腔缩小，状如皮革袋。胃黏液癌呈胶冻样；伴胃扩张、溃疡型均不符合；胃溃疡瘢痕形成可致胃变形，但不称革囊胃"},{"q":"下列关于蜂窝织炎的叙述，正确的是","o":["常由草绿色链球菌感染引起","常见部位是内脏器官、肌肉和阑尾","病变特点与链球菌分泌的链激酶和透明质酸酶有关","细菌不容易经组织间隙、淋巴管和血道蔓延扩散","常有明显的组织坏死和脓肿形成"],"a":2,"e":"蜂窝织炎多由溶血性链球菌引起，其分泌的透明质酸酶降解透明质酸、链激酶溶解纤维蛋白，细菌易经组织间隙和淋巴管弥漫扩散，与周围界限不清，一般无明显坏死和脓肿。草绿色链球菌与亚急性感染性心内膜炎相关；常见部位是皮肤、肌肉和阑尾"},{"q":"如图，心肌梗死后很少出现下列哪种改变","o":["梗死灶呈地图形","梗死灶心肌细胞再生","贫血性梗死","梗死灶周围充血出血带","继发附壁血栓形成"],"a":1,"e":"本题原题配有图片，图片未随文档保留，以下解析依文字线索推断：题干涉及图片/信息缺失，无法作答。心肌梗死属贫血性梗死，梗死灶灰白、形状不规则，周边有充血出血带，可继发附壁血栓。心肌细胞为永久性细胞，坏死后由纤维瘢痕修复，不能再生，故梗死灶内心肌细胞再生很少出现，也是其功能难以恢复的原因\n\n官方题库中缺失图片"},{"q":"同时累及脑膜、肾、肺、肠及骨的肉芽肿性病变常常是","o":["风湿小体","伤寒小体","麻风小结","矽结节","结核结节"],"a":4,"e":"结核分枝杆菌经血道播散可同时累及脑膜、肾、肺、肠和骨，各器官均形成结核结节伴干酪样坏死。伤寒小体见于回肠末段淋巴组织及肝脾；麻风小结见于皮肤和周围神经；矽结节仅见于肺和肺门淋巴结"},{"q":"左心室附壁血栓可引起","o":["心力衰竭","肺淤血","脑动脉栓塞","肺动脉栓塞","心壁穿孔"],"a":2,"e":"左心室附壁血栓位于体循环动脉系统的上游，脱落后栓子经主动脉进入脑、脾、肾及下肢动脉，引起脑动脉栓塞而致脑梗死。肺动脉栓塞的栓子来自下肢深静脉或右心；肺淤血由左心衰竭引起，与栓子无关；心力衰竭和心壁穿孔不是血栓脱落的结果"},{"q":"风湿性心内膜炎，心瓣膜上的赘生物为","o":["透明血栓","白色血栓","红色血栓","混合血栓","微血栓"],"a":1,"e":"风湿性心内膜炎的赘生物为白色血栓，由血小板和纤维蛋白构成，位于瓣膜闭锁缘、单行排列、不易脱落。透明血栓见于毛细血管内，红色血栓见于静脉，混合血栓见于静脉体部及心腔"},{"q":"下列哪项最能体现原位癌的特征","o":["发生于子宫颈黏膜上皮","是一种早期癌","癌变波及全层，但未突破基底膜","未发生转移","可长期保持原来结构，甚至消退"],"a":2,"e":"原位癌的本质是异型增生细胞累及上皮全层，形态和生物学特性同癌细胞，但未突破基底膜向下浸润，故尚无转移条件。A项子宫颈只是常见部位之一，非特征；B项早期癌还包括已浸润的黏膜内癌；D项未转移是结果，不能界定原位癌；E项长期保持或消退仅见于少数病例。是否突破基底膜是关键界限"},{"q":"一期愈合的特点不包括","o":["创缘整齐，对合严密","无感染与异物","愈合时间较短","愈合后常遗留下较大瘢痕","肉芽组织第3天即可从伤口边缘长出"],"a":3,"e":"一期愈合见于创缘整齐、对合严密、无感染和异物的伤口，仅有少量血凝块，表皮在24～48小时覆盖创面，肉芽组织第3天从伤口边缘长出，愈合快、瘢痕小。遗留较大瘢痕是二期愈合的特点。一期愈合的伤口炎症反应轻微，24～48小时表皮即可覆盖，故瘢痕呈线状而细小"},{"q":"下列哪项属于早期食管癌的必要条件","o":["癌变面积小于1.0cm","浸润深度未超过黏膜下层","无明显临床症状","无淋巴结转移","钡餐检查可有局限性僵硬"],"a":1,"e":"早期食管癌指癌组织限于黏膜层或黏膜下层、未侵及肌层，且无淋巴结转移，浸润深度是必要条件。癌变面积大小不作界定，早期癌可呈斑块、糜烂或隐伏型。无明显症状为常见表现但非诊断条件。钡餐见局限性僵硬提示浸润性生长，属进展期表现"},{"q":"肺硅沉着病的特征性病变是","o":["玻璃样硅结节形成","肺间质纤维化","肺间质纤维化玻璃样变","硅肺性空洞形成","胸膜纤维化"],"a":0,"e":"硅肺的基本病变是硅结节形成与肺组织弥漫性纤维化，硅结节境界清楚、灰白色、质硬有沙砾感，中心发生玻璃样变。肺间质纤维化虽并存但非特征性；硅肺性空洞由结节融合坏死形成，见于晚期重症"},{"q":"肉芽组织转化为瘢痕组织的过程，下列哪项是错误的","o":["毛细血管闭塞、数目减少","胶原纤维增多","成纤维细胞减少","炎细胞增多","间质的水分逐渐吸收减少"],"a":3,"e":"肉芽组织成熟为瘢痕时，毛细血管闭塞、数目减少，成纤维细胞转变为纤维细胞并减少，胶原纤维增多，间质水分被吸收，炎细胞逐渐减少而非增多，故该项错误。瘢痕组织由致密胶原构成，血供少、质地硬，可致器官挛缩变形"},{"q":"关于肉芽组织的结局，下列叙述正确的是","o":["最终填补缺损","最终纤维化形成瘢痕","抗感染的过程","产生细胞外基质的过程","分泌大量生长因子，调控细胞增生的过程"],"a":1,"e":"肉芽组织由新生毛细血管、成纤维细胞和炎细胞构成，最终血管闭塞减少、胶原增多、细胞减少，转变为瘢痕组织。填补缺损、抗感染、产生细胞外基质、分泌生长因子分别是其过程和功能，不属于结局"},{"q":"关于绒毛膜癌的叙述，下列哪项是错误的","o":["可见绒毛","侵袭血管是其生物学特性","引起组织出血、坏死","50%继发于葡萄胎","常浸润子宫肌层"],"a":0,"e":"绒毛膜癌由滋养层细胞恶性增生形成，镜下只见异型滋养层细胞和坏死出血，不形成绒毛或水泡状结构，这是与葡萄胎、侵蚀性葡萄胎的根本区别，故该项错误。B项侵袭血管、C项出血坏死、E项浸润肌层均为其恶性生物学行为，D项约半数继发于葡萄胎亦正确"},{"q":"直肠癌最常见的症状是","o":["肠梗阻","体重减轻","贫血","大便习惯改变","黏液血便"],"a":4,"e":"直肠癌位于盆腔，癌组织易溃破出血并分泌黏液，黏液血便出现早且最常见，常为首发症状。大便习惯改变表现为排便次数增多与里急后重，多与黏液血便并存。贫血与体重减轻属慢性失血和消耗的全身表现，肠梗阻多见于肿块增大致肠腔狭窄的晚期病例"},{"q":"关于鼻咽癌的转移，说法不正确的是","o":["约半数以上患者以颈部淋巴结肿大就诊","主要转移至颈部浅淋巴结","颈部淋巴结转移常为同侧","侵犯颅底骨主要破坏卵圆孔处","可侵犯耳咽管至中耳"],"a":1,"e":"鼻咽癌主要转移至颈深上淋巴结即颈上部深处的淋巴结，而非颈部浅淋巴结，且多为同侧。半数以上患者以颈部肿块就诊；癌易破坏颅底卵圆孔，并可经咽鼓管侵入中耳引起听力下降"},{"q":"下列哪项不是肝细胞癌镜下表现的主要特点","o":["癌巢间有大量纤维组织分割，状似假小叶","癌细胞呈小梁状排列","癌组织间富于血窦","癌组织呈腺泡样，内可含胆汁","癌细胞与肝细胞较相似"],"a":3,"e":"官方答案为【癌组织呈腺泡样，内可含胆汁】，但依据教材，正确答案为【癌巢间有大量纤维组织分割，状似假小叶】。肝细胞癌镜下癌细胞与肝细胞相似，呈小梁状或索状排列，癌巢间血窦丰富，也可形成腺泡样结构并分泌胆汁，故该项实为肝细胞癌的常见表现。癌巢间大量纤维组织分割、状似假小叶是肝硬化及纤维板层型肝癌的改变"},{"q":"下列哪项属于癌前疾病","o":["阑尾炎","乳腺纤维腺瘤","纤维囊性乳腺病","慢性肥厚性胃炎","韧带样瘤"],"a":2,"e":"纤维囊性乳腺病伴导管上皮增生和不典型增生时有恶变倾向，属于癌前疾病。B项乳腺纤维腺瘤为良性肿瘤，恶变率极低，不列为癌前病变；D项慢性肥厚性胃炎与癌变关系不明确，真正的癌前胃病是慢性萎缩性胃炎伴肠上皮化生"},{"q":"癌与肉瘤的最主要区别是","o":["瘤细胞的分布方式不同","组织来源不同","肿瘤内血管多少不同","转移的途径不同","发生的年龄不同"],"a":1,"e":"癌起源于上皮组织，癌细胞呈巢状排列，多经淋巴道转移；肉瘤起源于间叶组织，细胞间有网状纤维，多经血行转移。组织来源不同是最本质区别，发生年龄、血管多少、转移途径均为由此派生的差异"},{"q":"关于结节性甲状腺肿的叙述，下列哪项是错误的","o":["甲状腺滤泡过度扩大，大小差别明显","结节内常有出血、坏死、纤维增生等改变","结节边界清楚，有完整包膜","结节常为多个，大小不等","病变后期滤泡上皮增生与复旧不一致，分布不均"],"a":2,"e":"结节性甲状腺肿的结节常为多个、大小不等，境界虽清楚但无完整包膜，周围甲状腺组织无压迫现象并可见相似病变，故该项错误。A项滤泡过度扩大、大小差别明显，B项结节内出血坏死纤维增生，E项后期滤泡上皮增生与复旧不一致、分布不均，均符合本病。单发、有完整包膜是甲状腺腺瘤的鉴别要点"},{"q":"诊断肺心病主要诊断标准是","o":["肺动脉下2cm处，右室壁厚大于5mm","肺动脉圆锥膨隆","右心室扩张","心脏增大","心尖钝圆"],"a":0,"e":"肺心病病理诊断主要标准为肺动脉瓣下2cm处右心室前壁肌层厚度超过5mm，反映右室肥厚。肺动脉圆锥膨隆、右心室扩张、心脏增大、心尖钝圆均为伴随表现，但不是主要量化诊断标准"},{"q":"下列细胞中来源与巨噬细胞无关的是","o":["泡沫细胞","Aschoff细胞","伤寒细胞","印戒细胞","类上皮细胞"],"a":3,"e":"印戒细胞是黏液腺癌的癌细胞，胞质内充满黏液将核挤向一侧，来源于上皮组织，与巨噬细胞无关。A项泡沫细胞由巨噬细胞吞噬脂质形成；B项Aschoff细胞是风湿病灶中巨噬细胞来源的细胞；C项伤寒细胞为吞噬伤寒杆菌及碎片的巨噬细胞；E项类上皮细胞由巨噬细胞转化而来"},{"q":"关于胃癌的转移途径的叙述，下列哪项是错误的","o":["癌细胞脱落种植于盆腔器官","血行转移至肝脏","癌细胞脱落种植于十二指肠壁","淋巴道转移至所属局部淋巴结","淋巴道转移至大网膜淋巴结"],"a":2,"e":"胃癌可经血行转移至肝，经淋巴道转移至局部及大网膜淋巴结，脱落细胞种植于盆腔器官如卵巢形成Krukenberg瘤。癌细胞不会种植于十二指肠壁，该处蠕动活跃且非种植转移靶点，故为错误项"},{"q":"肝穿刺活检，镜下可见弥漫性肝细胞细胞质疏松化，气球样变，点状坏死及嗜酸性小体形成，汇管区有轻度炎细胞浸润。应诊断为","o":["急性普通型肝炎","慢性中度肝炎","肝硬化","急性重型肝炎","亚急性重型肝炎"],"a":0,"e":"肝细胞弥漫性疏松化、气球样变伴点状坏死和嗜酸性小体形成，汇管区轻度炎细胞浸润，是急性普通型肝炎的典型改变，坏死范围小而散在。慢性中度肝炎有碎片状坏死和桥接坏死；重型肝炎为大片或亚大块坏死；肝硬化可见假小叶"},{"q":"金黄色葡萄球菌的层粘连蛋白受体能","o":["使病变易于局限","容易形成溃疡","容易形成窦道","容易形成转移性脓肿","使组织容易受损"],"a":3,"e":"金黄色葡萄球菌具有层粘连蛋白受体，易黏附并穿过血管内皮与基底膜，随血流在远隔部位形成迁徙性脓肿。其产生的凝血酶使纤维蛋白原转为纤维蛋白，反而使原发病灶局限，故使病变局限是凝血酶的作用而非受体功能；窦道形成与组织受损均无特异性"},{"q":"下列哪种为癌基因","o":["ras基因","P53基因","Rb基因","APC基因","NF-1基因"],"a":0,"e":"ras编码小G蛋白，点突变后持续激活增殖信号，属显性癌基因。P53与Rb是经典抑癌基因，分别阻滞细胞周期和抑制E2F转录；APC、NF-1亦为抑癌基因，需失活才促癌，均非癌基因"},{"q":"栓子最确切的定义是","o":["循环血液内的有形成分","循环血液内不溶于血液的异常物质","循环血液内脱落的血栓","循环血液内脱落的肿瘤团块","循环血液内的脂肪滴"],"a":1,"e":"栓子指循环血液中不溶于血液、随血流运行并堵塞血管的异常物质，概念最确切。循环血液内的有形成分指血细胞；脱落血栓、肿瘤团块、脂肪滴仅为栓子的具体种类，不能涵盖全部栓子，均非最确切定义"},{"q":"下列哪种肿瘤的发生与EB病毒感染密切相关","o":["胃癌","鼻咽癌","膀胱癌","肺癌","胰腺癌"],"a":1,"e":"EB病毒与鼻咽癌关系密切，癌细胞中可检出EB病毒DNA和核抗原，低分化鳞癌尤为相关，EB病毒还引起Burkitt淋巴瘤。胃癌与幽门螺杆菌相关，肺癌与吸烟相关，膀胱癌与芳香胺类相关，胰腺癌与吸烟及K-ras突变相关"},{"q":"对图示炎症细胞描述正确的是","o":["出现在炎症的早期","出现在炎症的晚期","出现在化脓性炎中","出现在脓肿中","出现在假膜性炎"],"a":1,"e":"本题原题配有图片，图片未随文档保留，以下解析依文字线索推断：题干涉及图片/信息缺失，无法作答。若图示为淋巴细胞、浆细胞和单核细胞浸润，则见于慢性炎症，多在炎症后期出现。中性粒细胞浸润见于炎症早期及化脓性炎，脓肿中以大量中性粒细胞与坏死物为特征。假膜性炎以纤维蛋白渗出伴黏膜坏死形成假膜为特点\n\n官方题库中缺失图片"},{"q":"按发病率递减的顺序，食管癌最常见的部位依次是","o":["食管上段、中段、下段","食管中段、下段、上段","食管上段、下段、中段","食管中段、上段、下段","各段分布相等"],"a":1,"e":"食管癌好发部位以中段最多，约占50%，下段次之，上段最少。鳞癌多位于中段，腺癌多位于下段，与Barrett食管相关。故按发病率递减为食管中段、下段、上段。食管上段癌少见，确诊时多已较晚，故三段的发病率与就诊难度并不平行"},{"q":"静脉血栓形成时，不易发生的结局是","o":["脱落","机化","血流完全恢复正常","钙化","再通"],"a":2,"e":"静脉血栓形成后可脱落造成栓塞、机化、再通或钙化形成静脉石，但机化后管腔多遗留狭窄或闭塞，血流不可能完全恢复正常。B项机化、E项再通均为常见转归；D项钙化可见于陈旧血栓，只有血流完全恢复正常不会发生"},{"q":"骨肉瘤是指","o":["骨原发性的恶性肿瘤，有反应性骨质增生","肉瘤细胞直接形成肿瘤性骨样组织或骨组织的肿瘤","骨组织起源的肉瘤","骨组织中肉瘤的总称","骨组织来源的未分化肿瘤"],"a":1,"e":"骨肉瘤的特征是肿瘤细胞异型明显并直接形成肿瘤性骨样组织或骨组织，这是病理诊断最重要的依据。骨肉瘤并非泛指骨组织的肉瘤，也不是骨原发恶性肿瘤伴反应性骨质增生；软骨肉瘤、尤文肉瘤等虽源于骨，但不形成肿瘤性骨"},{"q":"早期大肠癌是","o":["局限于黏膜层及黏膜下层的癌","侵及黏膜下层的癌","侵及浅肌层的癌","无淋巴结转移的癌","直径小于2cm的癌"],"a":0,"e":"早期大肠癌指癌组织浸润限于黏膜层或黏膜下层，无论有无淋巴结转移。侵及肌层者属进展期癌；淋巴结转移状态不作为早期判定标准；直径大小仅用于早期胃癌中微小癌、小胃癌的划分"},{"q":"地方性甲状腺肿的主要病因是","o":["遗传因素","机体对碘或甲状腺素需求量增加","长期摄入大量钙","缺碘","吃海产品过多"],"a":3,"e":"地方性甲状腺肿的主要病因是土壤、水和食物缺碘，甲状腺素合成减少，TSH分泌增多，滤泡上皮增生并胶质贮积，形成弥漫性或结节性甲状腺肿。青春期、妊娠期碘需求增加属相对缺碘；摄碘过多、长期高钙饮食仅少数致甲状腺肿"},{"q":"流行性脑脊髓膜炎中，病原菌主要侵犯","o":["大脑皮质","额、顶叶及脑干","硬脑膜","蛛网膜下腔","丘脑及基底神经核"],"a":3,"e":"流脑由脑膜炎双球菌引起，主要侵犯软脑膜和蛛网膜下腔，形成化脓性炎，蛛网膜下腔充满脓性渗出物。大脑皮质、额顶叶及脑干、丘脑基底节为脑实质，硬脑膜病变均非流脑主要侵犯部位"},{"q":"关于胰腺癌的叙述，错误的是","o":["以胰尾部最多见","患者年龄多在60~80岁","可发生于胰头、体、尾部或累及整个胰腺","男性多于女性","大部分病例有K-ras基因突变"],"a":0,"e":"胰腺癌可发生于胰头、体、尾或弥漫累及全胰，但以胰头最常见（约60%～70%），故以胰尾部最多见的说法错误。B项好发60～80岁、D项男性多于女性、E项大部分有K-ras基因突变均符合胰腺癌特点；C项可累及各部本身无误，错的只是把最好发部位说成胰尾"},{"q":"在月经周期中子宫内膜腺体和间质明显增生，腺体数目增多，上皮呈高柱状，呈假复层排列，核椭圆形，由底部移向细胞中央，间质中可见有丝分裂，此时月经周期是","o":["增生晚期","分泌早期","增生早期","分泌晚期","月经前期"],"a":0,"e":"增生晚期即第11~14天，内膜腺体数目增多、显著增生弯曲，上皮呈高柱状假复层、核椭圆形并由基底移向中央，间质细胞有丝分裂活跃。增生早期腺体少而直；分泌期出现核下空泡与顶浆分泌"},{"q":"关于乳腺纤维腺瘤的叙述，错误的是","o":["是最常见的乳腺良性肿瘤","好发于20～30岁的青年女性","多为单侧","恶变率较高","分为管内型和管周型"],"a":3,"e":"乳腺纤维腺瘤是最常见的乳腺良性肿瘤，好发20～30岁青年女性，多为单侧，分管内型与管周型，恶变率极低。“恶变率较高”与事实不符，故为错误叙述"},{"q":"霍奇金淋巴瘤按预后好坏，排列顺序为","o":["混合细胞型，淋巴细胞减少型，结节硬化型，淋巴细胞为主型","淋巴细胞为主型，结节硬化型，淋巴细胞减少型，混合细胞型","淋巴细胞减少型，混合细胞型，结节硬化型，淋巴细胞为主型","淋巴细胞为主型，结节硬化型，混合细胞型，淋巴细胞减少型","淋巴细胞减少型，淋巴细胞为主型，结节硬化型，混合细胞型"],"a":3,"e":"经典型霍奇金淋巴瘤预后由好至差依次为淋巴细胞为主型、结节硬化型、混合细胞型、淋巴细胞减少型，淋巴细胞越多、瘤细胞越少者预后越好。淋巴细胞减少型瘤细胞多形、背景细胞稀少，预后最差。结节硬化型预后居中偏良，混合细胞型次之"},{"q":"膀胱癌的最好发部位是","o":["膀胱后壁","任何部位均可发生","膀胱前壁","膀胱侧壁和三角区","膀胱顶"],"a":3,"e":"膀胱癌好发于膀胱侧壁及三角区近输尿管开口处，该处黏膜与尿液接触时间长、致癌物浓度高，移行上皮长期受芳香胺类代谢物作用易癌变。前壁、后壁、顶部发生率明显为低，故不能笼统称任何部位均可发生"},{"q":"病毒性肝炎时最常见的肝细胞变性是","o":["嗜酸性变","脂肪变性","细胞水肿","玻璃样变","黏液样变"],"a":2,"e":"病毒性肝炎最常见的肝细胞变性是细胞水肿，因钠泵功能障碍致水钠潴留，轻者胞质疏松，重者气球样变。嗜酸性变仅累及个别肝细胞并形成嗜酸性小体；脂肪变性多见于酒精性肝病；玻璃样变见于酒精性透明小体"},{"q":"在葡萄球菌感染的炎症反应中所见到的炎细胞主要是","o":["淋巴细胞","单核细胞","嗜酸性粒细胞","肥大细胞","中性粒细胞"],"a":4,"e":"葡萄球菌和链球菌感染以中性粒细胞浸润为主，中性粒细胞趋化快、吞噬和杀菌能力强，是急性化脓性炎的主要效应细胞。A项淋巴细胞见于病毒感染和慢性炎症；B项单核细胞多在24～48小时后接替；C项嗜酸性粒细胞见于寄生虫感染和过敏反应；D项肥大细胞参与Ⅰ型超敏反应"},{"q":"下列哪项是变质性炎","o":["流行性脑脊髓膜炎","细菌性痢疾","大叶性肺炎","阿米巴肝脓肿","化脓性胆囊炎"],"a":3,"e":"阿米巴肝脓肿以溶组织内阿米巴分泌溶酶破坏肝组织、形成液化性坏死为主，属变质性炎。流行性脑脊髓膜炎为化脓性炎，细菌性痢疾为假膜性炎，大叶性肺炎为纤维素性炎，化脓性胆囊炎为化脓性炎"},{"q":"白色血栓主要由下列哪些成分构成","o":["白细胞、纤维素和血小板","血小板和纤维素","红细胞和白细胞","红细胞和纤维素","血小板和红细胞"],"a":1,"e":"白色血栓见于血流较快的心瓣膜与动脉内，由血小板小梁和纤维素构成，肉眼呈灰白色。混合血栓由血小板梁与红细胞层交替构成；红色血栓以红细胞和纤维蛋白为主，见于静脉；透明血栓为微循环内的纤维蛋白血栓"},{"q":"下列配对哪项是错误的","o":["皮肤表层水疱－化脓性炎","大叶性肺炎－纤维素性炎","风湿性关节炎－浆液性炎","结核病－肉芽肿性炎","皮肤疖－化脓性炎"],"a":0,"e":"皮肤表层水疱是浆液性渗出物在表皮内或表皮下积聚所致，如Ⅱ度烧伤水疱，与化脓性炎无关。大叶性肺炎为肺泡内纤维蛋白性炎，风湿性关节炎为滑膜浆液性炎，结核病为感染性肉芽肿性炎，皮肤疖为毛囊及周围组织的脓肿"},{"q":"下列属于肿瘤的是","o":["错构瘤","动脉瘤","室壁瘤","创伤性神经瘤","骨软骨瘤"],"a":4,"e":"骨软骨瘤由骨、软骨帽及纤维膜构成，是最常见的良性骨肿瘤，具有肿瘤性增生的结构。错构瘤是局部组织成分比例与排列异常形成的瘤样畸形，并非真性肿瘤；动脉瘤、室壁瘤分别为血管壁和心室壁的局限性膨出。创伤性神经瘤是神经断端的修复性增生，同属瘤样病变"},{"q":"下面叙述中不符合2型糖尿病的是","o":["成年发病，起病较轻，发展缓慢","无抗胰岛细胞抗体","胰岛数目正常或轻度减少","血胰岛素水平明显降低","肥胖者多见"],"a":3,"e":"2型糖尿病以胰岛素抵抗为主，β细胞早期可代偿，血胰岛素水平多正常或升高，不会明显降低。A项成年起病、起病缓符合；B项无抗胰岛细胞抗体，是与1型自身免疫性胰岛炎的关键区别；C项胰岛数目大致正常，仅1型才明显减少"},{"q":"下述关于脑动脉粥样硬化的叙述中，哪项是错误的","o":["大脑前动脉病变最重","脑动脉粥样硬化的发生比冠状动脉晚","继发脑动脉血栓形成","可引起脑软化","可引起小动脉瘤"],"a":0,"e":"脑动脉粥样硬化最常见于颈内动脉起始部、基底动脉、大脑中动脉和基底动脉环，其中大脑中动脉病变最重，故大脑前动脉病变最重错误。B项发生较冠状动脉晚、C项斑块溃疡可继发血栓形成、D项管腔狭窄引起脑软化、E项可形成小动脉瘤并破裂出血，均正确"},{"q":"乳腺癌表面皮肤橘皮样变是因为","o":["肿瘤细胞直接浸润表皮","肿瘤体积过大，压迫皮肤","肿瘤压迫静脉导致血液回流受阻","肿瘤细胞阻塞淋巴管导致淋巴液回流受阻而使皮肤水肿","肿瘤侵犯Cooper韧带所致"],"a":3,"e":"癌细胞阻塞真皮内淋巴管，淋巴液回流受阻致皮肤水肿，毛囊汗腺处组织致密相对下陷，形成橘皮样外观。A项直接浸润表皮形成癌性溃疡；E项侵犯Cooper韧带并使其缩短，引起乳头下陷和皮肤凹陷。C项静脉受压所致者为淤血性水肿，不产生橘皮样改变"},{"q":"不属于特异性心肌病的是","o":["致心律失常性右室心肌病","克山病","酒精性心肌病","围生期心肌病","药物性心肌病"],"a":0,"e":"原发性心肌病包括扩张型、肥厚型、限制型、致心律失常性右室心肌病及未分类心肌病；特异性心肌病指有明确病因者。克山病、酒精性心肌病、围生期心肌病、药物性心肌病均有已知病因，属特异性心肌病"},{"q":"髓母细胞瘤最常见的发生部位在","o":["大脑皮质","垂体","脑桥","小脑蚓部","延髓"],"a":3,"e":"髓母细胞瘤起源于小脑胚胎性外颗粒层细胞或室管膜下基质细胞，约75%的儿童病例位于小脑蚓部并突入第四脑室，易致颅内压增高与脑脊液播散。大脑皮质为胶质瘤好发部位，垂体多见腺瘤，脑桥与延髓多见胶质瘤，均非本瘤的典型部位"},{"q":"关于动脉性充血，下列哪项叙述是错误的","o":["细动脉扩张","见于心力衰竭","温度增高","见于减压后","局部呈鲜红色"],"a":1,"e":"动脉性充血时细动脉扩张、血流加快，局部红、热、体积增大，见于炎症早期、进食后及减压后。心力衰竭时静脉回流受阻、静脉压升高，属静脉性淤血，局部紫绀、温度降低，与动脉性充血相反"},{"q":"急性风湿热皮肤表现为","o":["Osler结节","Negri小体","Aschoff小体","环形红斑","McCallum斑"],"a":3,"e":"急性风湿热的皮肤表现以环形红斑和皮下结节最具诊断意义，环形红斑属渗出性病变，多见于躯干四肢，呈淡红色环状红晕而中央色泽正常。Aschoff小体位于心肌间质，属增生性病变而非皮肤表现。Osler结节见于感染性心内膜炎，Negri小体见于狂犬病，McCallum斑为心内膜的风湿性斑块"},{"q":"动脉血栓形成的最重要和最常见的原因是","o":["血流缓慢及涡流形成","血液成分改变","血管内膜损伤","血流速度变快","血液凝固性减低"],"a":2,"e":"心血管内膜损伤使内皮下胶原暴露，激活血小板与凝血因子Ⅻ，同时损伤内皮释放组织因子启动外源性凝血，是动脉血栓形成最重要、最常见的原因，见于粥样斑块溃疡处。血流缓慢及涡流为静脉血栓的主要条件，血液凝固性增高属辅助因素"},{"q":"引起胆囊炎或胆管炎的最常见致病菌是","o":["大肠杆菌","链球菌","真菌","葡萄球菌","伤寒杆菌"],"a":0,"e":"胆道感染多由肠道菌群上行所致，以大肠杆菌最常见，其次为肠球菌、克雷伯菌。链球菌、葡萄球菌多见于血源性感染；真菌见于长期使用广谱抗生素或免疫抑制者；伤寒杆菌可致胆囊带菌，但非胆囊炎常见致病菌"},{"q":"卵巢Krukenberg瘤的原发病灶常在","o":["肺","胃肠道","乳腺","肝脏","子宫内膜"],"a":1,"e":"Krukenberg瘤是转移性卵巢黏液腺癌，原发灶多位于胃肠道（胃、结肠），印戒细胞经腹膜或血道转移至双侧卵巢。C项乳腺癌、E项子宫内膜癌虽可转移至卵巢，但非Krukenberg瘤的典型来源；A项肺、D项肝脏更非其原发部位"},{"q":"胆囊炎最常见于","o":["男性","肥胖的妇女","肝硬化患者","酒精中毒者","Oddi（肝胰壶腹）括约肌慢性痉挛者"],"a":1,"e":"胆囊炎多继发于胆囊结石，肥胖、多产的中年女性因胆固醇代谢紊乱、胆汁胆固醇过饱和而易形成结石并继发炎症，故以肥胖妇女最常见。肝硬化患者与酒精中毒者并非胆囊炎的高发人群。Oddi括约肌慢性痉挛致胆汁淤滞，属少见诱因"},{"q":"导致肾脏体积明显缩小的疾病是","o":["糖尿病肾病","肾脓肿","肾盂积水","慢性硬化性肾小球肾炎","肾梗死"],"a":3,"e":"慢性硬化性肾小球肾炎大量肾小球硬化、肾小管萎缩、间质纤维化，双肾对称缩小、表面呈细颗粒状，称颗粒性固缩肾。糖尿病肾病早期肾体积增大，肾脓肿、肾盂积水均使肾体积增大，肾梗死只形成局限性瘢痕，不致全肾明显缩小"},{"q":"心内膜下心肌梗死的并发症是","o":["心脏破裂","附壁血栓形成","室壁瘤","无菌性纤维素性心包炎","心律失常"],"a":1,"e":"心内膜下心肌梗死累及心室壁内层1/3，坏死区内膜面粗糙，易形成附壁血栓。因梗死限于内层，不发生心脏破裂与室壁瘤；无菌性纤维素性心包炎见于透壁性梗死；心律失常可出现但不属特征性并发症"},{"q":"急性肾盂肾炎的主要病变特点是","o":["以肾盂为主的急性化脓性炎","以肾间质为主的化脓性炎、脓肿形成和肾小管坏死","以肾间质为主的增生性炎","单发性肾脓肿","以肾间质为主的过敏性炎"],"a":1,"e":"急性肾盂肾炎是肾盂、肾间质和肾小管的化脓性炎，镜下见灶状间质性化脓性炎或脓肿形成、肾小管腔内中性粒细胞集聚和肾小管坏死，常为多发小脓肿。慢性肾盂肾炎为慢性间质性炎伴纤维化；过敏性间质性肾炎以嗜酸性粒细胞浸润为特点"},{"q":"酒精性肝病的发病机制中，酒精可以影响脂肪酸的氧化，主要是因为在肝解毒过程中消耗了大量的","o":["二磷酸吡啶核苷酸（NAD）","三磷酸吡啶核苷酸（TPN）","一磷酸腺苷（AMP）","二磷酸腺苷（ADP）","三磷酸腺苷（ATP）"],"a":0,"e":"乙醇在肝内主要经乙醇脱氢酶氧化为乙醛，此过程大量消耗NAD使其转为NADH，NADH/NAD比值升高抑制线粒体脂肪酸β氧化，脂肪合成增加而分解减少，形成脂肪肝。B项TPN即NADP，主要参与合成代谢和抗氧化；C、D、E项AMP、ADP、ATP为腺苷酸，不是脱氢反应辅酶，与脂肪酸氧化抑制无直接关系"},{"q":"血栓的结局不包括","o":["溶解吸收","机化、再通","钙化","脱落形成栓子","肉芽肿形成"],"a":4,"e":"血栓的结局包括溶解吸收、机化再通、钙化形成静脉石、脱落形成栓子。肉芽肿形成为肉芽肿性炎的特征性改变，与血栓转归无关。血栓钙化后质地坚硬，位于静脉内者称静脉石，为影像学上常见的陈旧血栓标志"},{"q":"属于特异性心肌病的是","o":["扩张型心肌病","肥厚性心肌病","限制性心肌病","致心律失常性右室心肌病","克山病"],"a":4,"e":"特异性心肌病指有明确病因或继发于全身疾病者，克山病为硒缺乏所致的地方性心肌病，呈多发灶性坏死与纤维化。扩张型、肥厚型、限制型及致心律失常性右室心肌病均属原发性即特发性心肌病"},{"q":"下列哪项是Goodpasture综合征的主要病变","o":["肺出血合并肾盂肾炎","肺出血合并肾小管坏死","肺出血合并肾小球肾炎","肺水肿合并肾小球肾炎","肺出血合并肾衰竭"],"a":2,"e":"Goodpasture综合征因抗GBM抗体与肺泡毛细血管基膜交叉反应引起肺出血，同时损伤肾小球基膜致新月体性肾炎，故主要病变为肺出血合并肾小球肾炎。肾小管坏死与肾衰竭是肾炎进展的结果，并非主要病变。单纯肺水肿不伴咯血，不符合本征"},{"q":"肺癌的临床表现为","o":["咳嗽，咳铁锈色痰","刺激性干咳，无痰","长期咳嗽，咳白色泡沫痰","咳嗽，咯血，咳大量脓痰","刺激性呛咳，痰中带血"],"a":4,"e":"肺癌肿瘤刺激支气管黏膜引起刺激性干咳或呛咳，癌组织富血管且易坏死溃破，故痰中带血或咯血，两者组合最具提示意义。咳铁锈色痰是大叶性肺炎的典型表现。长期咳白色泡沫痰见于慢性支气管炎，咳大量脓痰见于支气管扩张症，均非肺癌的特点"},{"q":"Behcet（白塞）综合征的临床表现不包括","o":["皮肤结节性红斑","复发性口腔溃疡","生殖器溃疡","消化道溃疡","眼葡萄膜炎"],"a":3,"e":"白塞综合征以复发性口腔溃疡、生殖器溃疡、眼葡萄膜炎和皮肤结节性红斑为主要表现，本质为血管炎。消化道溃疡可见于克罗恩病，也可为肠白塞的受累形式，但不列为该综合征的典型临床表现。口腔与生殖器溃疡反复发作是诊断的主要依据"},{"q":"下列对诊断肥厚性胃炎最有诊断意义的是","o":["腺体萎缩","固有层结缔组织增生","黏膜肥厚，腺体增生肥大，腺体间有慢性炎细胞浸润","胃黏膜上皮细胞异型性增生","腺体肠上皮化生"],"a":2,"e":"肥厚性胃炎表现为胃黏膜肥厚、腺体增生肥大，腺体间有慢性炎细胞浸润，腺体数量与体积均增加，据此可与萎缩性胃炎鉴别。腺体萎缩、肠上皮化生为慢性萎缩性胃炎的特点；固有层结缔组织增生见于溃疡边缘或瘢痕；上皮异型性增生属癌前病变"},{"q":"卡他性炎指的是","o":["皮肤的浆液性炎","浆膜的浆液性炎","黏膜的浆液性炎","关节的浆液性炎","脑膜的浆液性炎"],"a":2,"e":"卡他性炎指黏膜的浆液性炎，渗出物稀薄并沿黏膜表面下流，如感冒初期鼻黏膜排出大量浆液性分泌物，镜下黏膜充血、浆液渗出伴少量炎细胞。浆膜、滑膜、皮肤和疏松结缔组织的浆液性炎不称卡他，如结核性胸膜炎所致胸腔积液"},{"q":"胰腺最常见的恶性肿瘤是","o":["导管腺癌","鳞状细胞癌","腺鳞癌","印戒细胞癌","肉瘤样癌"],"a":0,"e":"胰腺恶性肿瘤中导管腺癌占80%以上，源于导管上皮，呈腺管样结构并伴丰富纤维间质。鳞状细胞癌须经导管上皮鳞化后发生，罕见；腺鳞癌、肉瘤样癌、印戒细胞癌在胰腺均少见，不构成最常见类型"},{"q":"下列肿瘤中最容易经血行转移的是","o":["宫颈鳞状细胞癌","肠黏液腺癌","乳腺浸润性导管癌","绒毛膜癌","肺大细胞癌"],"a":3,"e":"绒毛膜癌滋养层细胞不形成绒毛与血管，直接侵入子宫肌层血窦，故早期即经血行广泛转移至肺、脑、肝。宫颈鳞癌、肠黏液腺癌、乳腺浸润性导管癌以淋巴道转移为主，肺大细胞癌多在晚期才血行转移"},{"q":"病理诊断慢性支气管炎的主要病变指标是","o":["支气管黏膜上皮细胞变性、坏死脱落","支气管壁黏液腺体增生、肥大","支气管壁充血、水肿、炎细胞浸润","支气管黏膜鳞状上皮化生","支气管壁平滑肌、软骨破坏"],"a":1,"e":"慢性支气管炎的病理诊断指标是黏膜下黏液腺体增生肥大、浆液腺黏液腺化生，致黏液分泌增多。上皮变性坏死、充血水肿、炎细胞浸润及鳞状化生均缺乏特异性；平滑肌与软骨破坏见于支气管扩张"},{"q":"关于动物实验，下列描述中哪项是错误的","o":["在适宜的动物身上可以复制某种疾病的动物模型","动物实验的结果可以直接应用于人体","可以了解疾病的病理发展过程","可在一定程度上了解药物或其他因素对某种疾病的疗效和影响","可利用动物研究疾病的病因、发病机制"],"a":1,"e":"动物实验可复制人类疾病模型，研究病因、发病机制与病理过程，并评价药物疗效，但动物与人存在物种差异，结果仅作参考，不能不加分析地直接套用于人体。可复制模型、观察病程、评价疗效等其余各项均正确反映了动物实验的价值与适用范围"},{"q":"漏出性出血的发生机制是由于","o":["组织的渗透压增高","毛细血管壁通透性增加","血管壁周围病变侵犯","血浆胶体渗透压降低","血管机械性损伤"],"a":1,"e":"漏出性出血因毛细血管和毛细血管后静脉通透性增高，红细胞经扩大的内皮间隙和受损基膜漏出，常见于缺氧、感染、中毒、维生素C缺乏及血小板减少。血管机械性损伤与周围病变侵蚀血管属破裂性出血；血浆胶体渗透压降低引起水肿而非出血；组织渗透压增高亦只致水肿"},{"q":"急性重型肝炎的病变，哪项是不正确的","o":["肝细胞大片坏死","肝窦扩张充血","网状支架塌陷","坏死灶及周围有炎细胞浸润","肝细胞再生结节形成"],"a":4,"e":"急性重型肝炎起病急骤，肝细胞弥漫性大片坏死，仅残留网状支架，肝窦扩张充血，坏死区及周围有中性粒细胞、淋巴细胞浸润，库普弗细胞增生；因病程短，肝细胞无明显再生，更无再生结节。再生结节形成见于亚急性重型肝炎及肝硬化"},{"q":"有关溃疡的并发症，下列哪项错误","o":["恶变","出血","幽门狭窄","穿孔","卒中"],"a":4,"e":"消化性溃疡的并发症为出血、穿孔、幽门梗阻和癌变，卒中介入无关。出血由溃疡底部血管被侵蚀破裂所致，穿孔多见于前壁，幽门狭窄由瘢痕收缩与痉挛引起，癌变多见于胃溃疡边缘。卒中属脑血管病变，与溃疡无因果关系"},{"q":"腹股沟疝嵌顿后，疝囊内的肠壁可发生","o":["凝固性坏死","湿性坏疽","干性坏疽","液化性坏死","气性坏疽"],"a":1,"e":"嵌顿疝时肠管静脉回流受阻而动脉供血尚存，肠壁充血水肿出血，加之细菌繁殖腐败，形成水分多、感染重的湿性坏疽。干性坏疽多为动脉阻塞、静脉通畅的肢体末端，干燥；凝固性坏死见心肾梗死，气性坏疽为产气荚膜梭菌感染，液化性坏死见脑与胰腺"},{"q":"不符合大叶性肺炎红色肝样变期病理变化的是","o":["肺泡壁血管贫血状态","肺泡腔内纤维素渗出","患者缺氧严重","肺泡腔内中性粒细胞渗出","肉眼实变，有如肝脏切面"],"a":0,"e":"大叶性肺炎红色肝样变期肺泡壁毛细血管扩张充血，肺泡腔内充满纤维素与中性粒细胞，肉眼实变如肝切面，患者缺氧明显。“肺泡壁血管贫血状态”与充血的事实相反，故为不符合的病变"},{"q":"获得性免疫缺陷综合征患者常见的恶性肿瘤是","o":["尤文氏肉瘤","Kaposi肉瘤","纤维肉瘤","膀胱移行细胞癌","直肠癌"],"a":1,"e":"艾滋病患者免疫缺陷，HHV-8感染引起Kaposi肉瘤，为其最常见的恶性肿瘤，表现为皮肤黏膜紫红色斑块与结节。尤文肉瘤见于儿童骨肿瘤；纤维肉瘤为软组织肉瘤；膀胱移行细胞癌与吸烟、职业接触有关；直肠癌多由腺瘤恶变"},{"q":"下列所有的临床特征中不符合肾病综合征的是","o":["蛋白尿","低蛋白血症","血尿","高脂血症","水肿"],"a":2,"e":"肾病综合征表现为大量蛋白尿超过3.5g/d、低蛋白血症低于30g/L、高度水肿与高脂血症。血尿属肾炎综合征表现，见于急性肾小球肾炎、IgA肾病等，不符合肾病综合征"},{"q":"绝大多数肺癌起源于","o":["支气管腺体","支气管黏膜上皮","Clara细胞","肺泡上皮","细支气管黏膜腺体"],"a":1,"e":"肺癌绝大多数起源于支气管黏膜上皮，鳞癌和小细胞癌多位于段以上支气管，腺癌多位于肺外周。支气管腺体起源者仅构成部分腺癌；Clara细胞与细支气管肺泡癌相关；小细胞癌起源于黏膜上皮的Kulchitsky细胞"},{"q":"炎症反应的最重要的特征是","o":["血清渗出","血浆渗出","纤维素渗出","白细胞渗出","红细胞渗出"],"a":3,"e":"白细胞渗出并聚集于炎症灶是炎症反应最重要的特征，包括边集、滚动、黏附、游出和趋化游走，是机体防御的核心环节。血浆、血清渗出属血管通透性增高的表现，纤维素渗出为纤维蛋白性炎的特点，红细胞漏出为淤血性出血，均不能代表炎症的本质"},{"q":"肿瘤细胞分化程度越低","o":["恶性程度越高","异型性越小","转移越晚","预后越好","对放射治疗越不敏感"],"a":0,"e":"分化程度越低，肿瘤组织形态与正常组织差异越大，异型性越明显，恶性程度越高、转移越早、预后越差。分化高者异型性小、生长缓慢、转移晚、预后较好，对放射治疗的敏感性随分化降低而升高"},{"q":"胃黏膜肠上皮化生最常见于","o":["慢性萎缩性胃炎","慢性胃溃疡","慢性浅表性胃炎","急性刺激性胃炎","先天性肠黏膜异位"],"a":0,"e":"慢性萎缩性胃炎时胃黏膜变薄、腺体减少或消失，伴假幽门腺化生与肠上皮化生，化生上皮出现杯状细胞及吸收细胞，是胃癌的癌前状态。慢性浅表性胃炎腺体完整、无萎缩；急性刺激性胃炎以充血水肿、糜烂为主；先天性肠黏膜异位为发育异常，与化生机制不同"},{"q":"关于甲状腺乳头状癌的叙述，下列不正确的是","o":["本癌发现时约50%已有颈淋巴结转移，因此预后很差","青少年女性多见","为最多见的甲状腺癌","生长较慢，预后较好","肿瘤间质中常见砂粒体"],"a":0,"e":"甲状腺乳头状癌初诊时约半数已有颈淋巴结转移，但分化好、生长缓慢，10年生存率可达80%以上，转移并不等于预后差，故该叙述错误。B项青少年女性多见、C项占甲状腺癌60%为最常见类型、D项生长慢预后好、E项间质常见砂粒体，均与本病相符。颈淋巴结转移对生存影响有限，是其特点之一"},{"q":"下列哪项决定肿瘤的生长速度","o":["肿瘤的生长方式","肿瘤的异型性","机体的免疫力","肿瘤的起源组织","肿瘤的发生部位"],"a":1,"e":"肿瘤生长速度主要由分化程度和异型性决定，分化差、异型性大的瘤细胞增殖活跃，短期内即可形成明显肿块。生长方式影响形态和边界；机体免疫力和发生部位影响病程；起源组织不决定生长快慢。分化差者核分裂象多、倍增时间短，可在数周内迅速增大；良性肿瘤生长常达数年"},{"q":"下列哪项因素与动脉粥样硬化发生关系最为密切","o":["吸烟","高脂血症","高血压","肥胖","遗传因素"],"a":1,"e":"高脂血症，尤其LDL和胆固醇升高，是动脉粥样硬化最重要的危险因素，脂质沉积于内膜下并被巨噬细胞吞噬形成泡沫细胞，是斑块形成的核心环节。吸烟、高血压、肥胖和遗传因素均可促进发病，但作用强度不及高脂血症；高血压主要促进斑块并发症与动脉瘤形成"},{"q":"风湿性心内膜炎最常累及","o":["二尖瓣及主动脉瓣","三尖瓣及肺动脉瓣","三尖瓣","二尖瓣","主动脉瓣"],"a":3,"e":"风湿性心内膜炎最常累及二尖瓣，其次为二尖瓣与主动脉瓣联合受累。三尖瓣、肺动脉瓣受累少见，单独主动脉瓣炎亦不如二尖瓣常见"},{"q":"肥厚型心肌病的病变特点是","o":["两侧心室肥大，四个心腔扩张","常伴有附壁血栓形成","心肌细胞异常肥大，排列方向紊乱","弥漫性心肌间质纤维化","心肌细胞数量增多"],"a":2,"e":"肥厚型心肌病以左心室和/或右心室肥厚、心室腔变小、舒张期顺应性下降为特征，镜下心肌细胞弥漫性肥大、核大畸形深染，心肌纤维走行紊乱。A项四腔扩张、B项附壁血栓、D项弥漫性间质纤维化为扩张型心肌病的特点；E项心肌细胞数量增多不成立，本病是细胞体积增大而非增生"},{"q":"肿瘤是局部细胞的","o":["多克隆性增生所致","不典型增生所致","组织转化所致","克隆性增生所致","炎性增生所致"],"a":3,"e":"肿瘤是局部细胞在基因突变基础上发生的单克隆性（克隆性）增生，起源于单个细胞的异常增殖。多克隆性增生为反应性病变，不典型增生属癌前病变，组织转化即化生，炎性增生为反应性改变，均非肿瘤本质"},{"q":"混合血栓见于","o":["毛细血管内","静脉血栓的头部","动脉血栓的起始部","心瓣膜上的赘生物","静脉血栓的体部"],"a":4,"e":"混合血栓由白色血栓与红色血栓相间构成，见于静脉血栓体部，也见于心腔内附壁血栓。静脉血栓头部为白色血栓，尾部为红色血栓；心瓣膜赘生物为白色血栓；毛细血管内为透明血栓"},{"q":"Ph1染色体主要出现在哪种白血病","o":["急性淋巴细胞白血病","慢性淋巴细胞白血病","急性粒细胞白血病","慢性粒细胞白血病","单核细胞白血病"],"a":3,"e":"Ph染色体即t(9;22)易位形成的BCR::ABL1融合基因，是慢性粒细胞白血病的标志，几乎见于全部慢粒患者。A项急性淋巴细胞白血病仅部分成人病例阳性，阳性率低；B项慢性淋巴细胞白血病无此改变；C项急性粒细胞白血病多见t(15;17)、t(8;21)；E项单核细胞白血病以MLL重排多见"},{"q":"AIDS患者继发的Kaposi肉瘤来源于","o":["滑膜细胞","血管内皮细胞","平滑肌细胞","淋巴细胞","血管周细胞"],"a":1,"e":"Kaposi肉瘤由血管内皮细胞来源，增生的梭形细胞形成裂隙状血管腔，伴红细胞外溢，与HHV-8感染相关，是AIDS患者常见的继发性肿瘤。滑膜细胞来源为滑膜肉瘤，平滑肌细胞为平滑肌肉瘤，血管周细胞为血管周细胞瘤"},{"q":"下列哪项对中性粒细胞无趋化作用","o":["细菌代谢产物","坏死组织","阳离子蛋白","C3a","激肽原酶"],"a":2,"e":"C3a是补体裂解产物，对中性粒细胞有强烈趋化作用；细菌代谢产物可释放甲酰肽直接吸引中性粒细胞，坏死组织亦然。阳离子蛋白实为嗜酸性粒细胞颗粒内的主要嗜碱性蛋白，对寄生虫有毒性并损伤上皮，无中性粒细胞趋化作用。激肽原酶作用于激肽原生成缓激肽，主要扩张血管、增加通透性"},{"q":"肾小球肾炎的基本病理改变不包括","o":["肾小球细胞增多","肾小球炎性渗出和坏死","肾间质内脓肿形成","基膜增厚、系膜基质增多","玻璃样变和硬化"],"a":2,"e":"肾小球肾炎的基本病变包括肾小球细胞增多、炎性渗出与坏死、基底膜增厚及系膜基质增多、玻璃样变和硬化。肾间质内脓肿形成是化脓性炎症即急性肾盂肾炎的特征，由细菌感染引起，与肾小球肾炎的免疫性损伤性质不同"},{"q":"萎缩的心肌细胞内常可出现","o":["橙色血质","含缺血黄素","脂褐素","疟色素","黑色素"],"a":2,"e":"萎缩的心肌细胞内脂褐素（老年色素）沉积增多，为自噬溶酶体未能彻底消化的细胞器碎片残体，致心肌呈褐色萎缩。橙色血质与含铁血黄素均与出血相关，疟色素见疟疾，黑色素由黑色素细胞产生，均非萎缩心肌细胞内常见色素"},{"q":"心肌脂肪变性时出现以下哪种病理改变","o":["心肌间质淋巴细胞浸润","心肌细胞脂肪组织浸润","心肌肉眼呈红、黄相间的条纹","心肌细胞空泡变性","心肌组织凝固性坏死"],"a":2,"e":"心肌脂肪变常累及左心室内膜下及乳头肌，脂肪变心肌呈黄色，与正常暗红色心肌相间形成黄红色斑纹，称虎斑心。心肌间质淋巴细胞浸润是心肌炎的炎症表现。心肌细胞空泡变性属细胞水肿。心肌组织凝固性坏死是梗死的改变，肉眼呈灰黄色而非条纹状"},{"q":"免疫荧光法显示IgG和C3沿毛细血管壁呈线形荧光者主要是","o":["脂性肾病","抗肾小球基底膜肾炎","膜性肾小球肾炎","膜增生性肾小球肾炎","局灶性节段性肾小球硬化"],"a":1,"e":"抗肾小球基底膜肾炎由抗GBM抗体沿基底膜连续沉积，免疫荧光呈特征性线形荧光，主要为IgG，部分伴C3。膜性肾病与膜增生性肾炎由免疫复合物沉积，呈颗粒状荧光。脂性肾病免疫荧光阴性。局灶性节段性肾小球硬化仅于硬化区见IgM和C3团块状沉积"},{"q":"慢性溃疡性结肠炎的病变特点不包括","o":["病变可累及结肠各段","临床上呈慢性经过","肠壁形成较大溃疡","易修复，不易癌变","常伴有肠外免疫性疾病"],"a":3,"e":"溃疡性结肠炎病变连续弥漫分布于结肠各段，呈慢性经过并反复发作，溃疡较浅、可伴假息肉形成，常伴肠外免疫性疾病如游走性多关节炎与葡萄膜炎。病程越长癌变风险越高，故不易癌变的说法错误。较大溃疡与肠壁增厚见于克罗恩病的纵行溃疡与铺路石样改变"},{"q":"口眼干燥综合征的组织学表现主要是","o":["受累腺体萎缩，不伴有淋巴浆细胞浸润","受累腺体间淋巴浆细胞浸润，伴有腺体结构破坏","受累腺体间常见上皮样肉芽肿","大量泡沫细胞浸润","有化脓性肉芽肿形成"],"a":1,"e":"口眼干燥综合征（干燥综合征）为自身免疫性外分泌腺病，泪腺、唾液腺间质大量淋巴浆细胞浸润并破坏腺体结构。腺体萎缩不伴浸润与事实相反；上皮样肉芽肿见结节病；泡沫细胞浸润见动脉粥样硬化；化脓性肉芽肿为感染性病变，均非本病表现"},{"q":"如图，可能的肾炎类型是","o":["急性肾小球肾炎","急进性肾小球肾炎","慢性肾小球肾炎","慢性肾盂肾炎","急性肾盂肾炎"],"a":2,"e":"本题原题配有图片，图片未随文档保留，以下解析依文字线索推断：题干涉及图片/信息缺失，无法作答。慢性肾小球肾炎为各类肾小球疾病的终末阶段，双肾对称缩小、表面呈弥漫细颗粒状，镜下大量肾小球玻璃样变、硬化，肾小管萎缩、间质纤维化，临床表现为慢性肾炎综合征和慢性肾衰竭。急进性肾炎以大量新月体为特征，慢性肾盂肾炎为双侧不对称的瘢痕凹陷，急性肾盂肾炎为化脓性炎\n\n官方题库中缺失图片"},{"q":"鼻咽癌最常见于鼻咽的哪个部位","o":["外侧壁","前壁","前壁和咽隐窝","咽隐窝","顶部"],"a":4,"e":"鼻咽癌最常发生于鼻咽顶部，其次为外侧壁和咽隐窝，前壁最少见。A项外侧壁、D项咽隐窝为第二好发部位，B项前壁与C项前壁及咽隐窝均把最少见的部位置于首位。顶部与侧壁可同时受累，黏膜下浸润型易早期转移至颈部淋巴结"},{"q":"关于萎缩性胃炎的病因，下列错误的是","o":["B型血中有内因子抗体","A型与自身免疫有关","B型与自身免疫无关","肠上皮化生","A型血中有壁细胞抗体"],"a":0,"e":"B型萎缩性胃炎与自身免疫无关，血清中无壁细胞抗体与内因子抗体，病变以胃窦为主。A型属自身免疫性，血中存在壁细胞抗体与内因子抗体，致维生素B12吸收障碍与恶性贫血；肠上皮化生为伴随病变"},{"q":"神经细胞卫星现象指","o":["淋巴细胞、单核细胞围绕血管","神经元被5个以下少突胶质细胞环绕","神经元被5个以上淋巴细胞环绕","神经节细胞周围被鞘膜细胞环绕","神经元被5个以上少突胶质细胞环绕"],"a":4,"e":"卫星现象指一个神经元被5个或5个以上少突胶质细胞围绕，见于灰质，其与神经元损害的程度和时间无明确关系。1～2个少突胶质细胞围绕神经元属正常分布；淋巴细胞围绕血管是血管套；噬神经细胞现象为小胶质细胞吞噬坏死神经元"},{"q":"急性病毒性肝炎的病变性质为","o":["急性增生性炎","急性出血性炎","急性浆液性炎","急性变质性炎","急性纤维素性炎"],"a":3,"e":"急性病毒性肝炎以肝细胞变性坏死为主，属变质性炎，同时伴少量炎细胞浸润和Kupffer细胞增生。A项增生性炎见于慢性炎症和肉芽肿性炎；B项出血性炎见于流行性出血热、炭疽；C项浆液性炎见于结核性胸膜炎、烫伤水疱；E项纤维素性炎见于大叶性肺炎、白喉"},{"q":"微循环血管壁通透性增高引起的出血是","o":["破裂性出血","体腔积血","外出血","漏出性出血","渗出性出血"],"a":3,"e":"微循环血管壁通透性增高，红细胞经增宽的内皮细胞间隙漏出，为漏出性出血，见于缺氧、感染、维生素C缺乏与血小板减少。破裂性出血为血管壁完整性破坏；体腔积血与外出血按部位分类；渗出性出血指炎症时伴渗出的红细胞漏出"},{"q":"对于喉癌的描述，下列哪项是错误的","o":["浸润性鳞癌最常见","声嘶是喉癌患者最常见的早期症状","常经淋巴道转移至颈总动脉分叉处淋巴结","更易早期转移到肺","常发生于声带"],"a":3,"e":"喉癌以淋巴道转移为主，常转移至颈总动脉分叉处淋巴结即颈深上淋巴结。血行转移少见且出现较晚，早期转移至肺的说法不成立。浸润性鳞状细胞癌占喉癌绝大多数，声带为最常见部位，声嘶出现早，是患者最常见的早期症状"},{"q":"下述哪种疾病属出血性炎","o":["病毒性肝炎","肠阿米巴病","流行性脑脊髓膜炎","钩端螺旋体病","丹毒"],"a":3,"e":"钩端螺旋体病属出血性炎，钩端螺旋体损伤毛细血管内皮，致全身广泛出血。病毒性肝炎、肠阿米巴病为变质性炎，流行性脑脊髓膜炎为化脓性炎，丹毒为链球菌引起的蜂窝织炎（化脓性炎），均非出血性炎"},{"q":"下列哪种激素具有抑制炎症的作用","o":["甲状腺素","生长激素","垂体促甲状腺素","促肾上腺皮质激素","糖皮质激素"],"a":4,"e":"糖皮质激素抑制磷脂酶A2及环氧合酶-2的转录，减少前列腺素和白三烯生成，并抑制IL-1、TNF-α等细胞因子，具强大抗炎作用。甲状腺素、生长激素、促甲状腺素无抗炎效应；促肾上腺皮质激素须经肾上腺皮质分泌皮质醇间接起效"},{"q":"下列肿瘤中，有明显家族发病倾向者为","o":["胶质瘤","结肠息肉性腺瘤","骨软骨瘤","畸胎瘤","淋巴瘤"],"a":1,"e":"家族性腺瘤性息肉病为常染色体显性遗传，结肠内多发腺瘤性息肉，几乎均癌变，有明显家族聚集倾向，属癌前疾病。胶质瘤、骨软骨瘤、畸胎瘤、淋巴瘤多为散发性，无明确家族发病倾向"},{"q":"早期确诊肺癌简单、有效的检查方法为","o":["痰脱落细胞检查","胸部X线检查","放射性核素肺扫描","支气管镜检查","活组织检查"],"a":1,"e":"官方答案为【胸部X线检查】，但依据教材，正确答案为【痰脱落细胞检查】。痰液脱落细胞学检查取材无创、可重复，对中央型肺癌早期阳性率可达80%以上，是早期诊断最简便有效的方法。胸部X线对早期黏膜病变敏感性低，仅作筛查；支气管镜与活组织检查虽可靠，但操作复杂，不符合简单的要求"},{"q":"食管癌中，最少见的肉眼类型是","o":["髓质型","蕈伞型","胶样型","溃疡型","缩窄型"],"a":2,"e":"食管癌肉眼类型包括髓质型、蕈伞型、溃疡型、缩窄型，其中髓质型最常见，胶样型最少见。蕈伞型、溃疡型、缩窄型均为常见类型，唯胶样型罕见，故为最少见类型"},{"q":"食管癌最常见的组织学类型是","o":["鳞状细胞癌","小细胞癌","腺癌","腺鳞癌","黏液癌"],"a":0,"e":"食管癌绝大多数为鳞状细胞癌，与食管黏膜鳞状上皮及吸烟、饮酒、亚硝胺等因素相关。小细胞癌、腺癌、腺鳞癌、黏液癌在食管均属少见类型"},{"q":"吞噬作用最为活跃的炎症细胞是","o":["淋巴细胞","中性粒细胞","浆细胞","嗜酸性粒细胞","肥大细胞"],"a":1,"e":"中性粒细胞吞噬能力最强，胞质颗粒含髓过氧化物酶和溶酶体酶，是急性炎症中吞噬和杀菌的主力。A项淋巴细胞主要参与免疫识别和细胞毒作用，吞噬能力弱；C项浆细胞产生抗体；D项嗜酸性粒细胞吞噬能力有限，主要杀伤寄生虫；E项肥大细胞释放组胺等介质"},{"q":"子宫内膜腺上皮的核下空泡出现在月经周期的","o":["11～14天","24～28天","20～23天","16～17天","17～19天"],"a":3,"e":"分泌早期即月经周期第16~17天，腺上皮出现核下空泡，为糖原聚集所致，是排卵的标志。增生期腺体小而直、核位于基底；第20~23天为分泌中期，核上移、腺腔内分泌物增多；第24~28天为分泌晚期"},{"q":"硅肺的特征性病变是","o":["类上皮肉芽肿","肺间质纤维化","硅肺空洞","硅结节","胸膜变厚"],"a":3,"e":"硅肺的基本病变是硅结节形成与肺组织弥漫性纤维化，硅结节境界清楚、圆形或椭圆形、灰白色、触之有沙砾感，是其最具特征性的病变。类上皮细胞肉芽肿见于结核病。硅肺空洞由结节中心缺血坏死溶解形成，见于晚期融合团块。胸膜增厚属继发改变"},{"q":"急进型高血压时，细动脉壁内有细丝、颗粒状或凝集成片块状的嗜酸物质，其改变可能是","o":["玻璃样变","淀粉样变","黏液样变性","纤维素样坏死","干酪样坏死"],"a":3,"e":"急进型高血压时细动脉壁发生纤维素样坏死，局部形成细丝状、颗粒状或片块状红染无结构物质，染色性质与纤维蛋白相似，常伴小血管破裂出血。玻璃样变见于缓进型高血压的细小动脉，为均质红染物质沉积。淀粉样变由淀粉样蛋白沉积所致，干酪样坏死为结核的特征性坏死"},{"q":"关于大肠癌的描述，下列正确的是","o":["盲肠癌最多见","类癌由腺瘤癌变而来","少数癌瘤产生CEA","Dukes后期向远隔器官远移","未分化癌多见"],"a":3,"e":"结直肠癌Dukes分期依据癌的扩散范围及淋巴结、远隔脏器转移，D期即已有远处转移。大肠癌以直肠最多见，盲肠次之；多数大肠癌CEA升高；未分化癌少见，以腺癌为主；类癌起源于神经内分泌细胞，并非由腺瘤癌变而来"},{"q":"关于栓子的运行途径，下列说法错误的是","o":["静脉系统及右心栓子常引起肺栓塞","动脉系统及左心栓子常引起脑、脾、肾等器官的栓塞","栓子运行一般逆压力差运行","下腔静脉内的血栓在胸、腹压突然升高时可发生逆行性栓塞","交叉性栓塞又称反常性栓塞"],"a":2,"e":"栓子一般随血流方向运行，最终停留在口径与其相当的血管内并阻断血流，并非逆压力差运行。静脉和右心栓子引起肺栓塞，左心和动脉栓子引起脑、脾、肾栓塞；下腔静脉血栓在胸腹压骤升时可逆行栓塞，经房室间隔缺损的交叉性栓塞又称反常性栓塞"},{"q":"最容易发生脑转移的恶性肿瘤是","o":["肾癌","肺癌","绒癌","恶性黑色素瘤","胃癌"],"a":1,"e":"肺癌最易发生脑转移，尤其小细胞癌与腺癌，癌细胞易侵入肺静脉进入体循环。肾癌多转移至肺、骨；绒毛膜癌血行转移至肺、脑但发生率较低；恶性黑色素瘤亦易转移至脑，总体仍以肺癌最多见。脑转移瘤多位于灰白质交界处，常为多发，周围水肿明显"},{"q":"风湿性肉芽肿中的坏死为","o":["固缩性坏死","干酪样坏死","纤维素样坏死","坏疽","液化性坏死"],"a":2,"e":"风湿性肉芽肿即风湿小体，中央为纤维蛋白样坏死，周围为成群的风湿细胞及少量淋巴细胞、浆细胞。干酪样坏死是结核病的特征；坏疽为坏死组织继发腐败菌感染；液化性坏死见于脑梗死与脓肿；固缩性坏死并非独立的坏死类型"},{"q":"流行性乙型脑炎的病原体是","o":["乙型链球菌","α-溶血性链球菌","脑膜炎双球菌","乙型脑炎病毒","柯萨奇病毒"],"a":3,"e":"流行性乙型脑炎的病原体是乙型脑炎病毒（日本脑炎病毒），经蚊虫叮咬传播。乙型链球菌、α溶血性链球菌为细菌，脑膜炎双球菌致流脑，柯萨奇病毒致病毒性心肌炎等，均非乙脑病原体"},{"q":"常发生机化的病灶，下列哪项除外","o":["风湿性小体","心肌梗死","脑梗死","肠上皮细胞化生","干酪样坏死"],"a":3,"e":"机化是肉芽组织长入并取代坏死组织、血栓、脓液或异物的过程，风湿小体、心肌梗死灶、脑梗死灶和干酪样坏死均可机化或被纤维包裹。肠上皮化生是胃黏膜上皮被肠型上皮取代的适应性改变，属化生而非机化"},{"q":"溶组织内阿米巴具有致病性的阶段主要是","o":["大滋养体","小滋养体","包囊","幼虫","成虫"],"a":0,"e":"溶组织内阿米巴的大滋养体为致病阶段，可伸出伪足运动、吞噬红细胞并分泌溶组织酶破坏肠壁，引起阿米巴痢疾。小滋养体为共生的肠腔阶段，包囊为感染阶段但不致病，幼虫、成虫非其生活史阶段"},{"q":"下列关于栓塞的叙述，哪项是正确的","o":["进入血液的癌细胞均可形成栓塞","脂肪栓塞均由创伤引起","羊水栓塞不会引起死亡","肺动脉血栓栓塞的栓子多来自于下肢深静脉","减压病是氧气栓塞"],"a":3,"e":"肺动脉血栓栓塞的栓子95%以上来自膝以上的下肢深静脉，尤其腘静脉、股静脉与髂总静脉。进入血液的癌细胞多数被清除，仅少数形成转移；脂肪栓塞也可由脂肪组织损伤、烧伤引起；羊水栓塞可迅速致死；减压病为氮气栓塞"},{"q":"脂性肾病的临床特点是","o":["成年人多见","高血压","明显血尿","无水肿","选择性蛋白尿"],"a":4,"e":"脂性肾病即微小病变性肾小球病，临床表现为肾病综合征，其特点是选择性蛋白尿（以白蛋白为主），对激素敏感。该病儿童多见而非成人，高血压与明显血尿不明显，水肿显著而非无水肿"},{"q":"慢性支气管炎患者通气障碍是由于","o":["黏液腺肥大、增生","上皮纤毛倒伏、脱落","软骨变性萎缩","小气道阻塞","管壁平滑肌萎缩"],"a":3,"e":"慢支通气障碍的关键在于小气道阻塞，黏液栓、管壁纤维化、平滑肌痉挛等使直径小于2mm的细支气管狭窄。黏液腺肥大增生、纤毛倒伏脱落、软骨变性萎缩、平滑肌萎缩均为伴随病变，但直接导致通气障碍的是小气道阻塞"},{"q":"对炎症病变痊愈来说，下列哪项是错误的","o":["致炎因子被清除","坏死组织被溶解吸收","由肉芽组织修复","损伤的组织结构和功能完全恢复","有肉芽肿形成"],"a":4,"e":"炎症痊愈需致炎因子被清除、坏死组织溶解吸收、由肉芽组织修复，最终组织结构和功能完全恢复。肉芽肿形成为特异性炎症的转归，提示病原未被清除、病变迁延，故不属痊愈表现。若坏死组织不能完全溶解吸收，则由肉芽组织机化形成瘢痕，属不完全痊愈"},{"q":"下列不符合阿尔兹海默病的特点的是","o":["老年斑","神经元纤维缠结","萎缩区皮质神经元丧失","弥漫性脑萎缩","与脑动脉硬化有密切关系"],"a":4,"e":"阿尔茨海默病以弥漫性脑萎缩、皮质神经元丧失、老年斑和神经元纤维缠结为特点，海马及额颞叶受累明显。与脑动脉硬化密切相关、表现为多发性梗死性痴呆的是血管性痴呆，两者病因与病理基础不同"},{"q":"膀胱上皮发生鳞状上皮化生后恶性变，这时所形成的恶性肿瘤称为","o":["膀胱移行细胞癌","膀胱癌肉瘤","膀胱鳞状细胞癌","膀胱腺棘皮癌","膀胱腺鳞癌"],"a":2,"e":"膀胱黏膜在长期刺激下发生鳞状上皮化生，化生上皮恶变形成的肿瘤为鳞状细胞癌，可见角化珠与细胞间桥。膀胱移行细胞癌即尿路上皮癌来源于尿路上皮，占膀胱癌的90%以上。癌肉瘤含癌与肉瘤两种成分。腺棘皮癌与腺鳞癌含腺上皮成分，与鳞化恶变不同"},{"q":"膜性肾小球肾炎电镜下常见","o":["基底膜外侧许多颗粒状电子致密物沉积","基底膜外侧有驼峰状电子致密物沉积","基底膜呈“双轨状”","脏层上皮细胞足突融合","基底膜内侧电子致密物散在沉积"],"a":0,"e":"膜性肾小球病为基底膜上皮侧即外侧弥漫颗粒状电子致密物沉积，基底膜弥漫增厚，临床多呈肾病综合征。驼峰状沉积见于急性感染后肾小球肾炎；双轨状见于膜增生性肾炎；足突融合是微小病变与大量蛋白尿的共同表现"},{"q":"构成胆道结石的化学成分不包括","o":["黏液物质","尿酸盐","钙盐","胆固醇","胆色素"],"a":1,"e":"胆道结石以胆固醇、胆色素、钙盐及黏液物质为主要成分，胆固醇结石多见于胆囊，胆色素结石多见于胆管。尿酸盐结石见于痛风与高尿酸血症，沉积于肾脏、关节及软组织，不参与胆石构成"},{"q":"关于浆细胞下列错误的是","o":["正常时不存在于血液中","无吞噬功能","来源于T淋巴细胞","椭圆形，核位于胞质一端，核染色呈车轮状分布","胞质内有丰富的粗面内质网"],"a":2,"e":"浆细胞由B淋巴细胞受抗原刺激后转化而来，故来源于T淋巴细胞的表述错误。浆细胞正常不存在于血液中，无吞噬功能而以分泌抗体为主，核偏位、染色质呈车轮状，胞质含丰富粗面内质网，这些均符合浆细胞特征"},{"q":"宫颈癌的好发部位","o":["宫颈外口鳞状上皮侧","宫颈外口鳞状上皮与柱状上皮交界处","宫颈内口","宫颈管","宫颈外口柱状上皮侧"],"a":1,"e":"子宫颈癌好发于宫颈外口鳞状上皮与柱状上皮交界处的移行带，该处上皮更替活跃、易受高危型HPV感染，癌变多起源于此。宫颈管内的柱状上皮侧、宫颈内口及宫颈阴道部的单纯鳞状上皮侧均非好发部位"},{"q":"病毒性肝炎时，下列哪项罕见","o":["溶解坏死","脂肪变性","嗜酸性变","胞质疏松化和气球样变","肝细胞再生"],"a":1,"e":"病毒性肝炎的肝细胞损伤以胞质疏松化、气球样变、嗜酸性变及溶解性坏死为主，坏死按范围分为点状、碎片状、桥接和大块坏死，并伴肝细胞再生，脂肪变性少见。脂肪变性主要见于酒精性肝病、非酒精性脂肪性肝病及肝淤血"},{"q":"青壮年患者骤然畏寒、高热、胸痛、咳铁锈色痰，最有可能是","o":["急性支气管炎","慢性支气管炎急性发作","大叶性肺炎","小叶性肺炎","病毒性肺炎"],"a":2,"e":"青壮年骤起畏寒高热、胸痛、咳铁锈色痰是肺炎链球菌所致大叶性肺炎的典型表现，痰呈铁锈色因肺泡内红细胞被巨噬细胞吞噬分解形成含铁血黄素。小叶性肺炎多见于婴幼儿与年老体弱者，以细支气管为中心的化脓性炎。病毒性肺炎与支原体肺炎为间质性肺炎，咳痰不显著"},{"q":"下列哪种癌较早经血行转移","o":["移行细胞癌","绒毛膜癌","肺大细胞癌","胃癌","乳腺浸润性导管癌"],"a":1,"e":"绒毛膜癌滋养层细胞直接侵入子宫肌层血窦，早期即经血行转移至肺、脑、阴道等处，是较早发生血行转移的恶性肿瘤。移行细胞癌、胃癌、乳腺浸润性导管癌以淋巴道为主，肺大细胞癌多在晚期血行转移"},{"q":"关于局限性肠炎下列哪项是错误的","o":["又称克罗恩病","主要累及回肠末端","临床出现腹痛、腹泻、肠穿孔和肠梗阻","病变呈节段性，由正常黏膜分隔","横行溃疡发展为裂隙，炎症浅表"],"a":4,"e":"克罗恩病主要累及回肠末端，病变呈节段性分布，由正常黏膜分隔，肠壁全层受累，黏膜面为纵行溃疡并进而形成裂隙、瘘管，故横行溃疡、炎症浅表的说法错误。横行溃疡为肠结核的特点，溃疡性结肠炎则呈连续性弥漫分布，病变多限于黏膜与黏膜下层"},{"q":"在免疫组化染色过程中，“血清封闭”的目的是","o":["抗原修复作用","增加反应敏感性","消除非特异性反应，降低背景染色","防止脱片","加强特异性反应，提高阳性率"],"a":2,"e":"血清封闭用正常血清预先覆盖组织中的Fc受体及带电荷位点，减少一抗非特异性结合，降低背景染色。抗原修复用于暴露抗原决定簇；多聚赖氨酸载玻片用于防脱片；敏感性由信号放大系统决定"},{"q":"下列哪种栓塞不会引起猝死","o":["颈内动脉栓塞","冠状动脉栓塞","肺动脉口栓塞","肺动脉较大分支栓塞","肾动脉栓塞"],"a":4,"e":"颈内动脉栓塞致脑梗死、冠状动脉栓塞致心肌梗死、肺动脉口或较大分支栓塞致急性右心衰竭，均可引起猝死。肾动脉栓塞仅造成肾梗死，肾脏有侧支血供，一般不危及生命，不会引起猝死"},{"q":"关于化脓性炎的叙述，下列不正确的是","o":["表面化脓是指发生在浆膜、黏膜的化脓性炎","黏膜的化脓性炎又可称为脓性卡他","化脓性炎可不伴有坏死","蜂窝织炎是指弥漫性化脓性炎","当脓液在组织间隙或体腔、自然管腔中积聚时称为积脓"],"a":2,"e":"化脓性炎以大量中性粒细胞渗出为主，必伴不同程度的组织坏死和脓液形成，故“可不伴有坏死”的说法错误。表面化脓指浆膜黏膜化脓，黏膜化脓称脓性卡他，蜂窝织炎为弥漫性化脓性炎，积脓为体腔管腔内脓液积聚，均正确"},{"q":"肝细胞碎片状坏死和桥接坏死最常见于","o":["急性普通型肝炎","重度慢性肝炎","急性普通型黄疸性肝炎","急性重型肝炎","亚急性重型肝炎"],"a":1,"e":"碎片状坏死指肝小叶周边界板肝细胞的灶性坏死，桥接坏死为中央静脉与门管区之间或两个门管区之间的坏死带，两者均见于中、重度慢性肝炎，提示炎症活动度高。急性普通型肝炎以点状坏死为主。急性重型肝炎为大片坏死，亚急性重型肝炎为亚大块坏死伴结节状再生"},{"q":"下列不是恶性肿瘤可以出现的情况的是","o":["转移","可出血、坏死、囊性变","可呈膨胀性生长或外生性生长","生长快，不浸润","浸润性生长"],"a":3,"e":"恶性肿瘤呈浸润性生长，破坏邻近组织并可发生转移，生长快但绝不缺乏浸润。膨胀性生长与外生性生长亦可见于恶性肿瘤；出血、坏死、囊性变是生长过快的继发改变，转移才是其本质特征"},{"q":"系统性红斑狼疮引起组织病理损害最重要的因素是","o":["CD8+细胞","CD4+细胞","自身抗体","苏木素小体","狼疮细胞"],"a":2,"e":"系统性红斑狼疮的组织损伤主要由自身抗体介导，抗核抗体形成免疫复合物沉积于血管壁和肾小球，激活补体引起Ⅲ型变态反应，故自身抗体是致病核心。A项CD8+细胞、B项CD4+细胞参与细胞免疫，不是主要效应环节；D项苏木素小体是受损的细胞核物质；E项狼疮细胞为吞噬狼疮小体的中性粒细胞或巨噬细胞，均属结果"},{"q":"肠伤寒溃疡的形态学特点是","o":["表浅不规则","烧瓶样","与肠轴平行","与肠轴垂直","边缘隆起火山口样"],"a":2,"e":"肠伤寒溃疡发生于回肠末端集合淋巴小结，溃疡长轴与肠管长轴平行，呈椭圆形，可深达肌层致穿孔。烧瓶样溃疡见于阿米巴痢疾，与肠轴垂直的溃疡见于肠结核，火山口样边缘隆起者多为癌性溃疡"},{"q":"伤寒小结的主要构成成分是","o":["类上皮细胞","淋病细胞","多核巨细胞","浆细胞","巨噬细胞"],"a":4,"e":"伤寒小结是伤寒的特征性病变，由增生的巨噬细胞聚集形成，这些巨噬细胞吞噬红细胞、淋巴细胞及伤寒沙门菌后称伤寒细胞，多见于回肠末端集合淋巴结、脾、肝、骨髓。类上皮细胞、多核巨细胞是结核结节等肉芽肿的成分；淋巴细胞、浆细胞虽可伴随存在，但非伤寒小结的主要构成细胞"},{"q":"下列不是神经鞘瘤的特点的是","o":["易于复发，易于恶变","有完整的包膜","Antoni A型结构","Antoni B型结构","椎管内最常见的肿瘤"],"a":0,"e":"神经鞘瘤有完整包膜，镜下见Antoni A区细胞密集、核栅栏状排列并形成Verocay小体，Antoni B区疏松黏液样，是椎管内最常见的肿瘤，良性、恶变罕见。神经纤维瘤无包膜、可多发，与此不同"},{"q":"坏死的结局不包括","o":["溶解吸收","分离排出","化生","钙化","机化包裹"],"a":2,"e":"坏死的结局有溶解吸收、分离排出、机化与包裹、钙化。化生是已分化成熟组织转变为另一种成熟组织，属适应性改变，不是坏死的转归。坏死组织也可被纤维包裹、钙化而长期存留；化生发生于上皮或结缔组织，与坏死无因果关系"},{"q":"关于溃疡底部的结构，下列不正确的是","o":["渗出层","坏死层","肉芽肿层","瘢痕层","肉芽组织层"],"a":2,"e":"慢性消化性溃疡底部由内向外分四层：渗出层、坏死层、肉芽组织层和瘢痕层，无肉芽肿层。肉芽肿是巨噬细胞及其衍生细胞增生形成的结节状病灶，见于结核、伤寒等肉芽肿性炎，与溃疡底部修复性肉芽组织性质不同"},{"q":"细胞内出现Mallory小体常见于","o":["门脉性肝硬化","坏死后性肝硬化","淤血性肝硬化","酒精性肝硬化","胆汁性肝硬化"],"a":3,"e":"Mallory小体（酒精性透明小体）是酒精性肝病时肝细胞内中间丝蛋白聚集形成的嗜酸性包涵体，常见于酒精性肝硬化。门脉性、坏死后性、淤血性、胆汁性肝硬化均非Mallory小体的典型背景"},{"q":"肝癌一般不转移至","o":["淋巴结","脾","腹膜","肺","脑"],"a":1,"e":"肝癌主要经血道转移至肺、骨、脑，经淋巴道转移至肝门淋巴结，并可种植于腹膜。脾脏缺乏输入淋巴管、血供方式特殊，肝癌极少转移至脾，故脾为一般不转移的部位。肝癌血行转移以肺最多见，其次为骨与脑；淋巴道转移至肝门淋巴结，腹膜种植常见"},{"q":"肺肉质变指的是","o":["胸膜渗出物纤维化","支气管壁纤维化","肺泡壁纤维化","肺泡壁平滑肌增生","肺泡腔内渗出物机化"],"a":4,"e":"肺肉质变指大叶性肺炎灰色肝样变期肺泡腔内纤维素性渗出物未能完全溶解吸收，由肉芽组织长入机化，肺组织呈肉样褐色。胸膜渗出物纤维化致胸膜粘连；支气管壁纤维化为慢性支气管炎改变；肺泡壁纤维化见于间质性肺疾病"},{"q":"继发性肺结核的早期病灶多出现在","o":["肺尖下2～4cm处","肺门","肺底部","右肺上叶背部","右肺上叶下部或下叶上部近脏胸膜处"],"a":0,"e":"继发性肺结核的早期病变为局灶型肺结核，病灶定位于肺尖下2～4cm处，直径0.5～1.0cm，境界清楚并有纤维包裹，属非活动性结核。肺门淋巴结肿大见于原发综合征；肺底部为原发性肺结核原发灶的常见部位；下叶上部近胸膜处不是其早期好发部位"},{"q":"心冠状动脉粥样硬化最常受累的动脉分枝是","o":["右冠状动脉主干","左冠状动脉主干","右冠状动脉后降支","左冠状动脉回旋支","左冠状动脉前降支"],"a":4,"e":"冠状动脉粥样硬化最常累及左冠状动脉前降支，其次为右冠状动脉主干、左旋支和左主干，病变多位于血管近端的心壁侧、呈偏心性。故左室前壁、心尖及室间隔前2/3的梗死最多见。右冠状动脉病变多致下壁梗死，左旋支病变多致侧壁梗死"},{"q":"与亚急性感染性心内膜炎无关的病变是","o":["肾梗死","皮肤黏膜出血点","皮肤环形红斑","心瓣膜赘生物","脾大"],"a":2,"e":"皮肤环形红斑是风湿病的渗出性皮肤病变，与A组链球菌感染后的免疫反应有关，与亚急性感染性心内膜炎无关。后者可因赘生物脱落引起肾梗死、脾大，因微血管炎及免疫复合物沉积出现皮肤黏膜出血点，瓣膜上形成赘生物"},{"q":"十二指肠溃疡病最好发于","o":["十二指肠各段","十二指肠降部","十二指肠球部","十二指肠降部和球部","十二指肠下段后壁"],"a":2,"e":"十二指肠溃疡最好发于十二指肠球部（壶腹部），此处直接承受胃酸与胃蛋白酶的物理化学刺激最强。十二指肠降部、降部与球部、下段后壁及十二指肠各段均非最好发部位"},{"q":"不符合小叶性肺炎的是","o":["属化脓性炎症","病变从细支气管开始","常咳黏液脓性痰","肺组织化脓性炎","常见于青壮年"],"a":4,"e":"小叶性肺炎多见于小儿、老年及体弱久病者，为细支气管及周围肺泡的化脓性炎，咳黏液脓性痰。青壮年多见的是大叶性肺炎，故常见于青壮年的说法不符合小叶性肺炎。病变以双肺下叶及背侧较重，可融合成大片实变，但性质仍属化脓性炎"},{"q":"骨化性纤维瘤不具有的特征是","o":["多见于上颌骨","女性发病率高","肿瘤中常见编织骨","常见成堆的多核巨细胞","多见于股骨、胫骨"],"a":4,"e":"骨化性纤维瘤多见于上颌骨等颌面骨，女性发病率高，由纤维组织和编织骨构成，常见成堆的多核巨细胞。股骨、胫骨是骨巨细胞瘤和骨肉瘤的好发部位，骨巨细胞瘤位于长骨骨端，呈皂泡状溶骨性破坏"},{"q":"肺癌最常见的类型是","o":["腺癌","鳞状细胞癌","胶样癌","黏液癌","未分化癌"],"a":0,"e":"肺癌最常见的组织学类型是腺癌，近年来发病率上升居首位，多为周围型，可见于非吸烟者及女性。鳞状细胞癌次之；胶样癌、黏液癌为腺癌的亚型，未分化癌较少见"},{"q":"高血压时心脏产生的病变如图所示指的是","o":["左心室心肌肥厚而心腔不扩张","左心室心肌肥厚而心腔扩张","左心室壁厚度正常而心腔明显扩张","左心室、左心房心肌明显增厚","左心室、左心房心肌正常"],"a":0,"e":"高血压长期使左心室后负荷增加，引起代偿性向心性肥大，室壁增厚达1.5～2.0cm，乳头肌和肉柱增粗，心腔不扩张而相对缩小。心腔扩张见于离心性肥大和心力衰竭；左心室与左心房同时增厚见于二尖瓣病变"},{"q":"深达肌肉的开放性创伤组织合并厌氧菌感染所致的坏死属于","o":["液化性坏死","凝固性坏死","干性坏疽","湿性坏疽","气性坏疽"],"a":4,"e":"深达肌肉的开放性创伤合并产气荚膜杆菌等厌氧菌感染，坏死组织内产生大量气体，按压有捻发感，属气性坏疽，为湿性坏疽的一种。干性坏疽见于动脉阻塞而静脉回流通畅的四肢末端，坏死区干燥皱缩。液化性坏死与凝固性坏死是坏死的形态类型，不反映感染性质"},{"q":"脂性肾病在电镜下最主要的变化是","o":["肾小球壁层上皮细胞内见大量脂质沉积","肾小球脏层上皮细胞足突广泛消失","肾小球毛细血管内皮细胞和系膜细胞增生","肾小球系膜基质增多","肾小球毛细血管基底膜外驼峰状沉积物"],"a":1,"e":"脂性肾病即微小病变性肾小球病，电镜下最突出的改变是肾小球脏层上皮细胞足突广泛消失，基底膜正常、无电子致密物，免疫荧光阴性。驼峰状上皮下沉积物见于急性弥漫性增生性肾炎；基底膜增厚伴钉突形成见于膜性肾病；系膜细胞增生见于系膜增生性肾炎"},{"q":"与Burkitt淋巴瘤有关的病毒是","o":["EB病毒","麻疹病毒","疱疹病毒","腺病毒","HTLV-1"],"a":0,"e":"Burkitt淋巴瘤与EB病毒感染密切相关，尤其非洲儿童型。麻疹病毒、疱疹病毒、腺病毒均非其相关病毒；HTLV-1与成人T细胞白血病/淋巴瘤有关，与Burkitt淋巴瘤无关"},{"q":"下列哪种肝硬化可出现肝细胞的羽毛状坏死","o":["坏死后性肝硬化","血吸虫性肝硬化","胆汁性肝硬化","门脉性肝硬化","淤血性肝硬化"],"a":2,"e":"胆汁性肝硬化时胆汁淤积，胆盐使肝细胞胞质疏松、胞核固缩，形成羽毛状坏死，伴毛细胆管胆栓及门管区纤维增生。门脉性肝硬化以肝细胞脂肪变、点状坏死及假小叶形成为主；血吸虫性与淤血性肝硬化以纤维条索分隔小叶为主，无明显肝细胞坏死"},{"q":"对于慢性胆囊炎的描述，错误的是","o":["可以发生癌变","黏膜多发性萎缩","常伴有明显纤维化","可由急性胆囊炎反复发作迁延所致","各层组织中均有中性粒细胞浸润"],"a":4,"e":"慢性胆囊炎以淋巴细胞、浆细胞浸润和纤维组织增生为主，胆囊壁增厚、黏膜萎缩，可急性发作，长期炎症可癌变。中性粒细胞浸润是急性胆囊炎的特点，而非慢性胆囊炎各层均有，故E项错误；A项可癌变、B项黏膜多发性萎缩、D项由急性迁延而来均符合"},{"q":"下列哪项不是胰岛素依赖型糖尿病的特点","o":["多发生于成年，发病缓慢","胰岛B细胞明显减少","是自身免疫性疾病","血中胰岛素明显降低","治疗依赖胰岛素"],"a":0,"e":"1型糖尿病以青少年发病、起病急、病情重为特点，胰岛B细胞严重受损致胰岛素绝对不足，属自身免疫性疾病，需终身依赖胰岛素。成年发病、起病缓慢、肥胖者多见是2型即非胰岛素依赖型的特点。胰岛B细胞减少与血胰岛素降低均为1型的实质改变，与其余各项一致"},{"q":"最有防御意义的炎症改变过程是","o":["炎症介质形成","分解代谢亢进","局部酸中毒","分子浓度增高","白细胞渗出"],"a":4,"e":"白细胞渗出并聚集于炎症灶是炎症反应最重要的特征，经边集、滚动、黏附、游出和趋化到达局部，发挥吞噬与免疫防御作用。炎症介质形成、局部酸中毒、分解代谢亢进和分子浓度增高属血管反应与代谢改变，防御意义次要"},{"q":"脑动脉粥样硬化时下列哪项不易发生","o":["引起脑萎缩","动脉瘤形成","引起延髓性麻痹","继发脑血栓形成","大脑中动脉病变最重"],"a":2,"e":"脑动脉粥样硬化使管腔狭窄、脑供血长期不足而致脑萎缩，斑块处继发血栓形成引起脑梗死，基底动脉环部可形成动脉瘤并破裂出血，病变以颈内动脉起始部、基底动脉和大脑中动脉最重。延髓性麻痹由延髓运动神经核及其神经受损所致，见于延髓空洞症、运动神经元病，不是脑动脉粥样硬化的常见结果"},{"q":"下列哪种因素对再生修复不利","o":["局部感染已被控制","患者无血管硬化性疾病","局部有较明显的瘢痕组织","创口缝合良好","充足维生素C的供给"],"a":2,"e":"明显的瘢痕组织血供差、缺乏再生支架，阻碍细胞迁移并影响营养供应，不利于再生修复。控制感染、无血管硬化性疾病、创口缝合良好及充足维生素C供给均有利于修复，维生素C参与胶原合成"},{"q":"目前临床主要应用的国际肿瘤分期方法是","o":["WHO系统","TNM系统","NIH系统","CDC系统","AJCS系统"],"a":1,"e":"TNM分期由国际抗癌联盟推行，T表示原发瘤范围、N表示区域淋巴结受累、M表示远处转移，是国际上广泛采用的肿瘤分期方法。WHO分类主要用于肿瘤的组织学命名与分类。AJCC在TNM基础上制定各部位肿瘤分期标准。NIH与CDC为美国行政与科研机构，不制定肿瘤分期"},{"q":"慢性肺源性心脏病的主要发病因素不包括","o":["肺循环阻力增加","体循环阻力增加","肺动脉高压","肺组织减少","气道阻塞"],"a":1,"e":"慢性肺源性心脏病由肺循环阻力增加、肺动脉高压引起，凡使肺组织减少（肺气肿）、气道阻塞（慢支、哮喘）、肺血管病变者均可致病。体循环阻力增加见于高血压和左心病变，引起左心室肥大，不属肺心病的发病因素"},{"q":"妇女最常见的乳腺良性肿瘤是","o":["乳腺纤维腺瘤","乳腺平滑肌瘤","乳腺错构瘤","乳管内乳头状瘤","脂肪瘤"],"a":0,"e":"乳腺纤维腺瘤由增生的腺管和纤维间质共同构成，是乳腺最常见的良性肿瘤，多见于20～35岁，界清、质韧、切面呈分叶状并见裂隙。乳管内乳头状瘤源于大导管上皮，以乳头溢液为特点；乳腺错构瘤、平滑肌瘤和脂肪瘤均少见"},{"q":"关于反流性食管炎的描述错误的是","o":["由胃内容物及十二指肠液反流引起","胃食管连接处以下出现Barrett食管改变","局部黏膜糜烂及溃疡","食管鳞状上皮增生","可导致食管环状纤维化和狭窄"],"a":1,"e":"Barrett食管指食管远端即胃食管连接处以上的鳞状上皮被柱状上皮取代，为食管腺癌的癌前病变，故该项将其说成连接处以下，部位颠倒。反流性食管炎由胃内容物及十二指肠液反流引起，表现为黏膜糜烂、溃疡，鳞状上皮可增生，晚期可致纤维化与狭窄"},{"q":"下列哪项属于静脉性充血","o":["减压后充血","妊娠子宫充血","炎性充血","进食后胃肠道的充血","静脉阻塞引起的充血"],"a":4,"e":"静脉性充血（淤血）因静脉回流受阻、血液淤积所致，静脉阻塞引起的充血属此类。减压后充血、妊娠子宫充血、炎性充血及进食后胃肠道充血均因局部动脉供血增多，属动脉性（主动性）充血"},{"q":"下述流行性脑脊髓膜炎的临床表现错误的是","o":["脑膜刺激征","颅内压升高症状","混浊或脓样脑脊液","血性脑脊液","皮肤瘀点及瘀斑"],"a":3,"e":"流行性脑脊髓膜炎为脑脊髓膜的急性化脓性炎，脑脊液浑浊或呈脓样、压力升高、蛋白增多、糖降低，涂片可找到脑膜炎双球菌，不会出现血性脑脊液。血性脑脊液是蛛网膜下腔出血的特征。A项脑膜刺激征、B项颅内压升高、E项皮肤瘀点瘀斑均为流脑常见表现"},{"q":"下述哪种病变不会引起远隔器官梗死","o":["风湿性二尖瓣狭窄","心肌梗死","心脏室壁瘤","亚急性感染性心内膜炎","高血压性心脏病"],"a":4,"e":"高血压性心脏病致左心衰竭，引起肺淤血水肿，不产生体循环动脉栓子，故不引起远隔器官梗死。风湿性二尖瓣狭窄和亚急性感染性心内膜炎可形成附壁血栓或瓣膜赘生物，心肌梗死、室壁瘤内附壁血栓脱落均可栓塞脑、脾、肾"},{"q":"光镜下判断细胞是否坏死，主要观察","o":["染色质形态的改变","核仁形态的改变","细胞质形态的改变","细胞核形态的改变","细胞形态的改变"],"a":3,"e":"细胞坏死在光镜下以核的改变为标志，表现为核固缩、核碎裂和核溶解，染色质致密成块、碎裂或溶解消失。细胞质嗜酸性增强、细胞肿胀属可逆性损伤，不能据以判定坏死；细胞整体形态改变见于细胞水肿等变性。染色质改变只是核改变的部分表现，判定坏死看核的整体变化"},{"q":"引起脑梗死最常见的原因是","o":["脑动脉栓塞","脑血管畸形","脑动脉硬化伴血栓形成","脑动脉粥样硬化斑块内出血","脑血管炎症"],"a":0,"e":"官方答案为【脑动脉栓塞】，但依据教材，正确答案为【脑动脉硬化伴血栓形成】。教材明确指出血栓形成致动脉血流中断是梗死形成的最常见原因，脑动脉粥样硬化合并血栓形成引起脑梗死。栓塞虽可致脑梗死，但发生率低于血栓形成；脑血管畸形、动脉炎、斑块内出血更少见"},{"q":"发生DIC死亡的病人尸体解剖后，在肺、肾、脑等组织切片中可见到","o":["白色血栓","红色血栓","混合血栓","透明血栓","静脉血栓"],"a":3,"e":"DIC时微循环毛细血管内形成由纤维蛋白构成的透明血栓，仅在显微镜下可见，又称微血栓。白色血栓见于心瓣膜和动脉内；红色血栓为静脉血流停止后的血液凝固，位于延续性血栓尾部；混合血栓见于动脉瘤、心房及静脉血栓体部"},{"q":"组胺类介质引起血管通透性升高的机制是","o":["引起内皮细胞收缩","引起内皮细胞损伤","介导白细胞对内皮细胞的损伤","使内皮细胞的穿胞作用增强","新生毛细血管的高通透性"],"a":0,"e":"组胺、缓激肽、白细胞三烯作用于毛细血管后微静脉内皮细胞，使其迅速收缩，细胞间出现0.5～1.0μm缝隙，通透性升高，此过程持续时间较短。B项内皮细胞损伤见于烧伤和化脓菌感染；C项白细胞介导的内皮损伤见于肺和肾小球；D项穿胞作用增强由VEGF等引起；E项新生毛细血管通透性高属修复期改变"},{"q":"下述关于动脉粥样硬化的危险因素中，哪项是错误的","o":["高脂血症，特别是血浆低密度脂蛋白（LDL）、极低密度脂蛋白（VLDL）水平与动脉粥样硬化的发病率呈正相关","吸烟是引起动脉粥样硬化的因素之一","高血压患者，动脉粥样硬化发病较早，病变较重","遗传因素是动脉粥样硬化的危险因素","雌激素可降低血浆胆固醇水平，因此，女性比同年龄男性动脉粥样硬化发病率低"],"a":4,"e":"高脂血症（LDL、VLDL升高）、高血压、吸烟和遗传因素均为动脉粥样硬化的明确危险因素。雌激素确能降低胆固醇，绝经前女性发病率低于男性，但绝经后该保护作用消失，发病率迅速上升并接近男性，故该说法绝对化而不成立"},{"q":"流行性乙型脑炎病变最明显的部位在","o":["脑桥","小脑","大脑皮质及基底核","脊髓","丘脑"],"a":2,"e":"乙脑病变最明显部位在大脑皮质及基底核，尚累及丘脑、中脑，以灰质神经元变性坏死为主。脑桥、小脑、脊髓病变轻，丘脑虽常受累但范围与程度不及大脑皮质及基底核"},{"q":"确诊淀粉样变常用的染色法是","o":["刚果红染色","苏丹Ⅲ染色","普鲁士蓝染色","PAS染色","HE染色"],"a":0,"e":"淀粉样蛋白与刚果红结合后呈橘红色，在偏振光显微镜下呈苹果绿色双折光，是确诊淀粉样变的经典染色。HE染色仅呈淡红色均质状，特异性差；苏丹Ⅲ染脂肪，普鲁士蓝染含铁血黄素，PAS染糖原与基膜"},{"q":"对狼疮性肾炎具有诊断价值的形态特征是","o":["狼疮小体","肾小球系膜细胞增生","补体沉积","电子致密物沉积","免疫球蛋白"],"a":0,"e":"狼疮小体即苏木素小体，由抗核抗体作用于受损细胞核使其肿胀均质化并被挤出胞体形成，对系统性红斑狼疮有明确诊断意义，吞噬该小体的细胞称狼疮细胞。系膜细胞增生、补体与免疫球蛋白沉积、电子致密物沉积可见于多种免疫复合物性肾炎，特异性不足"},{"q":"关于主动脉粥样硬化的叙述中下列错误的是","o":["病变多位于主动脉后壁和各分支开口处","可引起动脉血流障碍","可引起主动脉瓣膜病","可引起夹层动脉瘤","可继发溃疡及血栓形成"],"a":2,"e":"主动脉粥样硬化好发于主动脉后壁及各分支开口处，以腹主动脉最重，斑块可继发溃疡、血栓形成，中膜囊性变可致夹层动脉瘤。主动脉瓣膜病主要由风湿性主动脉炎引起，粥样硬化仅经瓣膜钙化间接导致狭窄，并非其直接病变；主动脉管腔大，斑块一般不致明显血流障碍"},{"q":"下列不符合肿瘤性增生的是","o":["与整个机体不协调","生长旺盛","增生过程中致瘤因子持续存在","具有相对自主性","不同程度的丧失了分化成熟的能力"],"a":2,"e":"肿瘤性增生相对自主、持续生长，去除致瘤因素后仍继续，与机体整体不协调，分化成熟能力不同程度丧失。增生过程中致瘤因子持续存在是炎症性与反应性增生的特点，去除病因后增生可消退"},{"q":"流行性乙型脑炎最具特征性的病变是","o":["噬神经细胞现象","卫星现象","筛网状软化灶","淋巴细胞袖口状浸润","胶质结节"],"a":2,"e":"乙脑病变严重时神经组织发生灶性液化性坏死，形成质地疏松、染色浅淡的镂空筛网状软化灶，对本病诊断具特征性意义。噬神经细胞现象、卫星现象、胶质结节及血管周围淋巴细胞袖套状浸润均为脑炎的非特异性炎症反应，其他病毒性脑炎同样可见"},{"q":"良性高血压病时，左心室向心性肥大属于","o":["肥大","增生","化生","再生","变性"],"a":0,"e":"良性高血压时左心室长期承受压力负荷，心肌细胞体积增大而数量不变，属肥大。增生为细胞数目增多，化生为组织类型转化，再生为损伤修复，变性为可逆性细胞损伤，均不符合左室向心性肥大的本质"},{"q":"急性重型肝炎大量肝细胞溶解性坏死可导致以下各项，除了","o":["胆红素大量入血","肝细胞性黄疸","凝血因子合成障碍","肝细胞再生","肝性脑病"],"a":3,"e":"急性重型肝炎肝细胞弥漫性大片坏死，数日内肝体积显著缩小、重量减轻、被膜皱缩，临床出现黄疸、出血和肝性脑病。大片坏死使肝细胞丧失再生能力，故不出现肝细胞再生；亚急性重型肝炎才表现为亚大块坏死伴结节状再生"},{"q":"引起肺褐色硬化的常见病变为","o":["二尖瓣狭窄","三尖瓣狭窄","肺动脉栓塞","急性肺淤血","右心衰竭"],"a":0,"e":"二尖瓣狭窄使左心房压升高、肺静脉高压，长期慢性肺淤血致肺泡内红细胞被巨噬细胞吞噬形成含铁血黄素，伴间质纤维化，肺呈棕褐色，称肺褐色硬化。三尖瓣狭窄与右心衰竭引起体循环淤血，肺动脉栓塞造成肺出血性梗死，急性肺淤血仅有水肿出血而无纤维化"},{"q":"霍奇金淋巴瘤最常发生的部位是","o":["纵隔淋巴结","腋窝淋巴结","颈部淋巴结","肠系膜淋巴结","腹膜后淋巴结"],"a":2,"e":"霍奇金淋巴瘤最常原发于颈部淋巴结，其次为纵隔、腋下和腹膜后，常沿淋巴道有序扩散。腹膜后、腹股沟、纵隔和腋下淋巴结虽可受累，但发生率均低于颈部，颈部是其最典型的首发部位"},{"q":"萎缩的心肌细胞内最易出现的色素是","o":["含铁血黄素","疟色素","胆色素","脂褐素","黑色素"],"a":3,"e":"萎缩心肌细胞胞质内出现大量脂褐素颗粒，为富含磷脂的细胞器残体未被彻底消化所致，是自由基脂质过氧化损伤的标志，又称消耗性色素。A项含铁血黄素见于出血后巨噬细胞吞噬红细胞；C项胆色素见于胆汁淤积；E项黑色素由酪氨酸经左旋多巴聚合而成。B项疟色素为疟原虫分解血红蛋白的产物，仅见于疟疾"},{"q":"关于肾小球肾炎的发病机制，目前认为关系最密切的是","o":["抗原抗体复合物形成","T淋巴细胞致敏","机体免疫功能低下","抗体直接损伤","B淋巴细胞致敏"],"a":0,"e":"肾小球肾炎的发病以免疫机制为核心，循环免疫复合物沉积或抗体与肾小球内抗原原位反应形成免疫复合物，激活补体并招募炎症细胞造成损伤。T、B淋巴细胞致敏主要参与细胞免疫与移植排斥。免疫功能低下不构成直接损伤机制，抗体直接损伤仅见于抗GBM型"},{"q":"高血压病时，细小动脉硬化的主要病理改变是","o":["内膜结缔组织增生","内膜弹力纤维增生","内膜胆固醇沉着","管壁玻璃样变","内膜下有粥样物质沉着"],"a":3,"e":"缓进型高血压的细动脉硬化表现为管壁玻璃样变，血浆蛋白渗入内皮细胞下沉积，管壁增厚、管腔狭窄，最易累及肾入球动脉、视网膜动脉和脾中央动脉。内膜结缔组织增生、弹力纤维增生及内膜下粥样物质沉着属动脉粥样硬化的改变"},{"q":"早期动脉粥样硬化的肉眼病变是","o":["脂纹","纤维斑块","粥样坏死","出血","玻璃样变"],"a":0,"e":"脂纹是动脉粥样硬化肉眼可见的最早病变，呈点状或条纹状黄色、不隆起或微隆起于内膜，常见于主动脉后壁及分支开口处，镜下为大量泡沫细胞聚集。B项纤维斑块由脂纹发展而来，表面有纤维帽；C项粥样坏死为斑块后期改变；D项出血、E项玻璃样变为继发改变，均非早期表现"},{"q":"表达AFP最强的癌是","o":["卵巢癌","肝癌","结肠癌","子宫内膜癌","胃癌"],"a":1,"e":"甲胎蛋白是肝细胞癌最常用的血清标志物，由肝癌细胞重新表达，阳性率和浓度均居各类肿瘤之首，故表达最强。A项卵巢癌多查CA125；C项结肠癌、E项胃癌常查CEA；D项子宫内膜癌无特异AFP升高，AFP主要提示肝细胞来源肿瘤"},{"q":"关于慢性萎缩性胃炎的病理特点，下列哪项是错误的","o":["胃黏膜萎缩变薄","腺体变小，并可有囊性扩张","肠上皮化生","胃黏膜表面有很多结节状突起，中心凹陷似痘疹","壁细胞和主细胞消失"],"a":3,"e":"慢性萎缩性胃炎胃黏膜变薄，腺体变小、数目减少，可伴囊性扩张和肠上皮化生，壁细胞与主细胞减少乃至消失。表面结节状突起、中心凹陷似痘疹是疣状胃炎（痘疹状胃炎）的内镜与病理表现，故该项错误"},{"q":"晚期胃癌，最常发生转移的远处淋巴结为","o":["颈部","腋窝","腹股沟","左锁骨上","胃窦部小弯处"],"a":3,"e":"胃癌经淋巴道转移至胸导管，再入左锁骨上淋巴结，即Virchow淋巴结，为晚期胃癌最常累及的远处淋巴结。腋窝淋巴结是乳腺癌转移的首站；颈部淋巴结多见于鼻咽癌、甲状腺癌；腹股沟淋巴结收纳下肢及会阴部引流，胃癌一般不累及"},{"q":"前列腺增生的发生和（ ）有关","o":["雌激素","雄激素","HPV感染","HBV感染","HHV8感染"],"a":1,"e":"前列腺增生（良性前列腺增生）的发生与雄激素密切相关，双氢睾酮刺激前列腺间质与腺体增生，多见于老年男性。雌激素仅起协同调节作用，HPV、HBV、HHV8感染分别与宫颈癌、肝癌、Kaposi肉瘤相关，与前列腺增生无关"},{"q":"人类免疫缺陷病毒可感染组织中的","o":["单核巨噬细胞","中性粒细胞","K细胞","NK细胞","B细胞"],"a":0,"e":"HIV经gp120与CD4结合入侵，表达CD4的T淋巴细胞为主要靶细胞，脑、淋巴结和肺等组织中的单核巨噬细胞亦可被感染，感染率可达10%～50%，并成为病毒储存库。中性粒细胞、NK细胞、K细胞与B细胞不表达CD4，不被HIV感染"},{"q":"下列疾病的出血不属于漏出性出血","o":["维生素C缺乏","食管下段静脉曲张","流行性出血热","原发免疫性血小板减少症","血友病"],"a":1,"e":"食管下段静脉曲张破裂属破裂性出血，门静脉高压使静脉壁薄而膨出，破裂时出血量大。漏出性出血是毛细血管和毛细血管后静脉通透性增高、红细胞经扩大的内皮间隙漏出，见于维生素C缺乏、流行性出血热、原发免疫性血小板减少症和血友病。A、C、D、E四项均属此机制"},{"q":"良性高血压最具特征性的动脉病变是","o":["细动脉的玻璃样变","细动脉的纤维素样坏死","细小动脉内膜炎","动脉粥样硬化","动脉中层钙化"],"a":0,"e":"良性高血压最具特征性的动脉病变为细动脉玻璃样变，因长期高压使血浆蛋白渗入细动脉壁。细动脉纤维素样坏死为恶性高血压特征；细小动脉内膜炎见血栓闭塞性脉管炎；动脉粥样硬化、中层钙化分别为大中动脉病变，均非良性高血压特征"},{"q":"浆液性炎症中，其渗出的浆液内蛋白质含量为","o":["1%～3%","3%～5%","5%～7%","7%～9%","＞10%"],"a":1,"e":"浆液性渗出液蛋白质含量约3%~5%，以白蛋白为主，细胞少、液体清亮，见于水疱、浆膜腔积液及急性炎症早期。纤维蛋白性炎渗出蛋白超过5%并含大量纤维蛋白；漏出液蛋白质含量低于3%"},{"q":"急性细菌性痢疾的假膜成分除外","o":["细菌","大量纤维蛋白","淋巴细胞","坏死上皮","中性粒细胞"],"a":2,"e":"急性菌痢的假膜由纤维蛋白、坏死脱落的黏膜上皮、中性粒细胞及大量繁殖的细菌共同构成，故假膜成分中不含淋巴细胞。淋巴细胞是慢性炎症与病毒感染的主要浸润细胞，在菌痢的急性假膜性炎中并非组成成分；中性粒细胞坏死形成脓细胞，是假膜的主要炎细胞"},{"q":"干性坏疽与湿性坏疽的区别在于前者","o":["好发生于四肢末端","与正常组织分界清楚","全身中毒症状严重","静脉回流通畅","有明显的臭味"],"a":3,"e":"干性坏疽发生于动脉阻塞而静脉回流尚通畅的四肢末端，水分不断蒸发使坏死区干燥皱缩、呈黑色，与正常组织界限清楚，腐败较轻。湿性坏疽因静脉回流受阻、水分多，腐败菌繁殖，肿胀呈蓝绿色、界限不清、有明显臭味并伴严重全身中毒症状"},{"q":"流行性脑脊髓膜炎是","o":["化脓性炎","变质性炎","出血性炎","纤维素性炎","肉芽肿性炎"],"a":0,"e":"流行性脑脊髓膜炎由脑膜炎双球菌引起，蛛网膜下腔充满灰黄色脓性渗出物，属急性化脓性炎症。乙型脑炎为变质性炎。出血性炎见于流行性出血热与鼠疫。纤维蛋白性炎见于大叶性肺炎与白喉。肉芽肿性炎见于结核病与结节病"},{"q":"最常出现砂粒体的甲状腺癌是","o":["髓样癌","滤泡性癌","未分化癌","乳头状癌","鳞状细胞癌"],"a":3,"e":"甲状腺乳头状癌的乳头间质内常见同心圆层状钙化的砂粒体，为诊断的重要依据。滤泡癌缺乏乳头和砂粒体，易血行转移；髓样癌间质可有淀粉样物沉积，刚果红染色阳性；未分化癌由未分化细胞组成；鳞状细胞癌可见角化珠与细胞间桥"},{"q":"慢性萎缩性胃炎B型的表现有","o":["胃体部黏膜弥漫性病变","胃窦部黏膜病变严重","血清自身抗体阳性","维生素B吸收障碍","常伴有恶性贫血"],"a":1,"e":"B型萎缩性胃炎病变以胃窦部为主且较重，血清壁细胞抗体与内因子抗体阴性，不引起恶性贫血及维生素B12吸收障碍。A型累及胃体、胃底，自身抗体阳性，胃酸分泌显著减少，常伴恶性贫血"},{"q":"结核结节中的Langhans巨细胞来源于","o":["支气管上皮细胞","上皮样细胞","肺泡上皮细胞","间叶细胞","成纤维细胞"],"a":1,"e":"朗汉斯巨细胞由上皮样细胞融合而成，或核分裂而胞质不分裂形成，核排列于胞质周边呈马蹄形或环形。上皮样细胞由巨噬细胞转化而来，二者构成结核结节的主体。支气管上皮、肺泡上皮与间叶细胞不参与其形成，成纤维细胞仅构成结节外周成分"},{"q":"HIV选择性破坏","o":["Ts细胞","Th细胞","TI细胞","Tc细胞","树突状细胞"],"a":1,"e":"HIV的包膜糖蛋白gp120与CD4分子结合，主要侵犯CD4+的辅助性T细胞即Th细胞，使其进行性减少，导致细胞免疫功能严重缺陷。Ts细胞、Tc细胞表面CD4表达低，不是主要靶细胞；树突状细胞可被感染并参与病毒播散，但非选择性破坏的主要对象"},{"q":"慢性支气管炎的病变性质是","o":["慢性特异性炎症","慢性非特异性炎症","急性浆液性炎症","急性出血性炎症","急性化脓性炎症"],"a":1,"e":"慢性支气管炎是气管支气管黏膜的慢性非特异性炎症，以黏液腺增生、纤毛受损和慢性炎细胞浸润为特征。非特异性指区别于结核、梅毒等特异性肉芽肿性炎，亦非急性炎症，故为慢性非特异性炎症"},{"q":"弥漫性腱鞘巨细胞瘤组织学可见","o":["滑膜细胞变性、坏死、脱落","滑膜细胞增生并吞噬大量含铁血黄素","滑膜细胞增生并吞噬大量脂褐素","滑膜细胞增生并吞噬大量黑色素","间质细胞无改变"],"a":1,"e":"弥漫性腱鞘巨细胞瘤即色素沉着绒毛结节性滑膜炎，滑膜细胞增生并吞噬含铁血黄素与脂质，多核巨细胞散在，含铁血黄素使组织呈黄褐色。滑膜细胞变性坏死见于类风湿关节炎；脂褐素见于萎缩心肌与肝细胞；黑色素见于黑色素瘤"},{"q":"弥散性血管内凝血（DIC）时引起的出血，与其关系最为密切的因素是","o":["肝脏合成凝血因子障碍","凝血因子Ⅻ被激活","凝血因子被大量消耗","血管通透性增高","血小板被激活"],"a":2,"e":"DIC时微血管内广泛微血栓形成，消耗大量凝血因子（尤其Ⅰ、Ⅱ、Ⅴ、Ⅷ）和血小板，继发纤溶亢进，故表现为出血。肝脏合成凝血因子障碍见于重症肝病；因子Ⅻ激活为启动环节；血管通透性增高引起漏出性出血，并非凝血因子消耗所致"},{"q":"不属于类风湿性关节炎病变特点的是","o":["急性坏死性动脉炎","滑膜下淋巴滤泡的形成","关节软骨表面血管翳的形成","Aschoff小体的生成","晚期关节的畸形"],"a":3,"e":"类风湿性关节炎特点为滑膜下淋巴滤泡形成、关节软骨表面血管翳、急性坏死性动脉炎及晚期关节畸形。Aschoff小体是风湿热（风湿病）的特征性病变，多位于心肌间质，不属于类风湿性关节炎的病变特点"},{"q":"下列病变中癌变可能性较大的是","o":["十二指肠溃疡","慢性萎缩性胃炎","浅表性胃炎","肥厚性胃炎","疣状胃炎"],"a":1,"e":"慢性萎缩性胃炎伴肠上皮化生和异型增生属癌前病变，与肠型胃癌关系密切，故癌变可能性最大。A项十二指肠溃疡几乎不癌变；C项浅表性胃炎腺体完整，一般不癌变；D项肥厚性胃炎恶变罕见；E项疣状胃炎恶变报道少。胃溃疡癌变率约1%，亦低于慢性萎缩性胃炎"},{"q":"大结节性肝硬化，结节粗大且大小不均，多数结节直径大于（ ），纤维间隔较宽，且宽窄不一","o":["5cm","3cm","5mm","4mm","3mm"],"a":4,"e":"大结节型肝硬化结节粗大、大小不均，多数直径大于3mm，纤维间隔宽，且宽窄不一；小结节型直径一般小于3mm。5cm、3cm、5mm、4mm 均超出教材界值，3mm 是划分大、小结节型的界值"},{"q":"与EB病毒感染密切相关的淋巴瘤类型是","o":["蕈样肉芽肿（蕈样霉菌病）","霍奇金淋巴瘤","外周T细胞淋巴瘤","滤泡性淋巴瘤","弥漫性大B细胞淋巴瘤"],"a":1,"e":"霍奇金淋巴瘤与EB病毒感染关系密切，瘤组织中EB病毒检出率可高达75%，经典型各亚型均可见。蕈样肉芽肿为原发皮肤T细胞淋巴瘤。滤泡性淋巴瘤与t（14；18）易位相关。弥漫性大B细胞淋巴瘤仅部分伴EBV，相关性不及霍奇金淋巴瘤"},{"q":"在结核病的基本病变以增生为主时，常形成","o":["增生性息肉","结核性肉芽肿","结核球","假结核结节","炎性假瘤"],"a":1,"e":"结核病以增生为主时形成结核结节即结核性肉芽肿，由上皮样细胞、朗汉斯巨细胞、外周淋巴细胞及成纤维细胞构成，中央常伴干酪样坏死，具诊断价值。增生性息肉属黏膜上皮的增生性病变。结核球为继发性肺结核的球形干酪样坏死灶。假结核结节见于血吸虫虫卵周围"},{"q":"如图显示肿瘤的转移方式是","o":["淋巴道转移","血行转移","种植转移","直接蔓延","广泛转移"],"a":2,"e":"本题原题配有图片，图片未随文档保留，以下解析依文字线索推断：题干涉及图片/信息缺失，无法作答。肿瘤转移包括淋巴道转移（癌多见，栓子入淋巴结）、血行转移（肉瘤多见，达肝肺骨）、种植转移（体腔器官肿瘤脱落种植，如卵巢Krukenberg瘤）与直接蔓延（相邻组织连续浸润）。须凭图片观察瘤细胞所在部位或管道才能判定，无图不能确定\n\n官方题库中缺失图片"},{"q":"动脉粥样硬化脂纹病变中主要的细胞成分是","o":["单核细胞","T淋巴细胞","泡沫细胞","平滑肌细胞","中性粒细胞"],"a":2,"e":"脂纹是AS最早期的病变，内膜下大量泡沫细胞聚集，泡沫细胞由巨噬细胞和迁入的平滑肌细胞摄取氧化型LDL形成，苏丹Ⅲ染色呈橘红色。T淋巴细胞仅少量散布；中性粒细胞不参与；单核细胞是泡沫细胞的前体，不是病灶主体"},{"q":"下列哪项最符合转移性肿瘤的概念","o":["远隔器官发生的另一种肿瘤","血行转移的结果","可形成“癌脐”","与原发瘤属同一类型","可进一步发生转移"],"a":3,"e":"转移性肿瘤指原发瘤细胞经血道、淋巴道或种植播散至远隔部位形成的继发瘤，其组织学类型与原发瘤相同，故与原发瘤属同一类型最符合概念。癌脐为体检体征；血行转移只是途径之一；远隔器官原发的另一肿瘤属重复癌"},{"q":"慢性风湿性心瓣膜病最常见的联合瓣膜病变是","o":["主动脉瓣和肺动脉瓣","二尖瓣和三尖瓣","三尖瓣和肺动脉瓣","二尖瓣和主动脉瓣","三尖瓣和主动脉瓣"],"a":3,"e":"慢性风湿性心瓣膜病最常见联合瓣膜病变为二尖瓣与主动脉瓣联合受累。主动脉瓣与肺动脉瓣、二尖瓣与三尖瓣、三尖瓣与肺动脉瓣及三尖瓣与主动脉瓣等组合均较少见"},{"q":"下列哪些病变的出血是属于漏出性出血","o":["脑动脉瘤","肺结核","肺淤血","胃溃疡","子宫颈癌"],"a":2,"e":"肺淤血时肺静脉压及毛细血管内压升高，内皮细胞间隙扩大、基底膜受损，红细胞漏出至肺泡腔，形成淤血性出血，属漏出性出血，可见心衰细胞。A项脑动脉瘤破裂、D项胃溃疡侵蚀血管、E项宫颈癌破坏血管均为破裂性出血；B项肺结核空洞内血管破裂亦属破裂性出血"},{"q":"二尖瓣狭窄不会引起","o":["右心房增大","左心房增大","右心室增大","左心室增大","肺动脉高压"],"a":3,"e":"二尖瓣狭窄使左心房血液流入左心室受阻，左心房压升高而扩大，继而肺静脉淤血、肺动脉高压、右心室肥大扩张，最终右心房增大。单纯二尖瓣狭窄不累及左心室，左心室因充盈减少反而缩小，故不会出现左心室增大"},{"q":"下列哪一项最能体现宫颈原位癌的特征","o":["发生于子宫颈黏膜的柱状上皮","未发生转移","是一种早期癌","是一种基底细胞癌","癌组织波及上皮全层，但未突破基底膜"],"a":4,"e":"宫颈原位癌指异型增生细胞累及上皮全层，细胞具癌细胞形态，但基底膜完整、未向间质浸润，属早期癌。未发生转移是原位癌的生物学表现，不能作为确诊依据。基底细胞癌是皮肤附属器来源的独立肿瘤类型。原位癌可长期保持，也可进展为浸润癌"},{"q":"与免疫复合物无关的肾小球肾炎是","o":["膜性肾炎","急性肾炎","微小病变性肾小球病","膜增生性肾小球肾炎","新月体性肾小球肾炎"],"a":2,"e":"微小病变性肾小球病（脂性肾病）发病与T细胞功能异常、足细胞足突融合有关，不依赖免疫复合物沉积。膜性肾炎、急性肾炎、膜增生性肾炎、新月体性肾炎均有免疫复合物形成或沉积参与"},{"q":"高血压的血管壁玻璃样变主要发生于","o":["细小动脉","毛细血管","大动脉","中动脉","细小静脉"],"a":0,"e":"高血压时血浆蛋白渗入细小动脉壁，平滑肌细胞产生大量基质，形成均质红染的玻璃样物质，使管壁增厚、管腔狭窄，称细小动脉玻璃样变。毛细血管无中膜不发生该变；大、中动脉以粥样斑块为主；细小静脉不典型"},{"q":"引起慢性肺源性心脏病最常见的原因是","o":["支气管哮喘","支气管扩张症","慢性支气管炎并发阻塞性肺气肿","肺尘埃沉着病","慢性纤维空洞型肺结核"],"a":2,"e":"慢性肺源性心脏病最常见病因为慢性阻塞性肺疾病，即慢性支气管炎并发阻塞性肺气肿，导致肺血管阻力增加和肺动脉高压。支气管哮喘、支气管扩张症、肺尘埃沉着病及慢性纤维空洞型肺结核亦可致病，但远不如慢支并发肺气肿常见"},{"q":"下列哪项叙述是更年期子宫内膜的组织学表现","o":["内膜薄，腔狭而直，腺上皮立方","内膜增厚，腺上皮增生，间质致密","内膜腺体形态不规则、排列紊乱，腺腔扩张，腺上皮高低不一，缺少分泌现象","内膜的间质细胞分化成为蜕膜细胞和内膜颗粒细胞","腺体上皮细胞质内出现空泡"],"a":2,"e":"更年期卵巢功能衰退、雌激素水平波动，子宫内膜呈增生与萎缩交替的不规则改变：腺体形态不规则、排列紊乱、腺腔扩张，腺上皮高低不一，缺少分泌现象。A项内膜薄、腔狭而直为绝经后萎缩内膜；B项内膜增厚、腺上皮增生为增生期；D项蜕膜细胞化为妊娠期；E项腺上皮空泡为分泌期"},{"q":"下列属于病理性再生的是","o":["消化道黏膜上皮细胞的更新","子宫内膜周期性脱落、增生、修复","鳞状上皮表层角化细胞脱落、基底细胞增生","血细胞的更新","皮肤缺损后由周围的被覆上皮增生、修复"],"a":4,"e":"病理性再生指病理状态下细胞、组织缺损后发生的再生，皮肤缺损后由创缘基底层细胞增生、迁移覆盖修复即属此类。A项消化道黏膜上皮更新、B项子宫内膜周期性增生修复、C项表皮角化脱落与基底细胞增生、D项血细胞更新，均为生理性再生，是机体正常的新旧更替"},{"q":"既有肝细胞的大片坏死，又有肝细胞的结节状再生，是哪种肝炎","o":["慢性轻度肝炎","急性重型肝炎","亚急性重型肝炎","急性普通型肝炎","慢性中度肝炎"],"a":2,"e":"亚急性重型肝炎的镜下特点是既有肝细胞的亚大块坏死，又有结节状肝细胞再生，坏死区与再生结节并存，肝体积缩小、表面不平。急性重型肝炎为弥漫性大片坏死而无再生；急性普通型肝炎以点状坏死为主"},{"q":"下列关于软骨瘤的叙述不正确的是","o":["多位于手、足各骨","男性发病率高","外生性软骨瘤位于骨皮质外侧","生长快，局部症状明显","内生性软骨瘤位于骨髓腔"],"a":3,"e":"软骨瘤为良性肿瘤，生长缓慢，多无疼痛，常因偶然发现或病理性骨折就诊，故生长快、局部症状明显不符合其生物学行为。内生软骨瘤位于骨髓腔，骨膜软骨瘤位于骨皮质外侧；本病多发生于手、足短管状骨，男性略多。生长迅速、疼痛明显者应警惕软骨肉瘤"},{"q":"下述均为急性链球菌感染后肾小球肾炎的特点，但除外","o":["多见于儿童","明显血尿","肾小球呈缺血状","上皮下驼峰状电子致密物","肾小球毛细血管内有链球菌菌栓"],"a":4,"e":"急性链球菌感染后肾炎由免疫复合物介导，菌体本身不在肾小球内形成菌栓，故该项不属本病特点。本病多见于儿童，常有明显血尿，免疫荧光呈颗粒状沉积，电镜下上皮下驼峰状电子致密物为特征。肾小球因内皮与系膜细胞增生肿胀、毛细血管腔狭窄而缺血"},{"q":"病毒性肝炎肝硬化最显著的特征是","o":["灶性肝细胞坏死","大量中性粒细胞浸润","大量嗜酸性粒细胞浸润","肝细胞脂肪变性","假小叶形成"],"a":4,"e":"病毒性肝炎肝硬化由肝细胞反复坏死、纤维组织增生及肝细胞结节状再生发展而来，假小叶形成是最显著的组织学特征。灶性坏死见于普通型肝炎，中性粒细胞浸润见于化脓性炎，脂肪变性多见于酒精性肝病"},{"q":"下列属病理性再生的是","o":["血细胞的更新","肠道黏膜上皮的更新","子宫内膜的周期性再生","皮肤缺损由周围的被覆上皮增生修复","口腔黏膜上皮脱落更新"],"a":3,"e":"病理性再生指组织缺损后由同种细胞增生修复，如皮肤缺损由周围被覆上皮增生覆盖。血细胞更新、肠道黏膜上皮更新、子宫内膜周期性再生、口腔黏膜上皮脱落更新均属生理性再生，按正常周期替换。若再生组织不能恢复原有结构，则由肉芽组织修复，属不完全再生"},{"q":"肿瘤细胞核染色体多呈","o":["单倍体","双倍体","三倍体","四倍体","多倍体"],"a":4,"e":"恶性肿瘤细胞染色体多呈非整倍体或多倍体，核内DNA含量增多、核深染，是细胞异型性的重要表现。正常体细胞为双倍体，单倍体见于生殖细胞，三倍体与四倍体虽属异常但不足以概括肿瘤的染色体特征"},{"q":"下述关于动脉粥样硬化性固缩肾的描述中，哪项是错误的","o":["可引起肾血管性高血压","肾动脉开口处或主干近侧端狭窄","肾动脉粥样硬化可并发血栓形成","受累的肾脏出现较大块的凹陷瘢痕","常引起肾功能不全"],"a":4,"e":"动脉粥样硬化性固缩肾为肾动脉狭窄致肾缺血萎缩，形成较大凹陷瘢痕，可引起肾血管性高血压；因病变不对称、进展缓慢，健存肾单位代偿，较少引起肾功能不全，故该项错误。肾动脉开口处及主干近侧端最常受累，并可继发血栓形成"},{"q":"急性肾小球肾炎的病变是","o":["纤维素性炎","变态反应性炎","变质性炎","化脓性炎","增生性炎"],"a":1,"e":"急性肾小球肾炎由链球菌抗原抗体复合物沉积于基底膜，激活补体引起免疫损伤，属变态反应性炎。其形态学表现为毛细血管内皮及系膜细胞增生，故又称增生性肾炎；纤维素性炎、化脓性炎与变质性炎均不符合其本质"},{"q":"间质性肺炎的特点不包括","o":["好发于儿童和青年","主要由肺炎支原体和病毒引起","一般无肺实变体征","预后大多较差","肺间质淋巴细胞和单核细胞浸润"],"a":3,"e":"间质性肺炎多由肺炎支原体和病毒引起，好发于儿童和青年，病变位于肺间质，肺泡内渗出少，一般无明显肺实变体征，预后大多良好。A项好发年龄、B项病原、C项无实变体征、E项间质淋巴细胞和单核细胞浸润均正确。预后差的是小儿及老年体弱者所患的小叶性肺炎"},{"q":"侵蚀性葡萄胎与绒毛膜癌的主要区别是","o":["细胞有明显的增生和异型性","浸润肌层","有出血坏死","转移的阴道结节","有绒毛结构"],"a":4,"e":"侵蚀性葡萄胎镜下可见水泡状绒毛，绒毛常侵入子宫肌层并伴出血坏死；绒毛膜癌由分化不良的滋养细胞构成，无绒毛结构，有无绒毛是两者的鉴别要点。两者均可浸润肌层、发生出血坏死并出现阴道转移结节，不能据以区分"},{"q":"下列哪项不符合凝固性坏死的特点","o":["坏死灶的质地较坚实","坏死灶体积可明显肿胀","坏死灶色泽灰白或黄白","坏死灶的水分含量减少","坏死灶的结构轮廓可保存"],"a":1,"e":"凝固性坏死的本质是蛋白质变性凝固，坏死组织水分减少、质地变实，色泽灰白或黄白，组织结构轮廓可保存，故体积明显肿胀不符。A项质地坚实、C项色泽灰白、D项水分减少、E项轮廓保存均符合。肿胀多见于液化性坏死和炎症性水肿；新鲜梗死灶因崩解吸收水分可轻度隆起，属早期大体改变"},{"q":"FISH主要检测细胞内哪项指标的变化","o":["基因拷贝数","DNA含量","mRNA含量","蛋白质含量","基因突变位点"],"a":0,"e":"FISH以荧光标记核酸探针与染色体原位杂交，检测基因扩增或缺失等拷贝数变化，如HER2扩增、BCR-ABL融合。DNA含量多用流式或图像分析测定，mRNA用RT-PCR或原位杂交，蛋白用免疫组化，点突变以测序最可靠"},{"q":"下述关于风湿性心内膜炎的叙述中，哪项是正确的","o":["瓣膜赘生物内有细菌","瓣膜赘生物牢固粘连","受累瓣膜容易发生穿孔、破裂","受累瓣膜以三尖瓣多见","赘生物位于房室瓣心室面"],"a":1,"e":"风湿性心内膜炎的疣状赘生物由血小板和纤维蛋白构成，单行排列于瓣膜闭锁缘，附着牢固、不易脱落，故不含细菌，也极少引起穿孔。感染性心内膜炎的赘生物含细菌、松脆易碎，常致瓣膜溃疡穿孔；受累瓣膜以二尖瓣最多见，三尖瓣少见"},{"q":"如图，下列脾梗死的形态特征哪项是错误的","o":["组织轮廓尚保存","镜下呈凝固性坏死","梗死区呈锥形","梗死灶周围无炎症反应","梗死灶呈灰白色"],"a":3,"e":"本题原题配有图片，图片未随文档保留，以下解析依文字线索推断：题干涉及图片/信息缺失，无法作答。脾梗死属贫血性梗死，呈凝固性坏死，梗死区锥形、灰白色，组织轮廓尚保存，周围有充血出血带及炎症反应，故无炎症反应的说法错误。C项锥形、E项灰白色、B项凝固性坏死、A项轮廓保存均为其真实特征\n\n官方题库中缺失图片"},{"q":"皮肤纤维组织细胞瘤的病变特点中，不包括","o":["病变呈漩涡状排列","病变多位于真皮和皮下","常见图顿巨细胞","瘤周呈高度浸润性生长，呈长条索状向周围脂肪伸展","有时可见泡沫样细胞"],"a":3,"e":"皮肤纤维组织细胞瘤位于真皮和皮下，由梭形纤维细胞和组织细胞构成，呈漩涡状或席纹状排列，可见图顿巨细胞和泡沫样细胞，体积小、界清、无明显浸润。瘤周呈长条索状向周围脂肪高度浸润生长的是隆突性皮肤纤维肉瘤和韧带样纤维瘤"},{"q":"下列不属于门脉高压症的表现的是","o":["脾大","肝大","食管-胃底静脉曲张","痔核形成","腹水"],"a":1,"e":"门脉高压症表现为脾大及脾功能亢进、食管胃底静脉曲张、腹水与痔核形成（直肠静脉丛曲张）。肝大由肝细胞病变及纤维化本身引起，属肝硬化肝脏改变，不属门脉高压的表现。腹壁浅静脉曲张亦属门脉高压侧支循环开放的表现"},{"q":"伤寒的传染途径是","o":["经口传染","呼吸传染","血液传染","接触传染","以上途径都可以"],"a":0,"e":"伤寒由伤寒沙门菌经口感染，细菌随粪、尿排出，污染水、食物或经苍蝇传播，侵入回肠末段淋巴组织，故为消化道传播。B项呼吸道传播见于流脑、肺结核；C项血液传播见于乙型、丙型肝炎和疟疾；D项接触传播多为皮肤黏膜直接接触。败血症期虽现菌血症，入侵门户仍是消化道"},{"q":"食管癌最好发的部位是","o":["上段","下段","中段","起始部","末端"],"a":2,"e":"食管癌好发于三个生理性狭窄部，以中段最多见，其次为下段，上段最少。中段癌常转移至食管旁和肺门淋巴结，下段癌转移至贲门旁及腹腔上部淋巴结，上段癌转移至颈部和上纵隔淋巴结。上段癌少见且预后较差；贲门癌属胃癌范畴，需与下段食管癌侵犯贲门相鉴别"},{"q":"梗死灶的形状取决于","o":["坏死灶的大小","坏死的类型","梗死灶内的含血量","该器官的血管分布","侧支循环的建立"],"a":3,"e":"梗死灶的形状取决于器官血管的分布方式：脾、肾、肺血管呈锥形分支，梗死灶呈锥形；肠系膜血管呈扇形，肠梗死呈节段形；冠状动脉分支不规则，心肌梗死呈地图状。A项坏死灶大小、B项坏死类型决定质地而非形状，C项含血量决定颜色，E项侧支循环影响梗死是否发生"},{"q":"流行性乙型脑炎的病变性质属于","o":["变质性炎","渗出性炎","增生性炎","肉芽肿性炎","化脓性炎"],"a":0,"e":"乙脑病变以神经细胞变性坏死为主，伴胶质细胞增生和血管周围淋巴细胞浸润，属变质性炎。渗出性炎以渗出为主，如大叶性肺炎的纤维蛋白性炎。增生性炎以组织增生为主，如结核性肉芽肿。化脓性炎以中性粒细胞渗出和脓液形成为特征，见于流行性脑脊髓膜炎"},{"q":"早期胃癌是指","o":["仅限于黏膜下层以内","仅限于肌层以内","仅限于浆膜以内","仅限于局部淋巴结转移","仅限于扩散至邻近器官"],"a":0,"e":"早期胃癌指癌组织浸润仅限于黏膜层或黏膜下层，无论有无淋巴结转移，术后5年生存率可达90%以上。浸润至肌层或浆膜层属中晚期癌；扩散至邻近器官或有远处转移属晚期。早期胃癌分隆起型、表浅型和凹陷型，以凹陷型最多见，镜下多为管状腺癌"},{"q":"阴茎癌最常见的类型是","o":["腺癌","鳞状细胞癌","髓样癌","小管癌","黏液癌"],"a":1,"e":"阴茎癌绝大多数为鳞状细胞癌，多发生于阴茎头和包皮内板，与包茎、包皮过长及HPV感染相关。A项腺癌、C项髓样癌、D项小管癌、E项黏液癌均非阴茎癌的常见组织学类型，这些类型多见于乳腺、甲状腺或消化道等部位"},{"q":"高血压患者肾脏，其大体如图所示，该肾脏又称为","o":["继发性颗粒性固缩肾","大红肾","原发性颗粒性固缩肾","大白肾","蚤咬肾"],"a":2,"e":"高血压病晚期因入球动脉玻璃样变和肌型小动脉硬化，肾小球缺血硬化，萎缩与代偿肥大并存，形成原发性颗粒性固缩肾，表面呈细颗粒状。继发性颗粒性固缩肾见于慢性肾小球肾炎；大红肾、蚤咬肾为急性弥漫性增生性肾炎；大白肾见于膜性肾病"},{"q":"慢性浅表性胃炎肉眼所见主要是","o":["胃黏膜失去正常光泽","胃黏膜皱襞变浅或消失","胃黏膜薄而光滑","可见黏膜充血、水肿","黏膜下小血管清晰可见"],"a":3,"e":"慢性非萎缩性即浅表性胃炎，肉眼表现为黏膜充血、水肿，呈淡红色，可伴点状出血和糜烂，表面覆灰白或灰黄黏液性渗出物。A项失去正常光泽、B项皱襞变浅消失、C项黏膜薄而光滑、E项黏膜下小血管透见，均为慢性萎缩性胃炎黏膜变薄、腺体减少的表现"},{"q":"下列哪项不是慢性肾盂肾炎的主要病变特点","o":["病变可单侧也可双侧发生，且两侧改变不对称","肉眼观表现为肾体积缩小，有瘢痕","均由急性肾盂肾炎转变而来","代偿扩张的肾小管内可出现甲状腺滤泡样管型","肾盂、肾盏变形，黏膜粗糙"],"a":2,"e":"慢性肾盂肾炎可单侧或双侧发生且两侧不对称，肾体积缩小、表面有不规则瘢痕，肾盂肾盏变形、黏膜粗糙，部分肾小管代偿扩张呈甲状腺滤泡样管型。相当一部分患者无急性肾盂肾炎病史，由反流性肾病或尿路梗阻缓慢发展而成，故并非均由急性转变"},{"q":"慢性胃溃疡最多见的部位是","o":["大弯近幽门部","小弯近幽门部","近贲门部","小弯角切迹部","小弯近胃窦部"],"a":4,"e":"胃溃疡好发于胃窦部小弯侧、近幽门处，此处黏膜与胃酸接触时间长、血供相对较差、黏膜防御力弱。大弯侧、贲门部与胃底发生率低，小弯角切迹虽邻近但非最多发部位；十二指肠溃疡多见于球部前壁"},{"q":"下列哪项是发生干性坏疽的条件","o":["发生于肺或子宫等内脏","有明显的腐败菌感染","全身中毒症状严重","病变部分较干燥，腐败菌感染较轻","病灶内坏死组织分界，产生大量气体"],"a":3,"e":"干性坏疽发生于动脉阻塞而静脉回流仍通畅的四肢末端，水分不断蒸发使坏死组织干燥皱缩、呈黑色，腐败菌感染轻，与正常组织界限清楚。湿性坏疽发生于内脏且伴静脉回流受阻；气性坏疽由产气荚膜梭菌引起并产生大量气体"},{"q":"冠状动脉粥样硬化最常受累的动脉分支是","o":["右冠状动脉主干","左冠状动脉主干","左冠状动脉回旋支","右冠状动脉后降支","左冠状动脉前降支"],"a":4,"e":"冠状动脉粥样硬化以左冠状动脉前降支受累率最高，其余依次为右主干、左主干或左旋支、后降支，故透壁性心肌梗死多位于左心室前壁、心尖部及室间隔前2/3。右冠状动脉病变引起左心室后壁及室间隔后1/3梗死"},{"q":"下列哪项不是慢性阻塞性肺病的共同特征","o":["呼气阻力增加","肺组织实变","肺实质受损害","小气道受损害","肺功能不全"],"a":1,"e":"慢性阻塞性肺疾病包括慢性支气管炎和肺气肿，共同特点是肺实质与小气道受损，导致气道阻塞、呼气阻力增加和肺功能不全。肺组织实变是肺炎的渗出性改变，气道仍然通畅，不属于COPD的共同特征"},{"q":"亚急性细菌性心内膜炎的特点除外下列哪项","o":["赘生物单个或多个，呈息肉状或菜花状","多发生于原有病变的瓣膜上","镜下表面有细菌团","赘生物脱落引起动脉栓塞和血管炎","外观污秽、质松软、灰黄、易脱落"],"a":2,"e":"亚急性感染性心内膜炎赘生物由纤维蛋白、血小板、坏死组织、炎细胞及细菌团构成，细菌多位于赘生物深部，表面为纤维蛋白，故表面有细菌团的描述不成立。赘生物呈息肉或菜花状、污秽质脆易脱落，多附着于已有病变的瓣膜，脱落可致动脉栓塞与血管炎"},{"q":"小叶性肺炎的病变性质是","o":["浆液性炎","卡他性炎","肉芽肿性炎","化脓性炎","纤维素性炎"],"a":3,"e":"小叶性肺炎为细支气管及周围肺泡的化脓性炎，以中性粒细胞渗出为主，形成实变灶。浆液性炎见于结核早期渗出；卡他性炎见于感冒与卡他性支气管炎；纤维素性炎见于大叶性肺炎；肉芽肿性炎见于结核、结节病"},{"q":"下列不是扩张型心肌病心肌组织的镜下特点的是","o":["心肌细胞呈均匀性肥大","核大、深染","核形不整，出现沟裂","胞质空泡变性、嗜酸性变","小灶性液化性肌溶解"],"a":0,"e":"扩张型心肌病镜下心肌细胞肥大与萎缩并存、分布不均，核大深染、核形不整并出现沟裂，胞质空泡变性、嗜酸性变及小灶性液化性肌溶解。均匀性肥大是高血压病左心室向心性肥大的特点，与本病不符"},{"q":"下列关于乙型脑炎病理改变的描述错误的是","o":["小血管周围有“血管套”形成","神经细胞变性坏死","筛状软化灶形成","胶质结节形成","蛛网膜下腔有较多的中性粒细胞"],"a":4,"e":"乙型脑炎的基本病变为神经细胞变性坏死、血管周围淋巴细胞袖套状浸润、筛状软化灶形成和胶质结节，脑膜仅轻度充血及单核细胞浸润。蛛网膜下腔大量中性粒细胞渗出是流行性脑脊髓膜炎的化脓性炎表现，不属于乙脑"},{"q":"微小病变病电镜下特征性病变是","o":["肾小球系膜内见致密沉积物","系膜细胞增生","肾小球毛细血管壁增厚","脏层上皮细胞足突广泛消失","肾小球毛细血管基膜上皮细胞侧见致密沉积物"],"a":3,"e":"微小病变性肾小球病的电镜特征是弥漫性脏层上皮细胞足突消失，基底膜正常、无电子致密物沉积，免疫荧光阴性。上皮下驼峰状沉积物见于急性弥漫性增生性肾小球肾炎；基底膜增厚伴钉突形成见于膜性肾病；系膜内致密沉积物见于系膜增生性肾炎"},{"q":"二尖瓣关闭不全与狭窄的病变不同之处是","o":["左心房肥大","右心房肥大","左心室肥大","右心室肥大","体循环淤血"],"a":2,"e":"单纯二尖瓣狭窄时血流受阻于左心房与左心室之间，左心室充盈减少，不肥大甚至缩小；二尖瓣关闭不全时收缩期血液反流入左心房，左心房与左心室容量负荷均增加，引起左心室肥大扩张。两者均可致左心房、右心室肥大和体循环淤血"},{"q":"纤维素样坏死常发生于","o":["骨组织、细动脉壁","结缔组织、平滑肌组织","神经组织、细动脉壁","鳞状上皮组织、移行上皮组织","结缔组织、细动脉壁"],"a":4,"e":"纤维素样坏死好发于结缔组织与细动脉壁，见于风湿病、系统性红斑狼疮、结节性多动脉炎等，坏死物呈纤维素样红染。骨组织、神经组织、鳞状上皮、移行上皮及平滑肌组织均非其好发部位"},{"q":"肾细胞癌最常发生于","o":["随机发生","肾中部","肾下极","肾上极","肾门"],"a":3,"e":"肾细胞癌多发生于一侧肾脏，以肾上、下两极多见，其中上极更为常见，肉眼为淡黄色球形肿块，伴出血、坏死及囊性变。肾中部与肾门区明显少见；双侧多灶性者提示家族性遗传性肾癌；随机发生不是解剖部位的描述"},{"q":"肺气肿大体表现的描述不正确的是","o":["肺体积膨大","指压后压痕不易消退","肺边缘锐利","柔软，缺乏弹性","入水漂浮"],"a":2,"e":"肺气肿时肺体积显著膨大，色灰白，边缘钝圆而非锐利，柔软缺乏弹性，指压后压痕不易消退，因含气量大而入水漂浮。A项体积膨大、B项压痕不易消退、D项柔软缺乏弹性、E项入水漂浮均正确。边缘锐利见于正常肺或纤维化收缩的肺，与肺气肿的膨胀状态相反"},{"q":"肝细胞大片崩解坏死并有肝细胞结节状再生者见于","o":["慢性持续性肝炎","慢性活动性肝炎","亚急性重型肝炎","急性普通型肝炎","急性重型肝炎"],"a":2,"e":"亚急性重型肝炎的肝细胞坏死呈大片状，同时因病程较长而出现肝细胞结节状再生，坏死区网状支架塌陷、结缔组织增生，成为坏死后性肝硬化的基础。急性重型肝炎病程短，肝细胞弥漫大片坏死而再生不明显；慢性肝炎以点状、碎片状坏死为主；急性普通型肝炎以气球样变和点状坏死为主"},{"q":"前列腺癌常见的类型为","o":["鳞状细胞癌","移行细胞癌","腺癌","透明细胞癌","腺鳞癌"],"a":2,"e":"前列腺癌绝大多数为腺癌，多起源于前列腺外周带，与雄激素相关。鳞状细胞癌、移行细胞癌、透明细胞癌、腺鳞癌在前列腺均属罕见类型，不是常见类型"},{"q":"中晚期食管癌最常见的肉眼类型是","o":["髓质型","缩窄型","溃疡型","蕈伞型","隆起型"],"a":2,"e":"官方答案为【溃疡型】，但依据教材，正确答案为【髓质型】。中晚期食管癌分髓质型、蕈伞型、溃疡型和缩窄型，髓质型癌组织在壁内浸润性生长、累及食管周径大部，最多见，约占60%。溃疡型以深达肌层的火山口状溃疡为特点，缩窄型因纤维增生致环形狭窄，蕈伞型向腔内突起，均较少见"},{"q":"大叶性肺炎合并肺肉质变的机制是","o":["病变范围太广","纤维素渗出太多","吞噬细胞渗出太少","肺组织结构被炎症破坏","病程太长"],"a":2,"e":"大叶性肺炎时渗出纤维蛋白过多，而中性粒细胞等吞噬细胞渗出过少，或组织内抗胰蛋白酶过多，纤维蛋白不能被溶解清除，由肉芽组织机化，肺组织呈褐色肉样，即肺肉质变。A项病变范围、E项病程长短不是决定因素；D项结构被破坏是结果而非机制；B项单纯纤维蛋白渗出多尚不足以致病"},{"q":"动脉粥样硬化的早期病变中，最早迁入内膜的细胞是","o":["单核细胞","淋巴细胞","平滑肌细胞","成纤维细胞","中性粒细胞"],"a":0,"e":"动脉粥样硬化早期内皮损伤后，氧化型LDL吸引单核细胞黏附并迁入内膜下，转变为巨噬细胞源性泡沫细胞，故单核细胞是最早进入内膜的细胞。平滑肌细胞随后由中膜迁入增生，成为进展期泡沫细胞的主要来源；淋巴细胞参与免疫反应，中性粒细胞不参与"},{"q":"关于血管瘤的叙述，下列哪项是错误的","o":["无包膜，呈浸润性生长","多为先天性","随身体发育而长大，可自然消退","对放射治疗和化疗敏感","多发生于皮肤"],"a":3,"e":"血管瘤为先天性血管畸形，无包膜，呈浸润性生长，多发于皮肤，随身体发育长大，部分可自然消退，对放射治疗和化疗不敏感。A项无包膜浸润性生长、B项多为先天性、C项随发育长大并可消退、E项多发于皮肤均正确。血管瘤呈浸润性生长但生物学行为良性，不转移"},{"q":"主动脉关闭不全的患者有以下临床表现，除外","o":["股动脉枪击音","X线示心脏增大","主动脉瓣区收缩期杂音","水冲脉","脉压增大"],"a":2,"e":"主动脉瓣关闭不全时舒张期血液反流，收缩压升高、舒张压降低、脉压增大，出现水冲脉、股动脉枪击音，左室扩大致心脏增大，杂音为舒张期叹气样。主动脉瓣区收缩期杂音见于主动脉瓣狭窄或升主动脉扩张，故属例外"},{"q":"慢性胃炎是","o":["细菌引起的胃黏膜的一种特异性炎症","病毒引起的胃黏膜的一种特异性炎症","支原体引起的胃黏膜的一种特异性炎症","病原微生物引起的胃黏膜的一种非特异性炎症","不同原因引起的胃黏膜的一种非特异性炎症"],"a":4,"e":"慢性胃炎是不同病因引起的胃黏膜慢性非特异性炎症，幽门螺杆菌为主要病因，病变以黏膜充血水肿、炎细胞浸润及腺体萎缩、肠上皮化生为特点。A、B、C三项均把它限定为某一病原体所致的特异性炎症，与定义不符，细菌性者仅指幽门螺杆菌相关性胃炎，病毒、支原体并非其致病主体。D项把病因限为病原微生物，遗漏胆汁反流、药物、自身免疫等非感染因素"},{"q":"慢性风湿性瓣膜病常见的联合瓣膜病变是","o":["二尖瓣和三尖瓣病变","二尖瓣、主动脉瓣和三尖瓣病变","主动脉瓣和三尖瓣病变","二尖瓣和主动脉瓣病变","主动脉瓣和肺动脉瓣病变"],"a":3,"e":"风湿性心瓣膜病以二尖瓣受累最多，约占70%，其次为二尖瓣合并主动脉瓣，占20%～30%，故最常见的联合瓣膜病变是二尖瓣和主动脉瓣。三尖瓣和肺动脉瓣极少受累，单纯主动脉瓣病变仅占2%～5%"},{"q":"血栓转归中不会发生的是","o":["钙化","溶解","化生","机化","再通"],"a":2,"e":"血栓的转归为溶解吸收、机化与再通、钙化形成静脉石，化生不属其转归。化生是已分化成熟的细胞在刺激下转变为另一种分化成熟细胞的过程，如支气管鳞状上皮化生、胃黏膜肠上皮化生，与血栓无关"},{"q":"不是急性胆囊炎的临床转归的是","o":["急性化脓性胆囊炎","慢性胆囊炎","蜂窝织炎性胆囊炎","胆囊癌","坏疽性胆囊炎"],"a":3,"e":"急性胆囊炎的转归包括发展为蜂窝织炎性胆囊炎、坏疽性胆囊炎、胆囊积脓，穿孔后引起胆汁性腹膜炎，反复发作转为慢性胆囊炎。胆囊癌是原发恶性肿瘤，在胆囊结石和慢性胆囊炎长期刺激基础上发生，不是急性炎症的转归"},{"q":"如图所示，在慢性炎症灶中以下列哪种细胞最常见","o":["嗜酸性粒细胞","肥大细胞","淋巴细胞","嗜碱性粒细胞","中性粒细胞"],"a":2,"e":"本题原题配有图片，图片未随文档保留，以下解析依文字线索推断：题干涉及图片/信息缺失，无法作答。慢性炎症灶浸润的细胞以淋巴细胞、浆细胞和单核巨噬细胞为主，反映持续免疫反应与组织修复。中性粒细胞见于急性炎症；嗜酸性粒细胞见于寄生虫感染与变态反应；肥大细胞与嗜碱性粒细胞参与Ⅰ型超敏反应，数量少\n\n官方题库中缺失图片"},{"q":"急性感染性心内膜炎不存在的特点是","o":["常发生于原来已有病变的心瓣膜上","常是致病力强的化脓菌引起的脓毒血症的并发症之一","可致瓣膜糜烂、穿孔或破裂","主要侵犯二尖瓣或主动脉瓣","瓣膜表面常形成巨大的、松脆的含细菌的赘生物"],"a":0,"e":"急性感染性心内膜炎多发生于原本无病变的瓣膜，由致病力强的化脓菌引起，是脓毒血症的并发症，瓣膜上形成巨大、松脆含菌的赘生物，易致糜烂、穿孔和破裂，主要侵犯二尖瓣和主动脉瓣。在原有病变瓣膜上形成赘生物是亚急性感染性心内膜炎的特点"},{"q":"大肠癌的好发部位是","o":["升结肠","横结肠","降结肠","乙状结肠","直肠"],"a":4,"e":"大肠癌最好发于直肠，其次为乙状结肠，再依次为升结肠、降结肠与横结肠。升结肠、横结肠、降结肠、乙状结肠虽均可发生，但发生率均低于直肠"},{"q":"下列关于Barrett食管的叙述错误的是","o":["胃食管反流是Barrett食管形成的主要原因","Barrett食管发生食管腺癌的危险性与病灶大小有关","内镜下可表现为齿状线上方数厘米处食管黏膜呈橘红色","Barrett食管容易发生鳞状细胞癌","组织学上可见鳞状上皮被柱状上皮所取代，若出现杯状细胞便可确诊"],"a":3,"e":"Barrett食管由长期胃食管反流致食管下段鳞状上皮被柱状上皮取代，出现杯状细胞即可确诊，属癌前病变。其发生食管腺癌的危险性与病灶长度有关，内镜下齿状线上方黏膜呈橘红色，故容易发生鳞状细胞癌的说法错误"},{"q":"淋巴结转移性肿瘤首先出现于淋巴结的","o":["副皮质区","髓质","边缘窦","髓窦","淋巴滤泡"],"a":2,"e":"淋巴结转移性肿瘤首先出现于边缘窦（被膜下窦），随后沿淋巴窦向髓窦与髓质扩散。副皮质区为T细胞依赖区，淋巴滤泡为B细胞区，均非转移瘤的首发部位。边缘窦最先接触输入淋巴液，故为转移瘤的起始部位；髓窦与髓质属后续扩散区域"},{"q":"甲状腺恶性肿瘤中生长慢，恶性程度低，发病率最高的是","o":["滤泡癌","乳头状癌","髓样癌","未分化癌","肉瘤"],"a":1,"e":"甲状腺乳头状癌占甲状腺癌的60%～70%，生长缓慢、恶性程度最低、预后最好，以淋巴道转移为主。滤泡癌多见血行转移；髓样癌源于C细胞、分泌降钙素；未分化癌恶性度最高、预后极差；肉瘤罕见"},{"q":"对原发性胰腺癌的诊断最有价值的检查是","o":["血清酸性磷酸酶活性升高","血清甲胎蛋白（AFP）升高","血清癌胚抗原（CEA）升高","血清谷丙转氨酶活性升高","血清糖类抗原19-9（CA19-9）升高"],"a":4,"e":"胰腺癌多起源于导管上皮，血清CA19-9升高对诊断和随访最有价值，胰头癌还伴进行性梗阻性黄疸。AFP升高见于肝细胞癌和生殖细胞肿瘤；CEA升高多见于结直肠癌；酸性磷酸酶升高见于前列腺癌骨转移；转氨酶升高反映肝细胞损伤"},{"q":"双侧卵巢Krukenberg瘤最常来源于","o":["卵巢","肠","胆囊","胃","乳房"],"a":3,"e":"Krukenberg瘤为双侧卵巢黏液细胞癌（印戒细胞癌），多由胃癌经腹腔种植或淋巴道转移而来，常伴腹膜种植。肠癌、胆囊癌亦可转移卵巢但较少见；乳腺癌可累及卵巢却不呈典型Krukenberg瘤；卵巢原发黏液癌为另一疾病"},{"q":"鼻咽癌最常转移到","o":["左锁骨上淋巴结","右锁骨上淋巴结","纵隔淋巴结","中央区淋巴结","颈上深淋巴结"],"a":4,"e":"鼻咽癌经咽后淋巴结转移至颈上深淋巴结，常在胸锁乳突肌后缘上1/3与中1/3交界处皮下出现无痛性结节，半数以上患者以此为首发症状。左锁骨上淋巴结为胃癌等腹腔肿瘤的转移部位。纵隔淋巴结受累较晚。中央区淋巴结属甲状腺癌的转移部位"},{"q":"毛玻璃样肝细胞内嗜酸性颗粒的成分是","o":["包涵体","凋亡小体","细胞内玻璃样变性","内质网池","HBsAg"],"a":4,"e":"慢性乙肝时HBsAg在肝细胞滑面内质网池内大量聚集，光镜下胞质呈毛玻璃样，故嗜酸性颗粒成分为HBsAg。凋亡小体为Councilman小体，包涵体为病毒或蛋白聚集体，细胞内玻璃样变性是形态学概念而非具体成分，内质网池只是聚集部位"},{"q":"患者颈部淋巴结肿大，病理检查发现有泡状核细胞癌转移，其来源为","o":["肺部","鼻咽部","气管","喉","胸膜"],"a":1,"e":"泡状核细胞癌是鼻咽癌未分化型的一种，癌细胞核大、空泡状、核仁明显，呈合体状排列，常早期转移至颈部淋巴结，故淋巴结内查见该癌提示原发灶在鼻咽部。A项肺、C项气管、D项喉的癌多为鳞癌或腺癌，核不以空泡状为特征；E项胸膜原发恶性肿瘤罕见"},{"q":"最容易引起皮肤潮红、水样腹泻、心动过速、支气管哮喘等症状的肺癌类型是","o":["大细胞癌","黏液癌","类癌","未分化腺癌","低分化鳞状细胞癌"],"a":2,"e":"类癌属神经内分泌肿瘤，瘤细胞分泌5-羟色胺等活性物质，引起皮肤潮红、水样腹泻、心动过速和支气管痉挛，即类癌综合征。小细胞癌同属神经内分泌癌亦可致此综合征，但不在选项之列；大细胞癌、黏液癌、腺癌与鳞癌无内分泌功能"},{"q":"下列哪项是变质性炎症","o":["肾盂肾炎","菌痢","大叶性肺炎","阿米巴肝脓肿","阑尾炎"],"a":3,"e":"阿米巴肝脓肿以组织液化性坏死为主，炎症细胞浸润轻微，属变质性炎。肾盂肾炎与阑尾炎均为化脓性炎，以中性粒细胞渗出为特征。大叶性肺炎为纤维蛋白性炎，细菌性痢疾为纤维蛋白性炎伴假膜形成。故只有阿米巴肝脓肿以变质为基本病变"},{"q":"关于浸润性生长，正确的是","o":["是恶性肿瘤所独有的生长方式","是良性肿瘤所独有的生长方式","良、恶性肿瘤均可以呈浸润性生长","良、恶性肿瘤均不可以呈浸润性生长","多数良性肿瘤的主要生长方式"],"a":2,"e":"浸润性生长指瘤细胞侵入并破坏周围组织，边界不清，是多数恶性肿瘤的生长方式，但血管瘤、韧带样纤维瘤等良性肿瘤亦可呈浸润性生长。膨胀性生长是多数良性肿瘤的方式；恶性肿瘤并非独有浸润性，良性肿瘤也不以浸润性生长为主"},{"q":"引起出血性炎的主要原因是","o":["血管破裂","血管壁损伤较重","组织缺血缺氧","组织内胶体渗透压升高","血浆晶体渗透压升高"],"a":1,"e":"出血性炎因血管壁损伤较重、通透性显著增高，红细胞大量漏出，常见于流行性出血热、钩端螺旋体病及鼠疫。血管破裂属破裂性出血；组织缺血缺氧与胶体渗透压升高参与水肿形成，不是出血的主要原因"},{"q":"关于肺硅沉着病，错误的说法是","o":["是一种常见职业病","脱离硅尘作业环境后病变不再进一步发展","硅结节中央常形成空洞","基本病变为硅结节和肺组织弥漫性纤维化","是一种慢性疾病"],"a":1,"e":"硅肺的基本病变是硅结节和肺组织弥漫性纤维化，属慢性职业病，多在接触硅尘10～15年后发病；硅尘被巨噬细胞反复释放，即使脱离作业环境，肺部病变仍继续发展。硅结节中央为玻璃样变的胶原纤维，可钙化，空洞多由合并肺结核引起"},{"q":"引起支气管哮喘典型症状的主要机制是","o":["管壁大量炎性细胞浸润","支气管壁平滑肌痉挛","腔内黏液栓阻塞","黏膜水肿、基膜增厚","黏膜上皮杯状细胞增多、黏液腺增生"],"a":1,"e":"支气管哮喘发作时支气管平滑肌痉挛使气道狭窄、气流受限，产生发作性呼气性呼吸困难伴哮鸣音，为典型症状的直接机制。黏膜水肿、基膜增厚、杯状细胞与黏液腺增生及黏液栓形成属慢性重塑和继发改变，炎细胞浸润是基础炎症，均非症状产生的直接原因"},{"q":"不属于法洛四联症的是","o":["肺动脉狭窄","房间隔缺损","室间隔缺损","主动脉骑跨","右心室肥厚"],"a":1,"e":"法洛四联症由肺动脉狭窄、室间隔缺损、主动脉骑跨和右心室肥厚四种畸形构成，肺动脉狭窄使肺血减少，故出现发绀。房间隔缺损属非发绀型先天性心脏病，独立存在，不属四联症成分。室间隔缺损与主动脉骑跨共同决定右向左分流"},{"q":"亚急性甲状腺炎较特征性的病理学改变是甲状腺","o":["体积增大、不对称","切面见斑片状坏死","滤泡被破坏","肉芽肿性炎","纤维化"],"a":3,"e":"亚急性甲状腺炎（巨细胞性甲状腺炎）的特征为滤泡破坏、胶质溢出，形成由巨细胞与类上皮细胞构成的肉芽肿，后期纤维化。甲状腺增大不对称、切面斑片状灰白病灶仅为大体改变；滤泡破坏虽存在却缺乏特异性"},{"q":"慢性萎缩性胃炎A型患者病变主要在","o":["胃窦","胃体","胃体和胃底","胃小弯","胃大弯"],"a":2,"e":"A型慢性萎缩性胃炎属自身免疫性，由抗壁细胞抗体和内因子抗体致病，病变位于胃体和胃底，胃酸明显降低，血清维生素B12降低，常伴恶性贫血。B型由幽门螺杆菌感染引起，病变在胃窦部，为我国多见类型"},{"q":"虫媒病毒性脑炎病变部位最常见于","o":["颞叶","海马及小脑","大脑白质","脊髓","大脑皮质、基底节及视丘"],"a":4,"e":"虫媒病毒性脑炎即流行性乙型脑炎，病变广泛累及脑脊髓实质，以大脑皮质、基底核及视丘最重，小脑皮质、丘脑与脑桥次之，脊髓最轻且仅限颈段。海马锥体细胞虽对缺氧敏感，但非本病最重部位。大脑白质受累较轻，脊髓病变最轻"},{"q":"慢性支气管炎的描述，正确的是","o":["黏液脓性痰","咳铁锈色痰","黏液泡沫痰","呼吸困难","桶状胸"],"a":2,"e":"慢性支气管炎因黏液腺增生、分泌亢进，咳白色黏液泡沫痰，急性发作时痰可呈黏液脓性。铁锈色痰见于大叶性肺炎；呼吸困难与桶状胸为合并肺气肿的表现，不属慢性支气管炎本身的特征。黏液脓性痰提示急性加重期合并细菌感染，此时中性粒细胞渗出增多"},{"q":"关于反流性食管炎的表述错误的是","o":["可见基底细胞增生","反流性食管炎的改变与病因、持续时间和病程的长短有关","长期病变可形成Barrett食管","上皮层嗜酸性粒细胞浸润是反流性食管炎的早期病变","组织学上表现为鳞状上皮的重度异型增生"],"a":4,"e":"反流性食管炎的组织学改变为鳞状上皮基底细胞增生、固有膜乳头延长、上皮内嗜酸性粒细胞和中性粒细胞浸润，可伴糜烂、溃疡，长期可形成Barrett食管，一般不出现重度异型增生。A项基底细胞增生、B项与病因病程相关、C项可形成Barrett食管、D项嗜酸性粒细胞浸润为早期病变，均正确"},{"q":"下列与肝细胞癌发生无关的因素是","o":["HBV，HCV","亚硝胺类化合物","黄曲霉毒素","某些藻类毒素","华支睾吸虫"],"a":4,"e":"华支睾吸虫寄生于肝内胆管，与肝内胆管癌发生有关，与肝细胞癌无明确关系。A项HBV、HCV慢性感染是肝细胞癌最重要的病因；B项亚硝胺类、C项黄曲霉毒素均为肯定致癌物；D项某些藻类毒素经饮水摄入亦参与肝癌发生。寄生虫所致肿瘤的部位取决于其寄生部位，不能一概归因于肝癌"},{"q":"减压病的发生主要是由于","o":["氧气栓塞","氮气栓塞","二氧化碳栓塞","氢气栓塞","混合气体栓塞"],"a":1,"e":"减压病是气体栓塞的一种，从高气压环境迅速转入常压环境时，溶于血液和组织的气体游离成气泡，氧和二氧化碳可再溶解吸收，氮气溶解迟缓而形成大量微气泡，故又称氮气栓塞。空气栓塞由静脉破裂进气所致"},{"q":"下列哪个器官的梗死灶为节段性","o":["脑","肝","心脏","小肠","脾"],"a":3,"e":"小肠梗死呈节段性，因肠系膜动脉弓状分支、吻合支少，一支阻塞即致所供肠段整段坏死。脑、脾、肾梗死呈楔形（锥形），心肌梗死呈地图形，肝梗死少见且形态不规则。节段性分布是肠梗死的特征，与其管状供血方式一致"},{"q":"下述支持胃的恶性溃疡的是","o":["溃疡呈圆形，椭圆形","边缘整齐，不隆起","底部较平坦","火山口状，底部凹凸不平","皱襞向溃疡集中"],"a":3,"e":"溃疡型胃癌呈皿状或火山口状，底部凹凸不平、有坏死出血，边缘不整并隆起，与良性溃疡的圆形、边缘整齐、底部平坦、皱襞向溃疡集中恰相反。A项圆形椭圆、B项边缘整齐不隆起、C项底部较平坦、E项皱襞向溃疡集中，均为良性胃溃疡的大体特点。恶性溃疡直径多大于2cm、较浅，周围黏膜皱襞中断"},{"q":"阑尾系膜静脉血栓形成易见于下列哪种阑尾炎","o":["急性坏疽性阑尾炎","慢性阑尾炎急性发作","急性单纯性阑尾炎","慢性阑尾炎","急性蜂窝织炎性阑尾炎"],"a":0,"e":"急性坏疽性阑尾炎时阑尾腔阻塞积脓、腔内压升高，阑尾系膜静脉受炎症波及发生血栓性静脉炎，致阑尾壁血液循环障碍而坏死，故该型最易出现系膜静脉血栓形成。单纯性与蜂窝织炎性阑尾炎以黏膜及阑尾壁化脓为主，慢性阑尾炎以纤维组织增生为主"},{"q":"慢性萎缩性胃炎的特征性病变是","o":["黏膜固有层淋巴细胞和浆细胞浸润","黏膜层有水肿、点状出血和上皮坏死","腺上皮萎缩伴淋巴细胞和浆细胞浸润","腺体萎缩伴肠上皮化生","腺上皮增生伴肠上皮化生"],"a":3,"e":"慢性萎缩性胃炎的特征为腺体萎缩减少、黏膜变薄，伴肠上皮化生及淋巴细胞、浆细胞浸润。仅炎细胞浸润见于非萎缩性胃炎；水肿、出血与上皮坏死为急性胃炎表现；腺上皮增生不伴萎缩不能诊断萎缩性胃炎"},{"q":"关于肺硅沉着病的叙述错误的是","o":["长期吸入游离的二氧化硅引起","及时脱离硅尘环境可防止病情发展","基本病变是硅结节形成和肺广泛纤维化","易激发肺的细菌和病毒感染","晚期常并发肺源性心脏病"],"a":1,"e":"硅沉着病由长期吸入游离二氧化硅引起，硅结节形成与肺广泛纤维化是基本病变，且病变具进行性，即使脱离硅尘环境仍可继续发展，故该叙述错误。D项易继发结核及细菌感染、E项晚期并发肺源性心脏病均为其真实特点"},{"q":"慢性胰腺炎患者，最不可能出现的情况是","o":["胰腺假囊肿","糖尿病","肥胖","胰腺癌","脂肪泻"],"a":2,"e":"慢性胰腺炎致胰腺外分泌与内分泌功能受损，出现脂肪泻与糖尿病，胰管阻塞可形成假性囊肿，长期炎症亦是胰腺癌的危险因素。肥胖是急性胰腺炎的危险因素，不是慢性胰腺炎的后果"},{"q":"慢性胃溃疡最好发的部位是","o":["胃大弯近幽门部","胃大弯近贲门部","胃小弯近幽门部","胃小弯近贲门部","胃体小弯侧"],"a":2,"e":"慢性胃溃疡最好发于胃小弯近幽门部（胃窦部），该处黏膜血供相对较差，且受胃酸、胃蛋白酶及幽门螺杆菌作用明显。胃大弯、贲门部及胃体的溃疡均较胃小弯近幽门部少见"},{"q":"下述哪种因素与血栓形成无关","o":["血管内膜损伤","血小板数量增多","血流缓慢","癌细胞崩解产物","纤溶酶增加"],"a":4,"e":"血栓形成三要素是心血管内膜损伤、血流状态改变和血液凝固性增高；纤溶酶活性增强促进血栓溶解，属抗血栓因素。癌细胞崩解产物可释放组织因子样物质，使血液凝固性增高。血小板数量增多、血流缓慢均直接促进血栓形成，血管内膜损伤则是最重要、最常见的原因"},{"q":"下列哪项不是引起肾盂肾炎的主要诱因","o":["感染","机体抵抗力下降","尿路阻塞","抗原抗体反应","膀胱输尿管反流"],"a":3,"e":"肾盂肾炎由细菌感染引起，以大肠埃希菌最常见；尿路阻塞使尿液滞留、膀胱输尿管反流使带菌尿液上行，均使感染易于发生，机体抵抗力下降亦为诱因。抗原抗体反应是肾小球肾炎的发病机制，属免疫复合物介导的损伤，与肾盂肾炎的化脓性炎症性质不同"},{"q":"血源性感染性肾盂肾炎的最常见病原菌是","o":["大肠杆菌","链球菌","金黄色葡萄球菌","真菌","肠球菌"],"a":2,"e":"血源性感染性肾盂肾炎少见，病原菌经血流抵达肾脏，多为金黄色葡萄球菌，常伴败血症或感染性心内膜炎，病变为多发性小脓肿。上行性感染最常见，病原菌以大肠埃希菌为主，故大肠杆菌是尿路感染总体的首位病原，而非血源性者；链球菌、肠球菌、真菌多经尿路上行"},{"q":"细菌性痢疾病变的最好发部位是","o":["空肠","回肠下段","回盲部","横结肠","乙状结肠和直肠"],"a":4,"e":"细菌性痢疾由志贺菌引起，病变主要累及大肠下段，以乙状结肠和直肠最重，表现为假膜性炎和溃疡。B项回肠下段是伤寒的好发部位；C项回盲部常见于阿米巴痢疾和肠结核；A项空肠、D项横结肠均非菌痢病变最集中处"},{"q":"流行性乙型脑炎时，病变的主要部位是","o":["大脑皮质","大脑灰质","小脑","大脑皮质及基底节、丘脑","软脑膜"],"a":3,"e":"乙脑病变主要累及大脑皮质、基底节、丘脑及中脑等灰质区，属病毒性脑炎。软脑膜病变主要为流脑特点；小脑非主要受累区；仅大脑皮质表述不全，故以大脑皮质及基底节、丘脑最准确"},{"q":"动脉性充血的主要病理变化是","o":["器官体积肿大","器官重量增加","局部呈红色","小动脉和毛细血管扩张，充满红细胞","局部温度升高"],"a":3,"e":"动脉性充血是主动过程，基本变化为局部细动脉和毛细血管扩张、充满红细胞，血流加快。A项器官体积轻度增大、B项重量增加、C项局部呈鲜红色、E项局部温度升高，均为血管扩张充血后的大体表现，属继发结果而非镜下本质。充血消退后局部血量即恢复正常"},{"q":"下列哪项病变不是假小叶的特点","o":["中央静脉缺失","肝细胞广泛凋亡，大量凋亡小体形成","可有2个以上中央静脉","肝细胞排列紊乱，有不同程度的坏死或脂肪变性","出现门管区"],"a":1,"e":"假小叶为肝硬化的特征性结构：中央静脉缺如或偏位、可有2个以上中央静脉、肝细胞索排列紊乱伴变性坏死、可见汇管区。肝细胞广泛凋亡并大量凋亡小体形成是病毒性肝炎尤其重型肝炎的改变，不属假小叶特点"},{"q":"头皮血肿被肉芽组织所取代，这种现象称为","o":["肉芽组织形成","肉芽肿形成","机化","纤维化","血栓机化"],"a":2,"e":"坏死组织、血栓、血肿或异物被新生肉芽组织长入并逐渐取代的过程称机化，头皮血肿被肉芽组织取代后最终形成瘢痕。肉芽肿是巨噬细胞增生形成的结节性病灶；纤维化为胶原沉积增多；血栓机化仅指血栓这一特定对象的机化，不能概括本例"},{"q":"下列哪项不是化生","o":["成纤维细胞变为纤维细胞","成纤维细胞变为成骨细胞","膀胱黏膜出现了鳞状上皮","柱状上皮转变为移行上皮","胃黏膜上皮转变为肠上皮"],"a":0,"e":"化生是一种已分化成熟细胞被另一种分化成熟细胞取代的适应性改变，如膀胱黏膜出现鳞状上皮、胃黏膜上皮肠化、柱状上皮转为移行上皮。成纤维细胞成熟为纤维细胞是同一细胞的分化成熟过程，细胞类型未改变，仅功能与形态趋于静止，不属化生"},{"q":"关于慢性硬化性肾小球肾炎的叙述，下列正确的是","o":["无肾小球肾炎的病史","可形成原发性颗粒性固缩肾","蛋白尿、管型尿进行性加重","常有贫血、持续性高血压和肾功能不全","最常见的死亡原因是冠心病"],"a":3,"e":"慢性硬化性肾小球肾炎是各类肾小球疾病发展的终末阶段，大量肾小球玻璃样变、硬化，肾小管萎缩、间质纤维化，故出现贫血、持续性高血压和慢性肾功能不全。其颗粒性固缩肾属继发性，原发性颗粒性固缩肾见于良性高血压。多数患者有肾炎病史，蛋白尿、管型尿在晚期反而减轻，死因多为尿毒症"},{"q":"大叶性肺炎患者灰色肝样变期与红色肝样变期的临床表现不同在于","o":["胸痛消失","咳铁锈色痰","缺氧状况有所好转","重新出现啰音","开始出现肺实变体征"],"a":2,"e":"红色肝样变期肺泡毛细血管扩张充血、肺泡腔内充满纤维蛋白和大量红细胞，换气面积显著减少，出现发绀等缺氧表现。灰色肝样变期充血消退、毛细血管受压血流量减少，缺氧反而减轻，铁锈色痰转为黏液脓痰，而肺实变体征两期均存在"},{"q":"淤血不会引起","o":["水肿","脂肪变","实质细胞增生","局部缺氧","胶原纤维增生"],"a":2,"e":"淤血使局部缺氧、代谢产物蓄积，毛细血管内压升高、通透性增大，引起淤血性水肿和漏出性出血；长期淤血使实质细胞萎缩、脂肪变，间质纤维组织增生形成淤血性硬化。实质细胞增生见于慢性炎症的修复反应，淤血时实质细胞以萎缩、变性为主"},{"q":"子宫内膜非典型增生与高分化子宫内膜癌鉴别的基本要点是","o":["细胞乳头状增生","宫内膜鳞状上皮化生","间质浸润","间质纤维组织增生","宫内膜细胞嗜酸性变"],"a":2,"e":"高分化子宫内膜癌与非典型增生的根本鉴别要点是是否存在间质浸润，癌组织突破基底膜侵犯间质或肌层。细胞乳头状增生、鳞状上皮化生、间质纤维组织增生及细胞嗜酸性变均非二者的关键鉴别点"},{"q":"下列关于肾细胞癌的主要特点正确的是","o":["无血尿","不发生出血","肿瘤间质丰富，血管少","肿瘤组织内可见软骨、肌肉","侵犯肾静脉，有血管内生长倾向"],"a":4,"e":"肾细胞癌源于近曲小管上皮，呈浸润性生长，易侵入肾静脉形成癌栓并延伸至下腔静脉，有沿血管内生长的倾向。因间质血管丰富，血尿与出血常见；间质少而薄壁血管多；软骨、肌肉成分见于肾母细胞瘤或畸胎瘤"},{"q":"门脉性肝硬化形成过程中的基本病理变化为","o":["肝细胞变性、坏死，肝纤维化","肝内胆管上皮增生，肝纤维化","肝细胞变性、坏死，肝细胞再生，肝弥漫性纤维化","肝细胞再生，肝纤维化","肝细胞变性、坏死，Kupffer细胞增生"],"a":2,"e":"门脉性肝硬化的基本病变是肝细胞变性坏死、残留肝细胞再生形成假小叶，并伴弥漫性纤维组织增生，三种改变同时存在、反复进行。B项肝内胆管上皮增生并非本病基本变化；D项仅列再生与纤维化，遗漏肝细胞坏死这一始动环节；E项Kupffer细胞增生属伴随现象，不构成基本病变"},{"q":"如图所示，下列哪种细胞参与形成卫星现象","o":["小胶质细胞","淋巴细胞","星形细胞","中性粒细胞","少突胶质细胞"],"a":4,"e":"本题原题配有图片，图片未随文档保留，以下解析依文字线索推断：题干涉及图片/信息缺失，无法作答。卫星现象指灰质中1~2个少突胶质细胞围绕于变性神经元胞体周围，见于神经元损伤。小胶质细胞构成噬神经细胞现象；星形细胞形成胶质瘢痕；淋巴细胞形成血管套；中性粒细胞见于化脓性炎\n\n官方题库中缺失图片"},{"q":"下列关于风湿病的病因和发病机制的叙述错误的是","o":["本病多始发于儿童","患者血清抗链球菌抗体滴度明显升高","多见于热带地区","发病前多先有急性扁桃体炎和咽峡炎","抗生素的广泛应用，降低了风湿病的发病率"],"a":2,"e":"风湿病多见于寒冷潮湿地区及冬春季，我国东北、华北发病率较高，与A组乙型溶血性链球菌感染有关。发病前常有急性扁桃体炎、咽峡炎，血清抗链球菌溶血素O抗体升高；抗生素广泛应用使发病率明显下降"},{"q":"有关血栓形成规律的说法中，不正确的是","o":["静脉血栓多于动脉血栓","下肢血栓多于上肢血栓","心腔内多形成附壁血栓","静脉血栓多为红色血栓","透明血栓多发生于微循环内"],"a":3,"e":"静脉血栓多于动脉、下肢多于上肢，因静脉血流缓慢、瓣膜处有涡流且管壁薄易受压；心腔内多形成附壁血栓，透明血栓见于微循环。静脉内延续性血栓由头部白色血栓、体部混合血栓和尾部红色血栓构成，故静脉血栓以混合血栓为主，并非红色血栓"},{"q":"下述炎症改变中，最有防御意义的是","o":["渗出液的产生","氧自由基释放","白细胞渗出","血液停滞","炎症介质形成"],"a":2,"e":"白细胞渗出并聚集于炎症灶、吞噬杀灭病原体，是炎症最重要的防御环节与特征性改变。渗出液仅能稀释毒素、带来抗体与补体，防御作用有限。氧自由基释放与炎症介质形成主要参与损伤和血管反应。血液停滞属血流动力学改变的淤血期表现，不利于防御"},{"q":"下肢静脉内血栓形成后，对机体的最为严重的后果是","o":["血栓脱落后引起冠状动脉栓塞","阻塞血管，引起下肢急性梗死","血栓被机化后永久阻塞下肢血管","血栓脱落后引起肺动脉栓塞","形成静脉石后造成下肢静脉的永久性阻塞"],"a":3,"e":"下肢深静脉血栓脱落后随静脉血流回右心，进入肺动脉造成肺动脉栓塞，大栓子嵌顿肺动脉主干可致猝死，是最严重后果。左心系统栓子才引起体循环动脉栓塞如冠状动脉栓塞；静脉血栓一般不引起下肢动脉性梗死，机化或形成静脉石仅造成局部静脉阻塞"},{"q":"血栓形成是指","o":["在活体的心脏和血管内血液成分形成固体质块的过程","血液发生凝固形成固体质块的过程","在活体组织内血液发生凝固形成固体质块的过程","血液在静止状态中发生的异常凝固","活体组织内红细胞发生凝固形成固体质块的过程"],"a":0,"e":"血栓形成指在活体的心脏和血管内，血液发生凝固或血液中某些有形成分凝集形成固体质块的过程，所形成质块为血栓。血液在血管外凝固称血凝块；在活体组织内凝固不属血栓形成；静止状态下的异常凝固表述不准确"},{"q":"血吸虫病时，引起机体损害最为严重的是","o":["尾蚴","童虫","死亡童虫","虫卵","成虫"],"a":3,"e":"血吸虫的尾蚴、童虫、成虫和虫卵均可造成损害，以虫卵引起的病变最严重：虫卵沉积于肝和肠壁形成虫卵结节，导致纤维化、门静脉高压和肠壁溃疡。尾蚴引起尾蚴性皮炎，童虫引起血管炎和肺炎，成虫损害较轻"},{"q":"脱落细胞涂片最常用的固定液是","o":["95%的乙醇","乙醚-乙醇混合液","Carnoy氏液","甲醇","甲醛"],"a":0,"e":"脱落细胞涂片常用95%乙醇固定，能迅速凝固蛋白、保持细胞形态，是最常用固定液。乙醚—乙醇混合液多用于组织切片；Carnoy液偏重核酸固定；甲醇、甲醛各有专门用途，均非脱落细胞涂片首选"},{"q":"上消化道大量出血最常见的原因是","o":["慢性浅表性胃炎","慢性萎缩性胃炎","革囊胃","溃疡病","巨大肥厚性胃炎"],"a":3,"e":"上消化道大出血最常见的原因是消化性溃疡，溃疡底部血管被胃酸和胃蛋白酶腐蚀破裂，十二指肠后壁溃疡常侵蚀胃十二指肠动脉。A、B项慢性胃炎仅少量渗血；C项革囊胃为弥漫浸润型胃癌，出血非主要表现；E项巨大肥厚性胃炎以蛋白丢失为主。肝硬化食管静脉曲张破裂居第二位"},{"q":"下列肺部炎症中属纤维素性炎的是","o":["肺结核","病毒性肺炎","大叶性肺炎","小叶性肺炎","支原体肺炎"],"a":2,"e":"大叶性肺炎由肺炎链球菌引起，肺泡内弥漫性纤维蛋白渗出，属纤维蛋白性炎。小叶性肺炎以细支气管为中心的化脓性炎为特点。病毒性肺炎与支原体肺炎均为间质性肺炎，渗出以浆液和单核细胞为主。肺结核的基本病变为渗出、增生与干酪样坏死，形成结核结节"},{"q":"富于淋巴细胞的经典型霍奇金淋巴瘤常见的肿瘤细胞是","o":["双核RS细胞","LP细胞","陷窝细胞","干尸细胞","多形性细胞"],"a":0,"e":"富于淋巴细胞的经典型霍奇金淋巴瘤背景为大量淋巴细胞，肿瘤性R-S细胞少，以双核R-S细胞为主。LP细胞（爆米花样细胞）见于结节性淋巴细胞为主型；陷窝细胞见于结节硬化型；干尸细胞为经典型R-S细胞的变异型"},{"q":"大肠癌的病因与下列哪些因素无关","o":["家族高发的遗传因素","p53基因点突变","富于刺激性纤维质多的食物","MSH2基因点突变","高营养低纤维质的食物"],"a":2,"e":"大肠癌发病与高营养、低纤维质饮食关系密切，膳食纤维可稀释并吸附致癌物、缩短其在肠道停留时间，故富于纤维的食物不属危险因素。p53点突变使抑癌功能丧失，MSH2属错配修复基因，突变后微卫星不稳定，二者均参与大肠癌发生。家族高发提示遗传易感，亦为公认危险因素"},{"q":"风湿小体发生于","o":["心瓣膜","心肌细胞","心肌间质","关节滑膜","心外膜"],"a":2,"e":"风湿小体位于心肌间质小血管旁，也见于心内膜下和皮下结缔组织，由风湿细胞、淋巴细胞和浆细胞构成。心瓣膜的风湿病变是闭锁缘的疣状赘生物，不含风湿小体；关节滑膜和心外膜以渗出性病变为主"},{"q":"坏死和坏疽的主要区别是","o":["发生部位不同","发生原因不同","有无腐败菌感染","是否存在淤血","动脉阻塞程度不同"],"a":2,"e":"坏疽是坏死组织继发腐败菌感染而呈黑褐色，故坏死与坏疽的本质区别在于有无腐败菌感染。发生部位（肢体末端、与外界相通的内脏）、原因（动脉阻塞伴静脉回流受阻）、淤血程度只是促成条件，不构成根本区别"},{"q":"假小叶的特征性病变不包括","o":["纤维组织增生，分割包绕肝小叶形成肝细胞团","肝细胞紊乱、脂肪变性","肝细胞团内出现汇管区","肝细胞团内缺少中央静脉","肝细胞团内中央静脉数量偏位或有2个以上"],"a":1,"e":"假小叶内中央静脉缺如、偏位或两个以上，汇管区可被纤维组织包入，肝细胞索排列紊乱。肝细胞脂肪变性属可逆性损伤，见于慢性肝淤血与酒精性肝病，不是假小叶的固有结构特征，故不列入其特征性病变"},{"q":"下列哪项对大肠癌诊断有意义","o":["血清酸性磷酸酶活性增加","癌胚抗原（CEA）高度阳性","甲胎蛋白（AFP）阳性","转肽酶活性增高","谷丙转氨酶活性增高"],"a":1,"e":"癌胚抗原（CEA）在结直肠腺癌中常显著升高，可用于大肠癌的辅助诊断、疗效观察和复发监测。A项酸性磷酸酶升高多见于前列腺癌；C项甲胎蛋白（AFP）是肝细胞癌标志；D项转肽酶（GGT）、E项谷丙转氨酶（ALT）主要反映肝胆疾病，均非大肠癌特异指标"},{"q":"属于癌前病变的是","o":["大肠腺瘤","皮下脂肪瘤","皮肤纤维瘤","子宫平滑肌瘤","乳腺纤维腺瘤"],"a":0,"e":"大肠腺瘤尤其绒毛状腺瘤可经腺瘤—癌序列演进为腺癌，是明确的癌前病变。皮下脂肪瘤、皮肤纤维瘤、子宫平滑肌瘤、乳腺纤维腺瘤均为分化良好的良性肿瘤，恶变极罕见，不属癌前病变"},{"q":"最常引起卵巢Krukenberg瘤的为","o":["宫颈癌","乳腺癌","胃癌","肺癌","肝癌"],"a":2,"e":"Krukenberg瘤多由胃肠道黏液癌，尤其是胃印戒细胞癌经种植性转移至双侧卵巢形成，也可经淋巴道或血行转移。乳腺癌可转移至卵巢，但形成的是乳腺癌的卵巢转移，不称此名。宫颈癌以直接蔓延与淋巴道转移为主，肺癌、肝癌卵巢转移少见且不具此命名"},{"q":"形成肉芽肿的心肌炎是","o":["白喉心肌炎","埃可病毒性心肌炎","柯萨奇病毒性心肌炎","特发性巨细胞性心肌炎","葡萄球菌性心肌炎"],"a":3,"e":"特发性巨细胞性心肌炎病灶内可见心肌灶状坏死与肉芽肿，中央为红染无结构坏死物，周围有淋巴细胞、单核细胞、浆细胞、嗜酸性粒细胞及多核巨细胞浸润，故形成肉芽肿。柯萨奇、埃可病毒性心肌炎以间质单核细胞浸润和心肌变性为主；白喉心肌炎为毒素所致变性坏死；葡萄球菌性心肌炎形成小脓肿"},{"q":"乙型肝炎病毒的主要传播途径是","o":["经飞沫传播","昆虫媒介传播","经口传播","皮肤黏膜接触传播","经血行传播"],"a":4,"e":"HBV主要经输血及血制品、血液污染的医疗器械、静脉吸毒等血行途径传播，密切接触与母婴垂直传播亦重要。粪-口途径是甲型与戊型肝炎的传播方式，故经口传播不成立；飞沫传播见于呼吸道病毒，昆虫媒介与HBV无关"},{"q":"鼻咽癌最早侵犯的淋巴结是","o":["颈浅淋巴结","颈上深淋巴结","锁骨上淋巴结","咽后壁淋巴结","咽外侧壁淋巴结"],"a":3,"e":"鼻咽癌的癌细胞先经咽后壁淋巴结转移至颈上深淋巴结，故最早受累的是咽后壁淋巴结。颈上深淋巴结肿大是患者就诊时触及的无痛性结节，位于胸锁乳突肌后缘上1/3处；锁骨上淋巴结属晚期转移；颈浅淋巴结收纳耳后及枕部引流"},{"q":"除外下列哪项均为乙型脑炎的病变","o":["“血管套”形成","小脓肿形成","神经细胞变性坏死","软化灶形成","胶质细胞增生"],"a":1,"e":"乙型脑炎病变为神经细胞变性坏死、卫星现象与噬神经细胞现象、筛状软化灶、胶质结节及淋巴细胞血管套。小脓肿形成为脑脓肿或化脓性脑炎的表现，故不属乙脑病变。乙脑病变以大脑皮质、基底核最重，脊髓受累较轻，与流脑的脑膜化脓性病变截然不同"},{"q":"易发生癌变的食管炎是","o":["急性食管炎","慢性食管炎","Barrett食管","反流性食管炎","感染性食管炎"],"a":2,"e":"Barrett食管指食管远端鳞状上皮被柱状上皮取代，多由胃食管反流引起，可发生异型增生并进展为食管腺癌，是大部分食管腺癌的癌前病变。急性、慢性食管炎及感染性食管炎以炎症为主，癌变风险低；反流性食管炎是Barrett食管的成因，本身不等同于癌前病变"},{"q":"以下为乙脑基本病理变化，但除外","o":["脑脊髓膜化脓性炎","脑实质细胞变性坏死","脑实质内血管袖套样改变","脑内筛状软化灶形成","脑质小结形成"],"a":0,"e":"乙型脑炎的基本病变在脑实质，包括神经细胞变性坏死、血管周围淋巴细胞袖套状浸润、筛状软化灶形成和胶质结节。脑脊髓膜化脓性炎是流行性脑脊髓膜炎的特点，乙脑仅见脑膜轻度充血和单核细胞浸润"},{"q":"下列哪种疾病不会引起肺气肿","o":["慢性支气管炎","支气管扩张症","支气管哮喘","大叶性肺炎","小叶性肺炎"],"a":3,"e":"大叶性肺炎为急性纤维素性炎，炎症消退后渗出物可完全吸收，肺泡壁结构不被破坏，故不引起肺气肿。慢性支气管炎、支气管扩张症、支气管哮喘等因慢性气道阻塞可致肺气肿；小叶性肺炎化脓破坏肺组织亦可为诱因"},{"q":"下列哪项属于门脉性肝硬化的病变特点","o":["假小叶大小不等","纤维间隔较宽","炎细胞浸润明显","假小叶大小相仿","碎片状坏死"],"a":3,"e":"门脉性肝硬化属小结节型，假小叶大小相仿、直径多小于3mm，纤维间隔较细且宽窄均匀，炎症细胞浸润较轻。假小叶大小不等、纤维间隔宽大者见于坏死后性肝硬化即大结节型。碎片状坏死是慢性肝炎的活动性病变，属肝硬化形成的前驱改变，非其结构特点"},{"q":"下列器官很少发生梗死的是","o":["心","脾","肾","肝","肠"],"a":3,"e":"肝有肝动脉和门静脉双重供血，两者间存在吻合，故肝梗死很少见，仅在肝动脉血栓栓塞时才偶有发生。A项心、B项脾、C项肾均为终末动脉供血，缺少有效侧支，梗死常见；E项肠系膜血管虽吻合较多，但肠管对缺血敏感，梗死仍较常见"},{"q":"病毒性肺炎的可靠诊断依据是","o":["间质性肺炎","淋巴细胞、单核细胞为主的炎细胞浸润","上皮细胞内病毒包涵体","肺泡上皮细胞增生","肺泡腔变大"],"a":2,"e":"病毒性肺炎时，增生的细支气管和肺泡上皮细胞及多核巨细胞内可检出病毒包涵体，其位置与染色因病毒种类而异，检出包涵体是病理组织学诊断的可靠依据。间质性肺炎、淋巴细胞与单核细胞浸润、肺泡上皮增生均为非特异性改变，多种病毒及其他病原体感染都可出现"},{"q":"结核病的基本病变不包括","o":["渗出性病变","化脓性病变","变质性病变","增生性病变","肉芽肿性病变"],"a":1,"e":"结核病基本病变为渗出、增生与变质三类，增生性病变即结核结节与肉芽肿，变质性病变为干酪样坏死，三者可互相转化。化脓性病变以中性粒细胞渗出为主，见于化脓性细菌感染，结核病灶中极少中性粒细胞"},{"q":"炎症时白细胞游出后定向移动的主要原因是","o":["炎症部位的化学趋向性","白细胞的阿米巴样运动","血管内压升高","轴流消失白细胞边集","血管壁的通透性增高"],"a":0,"e":"白细胞游出血管后向炎症灶定向移动，主要因炎症部位释放趋化因子产生的化学趋向性。阿米巴样运动是白细胞运动方式而非定向原因；血管内压升高、轴流消失边集及通透性增高均属渗出早期环节，不是定向移动的主因"},{"q":"下列关于肝癌肉眼类型及组织类型均为多见的叙述中，哪项是正确的","o":["多结节型与胆管上皮癌多见","巨块型与肝细胞癌多见","多结节型与肝细胞癌多见","巨块型与混合性肝癌多见","弥漫型与混合性肝癌多见"],"a":2,"e":"原发性肝癌肉眼分巨块型、多结节型和弥漫型，其中多结节型最多见；组织学上肝细胞癌占75%～85%，最为多见，故多结节型与肝细胞癌的组合正确。巨块型多见于无明显肝硬化者，弥漫型最少见；胆管细胞癌与混合型肝癌均少见"},{"q":"不能促进血小板聚集的是","o":["胶原纤维","凝血酶","血栓素A","ADP","前列环素"],"a":4,"e":"前列环素（PGI₂）由血管内皮细胞产生，可升高血小板内cAMP，抑制血小板聚集并扩张血管。胶原纤维、凝血酶、血栓素A₂及ADP均为促进血小板聚集的因子，故仅前列环素不能促进聚集"},{"q":"噬神经细胞现象是指","o":["少突胶质细胞环绕神经元","神经细胞吞噬崩解的脂质","胶质细胞增生取代死亡的神经元","小胶质细胞、巨噬细胞包围吞噬死亡的神经元","中性粒细胞吞噬死亡的神经元"],"a":3,"e":"噬神经细胞现象指坏死的神经元被增生的小胶质细胞或血源性巨噬细胞吞噬，是中枢神经系统对神经元坏死的反应。少突胶质细胞环绕神经元为卫星现象。胶质细胞增生取代坏死神经元形成胶质瘢痕，不称噬神经细胞现象。中性粒细胞不参与该过程"},{"q":"大量空气迅速进入血液循环引起死亡的原因是","o":["心肌梗死","急性心力衰竭和呼吸衰竭","脑栓塞","肺梗死","心脏破裂"],"a":1,"e":"大量空气迅速进入静脉后随血流进入右心和肺动脉，形成气泡阻塞肺循环，引起急性呼吸衰竭和急性右心衰竭而致死。肺梗死需在肺淤血基础上发生；脑栓塞多来自左心和主动脉系统栓子；心脏破裂与空气栓塞无关"},{"q":"结节性淋巴细胞为主型霍奇金淋巴瘤，肿瘤细胞免疫表型","o":["CD20+","CD3+","CD56+","CD68+","CD21+"],"a":0,"e":"结节性淋巴细胞为主型霍奇金淋巴瘤的肿瘤细胞（爆米花细胞）为B细胞来源，表达CD20、CD45与BCL6，不表达CD15、CD30。CD3为T细胞标志；CD56为NK细胞标志；CD68为组织细胞标志；CD21为滤泡树突细胞标志"},{"q":"肿瘤的演进是指","o":["细胞的恶性转化","恶性肿瘤的浸润能力","恶性肿瘤的转移现象","恶性肿瘤的生长速度","恶性肿瘤在生长过程中变得越来越富有侵袭性的现象"],"a":4,"e":"肿瘤演进指恶性肿瘤生长过程中侵袭性不断增强，表现为生长速度加快、浸润周围组织和发生远处转移，其基础是瘤细胞不断获得异质性。恶性转化是演进的起点；浸润与转移是演进的表现；生长速度只是表现之一，不能等同于演进"},{"q":"关于肥厚型心肌病特征的叙述，下列错误的是","o":["心脏肥大","心腔扩张","左心室流出道受阻","室间隔不匀称肥厚","舒张期充盈异常"],"a":1,"e":"肥厚型心肌病以室间隔不匀称肥厚、左心室流出道受阻、舒张期充盈异常为特征，心脏重量增加而心腔缩小，镜下心肌细胞排列紊乱。心腔扩张是扩张型心肌病的特点，与肥厚型相反"},{"q":"原位癌与浸润癌的主要区别是","o":["肿瘤大小","基膜是否完整","边界是否清楚","有无血管浸润","有无淋巴管浸润"],"a":1,"e":"原位癌癌细胞累及上皮全层但未突破基底膜，浸润癌已穿透基底膜侵入下方间质，故二者区别在于基膜是否完整。肿瘤大小、边界是否清楚均不能判定；有无血管、淋巴管浸润属浸润癌的进一步生物学行为，不是二者的分界标准"},{"q":"肺癌一般不转移至","o":["脑","骨","肾","肝","心"],"a":4,"e":"肺癌血行转移常见于脑、骨、肝、肾上腺及肾，心脏转移罕见，因心肌持续收缩挤压瘤栓且冠状动脉供血丰富。淋巴结与胸膜亦常受累，属淋巴道及种植性扩散，心包转移多于心肌"},{"q":"潜水员从深水中过快地升向水面，容易发生","o":["肺水肿","氮气栓塞","二氧化碳栓塞","肺不张","氧气栓塞"],"a":1,"e":"潜水员快速上浮时环境压力骤降，原溶于血液和组织液的氮气迅速游离形成气泡阻塞血管，故减压病又称氮气栓塞。氧与二氧化碳可重新溶解吸收，不构成主要栓子。肺水肿与肺不张为继发改变，不属栓塞类型"},{"q":"风湿性心内膜炎心内膜之赘生物的实质是","o":["增生的肉芽组织","风湿性肉芽肿","机化的瘢痕","混合血栓","白色血栓"],"a":4,"e":"风湿性心内膜炎瓣膜闭锁缘形成灰白色赘生物，由血小板和纤维素构成，本质为白色血栓，故不易脱落。B项风湿性肉芽肿（Aschoff小体）发生于心肌间质，并非赘生物成分；D项混合血栓多见于动脉瘤或心腔内，呈层状结构，与其不同"},{"q":"下列哪项符合支原体肺炎的病变特点","o":["包涵体形成","可引起干酪性肺炎","病灶呈节段性分布","肺的纤维素性炎症","以细支气管为中心的化脓性炎症"],"a":2,"e":"支原体肺炎病变主要位于肺间质，肺泡内渗出少、实变不明显，病灶常沿支气管树呈节段性分布，以下叶多见。A项包涵体见于病毒性肺炎，是病毒感染的诊断依据；B项干酪性肺炎为继发性肺结核；D项纤维素性炎见于大叶性肺炎；E项以细支气管为中心的化脓性炎是小叶性肺炎的本质"},{"q":"不是胰腺癌的临床表现是","o":["腹水","黄疸进行性加重","疼痛","CA19-9升高","血清碱性磷酸酶活性升高"],"a":4,"e":"胰腺癌的临床表现有腹痛、黄疸进行性加重、腹水、消瘦及CA19-9升高，胰头癌压迫胆总管致梗阻性黄疸，腹痛多位于上腹并放射至腰背。血清碱性磷酸酶活性升高主要见于骨软化症、佝偻病及骨肿瘤等骨病，不是胰腺癌的特征性表现"},{"q":"关于大肠多发性息肉病，下列哪项是错误的","o":["是一种显性遗传病","肠黏膜上有多个息肉","息肉为腺瘤性","息肉带有错构瘤性质","息肉易发生癌变"],"a":3,"e":"家族性腺瘤性息肉病为常染色体显性遗传，大肠黏膜布满腺瘤性息肉，40岁前几乎均癌变，属典型癌前疾病，与APC基因突变有关。错构瘤性息肉见于幼年性息肉及Peutz-Jeghers综合征，与腺瘤性息肉病性质不同"},{"q":"主动脉粥样硬化大体检查如图，镜下观如图所示，该病变最佳名称为","o":["脂纹","纤维斑块","粥样斑块","粥瘤性溃疡","动脉瘤形成"],"a":3,"e":"本题原题配有图片，图片未随文档保留，以下解析依文字线索推断：题干涉及图片/信息缺失，无法作答。主动脉粥样硬化由脂纹进展为纤维斑块、粥样斑块，斑块表面溃破、坏死物排出即形成粥瘤性溃疡，可继发血栓、钙化和动脉瘤。纤维斑块表面为完整纤维帽，脂纹为内膜下泡沫细胞聚集的平坦条纹，均无溃破；不见镜下溃破形态则无法与粥样斑块区分\n\n官方题库中缺失图片"},{"q":"流行性乙型脑炎的传播途径","o":["呼吸道","消化道","神经","虫媒传染","皮肤接触传染"],"a":3,"e":"流行性乙型脑炎经虫媒传播，媒介为库蚊、伊蚊和按蚊，我国主要为三节吻库蚊，带毒蚊叮咬吸血时病毒侵入人体，先在内皮细胞及单核巨噬细胞系统繁殖再形成病毒血症。A项呼吸道、B项消化道、C项神经途径、E项皮肤接触均非其传播方式。传染源为患者及猪等家畜家禽"},{"q":"肉芽组织和肉芽肿的区别点在于","o":["是否为慢性炎症","是否导致局部纤维化","是否由急性转化而来","组成成分不同","最后结局不同"],"a":3,"e":"肉芽组织由新生毛细血管、成纤维细胞和炎细胞构成，用于修复缺损；肉芽肿由巨噬细胞及其衍生细胞即上皮样细胞、多核巨细胞增生形成结节状病灶，属特殊类型慢性炎，两者组成成分截然不同。A项肉芽组织也见于急性损伤修复，B项两者均可致纤维化，C项与急性炎症转化无必然联系，E项结局均可为瘢痕形成"},{"q":"沃-弗综合征（Waterhouse-Friderichsen syndrome）主要发生于","o":["中毒性菌痢","大叶性肺炎","间质性肺炎","流行性脑脊髓膜炎","流行性乙型脑炎"],"a":3,"e":"沃-弗综合征见于暴发型流行性脑脊髓膜炎，因双侧肾上腺广泛出血坏死致急性肾上腺皮质功能衰竭，表现为高热、休克、DIC及皮肤大片瘀斑。中毒性菌痢可致休克但无肾上腺出血坏死；大叶性肺炎、间质性肺炎、乙脑均不发生"},{"q":"门脉性肝硬化脾肿大的主要原因是","o":["脾脏内单核巨噬细胞增生","门静脉压力增高","肝静脉血栓形成","腹水压迫使脾静脉回流障碍","脾脏内纤维结缔组织增生"],"a":1,"e":"门脉性肝硬化时假小叶压迫小叶下静脉及肝静脉，肝血窦受压闭塞，门静脉回流受阻、压力升高，脾静脉回流障碍致脾淤血性肿大。脾内单核巨噬细胞增生与纤维组织增生只是继发改变；肝静脉血栓形成为Budd-Chiari综合征，不属本病"},{"q":"痰涂片阳性检出率最高的肺癌是","o":["大细胞癌","小细胞癌","腺癌","鳞状细胞癌","细支气管肺泡癌"],"a":3,"e":"鳞状细胞癌多位于肺门附近的大支气管，癌细胞间桥粒丰富、彼此连接松散，脱落入痰液的机会多，痰涂片阳性率最高。小细胞癌细胞小、易挤压变形，腺癌多位于肺周边，大细胞癌少见，细支气管肺泡癌痰检阳性率低"},{"q":"炎症时，引起白细胞渗出最重要的因素是","o":["血管壁通透性升高","白细胞附壁","炎症介质起作用","白细胞的阿米巴运动","血管内压力升高"],"a":2,"e":"炎症时白细胞渗出的最重要因素是炎症介质的作用，组胺、白三烯、趋化因子、细胞因子等介质介导血管扩张、通透性升高及白细胞黏附游出。血管壁通透性升高、白细胞附壁、阿米巴运动及血管内压升高均为渗出的具体环节，不起决定性主导作用"},{"q":"急性重型肝炎发生肝萎缩的主要原因是","o":["肝细胞大片坏死，仅周边残留少数变性的肝细胞","肝细胞发生大片坏死，少数残留肝细胞又能再生","肝细胞大片萎缩","肝细胞发生碎片状坏死","肝细胞发生桥接坏死"],"a":0,"e":"急性重型肝炎肝细胞自小叶中央迅速向周边广泛坏死，仅小叶周边残留少许变性肝细胞，肝体积显著缩小、重量减至600～800g，故称急性黄色肝萎缩。残留肝细胞再生不明显，故非肝萎缩的另一原因。碎片状坏死与桥接坏死见于慢性肝炎，不引起肝体积显著缩小"},{"q":"病毒性肝炎时最常见的肝细胞坏死是","o":["嗜酸性坏死","点状坏死","溶解性坏死","碎片状坏死","桥接坏死"],"a":2,"e":"病毒性肝炎时肝细胞严重变性（气球样变）后发展而来的溶解性坏死最常见，表现为核固缩、溶解、消失，细胞膜破裂解体，局部伴淋巴细胞浸润。嗜酸性坏死为单个肝细胞的凋亡；点状、碎片状、桥接坏死是按坏死范围与分布划分的类型，反映病变程度而非最常见形式"},{"q":"下列选项中，不是侵袭性血管黏液瘤的特征的是","o":["好发于女性盆腔","瘤细胞核分裂很多见","瘤组织呈浸润性生长","瘤组织富含黏液","瘤组织由散在梭形、星形的间叶细胞构成"],"a":1,"e":"侵袭性血管黏液瘤好发于女性盆腔及会阴，瘤组织富含黏液、呈浸润性生长，由散在的梭形、星形间叶细胞构成，细胞无异型，核分裂罕见，故核分裂很多见不符合其特征。核分裂活跃、细胞异型明显多见于肉瘤等恶性间叶肿瘤"},{"q":"下列关于AIDS的叙述错误的是","o":["AIDS的潜伏期长","AIDS是由HIV感染所引起的","HIV是一种逆转录病毒","AIDS可通过游泳和公共洗浴感染","AIDS常伴有肿瘤的发生"],"a":3,"e":"AIDS由HIV感染引起，HIV属逆转录病毒，攻击CD4+T细胞，潜伏期长达数年，免疫缺陷后易发生机会性感染和卡波西肉瘤、淋巴瘤等肿瘤。传播途径为性接触、血液及母婴垂直传播，游泳与公共洗浴不传播，故该项错误"},{"q":"肾综合征出血热最常见的死亡原因是","o":["急性肾衰竭","急性心力衰竭","出血性休克","呼吸衰竭","中毒性休克"],"a":0,"e":"肾综合征出血热少尿期因肾小管坏死、间质水肿和肾血流量下降发生急性肾衰竭，是本病最常见的死亡原因。低血压休克期可因出血性休克致死，但比例较低；心力衰竭和呼吸衰竭多为继发性改变。本病死因依次为急性肾衰竭、休克和出血，少尿期还伴高钾血症和氮质血症"},{"q":"良性肿瘤对机体的影响主要取决于肿瘤的","o":["生长方式","生长部位","生长速度","有无复发","有无转移"],"a":1,"e":"良性肿瘤分化好、不转移，对机体影响主要取决于生长部位，位于颅内、心脏或气道等关键部位者虽小亦可致命。生长方式、生长速度影响有限；良性肿瘤不发生转移，有无转移不构成影响，复发也非主要决定因素"},{"q":"肿瘤恶性程度的高低取决于","o":["肿瘤体积的大小","肿瘤患者的临床表现","肿瘤的生长速度","肿瘤细胞的分化程度","肿瘤发生的部位"],"a":3,"e":"肿瘤的恶性程度取决于瘤细胞的分化程度，分化越低、异型性越大，恶性程度越高，病理分级即依此判定。肿瘤体积、生长速度和发生部位只反映病程与解剖条件，患者的临床表现是结果而非依据。分级采用三级法，1级高分化、2级中分化、3级低分化，级别越高恶性程度越高"},{"q":"下列哪项不是恶性肿瘤","o":["Krukenberg瘤","Ewing肉瘤","Hodgkin瘤","淋巴瘤","多形性腺瘤"],"a":4,"e":"多形性腺瘤（混合瘤）是唾液腺良性肿瘤，生长缓慢、边界清，不属恶性。Krukenberg瘤为胃癌卵巢转移，Ewing肉瘤、Hodgkin瘤、淋巴瘤均为恶性肿瘤，故唯多形性腺瘤不是恶性"},{"q":"诊断慢性浅表性胃炎最有意义的一项是","o":["黏膜浅层有淋巴细胞、浆细胞浸润","黏膜浅层有炎细胞浸润、腺体增生","黏膜浅层有水肿、点状出血和上皮坏死","黏膜浅层有炎细胞浸润、腺体破坏","黏膜浅层有嗜酸性粒细胞和中性粒细胞浸润"],"a":0,"e":"慢性浅表性胃炎病变限于黏膜浅层，以淋巴细胞、浆细胞浸润为特征，腺体结构完整，这是其诊断依据。B项的腺体增生并非本病特点；D项出现腺体破坏、减少则已属萎缩性胃炎，两者以腺体是否保存相区分"},{"q":"大肠癌的好发部位依次是","o":["直肠、升结肠、降结肠、乙状结肠、横结肠","直肠、乙状结肠、横结肠、升结肠、降结肠","直肠、乙状结肠、盲肠、升结肠、横结肠、降结肠","升结肠、横结肠、盲肠、降结肠、乙状结肠、直肠","升结肠、降结肠、盲肠、横结肠、直肠、乙状结肠"],"a":2,"e":"大肠癌好发部位以直肠最多，约50%，其次为乙状结肠约20%，其后为盲肠、升结肠、横结肠，降结肠最少，故该顺序正确。A项把降结肠提到乙状结肠之前、B项把横结肠置于盲肠和升结肠之前，均与解剖分布不符。E项以升结肠起首，颠倒了直肠最多见的规律"},{"q":"绒癌最常继发于","o":["正常妊娠","早产","流产","异位妊娠","葡萄胎"],"a":4,"e":"绒毛膜癌半数以上继发于完全性葡萄胎，其余继发于流产、正常妊娠与异位妊娠。葡萄胎滋养细胞增生并具恶变潜能，约2%～3%的完全性葡萄胎可发展为绒癌。自然流产或人工流产约占25%，正常分娩后约占22.5%，异位妊娠仅约2.5%，均明显低于葡萄胎"},{"q":"有关食管癌的组织类型，下列哪项最多见","o":["腺癌","类癌","鳞癌","未分化癌","腺鳞癌"],"a":2,"e":"中国人食管癌以鳞状细胞癌最常见，约占90%以上，多位于食管中段，与饮酒、吸烟及热食刺激有关。腺癌多来自贲门或食管下段黏膜下腺体，近年发病率上升但居次位。腺鳞癌、黏液表皮样癌与未分化癌均少见，类癌罕见"},{"q":"风湿病的特异性病理变化是指","o":["风湿小结形成","结缔组织的黏液变化","胶原纤维的变性、坏死","病灶中发生的纤维素样坏死","病灶内出现梭形小瘢痕"],"a":0,"e":"风湿病的特异性病变是风湿小体即Aschoff小体，由纤维蛋白样坏死、成群的风湿细胞及少量淋巴细胞、浆细胞构成，是诊断风湿病的依据。黏液样变性、胶原纤维变性坏死属变质期改变，不具特异性；纤维蛋白样坏死亦见于结节性多动脉炎；梭形小瘢痕为愈合期结局而非特异性病变"},{"q":"睾丸最常见的生殖细胞肿瘤是","o":["精原细胞瘤","胚胎性癌","卵黄囊瘤","成熟型畸胎瘤","未成熟型畸胎瘤"],"a":0,"e":"睾丸生殖细胞肿瘤中精原细胞瘤最常见，瘤细胞大而一致、胞质空亮含糖原、核仁明显，与卵巢无性细胞瘤同源。B项胚胎性癌、C项卵黄囊瘤、E项未成熟型畸胎瘤均较少见，且患者年龄更轻。D项成熟型畸胎瘤在卵巢远多于睾丸，不是睾丸最常见类型"},{"q":"关于急性普通型肝炎的病变，下列哪项是错误的","o":["气球样变","嗜酸性变","溶解坏死","肝细胞再生","结缔组织增生"],"a":4,"e":"急性普通型肝炎以肝细胞广泛气球样变、嗜酸性变及点状坏死为特征，坏死可溶解吸收，肝细胞沿网状支架再生，结构多能恢复，一般不出现明显纤维组织增生。结缔组织增生见于慢性肝炎与肝硬化。溶解坏死与肝细胞再生在本型中均可出现，属其常见改变"},{"q":"关于恶性肿瘤的超微结构的叙述，错误的是","o":["细胞器数目减少","可见核内陷和怪形核","可见特异性超微结构","细胞间连接减少","核仁数目增多"],"a":0,"e":"恶性肿瘤超微结构表现为核大、核内陷、怪形核、核仁增多增大、细胞间连接减少，细胞器数目常增多而非减少。特异性超微结构如黑色素小体、神经内分泌颗粒具有诊断价值，故细胞器数目减少的说法错误"},{"q":"急性输卵管炎的基本病变是","o":["黏膜层的增生性炎","肌层的化脓性炎","全层的坏疽性炎","黏膜层的肉芽肿性炎","浆膜层的卡他性炎"],"a":4,"e":"急性输卵管炎的基本病变为输卵管浆膜层及黏膜的卡他性炎（浆液纤维素性炎），重者可化脓。黏膜层增生性炎、肌层化脓性炎、全层坏疽性炎及黏膜层肉芽肿性炎均非其基本病变"},{"q":"肺心病时，下列哪种病变最不容易见到","o":["肺动脉圆锥膨隆","心尖钝圆、肥厚，主要由右心室构成","心脏横径增大，形成横位心","室上嵴增厚、增粗","右心室向心性肥大"],"a":4,"e":"肺心病时右心室因容量负荷增加呈离心性肥大，心腔扩张、心尖钝圆且由右心室构成，肺动脉圆锥膨隆、室上嵴增厚、心脏横径增大形成横位心。向心性肥大是高血压病左心室压力负荷下的表现，室壁增厚而心腔不扩大，肺心病不见此种改变"},{"q":"黏液癌最常见于","o":["血管壁","腹膜后","胃肠道","子宫","胆囊"],"a":2,"e":"黏液癌以细胞内或细胞外大量黏液积聚、形成黏液湖为特征，最常见于胃肠道（胃与结直肠）。血管壁、腹膜后非其好发部位；子宫多见子宫内膜样腺癌；胆囊以腺癌为主，均非黏液癌最典型发生处"},{"q":"家族性腺瘤性息肉综合征属于","o":["常染色体显性遗传病","常染色体隐性遗传病","X连锁显性遗传病","X连锁隐性遗传病","Y连锁遗传病"],"a":0,"e":"家族性腺瘤性息肉病由APC基因突变致病，致病基因位于常染色体，杂合即可发病，属常染色体显性遗传病。神经纤维瘤、家族性高胆固醇血症同为常染色体显性；苯丙酮尿症、白化病、半乳糖血症为常染色体隐性；血友病、G6PD缺乏症属X连锁隐性遗传"},{"q":"在肉芽组织内具有收缩功能，又能产生基质和胶原的细胞是","o":["成肌纤维细胞","巨噬细胞","血管内皮细胞","成纤维细胞","中性粒细胞"],"a":0,"e":"成肌纤维细胞兼有成纤维细胞合成胶原、基质的功能与平滑肌细胞的收缩功能，收缩可使创口缩小。成纤维细胞仅合成基质与胶原而无收缩性；巨噬细胞负责吞噬清除；血管内皮细胞构成新生毛细血管"},{"q":"细菌性痢疾的肠道病变特点是","o":["浆液性炎","纤维素性炎","肉芽肿性炎","出血性坏死炎","蜂窝织炎"],"a":1,"e":"细菌性痢疾由志贺菌引起，结肠黏膜大量纤维蛋白原渗出并转为纤维蛋白，与坏死上皮、中性粒细胞、细菌共同构成假膜，属典型纤维素性炎。浆液性炎以血浆渗出为主，见于烧伤水疱；肉芽肿性炎以巨噬细胞结节为特征，见于结核；蜂窝织炎为疏松结缔组织的弥漫性化脓性炎"},{"q":"如图所示，结核结节主要由什么细胞构成","o":["浆细胞","淋巴细胞","成纤维细胞","巨噬细胞","上皮样细胞和朗汉斯巨细胞"],"a":4,"e":"结核结节由上皮样细胞、朗汉斯巨细胞及外周淋巴细胞、少量成纤维细胞构成，中央常有干酪样坏死，上皮样细胞与朗汉斯巨细胞是其特征性成分。浆细胞和淋巴细胞为反应性成分；成纤维细胞参与结节周边包膜形成"},{"q":"下列因素与动脉阻塞无关的是","o":["血栓形成","动脉瘤","肿瘤压迫","动脉粥样硬化","动脉栓塞"],"a":1,"e":"动脉瘤是动脉壁局部薄弱后向外膨出形成的永久性扩张，本身不阻塞管腔，其主要后果为破裂出血或附壁血栓形成，与动脉阻塞无直接关系。血栓形成、动脉栓塞可直接堵塞管腔，动脉粥样硬化斑块使管腔狭窄，肿瘤压迫亦可致外压性阻塞"},{"q":"贫血性梗死发生于","o":["组织疏松的器官","有双重血液供给的器官","严重淤血的器官","组织结构致密的器官","侧支循环充分的器官"],"a":3,"e":"贫血性梗死发生于组织结构较致密、侧支循环不充分的实质器官，如脾、肾、心和脑，故梗死灶灰白、色淡。组织疏松的器官梗死时血液易渗入，形成出血性梗死。双重血液供给或侧支循环充分的器官如肺、肝很少发生梗死。严重淤血的肺、肠发生的是出血性梗死"},{"q":"下面关于慢性支气管炎的描述不正确的是","o":["是一种由呼吸道过敏引起的以支气管可逆性发作性痉挛为特征的慢性阻塞性炎性疾病","支气管壁平滑肌断裂、萎缩","黏膜腺体增生肥大","黏膜上皮可出现鳞状化生","支气管壁充血水肿，淋巴细胞、浆细胞浸润"],"a":0,"e":"慢性支气管炎是支气管黏膜及周围组织的慢性非特异性炎症，与吸烟、感染、理化刺激有关。由过敏引起、以可逆性支气管痉挛为特征的是支气管哮喘；腺体增生、平滑肌断裂、鳞状化生及慢性炎细胞浸润均为慢支表现"},{"q":"慢性支气管炎伴哮喘的主要因素是","o":["支气管黏膜内杯状细胞增多","支气管黏膜水肿","支气管壁平滑肌痉挛","支气管腔内黏液增多","支气管管壁炎细胞浸润"],"a":2,"e":"喘息型慢性支气管炎因管壁平滑肌束增生、肥大并发生痉挛，出现伴哮鸣音的呼气性呼吸困难。杯状细胞增多和黏液腺增生致痰量增多；黏膜水肿和炎细胞浸润是慢性炎症的基本改变，均不直接引起哮喘样发作"},{"q":"引起急性弥漫性增生性肾小球肾炎的致病抗原常来自","o":["乙型肝炎病毒","葡萄球菌","肺炎球菌","溶血性链球菌","麻疹病毒"],"a":3,"e":"急性弥漫性增生性肾小球肾炎多为A组溶血性链球菌感染后的免疫复合物性肾炎，致病抗原常来自溶血性链球菌。乙型肝炎病毒、葡萄球菌、肺炎球菌、麻疹病毒均非常见的致病抗原来源"},{"q":"如图所见血栓可见于","o":["静脉内柱状血栓的尾部","毛细血管内","急性风湿性心内膜炎的瓣膜闭锁缘","动脉血栓的头部","左心房球形血栓"],"a":4,"e":"本题原题配有图片，图片未随文档保留，以下解析依文字线索推断：题干涉及图片/信息缺失，无法作答。左心房内的混合血栓因心房收缩与舒张而呈球形，称球形血栓，多见于二尖瓣狭窄伴心房颤动。静脉内延续性血栓尾部为红色血栓；心瓣膜闭锁缘和动脉血栓头部为白色血栓；毛细血管内为透明血栓\n\n官方题库中缺失图片"},{"q":"下列哪项不属于细胞异型性","o":["核数目不一","核肿胀，核膜不清","核染色质分布不均","核大小不等，核畸形","病理性核分裂象"],"a":1,"e":"细胞异型性表现为核大小不等、形状不一、核畸形，染色质分布不均而深染，核仁增大增多，核分裂象增多并出现病理性核分裂。核肿胀、核膜不清属坏死的核改变，是核溶解的表现，不属异型性范畴。核数目不一见于多核瘤巨细胞，属细胞异型性的内容"},{"q":"关于小叶性肺炎，下列哪一项是错误的","o":["细支气管和肺泡的化脓性炎","可并发肺脓肿和脑脓肿","严重者病灶发生融合","病灶周围肺组织充血","病灶散在于两肺，以上肺多见"],"a":4,"e":"小叶性肺炎病灶散在于两肺，以两肺下叶及背侧下垂部位多见，而非上肺。其为细支气管和肺泡的化脓性炎，可并发肺脓肿和脑脓肿，严重者病灶融合，周围肺组织充血，均属正确描述"},{"q":"动脉瘤应该除外","o":["圆柱状动脉瘤","蜿蜒状动脉瘤","囊状动脉瘤","真性动脉瘤","舟状动脉瘤"],"a":3,"e":"动脉瘤按形态分为囊状、梭形即圆柱状、蜿蜒状与舟状动脉瘤。真性动脉瘤是按瘤壁结构分类，指瘤壁仍由动脉壁三层构成者，与假性动脉瘤相对，不属于形态学类型，故不能与上述并列"},{"q":"化生不可能发生于","o":["支气管假复层纤毛柱状上皮","宫颈柱状上皮","肾盂黏膜上皮","神经纤维","结缔组织"],"a":3,"e":"化生是一种分化成熟组织转变为另一种分化成熟组织，只发生于上皮组织和结缔组织。神经纤维属神经组织，无化生能力，故化生不可能发生于神经纤维。支气管假复层纤毛柱状上皮、宫颈柱状上皮、肾盂移行上皮均可鳞状化生，结缔组织可化生为骨或软骨"},{"q":"符合门脉性肝硬化特点的是","o":["结节大小相仿，纤维间隔薄而均匀","结节大小不等，纤维间隔厚薄不均","结节呈细颗粒状，深绿色","结节不明显","肝内散在多个粗大结节"],"a":0,"e":"门脉性肝硬化属小结节型，再生结节大小相仿、直径多小于3mm，纤维间隔薄而均匀，多由轻型肝炎或慢性酒精中毒引起。结节大小不等、纤维间隔厚薄不均为坏死后性（大结节型）肝硬化的特点；结节呈细颗粒状、深绿色为胆汁性肝硬化的表现；结节不明显见于血吸虫性肝纤维化"},{"q":"肾梗死灶大体形态的主要特点为","o":["多呈楔形，暗红色，界限不清","多呈地图形，灰白色，界限清楚","多呈楔形，灰白色，界限清楚","多呈不规则形，暗红色，界限不清","多呈地图形，暗红色，界限不清"],"a":2,"e":"肾梗死为贫血性梗死：肾动脉呈锥形分支，梗死灶呈楔形、尖端指向肾门，灰白色，与周围界限清楚，周边有充血出血带。地图形梗死见于心肌；暗红色、界限不清为出血性梗死（肺、肠）的特点。肾、脾、肺的动脉均为终末支，阻塞后易梗死；肾梗死后期瘢痕收缩使肾表面凹陷"},{"q":"病毒性肺炎的特点中不包括","o":["多由上呼吸道病毒感染蔓延引起","炎症主要累及肺间质","流感病毒常见","肺组织化脓","细胞内可出现包涵体"],"a":3,"e":"病毒性肺炎多为上呼吸道病毒感染向下蔓延所致，病变主要累及肺间质，表现为间质淋巴细胞、单核细胞浸润及肺泡隔增宽，流感病毒最常见，增生的上皮内可查见病毒包涵体。肺组织化脓是细菌性肺炎的特点，病毒本身不引起化脓性病变"},{"q":"下列关于肺癌的描述哪项是错误的","o":["同一肿瘤可有不同的组织学类型","同一肿瘤的不同部位可分化程度不一","未分化腺癌可出现肉瘤样结构","转移癌的组织学类型可与原发癌不同","肺癌中最常见组织类型是小细胞癌"],"a":4,"e":"肺癌最常见的组织学类型是鳞状细胞癌，小细胞癌约占10%~20%，恶性度最高而对放化疗敏感。同一肿瘤可混合不同组织学类型，不同部位分化程度可不一；未分化癌可出现肉瘤样结构，属形态变异而非独立类型"},{"q":"肿瘤血行转移的确切证据是","o":["恶性肿瘤细胞侵入静脉","恶性肿瘤细胞侵入动脉","血液中查见肿瘤细胞","肿瘤细胞栓塞于远隔器官","在远隔器官形成同一类型的肿瘤"],"a":4,"e":"转移的确切证据是在远隔部位形成与原发瘤组织学类型相同的肿瘤。瘤细胞侵入静脉或动脉仅说明具备入血条件，血中查见瘤细胞或瘤细胞栓塞于远隔器官，均可能被机体清除而不形成转移灶。入血的单个瘤细胞多数被NK细胞消灭"},{"q":"下述成分是粥样斑块中所不具备的是","o":["胆固醇结晶","纤维结缔组织","中性粒细胞","泡沫细胞","坏死物质"],"a":2,"e":"粥样斑块由纤维帽、脂质核心与泡沫细胞构成，纤维帽为纤维结缔组织，核心含坏死物质、胆固醇结晶及钙盐，斑块内无中性粒细胞。中性粒细胞是急性炎症的浸润细胞，粥样硬化属慢性炎症，浸润细胞以巨噬细胞和T淋巴细胞为主"},{"q":"下列组织愈合是由瘢痕修复的是","o":["心肌梗死","皮肤的浅表性缺损","月经期子宫内膜脱落","肝细胞点状坏死","慢性细菌性痢疾的假膜性炎"],"a":0,"e":"心肌属永久性细胞，梗死后不能再生，由肉芽组织长入取代，最终形成瘢痕。皮肤浅表缺损由表皮基底层细胞再生修复；子宫内膜周期性脱落属生理性再生；肝细胞点状坏死可完全再生并恢复结构；菌痢假膜脱落后由黏膜上皮再生覆盖"},{"q":"沃-弗综合征的发生机制是","o":["细菌性栓子所致的肾上腺广泛出血坏死","败血症引起的急性肾上腺皮质功能衰竭","大量内毒素释放所引起的弥散性血管内凝血","败血症引起的中毒性休克及肾上腺出血","严重感染而致双肾上腺广泛出血及急性肾上腺皮质功能衰竭"],"a":2,"e":"沃-弗综合征由大量内毒素释放入血，引起中毒性休克和弥散性血管内凝血，两者相互影响使病情恶化。肾上腺广泛出血及急性肾上腺皮质功能衰竭是DIC与休克造成的后果，不是起始机制；细菌性栓子所致肾上腺出血坏死属败血性栓塞"},{"q":"动脉粥样硬化合并血栓形成的最主要的机制是","o":["血流涡流形成","局部血流缓慢","内膜受损、胶原纤维暴露","局部血液凝固性增高","炎性细胞浸润"],"a":2,"e":"粥样斑块表面溃破使内膜下胶原纤维暴露，血小板黏附、聚集并激活凝血系统，是AS合并血栓形成的主要机制。血流缓慢和涡流只提供局部条件；血液凝固性增高见于高脂血症、糖尿病，属次要因素；炎细胞浸润参与斑块进展，不直接促凝"},{"q":"关于骨巨细胞瘤的描述，不正确的是","o":["常在20岁以前发病","虽然是良性的，也要切除","长管骨末端常见","约1/2者有局部复发和转移","病变常由含有肿瘤的薄层骨包绕"],"a":0,"e":"骨巨细胞瘤好发于20～40岁青壮年，多在骺板闭合后发生，故20岁以前发病错误，该年龄段多见骨肉瘤和尤因肉瘤。C项长管骨末端如股骨下端、胫骨上端为典型部位，E项病变常由薄层骨壳包绕，B项虽属良性但具局部侵袭性需切除，D项约半数复发并可肺转移，均正确"},{"q":"致使肺梗死的血栓栓子一般来自","o":["静脉系统或右心的血栓","二尖瓣疣状血栓的脱落","门静脉的血栓脱落","左心房附壁血栓","动脉及左心房的血栓脱落"],"a":0,"e":"肺梗死多由体静脉或右心腔的血栓脱落，栓子随血流栓塞肺动脉分支引起，且需以肺淤血作为先决条件。二尖瓣疣状血栓和左心房附壁血栓属左心系统，脱落后引起脑、脾、肾等体循环栓塞；门静脉血栓引起肝内门静脉分支栓塞"},{"q":"下列肠疾病最可能发生癌变的是","o":["出血坏死性肠炎","局限性肠炎","慢性溃疡性结肠炎","肠结核","肠阿米巴病"],"a":2,"e":"慢性溃疡性结肠炎因黏膜反复损伤与增生修复，病程越长癌变风险越高，属癌前疾病。出血坏死性肠炎与肠阿米巴病为急性病变，癌变罕见。肠结核经治疗可愈合，不列为癌前病变。局限性肠炎即克罗恩病癌变率很低"},{"q":"肝硬化晚期腹水的形成原因中，哪项是错误的","o":["肝细胞合成凝血酶原减少","肝淋巴液外溢","肝细胞合成蛋白功能低下","抗利尿激素、醛固酮在血内水平增高","门静脉高压"],"a":0,"e":"肝硬化腹水由门静脉高压使毛细血管静水压升高、肝细胞合成白蛋白减少使血浆胶体渗透压降低、肝淋巴液自肝表面漏出，以及继发性醛固酮和抗利尿激素增多致水钠潴留共同造成。凝血酶原合成减少引起出血倾向，与腹水形成无关"},{"q":"下列哪项为动脉粥样硬化早期的病理变化","o":["纤维帽形成","由于氧化LDL的毒性作用使泡沫细胞坏死","血液单核细胞迁入内膜并形成泡沫细胞","中膜平滑肌细胞迁入内膜并增生","淋巴细胞浸润心肌间质"],"a":2,"e":"动脉粥样硬化早期为脂纹，血液单核细胞迁入内膜并摄取氧化低密度脂蛋白转化为泡沫细胞，形成脂质条纹。纤维帽形成属纤维斑块期；泡沫细胞坏死、平滑肌细胞迁入内膜并增生见于病变进展期"},{"q":"关于干酪样肺炎的叙述，下列哪项是正确的","o":["是原发性肺结核的一种常见类型","多由急、慢性空洞内的结核杆菌经血行播散所致","可由浸润型肺结核恶化、进展而来","病变性质为富含脂质的化脓性炎","常发生在免疫力强或变态反应低的患者"],"a":2,"e":"干酪性肺炎可由浸润型肺结核恶化进展而来，也可由急、慢性空洞内的结核分枝杆菌经支气管播散所致，故经血行播散的说法错误。病变为大片干酪样坏死伴肺泡内浆液纤维蛋白渗出，属变质性炎而非化脓性炎；多发生于机体免疫力低下、变态反应增强者，不是原发性肺结核的常见类型"},{"q":"下列哪种肿瘤的形状，癌的可能性大","o":["息肉状","火山口状溃疡","分叶状","结节状","乳头状"],"a":1,"e":"癌多呈火山口状溃疡，边缘隆起外翻、底部污秽，由癌组织坏死脱落后形成。息肉状、乳头状、分叶状、结节状多见于良性肿瘤，肉瘤多呈鱼肉状、境界不清，均不提示癌。溃疡型癌直径常大于2cm，边缘不整、底部不平，与良性溃疡的整齐边缘不同"},{"q":"肝脏上有一转移瘤，镜下表现如图，肝外最可能的原发部位是","o":["食管","膀胱","结肠","股骨","小脑"],"a":2,"e":"本题原题配有图片，图片未随文档保留，以下解析依文字线索推断：题干涉及图片/信息缺失，无法作答。肝转移瘤常为多个结节、中央脐凹，镜下腺样结构提示腺癌；消化道腺癌经门静脉入肝，结肠腺癌是最常见来源之一。食管癌以鳞癌为主，肝转移较少；膀胱、股骨、小脑的原发肿瘤罕有肝转移\n\n官方题库中缺失图片"},{"q":"胆囊最常见的恶性肿瘤是","o":["鳞癌","腺癌","腺鳞癌","腺棘皮癌","类癌"],"a":1,"e":"胆囊癌以腺癌最多见，占80%以上，由胆囊黏膜腺上皮恶变而来。A项鳞癌少见，多伴胆囊黏膜鳞状化生；C项腺鳞癌、D项腺棘皮癌更为罕见；E项类癌属神经内分泌肿瘤，几乎不发生于胆囊。本病与胆石症、慢性胆囊炎长期刺激有关，早期即易直接浸润肝床"},{"q":"下列哪项不属于门脉高压症","o":["脾大","腹水","侧支循环形成","胃肠道淤血","蜘蛛痣"],"a":4,"e":"门脉高压症表现为脾大、腹水、侧支循环形成及胃肠道淤血，由门静脉回流受阻引起。蜘蛛痣源于肝功能减退致雌激素灭活减少、小动脉末梢扩张，属肝功能不全的表现，不属门脉高压症范畴。侧支循环形成可致食管胃底静脉曲张破裂出血"},{"q":"大叶性肺炎发生肺肉质变是因为","o":["变态反应剧烈","成纤维细胞增生","机体抵抗力降低","吞噬细胞数量少","病变范围过大"],"a":3,"e":"肺肉质变因渗出纤维蛋白过多而中性粒细胞过少，蛋白水解酶不足，纤维蛋白不能被溶解而由肉芽组织机化。机体抵抗力降低、变态反应剧烈、病变范围过大只影响病情轻重，成纤维细胞增生是机化的结果而非原因"},{"q":"一坏死组织肉眼观察呈白色或微黄色、细腻，最有可能的是","o":["胰腺炎所致的脂肪坏死","脓肿所致的液化性坏死","缺血所致的凝固性坏死","免疫反应所致的纤维蛋白样坏死","结核病所致的干酪样坏死"],"a":4,"e":"干酪样坏死是结核病的典型坏死，因坏死组织含脂质较多，肉眼呈白色或微黄色、细腻均质如奶酪，镜下为红染无结构的颗粒状物。脂肪坏死为灰白色斑点状钙化灶，凝固性坏死灰白干燥、轮廓保存，液化性坏死形成囊腔，纤维蛋白样坏死见于结缔组织与小血管壁，肉眼均不呈细腻黄色"},{"q":"主动脉瓣狭窄的描述中下列哪一项是错误的","o":["心室代偿性肥大","左心房失代偿性扩张","肺淤血水肿","右心代偿性肥大","主动脉瓣区收缩期杂音"],"a":3,"e":"主动脉瓣狭窄使左心室压力负荷增加，先出现左心室向心性肥大，失代偿后左心房扩张、肺淤血水肿，晚期经肺动脉高压才累及右心，故右心代偿性肥大不是本病的原发代偿表现。主动脉瓣区收缩期喷射性杂音为其特征性体征"},{"q":"槟榔肝可发展为","o":["坏死后肝硬化","门脉性肝硬化","淤血性肝硬化","胆汁性肝硬化","寄生虫性肝硬化"],"a":2,"e":"槟榔肝是慢性肝淤血时肝小叶中央区淤血出血、周边肝细胞脂肪变性形成的红黄相间切面，长期淤血可致肝纤维化，发展为淤血性肝硬化。坏死后性肝硬化多由病毒性肝炎所致，门脉性与酒精等相关，胆汁性因胆道阻塞，寄生虫性见于血吸虫，均非槟榔肝结局"},{"q":"恶性高血压病特征性病变是","o":["细动脉纤维素样坏死","血管壁单核细胞，中性粒细胞浸润","弓形动脉内膜显著增生","小动脉内弹力膜分裂","小动脉内微血栓形成"],"a":0,"e":"恶性高血压以细动脉纤维素样坏死为特征，管壁出现纤维蛋白沉积和坏死，可伴增生性小动脉硬化（洋葱皮样改变），进展快。B项单核细胞、中性粒细胞浸润非其特征；C项弓形动脉内膜增生多见于良性高血压长期病变；E项微血栓并非其标志性改变"},{"q":"超急性排斥反应多发生在","o":["移植后数月","移植后数分钟或数小时","移植后数日","随时可能发生","移植后数年"],"a":1,"e":"超急性排斥反应由受者体内预存的供体特异性HLA抗体或ABO血型不合引起，本质上属Ⅲ型超敏反应，移植后数分钟至数小时即发生，一旦出现无法逆转。急性排斥反应多发生于移植后数天至数月，经免疫抑制治疗者可延迟至数月或数年。慢性排斥反应发生于数月至数年"},{"q":"口眼干燥综合征患者血清内特征性抗体是","o":["抗HIV抗体阳性","抗HLA抗体阳性","抗IgE分子Fc段抗体阳性","抗核抗体阳性","抗SS-A抗体和抗SS-B抗体阳性"],"a":4,"e":"干燥综合征以淋巴细胞增殖和外分泌腺进行性损伤为特征，血清中出现抗SS-A和抗SS-B抗体，两者对本病相对特异。抗Scl-70抗体、抗着丝点抗体见于系统性硬化；抗核抗体在多种结缔组织病均可阳性，缺乏特异性；抗HIV抗体与艾滋病相关"},{"q":"引起成人肾病综合征最常见的原因为","o":["系膜增生性肾小球肾炎","膜增生性肾小球肾炎","局灶性节段性肾小球硬化","脂性肾病","膜性肾小球肾炎"],"a":4,"e":"膜性肾小球病是成人肾病综合征最常见的原因，上皮下免疫复合物沉积、基底膜弥漫增厚并形成钉突。脂性肾病是儿童肾病综合征最常见的原因；系膜增生性肾炎、膜增生性肾炎和局灶节段性肾小球硬化均非成人首位病因"},{"q":"膜性肾小球肾炎的病变特点是","o":["肾小球毛细血管基膜变薄、断裂，通透性增加","肾小球毛细血管基膜增厚、滤过率降低","肾小球毛细血管基膜变薄、断裂","肾小球毛细血管基膜增厚、通透性增加","肾小球毛细血管基膜增厚呈双车轨状或分层状"],"a":3,"e":"膜性肾病基底膜弥漫增厚，上皮下免疫复合物沉积破坏基膜屏障，滤过率下降而通透性增高，出现大量蛋白尿。基膜变薄、断裂见于微小病变与Alport综合征；双轨状或分层状为膜增生性肾炎的特点"},{"q":"关于慢性纤维空洞型肺结核的叙述，下列哪项是正确的","o":["结核空洞多位于肺下叶","病变局限，组织破坏不明显","无肺功能受损害","少见的继发性肺结核的一个类型","多由浸润型肺结核形成急性空洞后经久不愈发展而来"],"a":4,"e":"慢性纤维空洞型肺结核属继发性肺结核，多由浸润型肺结核溶解形成急性空洞后经久不愈、纤维组织包裹而成，空洞多位于肺上叶，可致肺组织广泛破坏、肺功能受损并引起喉结核。病变局限、无肺功能损害的描述不符"},{"q":"下列不属于非特异性反应性淋巴滤泡增生特点的是","o":["淋巴结大，淋巴滤泡增生，生发中心明显扩大","增生的淋巴滤泡内有各种转化的淋巴细胞，核较大，有裂或无裂，核分裂象多见","增生的淋巴滤泡有多数巨噬细胞，胞质内含有吞噬的细胞碎屑","增生的淋巴结结构破坏，淋巴滤泡消失","在滤泡之间的淋巴组织内可见浆细胞、组织细胞及少量中性粒细胞和嗜酸性粒细胞浸润，淋巴窦内的组织细胞和内皮细胞增生"],"a":3,"e":"非特异性反应性淋巴滤泡增生时淋巴结结构保留，淋巴滤泡数量增多、生发中心明显扩大，内含转化的B细胞及吞噬核碎片的巨噬细胞，滤泡间可见浆细胞、组织细胞及少量中性、嗜酸性粒细胞。淋巴结结构破坏、滤泡消失是恶性淋巴瘤的特征"},{"q":"下列哪一项不符合鼻咽癌的特性","o":["发生于鼻咽部柱状上皮","最常见于鼻咽的顶部","常破坏颅底骨并侵入颅内","癌组织有迅速向深部浸润生长的倾向","晚期常经淋巴道及血行转移至颈部淋巴结及肺、骨、肝等处"],"a":4,"e":"鼻咽癌早期即可发生淋巴道转移，半数以上患者以颈部淋巴结肿大为首发症状，故晚期才转移至颈部淋巴结的表述错误。癌多发生于鼻咽顶部与咽隐窝，易破坏颅底侵入颅内，并向深部浸润，晚期可血行转移至肺、骨、肝"},{"q":"原发性高血压脑出血最常见的部位是","o":["大脑皮质","豆状核和丘脑","蛛网膜下隙","内囊和基底核","侧脑室"],"a":3,"e":"高血压脑出血最常见于基底核即豆状核与内囊，因豆纹动脉由大脑中动脉垂直发出、承受高压，最易破裂形成血肿。大脑皮质出血多见于淀粉样血管病，蛛网膜下隙出血多由动脉瘤破裂引起"},{"q":"链球菌感染后肾小球肾炎电镜下沉积物多存在于","o":["内皮下","基底膜致密层","基底膜和脏层上皮细胞间，呈驼峰状","基底膜和脏层上皮细胞间，被基底膜钉状突起分隔","壁层上皮下"],"a":2,"e":"链球菌感染后肾炎的电子致密物主要位于脏层上皮细胞与基底膜之间，呈驼峰状突起，免疫荧光为颗粒状IgG、C3沉积。内皮下沉积见于膜增生性肾炎Ⅰ型。基底膜致密层内带状沉积为Ⅱ型膜增生性肾炎。被基底膜钉状突起分隔的上皮下沉积见于膜性肾病"},{"q":"膀胱癌的最常见转移部位是","o":["子宫旁、髂动脉旁和主动脉旁淋巴结","种植到卵巢","局部淋巴结","肝","肺"],"a":2,"e":"膀胱癌主要经淋巴道转移，最先累及盆腔区域淋巴结，故最常见转移部位为局部淋巴结。血行转移至肝、肺、骨多见于晚期，种植性转移可累及腹腔脏器但少见。子宫旁、主动脉旁淋巴结已超出区域范围，属远处淋巴结，不能与局部淋巴结等同"},{"q":"关于结外NK/T细胞淋巴瘤的叙述，下列哪项是错误的","o":["瘤细胞大小不等，形态多样","伴有凝固性坏死和多种炎细胞浸润","肿瘤性淋巴细胞散在分布或弥漫分布","是一种非霍奇金淋巴瘤","好发于年轻人"],"a":4,"e":"结外NK/T细胞淋巴瘤好发于中年男性而非年轻人，故该项错误。A项瘤细胞大小不等、形态多样，B项伴凝固性坏死和多种炎细胞浸润，C项瘤细胞散在或弥漫分布，D项属非霍奇金淋巴瘤，均正确。本瘤好发于鼻腔，与EB病毒感染相关，呈血管中心性浸润和破坏"},{"q":"左心衰竭病人的股静脉血栓脱落可引起","o":["肺凝固性坏死","肺液化性坏死","肺出血性梗死","肺贫血性梗死","心肌梗死"],"a":2,"e":"股静脉血栓脱落经右心阻塞肺动脉分支，肺有肺动脉与支气管动脉双重供血且组织疏松，动脉阻断后支气管动脉仍供血，坏死区出血显著，形成肺出血性梗死。肺凝固性坏死见于缺血早期尚无出血者；贫血性梗死见于心、脾、肾等结构致密器官"},{"q":"肝豆状核变性的特点是","o":["铁代谢障碍","脂类代谢障碍","铜代谢障碍","糖类代谢障碍","维生素C代谢障碍"],"a":2,"e":"肝豆状核变性为13号染色体隐性基因缺陷所致铜代谢障碍，铜不能经胆汁排出而沉积于肝、脑及角膜，引起肝硬化、豆状核变性及角膜K-F环。铁代谢障碍见于血色病，脂类代谢障碍见于动脉粥样硬化与脂质沉积症，糖代谢障碍见于糖尿病"},{"q":"下列哪种疾病不属于慢性阻塞性肺疾病","o":["支气管炎","肺气肿","支气管哮喘","慢性肺源性心脏病","支气管扩张症"],"a":3,"e":"慢性阻塞性肺疾病包括慢性支气管炎、肺气肿、支气管哮喘和支气管扩张症，以气道阻塞、气流受限为共同特征。慢性肺源性心脏病是上述疾病导致肺动脉高压后的心脏并发症，属其后果而非组成部分。支气管扩张症伴持久气道扩张与阻塞，亦归入本病范畴"},{"q":"关于肺气肿患者的临床表现，下面错误的是","o":["逐渐加强的吸气性呼吸困难","低氧血症","桶状胸","胸透肺野透明度增加","肺动脉高压和肺源性心脏病"],"a":0,"e":"肺气肿表现为进行性加重的呼气性呼吸困难，因小气道阻塞、呼气延长，而非吸气性呼吸困难。低氧血症、桶状胸、胸透肺野透明度增加及肺动脉高压、肺源性心脏病均为其典型表现"},{"q":"胃窦部黏膜组织活检，镜下如图所示，胃黏膜发生的有关病变的描述，错误的是","o":["黏膜腺体中度肠上皮化生","这种分化上的转向，只发生于同源细胞之间","可分为不完全肠化和完全肠化","该化生对机体有利，不会发生恶变","该化生可恶变形成肠型腺癌"],"a":3,"e":"本题原题配有图片，图片未随文档保留，以下解析依文字线索推断：题干涉及图片/信息缺失，无法作答。胃黏膜肠上皮化生指胃固有腺体被含杯状细胞的肠型上皮取代，分为完全型和不完全型，化生上皮可进一步异型增生并恶变为肠型腺癌。B项化生可跨胚层发生，如支气管柱状上皮鳞化，并非只限同源细胞之间。D项称化生对机体有利、不会恶变，与化生属癌前状态的结论相反\n\n官方题库中缺失图片"},{"q":"风湿性心内膜炎会出现以下哪种特征性结构","o":["Osler结节","Negri小体","Aschoff小体","环形红斑","McCallum斑"],"a":4,"e":"风湿性心内膜炎时瓣膜赘生物机化、瓣膜增厚变形，左心房后壁心内膜受血流冲击而增厚粗糙，形成McCallum斑，为本病特征。Osler结节见感染性心内膜炎，Negri小体见狂犬病，Aschoff小体位于心肌间质，环形红斑为皮肤表现，均非心内膜炎特征结构"},{"q":"沃-弗综合征发生时，下列哪个器官病变比较明显","o":["甲状腺","肾上腺","胸腺","胰腺","肾脏"],"a":1,"e":"沃-弗综合征见于暴发型脑膜炎双球菌败血症，双侧肾上腺广泛出血坏死、皮质功能急性衰竭，导致顽固性休克和皮肤大片瘀斑，故肾上腺病变最明显。A项甲状腺、C项胸腺、D项胰腺在该综合征中无特征性出血坏死。E项肾脏可因休克出现急性肾小管坏死，但属继发改变，不及肾上腺出血坏死具诊断意义"},{"q":"乳腺癌患者中，常选择哪组抗原检测对临床指导治疗和判断肿瘤预后有积极意义","o":["ER、PR、CK-L、CK-H、P53","ER、PR、P53、CK-P、nm23","ER、PR、nm23、S-100、EMA","ER、PR、nm23、c-erbB-2、P53","ER、PR、c-erbB-2、Ck-P EMA"],"a":3,"e":"ER、PR反映肿瘤对内分泌治疗的敏感性，阳性者预后较好；c-erbB-2（HER2）过表达提示预后差且可行靶向治疗；nm23与转移抑制相关，P53突变提示预后不良，故这组指标对治疗选择与预后判断有意义。CK-L、CK-H、EMA为上皮性标记，S-100为神经及黑色素细胞标记，无指导治疗价值"},{"q":"关于细胞外基质表述错误的是","o":["生成多种细胞因子","参与血管新生","影响细胞的分化","维持组织的结构和弹性","参与细胞再生"],"a":0,"e":"细胞外基质由胶原、蛋白多糖、糖蛋白和弹力蛋白构成，起支持连接、维持组织结构和弹性、影响细胞分化与再生、参与血管新生的作用，但本身不生成细胞因子，细胞因子由细胞合成分泌。B项血管新生、C项影响分化、D项维持结构和弹性、E项参与再生均为基质的已知功能"},{"q":"以下哪项与流脑、乙脑的区别无关","o":["中枢神经系统病变","病原微生物","传染途径","病变性质","炎症细胞种类"],"a":0,"e":"流脑与乙脑均累及中枢神经系统，都存在中枢神经系统病变，这是共同点，与两者区别无关。病原体（脑膜炎双球菌对乙脑病毒）、传染途径（呼吸道对蚊媒）、病变性质（化脓性炎对变质性炎）、炎症细胞种类（中性粒细胞对淋巴细胞单核细胞）均不同，是主要鉴别点"},{"q":"慢性支气管炎时，咳黏液泡沫痰的病变基础是","o":["支气管黏膜上皮损伤","黏液腺体肥大，黏膜上皮内杯状细胞增多","支气管壁纤维化、管腔狭窄","支气管平滑肌破坏","支气管扩张"],"a":1,"e":"慢支黏液腺体肥大、杯状细胞增多使黏液分泌增加，分泌物与吸入气体混合形成黏液泡沫痰。上皮损伤与纤毛脱落致排痰不畅，平滑肌破坏与纤维化致管腔狭窄、呼吸困难，支气管扩张则表现为大量脓痰与咯血"},{"q":"最常见的栓子是","o":["脱落的肿瘤细胞团","空气","血栓","羊水","寄生虫"],"a":2,"e":"血栓是最常见的栓子，占所有栓塞的99%以上，多来自下肢深静脉与左心腔。肿瘤细胞团、空气、羊水、寄生虫均可成为栓子但少见；脂肪栓塞多见于长骨骨折与脂肪组织挫伤，减压病为氮气栓塞"},{"q":"关于风湿性心内膜炎，下列叙述哪项是错误的","o":["赘生物如粟粒，灰白色，成串珠状、单行排列","赘生物附着牢固，易机化","赘生物多位于瓣膜闭锁缘","受累瓣膜易发生溃疡及穿孔","其实质是白色血栓"],"a":3,"e":"风湿性心内膜炎赘生物细小、灰白色、呈串珠状单行排列于瓣膜闭锁缘，附着牢固易机化，本质为白色血栓，通常不引起瓣膜溃疡及穿孔。溃疡与穿孔多见于感染性心内膜炎，故该项叙述错误"},{"q":"下列疾病均能引起门脉高压症，但以哪种疾病的门脉高压最为明显","o":["血吸虫性肝硬化","门脉性肝硬化","胆汁性肝硬化","淤血性肝硬化","坏死后性肝硬化"],"a":0,"e":"血吸虫虫卵在肝门管区反复沉积，形成虫卵结节与广泛纤维化，纤维条索紧束门静脉分支使其血流受阻，故门脉高压出现早而显著，常伴巨脾和食管静脉曲张。B项门脉性肝硬化假小叶压迫肝窦和小叶下静脉，高压出现较晚；C项胆汁性、D项淤血性肝硬化以纤维增生为主、肝内改建轻，高压较轻。E项坏死后性肝硬化高压亦不如血吸虫性突出"},{"q":"急性普通型病毒性肝炎中具有诊断意义的病变是","o":["肝细胞脂肪变性","肝细胞细胞质疏松化和气球样变","肝细胞嗜酸性坏死","肝细胞水肿","肝细胞玻璃样变性"],"a":1,"e":"急性普通型病毒性肝炎以肝细胞广泛水肿为主，胞质疏松化、气球样变，伴点灶状坏死与炎细胞浸润，气球样变最具诊断意义。脂肪变性见于酒精性或代谢性肝病；嗜酸性坏死（Councilman小体）多见于重型肝炎；玻璃样变即Mallory小体，见于酒精性肝炎"},{"q":"下列哪项是伤口二期愈合的特点","o":["创面小","创面不洁、伴感染","手术切口","肉芽组织少","形成瘢痕小"],"a":1,"e":"二期愈合见于创面大、创缘不整、无法严密对合或伴感染与异物的伤口，坏死组织多，肉芽组织生长多，瘢痕大，愈合时间长。创面小、手术切口、无感染及瘢痕小均为一期愈合的特点。二期愈合须先控制感染、清除坏死组织和异物，愈合后瘢痕收缩可引起器官变形"},{"q":"透明细胞肉瘤免疫组化示","o":["CK（＋）","HMB45（＋）","EMA（＋）","Desmin（＋）","CD117（＋）"],"a":1,"e":"透明细胞肉瘤属软组织黑色素瘤，瘤细胞含黑色素小体，HMB45为黑色素相关抗原标记，呈阳性表达。CK是上皮细胞角蛋白，阳性提示癌；desmin为肌源性标记，见于横纹肌和平滑肌肿瘤。CD117多表达于胃肠道间质瘤，EMA见于上皮性肿瘤与脑膜瘤，均不标记本瘤"},{"q":"病变呈节段性分布的局限性肠炎是指","o":["慢性溃疡性结肠炎","克罗恩病","细菌性痢疾","肠阿米巴病","伤寒"],"a":1,"e":"克罗恩病又称局限性肠炎，病变呈节段性分布，主要累及回肠末端，肠壁全层炎伴淋巴滤泡增生和非干酪样肉芽肿，黏膜呈铺路石样并有纵行溃疡。溃疡性结肠炎病变连续弥漫、限于结肠黏膜；细菌性痢疾有假膜形成；肠阿米巴病为烧瓶状溃疡"},{"q":"引起病毒性心肌炎的常见病原体是","o":["草绿色链球菌","金黄色葡萄球菌","痢疾杆菌","柯萨奇B组病毒","朊病毒"],"a":3,"e":"病毒性心肌炎最常见病原体为柯萨奇B组病毒，其次为柯萨奇A组、Echo病毒及流感病毒等。草绿色链球菌致亚急性心内膜炎，金黄色葡萄球菌致急性心内膜炎，痢疾杆菌致细菌性痢疾，朊病毒致海绵状脑病，均非心肌炎常见病原"},{"q":"心肌脂肪变性引起“虎斑心”时，最易出现变化的部位是","o":["左心房及左心耳内膜下心肌","右心室内膜下心肌及乳头肌","左心室内膜下心肌及乳头肌","右心房及右心耳内膜下心肌","左心室前壁及心尖区心肌"],"a":2,"e":"慢性缺氧或中毒时心肌脂肪变最常累及左心室内膜下心肌和乳头肌，该处供血相对不足、负荷较重，脂肪变心肌呈黄色并与正常暗红色心肌相间，形成虎斑心。右心室、心房肌及心外膜下心肌受累较轻。镜下脂肪变的肌纤维呈空泡状，苏丹Ⅲ染色阳性，严重者心肌收缩力下降"},{"q":"寄生虫感染引起的炎症，下列哪种细胞多见","o":["中性粒细胞","嗜酸性粒细胞","单核巨噬细胞","淋巴细胞","浆细胞"],"a":1,"e":"寄生虫感染时嗜酸性粒细胞显著增多，其受肥大细胞释放的趋化因子吸引，颗粒内主要碱性蛋白可杀伤虫体。中性粒细胞见于细菌感染；单核巨噬细胞见于结核等慢性炎症；淋巴细胞与浆细胞见于病毒感染及慢性炎症"},{"q":"脂肪变性的肉眼观察其主要的病变特点是","o":["体积减小，有油腻感，重量减轻，黄色质软","体积增大，有油腻感，重量正常，白色质软","体积增大，有油腻感，重量增加，黄色质软","体积增大，有油腻感，重量增加，红色质软","体积增大，有油腻感，重量减轻，黄色质软"],"a":2,"e":"脂肪变性时脂滴在细胞内聚集，器官体积增大、边缘圆钝、色淡黄、切面有油腻感、重量增加、质地柔软。体积缩小和重量减轻与萎缩相符；色泽苍白见于缺血或纤维化，均不符合脂肪变。镜下见肝细胞胞质内大小不等的球形脂滴，大者将核挤向一侧，冰冻切片苏丹Ⅲ染色呈橘红色"},{"q":"恶性高血压患者死于尿毒症的主要原因是","o":["肾小管坏死","肾间质出血","肾动脉血栓形成","肾小球纤维化","肾细小动脉纤维素样坏死"],"a":4,"e":"恶性高血压时肾细小动脉壁发生纤维素样坏死，并伴增生性小动脉硬化和洋葱皮样改变，入球动脉坏死使肾小球缺血、滤过功能急剧下降，短期内肾功能衰竭而死于尿毒症。A项肾小管坏死多为缺血或中毒所致，B项间质出血为伴随改变，D项肾小球纤维化见于良性高血压的慢性过程，均非致死主因"},{"q":"晚期胃癌常转移到左锁骨上淋巴结，后者又称","o":["Aschoff淋巴结","Ewing淋巴结","Krukenberg淋巴结","Schwann淋巴结","Virchow淋巴结"],"a":4,"e":"胃癌晚期经胸导管转移至左锁骨上淋巴结，称Virchow淋巴结，为胃淋巴引流的重要标志。Krukenberg瘤是胃癌转移至卵巢形成的黏液癌；Aschoff小体为风湿性肉芽肿；Ewing肉瘤为骨的小圆细胞恶性肿瘤"},{"q":"高分化的恶性肿瘤的主要特征是","o":["细胞形态和组织结构与起源组织相似","不向周围组织直接蔓延","不发生转移","手术切除后一般不复发","对机体危害程度较轻"],"a":0,"e":"分化程度指肿瘤组织与起源组织的相似程度，高分化者细胞形态和组织结构接近起源组织，异型性小。分化高并不等于良性，仍可浸润和转移，故不发生转移、术后不复发、危害较轻均不成立；向周围组织直接蔓延正是恶性肿瘤的生物学行为之一"},{"q":"如图，此肿瘤生长方式是","o":["浸润性生长","外生性生长","膨胀性生长","浸润与外生","膨胀与浸润"],"a":0,"e":"本题原题配有图片，图片未随文档保留，以下解析依文字线索推断：题干涉及图片/信息缺失，无法作答。浸润性生长是恶性肿瘤的常见方式，瘤细胞侵入并破坏周围组织，无包膜，与邻近组织分界不清，切除后易复发。B项外生性生长指向体表或腔面突起，良恶性均可；C项膨胀性生长为良性肿瘤推开周围组织并有包膜；D、E项混合方式须依图像判断\n\n官方题库中缺失图片"},{"q":"下列病变属于梗死的是","o":["深Ⅱ度烧伤","足坏疽","刀割伤","病毒性肝炎","脓肿"],"a":1,"e":"梗死为缺血所致坏死，足坏疽多因下肢动脉阻塞致缺血，属梗死范畴。深Ⅱ度烧伤为热力损伤，刀割伤为机械性创伤，病毒性肝炎为变质性炎，脓肿为化脓性炎，均非缺血性坏死，不属梗死"},{"q":"单侧肾切除后，残留肾脏发生的病变为","o":["适应性肥大","代偿性肥大","生理性增生","病理性增生","化生"],"a":1,"e":"单侧肾切除后，残留肾的滤过负荷加重，肾小球体积增大、肾小管上皮增生，属代偿性肥大。适应性肥大指器官因功能需要而增大，如运动致骨骼肌增粗；生理性增生见于青春期乳腺、子宫内膜周期变化；病理性增生见于雌激素持续刺激的子宫内膜；化生为上皮或结缔组织转化"},{"q":"霍奇金淋巴瘤中的反应性细胞是","o":["Reed-Sternberg cell","镜影细胞","淋巴细胞、浆细胞","霍奇金细胞","陷窝细胞"],"a":2,"e":"霍奇金淋巴瘤的肿瘤细胞为Reed-Sternberg细胞及其变异型（镜影细胞、霍奇金细胞、陷窝细胞），而淋巴细胞、浆细胞、嗜酸性粒细胞等为其反应性背景细胞。故反应性细胞是淋巴细胞、浆细胞"},{"q":"关于风湿病增生期Aschoff小体的描述中，下列错误的是","o":["小体中心部为纤维素样坏死灶","坏死灶周围可见Aschoff巨细胞","坏死灶周围可见Anitschkow细胞","主要成分为Langhans细胞","小体内还有少量淋巴细胞"],"a":3,"e":"Aschoff小体中心为纤维素样坏死，周围有Anitschkow细胞、Aschoff巨细胞及少量淋巴细胞，主要成分是Anitschkow细胞，并非Langhans细胞，故该项错误。Langhans巨细胞是结核等肉芽肿性炎的特征，由上皮样细胞融合而成，与风湿性肉芽肿来源不同"},{"q":"进展期胃癌最多见的类型是","o":["息肉型","蕈伞型","溃疡型","浸润型","胶样癌"],"a":2,"e":"进展期胃癌中溃疡型最常见，癌组织中央坏死脱落形成溃疡，边缘隆起、底部凹凸不平，好发于胃窦和小弯。A项息肉型、B项蕈伞型均属隆起型，较局限；D项浸润型（皮革胃）使胃壁弥漫增厚变硬，恶性度高但发生率低于溃疡型；E项胶样癌少见，以黏液湖为特征"},{"q":"动脉粥样硬化固缩肾表现为","o":["表面呈颗粒状","两肾肿大，颜色苍白","肾脏可见凹陷性瘢痕","肾内形成多发性栓塞小脓肿","两肾肿大充血，呈“大红肾”"],"a":2,"e":"动脉粥样硬化性固缩肾因肾动脉管腔狭窄、肾组织缺血萎缩，梗死区机化后形成较大凹陷瘢痕。表面细颗粒状为慢性肾小球肾炎的颗粒性固缩肾；两肾肿大苍白为脂性肾病；大红肾为急性肾小球肾炎；多发小脓肿为急性感染性心内膜炎的栓塞性脓肿"},{"q":"以下关于Barrett食管的说法错误的是","o":["是一种化生性病变","常发生在食管胃交界齿状线以上数厘米","可继发糜烂、溃疡","不会发生癌变","主要并发症包括狭窄、出血、裂孔疝"],"a":3,"e":"Barrett食管为食管远端鳞状上皮被柱状上皮取代，属化生性病变，是食管腺癌的癌前病变，可继发糜烂、溃疡、狭窄、出血及裂孔疝，故不会癌变的说法错误。病变多位于食管胃交界齿状线以上数厘米"},{"q":"与门静脉高压无关的是","o":["慢性淤血性脾大","食管下段静脉丛曲张","胃肠壁淤血、水肿","肝掌","腹水"],"a":3,"e":"肝掌是肝功能减退、雌激素灭活减少致手掌大、小鱼际及指尖充血发红，属肝功能不全表现，与门静脉高压无关。A项淤血性脾大、B项食管下段静脉丛曲张、C项胃肠壁淤血水肿、E项腹水均由门静脉回流受阻、侧支循环开放和低蛋白血症引起，构成门脉高压综合征"},{"q":"下列哪项是恶性肿瘤的主要特征","o":["核分裂象多见","细胞丰富","瘤巨细胞形成","浸润性生长和转移","血管丰富"],"a":3,"e":"浸润性生长与转移是恶性肿瘤的本质特征，转移是判断恶性最可靠的证据。核分裂象多见、细胞丰富、瘤巨细胞形成及血管丰富在生长活跃的良性肿瘤或交界性肿瘤中也可出现，特异性不足"},{"q":"不符合乳腺癌的描述是","o":["多来源于导管上皮细胞","多发生于外上象限","以鳞癌多见","多数为实性癌","以淋巴道转移多见"],"a":2,"e":"乳腺癌绝大多数起源于导管上皮，属腺癌，多位于外上象限，以淋巴道转移至同侧腋窝淋巴结最常见，多数为实性癌。鳞状细胞癌仅在鳞状化生基础上发生，比例很低，故以鳞癌多见不符合乳腺癌的实际"},{"q":"胃溃疡的合并症最常见的是","o":["梗阻","穿孔","出血","癌变","粘连"],"a":2,"e":"溃疡底部的血管被侵蚀破裂是出血的解剖基础，出血居胃溃疡合并症之首，约占患者的20%～25%。穿孔多发生于溃疡深达浆膜、胃壁变薄处，发生率低于出血。梗阻由幽门区瘢痕收缩与痉挛引起，癌变仅见于极少数长期胃溃疡，粘连则是穿孔局限化的后果"},{"q":"下列不是病理学的研究范畴的是","o":["病因学","发病学","疾病的治疗","病理变化","患病机体的功能、代谢变化"],"a":2,"e":"病理学研究疾病病因学、发病学、病理变化及患病机体的功能代谢变化。疾病的治疗属临床医学范畴，不属于病理学的研究内容，故为不包括项"},{"q":"子宫内膜异位症最多见于","o":["子宫直肠窝","子宫肌层","卵巢","输卵管","子宫韧带"],"a":2,"e":"子宫内膜异位症指子宫内膜腺体和间质出现于子宫内膜以外的部位，80%发生于卵巢，可形成巧克力囊肿，其余依次为子宫阔韧带、直肠子宫陷凹、盆腔腹膜和手术瘢痕。位于子宫肌层内者称子宫腺肌病；输卵管和子宫韧带受累较少"},{"q":"图为休克死亡者，在肺组织切片中可见","o":["混合血栓","红色血栓","透明血栓","白色血栓","附壁血栓"],"a":2,"e":"本题原题配有图片，图片未随文档保留，以下解析依文字线索推断：题干涉及图片/信息缺失，无法作答。就知识点而言，休克尤其弥散性血管内凝血死亡者肺微血管内常见透明血栓，由纤维蛋白构成，见于微循环衰竭期。A项混合血栓多见于静脉血栓体部；B项红色血栓见于静脉血栓尾部；D项白色血栓多为动脉血栓头部；E项附壁血栓多见于心房或动脉瘤内，均非休克肺微血管的典型血栓\n\n官方题库中缺失图片"},{"q":"右冠状动脉阻塞引起的梗死区域为","o":["右心房、右心室","左心室侧壁及右心室","室间隔前2/3、心尖及右心室","左心室后壁、室间隔后1/3及右心室","室间隔后2/3及右心房、右心室"],"a":3,"e":"右冠状动脉供应左心室后壁、室间隔后1/3及右心室，其阻塞所致梗死约占心肌梗死的25%。左前降支供应左心室前壁、心尖及室间隔前2/3，左旋支供应左心室侧壁；右心房和右心室梗死较为少见"},{"q":"慢性支气管炎最常见的并发症是","o":["支气管扩张症","大叶性肺炎","肺气肿","小叶性肺炎","肺脓肿"],"a":2,"e":"慢性支气管炎长期气道阻塞、细支气管壁破坏，使肺泡壁断裂融合，最常并发阻塞性肺气肿。支气管扩张症、肺脓肿、肺炎、肺结核也可发生，但都不如肺气肿常见，肺气肿是慢支最主要、最常见的结局"},{"q":"经过治疗的毒性甲状腺肿的形态学特征是","o":["滤泡增生，滤泡大小不等","滤泡内胶质少而稀薄","滤泡上皮细胞呈立方形或高柱状","滤泡上皮细胞变矮小，间质血管少","多量淋巴细胞浸润并有滤泡形成"],"a":3,"e":"毒性甲状腺肿经碘剂及抗甲状腺药物治疗后，甲状腺缩小变实，滤泡上皮变矮、增生减轻，胶质增多变浓，吸收空泡减少，间质血管与淋巴细胞减少。滤泡上皮呈立方形或高柱状、胶质少而稀薄、间质充血为未经治疗的甲亢表现；多量淋巴细胞浸润伴淋巴滤泡形成见于桥本甲状腺炎，属自身免疫性炎"},{"q":"陷窝细胞常见于霍奇金淋巴瘤的哪种组织学类型","o":["结节性淋巴细胞为主型","淋巴细胞为主型","淋巴细胞减少型","混合细胞型","结节硬化型"],"a":4,"e":"陷窝细胞是经典型霍奇金淋巴瘤结节硬化型的特征性瘤细胞，胞质丰富透亮、核分叶，因固定收缩与周围胶原分隔而似陷于陷窝。混合细胞型以典型R-S细胞为主。淋巴细胞减少型瘤细胞多形性明显、背景细胞稀少。结节性淋巴细胞为主型的特征细胞为爆米花细胞"},{"q":"血管内皮细胞、成纤维细胞、淋巴细胞常见于","o":["急性炎症","炎性肉芽组织","伤口愈合处","肉芽肿性炎","化脓性炎症"],"a":1,"e":"炎性肉芽组织由新生毛细血管、增生的成纤维细胞及淋巴细胞、中性粒细胞等炎细胞构成，故三种细胞可同时出现。肉芽肿性炎以巨噬细胞及其衍生的上皮样细胞、多核巨细胞增生为特征；急性炎症以中性粒细胞浸润为主，化脓性炎则为大量中性粒细胞浸润伴组织液化"},{"q":"肺癌切除后，残余肺组织过度充气称为","o":["全腺泡型肺气肿","腺泡中央型肺气肿","腺泡周围型肺气肿","瘢痕旁肺气肿","代偿性肺气肿"],"a":4,"e":"肺叶切除后残余肺组织为代偿通气而肺泡过度充气，通常不伴气道与肺泡壁明显破坏，属代偿性肺气肿。腺泡中央型肺气肿累及呼吸性细支气管，与吸烟及慢性支气管炎有关。腺泡周围型累及肺泡管与肺泡囊。瘢痕旁肺气肿位于纤维瘢痕灶周围"},{"q":"目前认为乙型肝炎病毒引起肝细胞损害的主要机制是","o":["病毒直接破坏肝细胞膜","病毒损坏肝细胞的线粒体","病毒代谢产物的损害作用","激活机体细胞免疫反应损害肝细胞","通过抗原抗体反应激活补体"],"a":3,"e":"乙型肝炎病毒不直接杀伤肝细胞，其抗原表达于肝细胞表面后激活细胞毒性T淋巴细胞，通过细胞免疫反应造成肝细胞损伤。病毒直接破坏胞膜、损伤线粒体、代谢产物毒性及补体激活均非主要机制"},{"q":"下列均为假小叶的特点，但除外","o":["肝小叶内中央静脉缺如","肝小叶内出现汇管区","肝小叶内可有2条以上中央静脉","肝细胞排列紊乱，可出现双核肝细胞","肝细胞广泛凋亡，大量凋亡小体形成"],"a":4,"e":"假小叶内中央静脉常缺如、偏位，也可出现两条以上，其中可见汇管区，肝细胞排列紊乱并出现双核肝细胞，均为其结构特点。肝细胞广泛凋亡、大量凋亡小体形成是细胞凋亡的形态改变，见于病毒性肝炎的嗜酸性小体，不构成假小叶的结构特征"},{"q":"酒精性肝炎镜下表现为肝细胞脂肪变性，并可见形成","o":["Russell小体","Negri小体","Dutcher小体","Mallory小体","Aschoff小体"],"a":3,"e":"酒精性肝炎的三大病变为肝细胞脂肪变性、Mallory小体形成和点灶状坏死伴中性粒细胞浸润；Mallory小体是胞质内嗜酸性不规则玻璃样物质，由中间丝蛋白聚集而成。Russell小体为浆细胞胞质内免疫球蛋白蓄积，Negri小体见于狂犬病海马锥体细胞，Dutcher小体为核内免疫球蛋白假包涵体，Aschoff小体是风湿病心肌间质的肉芽肿"},{"q":"Krukenberg瘤指的是转移的","o":["肝细胞癌","胃黏液腺癌","乳腺癌","卵巢癌","肺小细胞癌"],"a":1,"e":"Krukenberg瘤是胃黏液腺癌（印戒细胞癌）脱落细胞经腹腔种植转移至卵巢所形成的转移性腺癌。肝细胞癌、乳腺癌、卵巢原发癌、肺小细胞癌均非Krukenberg瘤的原发来源"},{"q":"下列哪种炎症介质不具有对白细胞的阳性趋化作用","o":["白细胞三烯","IL-8","IL-5","TNF","缓激肽"],"a":4,"e":"缓激肽使细动脉扩张、血管通透性增高、支气管平滑肌收缩并引起疼痛，无白细胞趋化作用。白细胞三烯B4、IL-8为强趋化因子，TNF可激活内皮并促进白细胞渗出，IL-5主要趋化并活化嗜酸性粒细胞，故均可归入趋化因子之列"},{"q":"风湿性心脏病瓣膜疣赘物的结局是","o":["溶解吸收","机化引起心瓣膜病变","软化脱落引起栓塞","引起瓣膜穿孔","引起败血症"],"a":1,"e":"风湿性心内膜炎的疣状赘生物附着牢固、不易脱落，由纤维蛋白与血小板构成，最终机化使瓣膜增厚、粘连、腱索缩短，形成瓣膜狭窄与关闭不全。赘生物松软易脱落引起栓塞者见于感染性心内膜炎。瓣膜穿孔亦多见于感染性心内膜炎。败血症须有细菌入血繁殖"},{"q":"血栓中的纤维蛋白被溶解称为","o":["血栓再通","溶解吸收","血栓机化","血栓钙化","血栓栓塞"],"a":1,"e":"血栓内纤维蛋白被蛋白水解酶溶解，血栓软化、液化并被吸收，称溶解吸收，见于新鲜而较小的血栓。血栓机化是肉芽组织长入并取代血栓；再通为机化后血流重建；钙化为营养不良性钙盐沉积"},{"q":"下列哪项不属于动脉性充血","o":["膀胱减压后充血","炎性充血","肝硬化时，胃肠道和脾脏充血","进食后的胃肠道充血","运动时骨骼肌充血"],"a":2,"e":"动脉性充血为细动脉扩张、血流加快，见于进食后胃肠道、运动时骨骼肌、减压后及炎症早期。肝硬化时胃肠道和脾脏充血由门静脉高压致静脉回流受阻引起，属静脉性淤血即被动性充血，与动脉性充血机制相反"},{"q":"低蛋白血症引起水肿的机制是","o":["毛细血管内压升高","血浆胶体渗透压下降","组织间液的胶体渗透压升高","组织间液的流体静压下降","毛细血管的流体静压升高"],"a":1,"e":"血浆胶体渗透压主要由白蛋白维持，低蛋白血症时胶体渗透压下降，平均有效滤过压增大，组织液生成增多而形成水肿。毛细血管流体静压升高见于右心衰竭与静脉回流受阻，属另一类水肿机制。组织间液胶体渗透压升高见于炎症时蛋白渗出，与低蛋白血症不同"},{"q":"动脉粥样硬化主要累及","o":["小动脉的内膜","大、中动脉的中膜","大、中动脉的内膜","小动脉的中膜","细动脉壁"],"a":2,"e":"动脉粥样硬化主要累及大、中动脉的内膜，在内膜下形成脂纹、纤维斑块和粥样斑块，导致管腔狭窄。细小动脉玻璃样变见于良性高血压和糖尿病，属细小动脉硬化；中膜病变主要为中膜钙化或囊性变，与粥样硬化的内膜病变不同"},{"q":"导致肺褐色硬化的疾病是","o":["肺动脉狭窄","三尖瓣狭窄","二尖瓣狭窄","肺动脉栓塞","硅沉着病"],"a":2,"e":"二尖瓣狭窄致左房压升高、肺静脉高压、肺淤血，长期含铁血黄素沉积使肺质地变硬、呈棕褐色，称肺褐色硬化。肺动脉狭窄、三尖瓣狭窄引起右心改变，不致肺淤血；肺动脉栓塞引起肺出血性梗死；硅沉着病为硅结节伴纤维化"},{"q":"下列哪种疾病不出现肺透明膜","o":["病毒性肺炎","慢性支气管炎","SARS","新生儿呼吸窘迫综合征","腺病毒肺炎"],"a":1,"e":"慢性支气管炎为支气管黏膜及其周围组织的慢性非特异性炎症，不损伤肺泡上皮与毛细血管，无透明膜形成。病毒性肺炎、腺病毒肺炎、SARS因肺泡上皮弥漫损伤及渗出物机化，新生儿呼吸窘迫综合征因表面活性物质缺乏，均可形成透明膜"},{"q":"大叶性肺炎的病变表现描述中错误的是","o":["肺脏胸膜充血、水肿伴纤维素渗出","病灶的病变特点是以细支气管为中心的化脓性炎","炎症不破坏肺泡壁结构","病变多累及一个大叶或一肺段","炎症以纤维素渗出为主"],"a":1,"e":"大叶性肺炎是肺炎链球菌引起的急性纤维素性炎，病变累及一个大叶或肺段，不破坏肺泡壁结构，胸膜有纤维素渗出。以细支气管为中心的化脓性炎是小叶性肺炎的特点，而非大叶性肺炎，故该描述错误"},{"q":"不符合肿瘤性生长的特点是","o":["与机体的需要不协调","致瘤因素消除后就不继续生长","生长旺盛","不同程度失去分化成熟能力","相对自主性生长"],"a":1,"e":"肿瘤性生长的本质是相对自主性，引起肿瘤的初始因素消除后仍持续生长，故致瘤因素消除后就不继续生长错误。A项与机体需要不协调、C项生长旺盛、D项不同程度失去分化成熟能力、E项相对自主性生长均为其特点。肿瘤细胞获得克隆性增殖能力后，生长不再依赖原始刺激"},{"q":"关于肝硬化的叙述，下列哪项是错误的","o":["蜘蛛状血管痣","男性女性化","腹腔积液","胃肠道出血","病因被消除后，肝脏的正常结构可以恢复"],"a":4,"e":"肝硬化时假小叶形成、纤维间隔分割使肝小叶结构破坏，属不可逆改变，病因去除后纤维化可减轻而正常结构不能恢复。蜘蛛痣与男性女性化由雌激素灭活减少引起。腹水与胃肠道出血分别源于门脉高压、低蛋白血症及凝血障碍、静脉曲张破裂"},{"q":"流行性脑脊髓膜炎最常见的病原菌是","o":["肺炎球菌","脑膜炎球菌","金黄色葡萄球菌","溶血性链球菌","大肠杆菌"],"a":1,"e":"流行性脑脊髓膜炎由脑膜炎奈瑟菌即脑膜炎球菌引起，经飞沫传播，多见于冬春季儿童，病变为软脑膜化脓性炎。肺炎球菌主要引起大叶性肺炎，金黄色葡萄球菌与大肠埃希菌多见于新生儿或术后感染"},{"q":"髓母细胞瘤具有以下特点，但除外下列哪项","o":["间质较少","核分裂象较多","常发生于成年人","有菊形团形成","瘤细胞多呈圆形、瓜子形，细胞质少，核深染"],"a":2,"e":"髓母细胞瘤是儿童常见的胚胎性恶性肿瘤，多位于小脑蚓部，瘤细胞呈圆形或瓜子形、胞质少、核深染，核分裂象多，可见菊形团，间质较少。成年人少见，成人小脑肿瘤以转移瘤和血管母细胞瘤为多。髓母细胞瘤易经脑脊液种植转移至椎管，对放射治疗敏感，组织学属高度恶性"},{"q":"以下关于急性胆囊炎的表现，描述错误的是","o":["麦氏点压痛","腹痛位于右上腹","多有胆囊结石病史","常在进食油腻食物后出现","腹痛程度常随体位改变而改变"],"a":0,"e":"急性胆囊炎表现为右上腹痛、进食油腻食物后发作，多有胆囊结石病史，Murphy征阳性。麦氏点压痛为急性阑尾炎体征，位于右下腹，故该项错误；腹痛随体位改变多见于结石性绞痛，亦非胆囊炎特征"},{"q":"急性炎症时，炎症局部血流速度的减慢主要是由于","o":["血管内流体静压下降","血管口径变小，血流阻力增大","微血管通透性升高的结果","组织水肿升高对血管产生压迫","血管阻塞"],"a":2,"e":"急性炎症时微血管通透性升高，血浆外渗、血液浓缩，红细胞聚集使血液黏稠度增加，是局部血流速度减慢的主要原因。B项血管口径变小属于缺血改变；D项组织水肿压迫并非主要机制；E项血管阻塞见于血栓形成，均非急性炎症血流淤滞的根本原因"}];
